package com.bronzemantcg;

import com.bronzemantcg.catalog.ResourceNodeCatalog;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class ThievingChestDataTest
{
	private final ResourceNodeCatalog catalog = new ResourceNodeCatalog(new Gson());

	@Test
	public void objectIdsDistinguishChestsWithTheSameDisplayName()
	{
		ResourceNodeCatalog.Rule coins = catalog.find(
			"object", "Chest", "Search for traps", 11735);
		ResourceNodeCatalog.Rule nature = catalog.find(
			"object", "Chest", "Search for traps", 11736);

		assertNotNull(coins);
		assertNotNull(nature);
		assertEquals(List.of("Coins"), missing(coins, Collections.emptySet(), false));
		assertEquals(List.of("Nature rune / Coins"),
			missing(nature, Collections.emptySet(), false));
		assertNull(catalog.find("object", "Chest", "Search for traps", 999999));
	}

	@Test
	public void anyOfAndAllUseTheSameChestLootGroup()
	{
		ResourceNodeCatalog.Rule nature = catalog.find(
			"object", "Chest", "Search for traps", 11736);

		assertEquals(Collections.emptyList(), missing(nature, Set.of("coins"), false));
		assertEquals(List.of("Nature rune"), missing(nature, Set.of("coins"), true));
	}

	@Test
	public void supportsUnderwaterAndModernPicklockChests()
	{
		assertNotNull(catalog.find("object", "Chest", "Search", 30971));
		assertNotNull(catalog.find("object", "Chest", "Picklock", 54773));
		assertNotNull(catalog.find("object", "Chest", "Pick-lock", 22681));
		assertNotNull(catalog.find("object", "Reinforced chest", "Picklock", 60517));
	}

	private List<String> missing(ResourceNodeCatalog.Rule rule, Set<String> owned,
		boolean requireAll)
	{
		return rule.missingRequirements(owned, Collections.emptySet(), requireAll);
	}
}

package com.bronzemantcg.support;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.CardIdentityCatalog;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Small test-only catalogue representing reviewed OSRS TCG v1 parent/variant relationships. */
public final class SimulatedV1CardIdentityCatalog implements CardIdentityCatalog
{
	private final Map<CardEntityKind, Map<Integer, List<CardIdentity>>> byId = new LinkedHashMap<>();
	private final Map<CardEntityKind, Map<String, List<CardIdentity>>> byName = new LinkedHashMap<>();
	private final Map<CardEntityKind, Map<String, List<CardIdentity>>> byCardName = new LinkedHashMap<>();

	public SimulatedV1CardIdentityCatalog()
	{
		for (CardEntityKind kind : CardEntityKind.values())
		{
			byId.put(kind, new LinkedHashMap<>());
			byName.put(kind, new LinkedHashMap<>());
			byCardName.put(kind, new LinkedHashMap<>());
		}

		add(CardEntityKind.ITEM, "Water rune", names("Water rune pack"),
			names("Water rune"), 555, 12730);
		add(CardEntityKind.ITEM, "Attack potion", Collections.emptyList(),
			names("Attack potion"), 121, 123);
		add(CardEntityKind.ITEM, "Dragon axe", Collections.emptyList(),
			names("Dragon axe"), 6739);
		add(CardEntityKind.NPC, "Armoured zombie (Defender of Varrock)",
			names("Armoured zombie (quest)"), names("Armoured zombie"), 12730, 12731);
		add(CardEntityKind.NPC, "Monkey Archer", Collections.emptyList(),
			names("Monkey archer"), 5272, 5274);
		add(CardEntityKind.ITEM, "Crawling hand", Collections.emptyList(),
			names("Crawling hand"), 7975, 7982);
		add(CardEntityKind.NPC, "Crawling Hand", Collections.emptyList(),
			names("Crawling hand"), 448, 449, 12249);
		add(CardEntityKind.ITEM, "Manta ray", Collections.emptyList(),
			names("Manta ray"), 391, 393, 24589);
		add(CardEntityKind.NPC, "Manta ray", Collections.emptyList(),
			names("Manta ray"), 15220, 15221);
		add(CardEntityKind.ITEM, "Rock golem", Collections.emptyList(),
			names("Rock golem"), 13321, 21187, 31278);
		add(CardEntityKind.NPC, "Rock Golem", Collections.emptyList(),
			names("Rock golem"), 2182, 6725, 14923);
		add(CardEntityKind.NPC, "First ambiguous parent", Collections.emptyList(),
			names("Ambiguous NPC"), 9000);
		add(CardEntityKind.NPC, "Second ambiguous parent", Collections.emptyList(),
			names("Ambiguous NPC"), 9000);
	}

	@Override
	public List<CardIdentity> findById(CardEntityKind kind, int entityId)
	{
		return find(byId, kind, entityId);
	}

	@Override
	public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
	{
		return find(byName, kind, normalize(entityName));
	}

	@Override
	public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
	{
		return find(byCardName, kind, normalize(cardName));
	}

	private void add(CardEntityKind kind, String cardName, List<String> legacyCardNames,
		List<String> entityNames, Integer... entityIds)
	{
		CardIdentity identity = new CardIdentity(kind, cardName,
			new LinkedHashSet<>(legacyCardNames),
			new LinkedHashSet<>(Arrays.asList(entityIds)));
		add(byCardName.get(kind), normalize(cardName), identity);
		for (String legacyCardName : legacyCardNames)
		{
			add(byCardName.get(kind), normalize(legacyCardName), identity);
		}
		for (String entityName : entityNames)
		{
			add(byName.get(kind), normalize(entityName), identity);
		}
		for (Integer entityId : entityIds)
		{
			add(byId.get(kind), entityId, identity);
		}
	}

	private static <K> List<CardIdentity> find(
		Map<CardEntityKind, Map<K, List<CardIdentity>>> index, CardEntityKind kind, K key)
	{
		Map<K, List<CardIdentity>> values = index.get(kind);
		if (values == null)
		{
			return Collections.emptyList();
		}
		return values.getOrDefault(key, Collections.emptyList());
	}

	private static <K> void add(Map<K, List<CardIdentity>> index, K key,
		CardIdentity identity)
	{
		index.computeIfAbsent(key, ignored -> new ArrayList<>()).add(identity);
	}

	private static List<String> names(String... values)
	{
		return Arrays.asList(values);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}
}

package com.bronzemantcg.interop;

import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class BetaCardLookupClientTest
{
	private static final String ENDPOINT = "https://example.test/api/v1/players";

	@Test
	public void usesCurrentPlayerEndpoint()
	{
		assertEquals("https://osrs-tcg.net/api/v1/players",
			BetaCardLookupClient.PLAYERS_URL);
	}

	@Test
	public void encodesPlayerAsOnePathSegmentAndBypassesHttpCache() throws Exception
	{
		byte[] body = "{\"displayName\":\"A/B Name\",\"revision\":1,\"cardNames\":[]}"
			.getBytes(StandardCharsets.UTF_8);
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			assertEquals("/api/v1/players/A%2FB%20Name/beta-names",
				chain.request().url().encodedPath());
			assertTrue(chain.request().cacheControl().noCache());
			assertTrue(chain.request().cacheControl().noStore());
			return response(chain.request(), 200, body);
		}).build();

		BetaCardLookupClient.LookupResponse result = fetch(
			new BetaCardLookupClient(http, ENDPOINT, 1024), "A/B Name");

		assertEquals(200, result.getStatusCode());
		assertArrayEquals(body, result.getBody());
	}

	@Test
	public void rejectsResponsesAboveTheConfiguredLimit()
	{
		BetaCardLookupClient client = new BetaCardLookupClient(
			clientReturning(200, "12345".getBytes(StandardCharsets.UTF_8)), ENDPOINT, 4);

		ExecutionException exception = assertThrows(ExecutionException.class,
			() -> fetch(client, "Player"));
		assertTrue(exception.getCause().getMessage().contains("size limit"));
	}

	private static BetaCardLookupClient.LookupResponse fetch(BetaCardLookupClient client,
		String name) throws InterruptedException, ExecutionException, TimeoutException
	{
		CompletableFuture<BetaCardLookupClient.LookupResponse> future = new CompletableFuture<>();
		client.fetch(name, new BetaCardLookupClient.Listener()
		{
			@Override
			public void onResponse(BetaCardLookupClient.LookupResponse response)
			{
				future.complete(response);
			}

			@Override
			public void onFailure(Throwable cause)
			{
				future.completeExceptionally(cause);
			}
		});
		return future.get(2, TimeUnit.SECONDS);
	}

	private static OkHttpClient clientReturning(int code, byte[] body)
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain -> response(chain.request(), code, body)).build();
	}

	private static Response response(okhttp3.Request request, int code, byte[] body)
	{
		return new Response.Builder().request(request).protocol(Protocol.HTTP_1_1)
			.code(code).message(code == 200 ? "OK" : "Error")
			.body(ResponseBody.create(MediaType.parse("application/json"), body)).build();
	}
}

package com.bronzemantcg.interop;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OsrsTcgInteropServiceTest
{
	private TcgCollectionReader collectionReader;
	private EventBus eventBus;
	private OsrsTcgInteropService service;
	private List<PluginMessage> posted;

	@Before
	public void setUp()
	{
		// These tests exercise only the API path, so no persisted-state dependencies are read.
		collectionReader = new TcgCollectionReader(null, null);
		eventBus = new EventBus();
		service = new OsrsTcgInteropService(collectionReader, eventBus);
		posted = new ArrayList<>();
		eventBus.register(PluginMessage.class, posted::add, 0);
	}

	@Test
	public void ignoresNullUnrelatedAndMalformedMessages()
	{
		assertEquals(OsrsTcgInteropService.UpdateResult.IGNORED,
			service.onPluginMessage(null));
		assertEquals(OsrsTcgInteropService.UpdateResult.IGNORED,
			service.onPluginMessage(message("other", "owned-names", names("Dragon axe"))));
		assertEquals(OsrsTcgInteropService.UpdateResult.IGNORED,
			service.onPluginMessage(message("osrstcg", "other", names("Dragon axe"))));
		assertEquals(OsrsTcgInteropService.UpdateResult.IGNORED,
			service.onPluginMessage(new PluginMessage("osrstcg", "owned-names")));

		Map<String, Object> malformed = new HashMap<>();
		malformed.put("ownedNames", "Dragon axe");
		assertEquals(OsrsTcgInteropService.UpdateResult.IGNORED,
			service.onPluginMessage(message("osrstcg", "owned-names", malformed)));
		assertFalse(collectionReader.hasApiData());
	}

	@Test
	public void acceptsLegacyNamesOnlyPayload()
	{
		Map<String, Object> data = names(" Dragon axe ", 42, null);
		assertEquals(OsrsTcgInteropService.UpdateResult.FIRST_UPDATE,
			service.onPluginMessage(message("osrstcg", "owned-names", data)));

		TcgOwnershipSnapshot snapshot = collectionReader.getOwnershipSnapshot();
		assertEquals(Collections.singleton("dragon axe"), snapshot.getOwnedCardNamesLowerCase());
		assertFalse(snapshot.hasEntityIds(CardEntityKind.ITEM));
		assertFalse(snapshot.hasEntityIds(CardEntityKind.NPC));
		assertFalse(collectionReader.hasLiveV1Capability());
	}

	@Test
	public void preservesEmptyIdNamespaceAsAuthoritative()
	{
		Map<String, Object> data = names("Test card");
		data.put("ownedItemIds", Collections.emptyList());
		data.put("ownedNpcIds", Collections.singletonList(100));
		data.put("groupKey", " group-a ");
		service.onPluginMessage(message("osrstcg", "owned-names-changed", data));

		TcgOwnershipSnapshot snapshot = collectionReader.getOwnershipSnapshot();
		assertTrue(snapshot.hasEntityIds(CardEntityKind.ITEM));
		assertFalse(snapshot.ownsEntityId(CardEntityKind.ITEM, 100));
		assertTrue(snapshot.hasEntityIds(CardEntityKind.NPC));
		assertTrue(snapshot.ownsEntityId(CardEntityKind.NPC, 100));
		assertEquals("group-a", snapshot.getGroupKey());
		assertTrue(collectionReader.hasLiveV1Capability());
	}

	@Test
	public void distinguishesFirstPayloadFromLaterPushes()
	{
		assertEquals(OsrsTcgInteropService.UpdateResult.FIRST_UPDATE,
			service.onPluginMessage(message("osrstcg", "owned-names", names("Dragon axe"))));
		assertEquals(OsrsTcgInteropService.UpdateResult.UPDATED,
			service.onPluginMessage(message("osrstcg", "owned-names-changed", names("Rune axe"))));
		assertEquals(Collections.singleton("rune axe"),
			collectionReader.getOwnedCardNamesLowerCase());
	}

	@Test
	public void startupQueriesOnFirstTickAndRetriesAtExistingCadence()
	{
		service.startUp();
		service.onGameTick();
		assertEquals(1, posted.size());
		assertQuery(posted.get(0));

		for (int i = 0; i < 100; i++)
		{
			service.onGameTick();
		}
		assertEquals(1, posted.size());
		service.onGameTick();
		assertEquals(2, posted.size());
	}

	@Test
	public void synchronousReplyStopsQueryRetries()
	{
		eventBus.register(PluginMessage.class, query ->
		{
			if ("osrstcg".equals(query.getNamespace()) && "query-owned-names".equals(query.getName()))
			{
				service.onPluginMessage(message("osrstcg", "owned-names", names("Dragon axe")));
			}
		}, 1);

		service.startUp();
		service.onGameTick();
		for (int i = 0; i < 250; i++)
		{
			service.onGameTick();
		}
		assertEquals(1, posted.size());
		assertTrue(collectionReader.hasApiData());
	}

	@Test
	public void profileChangeDropsApiSnapshotAndRearmsQuery()
	{
		service.onPluginMessage(message("osrstcg", "owned-names", names("Dragon axe")));
		assertTrue(collectionReader.hasApiData());

		service.onProfileChanged();
		assertFalse(collectionReader.hasApiData());
		assertFalse(collectionReader.hasLiveV1Capability());
		service.onGameTick();
		assertEquals(1, posted.size());
		assertQuery(posted.get(0));
	}

	private static Map<String, Object> names(Object... values)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("ownedNames", Arrays.asList(values));
		return data;
	}

	private static PluginMessage message(String namespace, String name, Map<String, Object> data)
	{
		return new PluginMessage(namespace, name, data);
	}

	private static void assertQuery(PluginMessage message)
	{
		assertEquals("osrstcg", message.getNamespace());
		assertEquals("query-owned-names", message.getName());
		assertTrue(message.getData().isEmpty());
	}
}

package com.bronzemantcg.interop;

import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Set;
import java.util.zip.GZIPOutputStream;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TcgPersistedStateTest
{
	private static final byte[] XOR_SALT = {
		(byte) 0x52, (byte) 0x4c, (byte) 0x54, (byte) 0x43, (byte) 0x47,
		(byte) 0x7c, (byte) 0x6f, (byte) 0x73, (byte) 0x72, (byte) 0x73,
		(byte) 0x2d, (byte) 0x74, (byte) 0x63, (byte) 0x67, (byte) 0x21,
	};

	@Test
	public void decodesLegacyV2InstancesForNamesOnlyOwnership() throws Exception
	{
		String json = "{\"schemaVersion\":3,\"cardInstances\":["
			+ "{\"cardName\":\"Water rune pack\",\"foil\":false},"
			+ "{\"cardName\":\"Manta ray\",\"foil\":true}]}";
		String stored = encode(json, true);

		assertEquals(json, TcgStateDecoder.decode(stored));
		TcgCollectionReader.PersistedState parsed =
			TcgCollectionReader.parsePersistedState(stored, new Gson());
		assertTrue(parsed.isCollectionPresent());
		assertEquals(Set.of("water rune pack", "manta ray"), parsed.getOwnedNames());
	}

	@Test
	public void legacyBetaMetadataDoesNotChangeNamesOnlyOwnership() throws Exception
	{
		String stored = encode("{\"cardInstances\":["
			+ "{\"cardName\":\"Water rune\",\"beta\":true},"
			+ "{\"cardName\":\"Manta ray\",\"beta\":false}]}", true);

		TcgCollectionReader.PersistedState parsed =
			TcgCollectionReader.parsePersistedState(stored, new Gson());
		assertEquals(Set.of("water rune", "manta ray"), parsed.getOwnedNames());
	}

	@Test
	public void decodesV3CardEntriesAndCountsOnlyPositiveVariants() throws Exception
	{
		String json = "{\"schemaVersion\":6,\"cardEntries\":["
			+ "{\"cardName\":\"Water rune\",\"variants\":["
			+ "{\"beta\":true},{\"foil\":true}]},"
			+ "{\"cardName\":\"Manta ray\",\"variants\":[{}]},"
			+ "{\"cardName\":\"Ignored\",\"variants\":[{\"beta\":true,\"quantity\":0}]}]}";
		String stored = encode(json, false);

		assertEquals(json, TcgStateDecoder.decode(stored));
		TcgCollectionReader.PersistedState parsed =
			TcgCollectionReader.parsePersistedState(stored, new Gson());
		assertEquals(Set.of("water rune", "manta ray"), parsed.getOwnedNames());
	}

	@Test
	public void preservesACompleteEmptyCollectionAndRejectsBadData() throws Exception
	{
		TcgCollectionReader.PersistedState empty = TcgCollectionReader.parsePersistedState(
			encode("{\"cardEntries\":[]}", false), new Gson());
		assertTrue(empty.isCollectionPresent());
		assertTrue(empty.getOwnedNames().isEmpty());

		assertEquals("", TcgStateDecoder.decode("not-osrs-tcg-state"));
		TcgCollectionReader.PersistedState malformed =
			TcgCollectionReader.parsePersistedState("RLTCG_v3:not-base64", new Gson());
		assertFalse(malformed.isCollectionPresent());
	}

	@Test
	public void rejectsDecodedStateBeyondTheBoundedSize() throws Exception
	{
		String oversized = "x".repeat(16 * 1024 * 1024 + 1);
		assertEquals("", TcgStateDecoder.decode(encode(oversized, false)));
	}

	private static String encode(String json, boolean legacyV2) throws Exception
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (GZIPOutputStream gzip = new GZIPOutputStream(output))
		{
			gzip.write(json.getBytes(StandardCharsets.UTF_8));
		}
		byte[] compressed = output.toByteArray();
		if (legacyV2)
		{
			for (int i = 0; i < compressed.length; i++)
			{
				compressed[i] ^= XOR_SALT[i % XOR_SALT.length];
			}
		}
		return (legacyV2 ? TcgStateDecoder.STORAGE_PREFIX_V2
			: TcgStateDecoder.STORAGE_PREFIX_V3)
			+ Base64.getEncoder().encodeToString(compressed);
	}
}

package com.bronzemantcg.interop;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardOwnershipService;
import com.bronzemantcg.ownership.CardResolver;
import com.bronzemantcg.ownership.BetaCardUnlockSource;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.bronzemantcg.support.SimulatedV1CardIdentityCatalog;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Exercises the proposed v1 ownership payload through the real Bronzeman interop path. */
public class OsrsTcgV1SimulationTest
{
	private TcgCollectionReader collectionReader;
	private OsrsTcgInteropService interopService;
	private CardOwnershipService ownershipService;

	@Before
	public void setUp()
	{
		collectionReader = new TcgCollectionReader(null, null);
		interopService = new OsrsTcgInteropService(collectionReader, new EventBus());
		ownershipService = new CardOwnershipService(
			new CardResolver(new SimulatedV1CardIdentityCatalog()));
	}

	@Test
	public void betaWaterRunePackVariantUnlocksV1WaterRuneParent()
	{
		accept(payload(Collections.singletonList("Water rune pack"),
			Collections.singletonList(12730), Collections.emptyList(), "group-a"));

		TcgOwnershipSnapshot ownership = collectionReader.getOwnershipSnapshot();
		assertEquals("group-a", ownership.getGroupKey());
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decideCard("Water rune", ownership, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 555, "Water rune",
				ownership, null, null));
		assertTrue(ownershipService.isCollectedCard("Water rune", ownership, null));
	}

	@Test
	public void reviewedBetaNameUnlocksParentWhenCurrentIdsAreMissing()
	{
		accept(payload(Collections.singletonList("Water rune pack"),
			Collections.emptyList(), Collections.emptyList(), null));
		TcgOwnershipSnapshot ownership = collectionReader.getOwnershipSnapshot();
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decideCard("Water rune", ownership, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 555, "Water rune",
				ownership, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 12730, "Water rune pack",
				ownership, null, null));
		assertTrue(ownershipService.isCollectedCard("Water rune", ownership, null));
	}

	@Test
	public void betaCacheUnlocksParentAfterPluginMessageDropsBetaCards()
	{
		accept(payload(Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), null));
		TcgOwnershipSnapshot v1Only = collectionReader.getOwnershipSnapshot();
		BetaCardUnlockSource.View beta = new BetaCardUnlockSource.View(1L,
			Collections.singleton("water rune"), Collections.emptySet());

		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decideCard("Water rune", v1Only, beta, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 555, "Water rune",
				v1Only, beta, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 12730, "Water rune pack",
				v1Only, beta, null, null));
	}

	@Test
	public void equalItemAndNpcIdsRemainSeparateNamespaces()
	{
		accept(payload(Collections.singletonList("Water rune pack"),
			Collections.singletonList(12730), Collections.emptyList(), "group-a"));
		TcgOwnershipSnapshot itemOnly = collectionReader.getOwnershipSnapshot();
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 12730, "Water rune pack",
				itemOnly, null, null));
		assertStatus(CardOwnershipService.Status.LOCKED,
			ownershipService.decide(CardEntityKind.NPC, 12730, "Armoured zombie",
				itemOnly, null, null));

		accept(payload(Collections.singletonList("Armoured zombie (Defender of Varrock)"),
			Collections.emptyList(), Collections.singletonList(12730), "group-a"));
		TcgOwnershipSnapshot npcOnly = collectionReader.getOwnershipSnapshot();
		assertStatus(CardOwnershipService.Status.LOCKED,
			ownershipService.decide(CardEntityKind.ITEM, 12730, "Water rune pack",
				npcOnly, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.NPC, 12731, "Armoured zombie",
				npcOnly, null, null));
	}

	@Test
	public void presentEmptyIdsOverrideNamesWhileMissingIdsRetainCompatibility()
	{
		accept(payload(Collections.singletonList("Dragon axe"),
			Collections.emptyList(), Collections.emptyList(), null));
		assertStatus(CardOwnershipService.Status.LOCKED,
			ownershipService.decideCard("Dragon axe", collectionReader.getOwnershipSnapshot(),
				null, null));

		Map<String, Object> legacy = new HashMap<>();
		legacy.put("ownedNames", Collections.singletonList("Dragon axe"));
		accept(legacy);
		TcgOwnershipSnapshot legacyOwnership = collectionReader.getOwnershipSnapshot();
		assertFalse(legacyOwnership.hasEntityIds(CardEntityKind.ITEM));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decideCard("Dragon axe", legacyOwnership, null, null));
	}

	@Test
	public void variantIdsOwnTheirParentAcrossItemAndNpcFamilies()
	{
		accept(payload(Collections.emptyList(), Collections.singletonList(123),
			Collections.singletonList(5272), null));
		TcgOwnershipSnapshot ownership = collectionReader.getOwnershipSnapshot();
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.ITEM, 121, "Attack potion(3)",
				ownership, null, null));
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decide(CardEntityKind.NPC, 5274, "Monkey archer",
				ownership, null, null));
	}

	@Test
	public void malformedElementsAreIgnoredWithoutDiscardingValidIds()
	{
		accept(payload(Collections.singletonList("Water rune pack"),
			Arrays.asList(12730L, "555", -1, 2.5, null),
			Arrays.asList(12731.0, "12730", -5), " group-b "));

		TcgOwnershipSnapshot ownership = collectionReader.getOwnershipSnapshot();
		assertEquals(Collections.singleton(12730), ownership.getOwnedItemIds());
		assertEquals(Collections.singleton(12731), ownership.getOwnedNpcIds());
		assertEquals("group-b", ownership.getGroupKey());
		assertStatus(CardOwnershipService.Status.OWNED,
			ownershipService.decideCard("Water rune", ownership, null, null));
	}

	@Test
	public void unknownMismatchAndAmbiguityFailOpen()
	{
		accept(payload(Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), null));
		TcgOwnershipSnapshot ownership = collectionReader.getOwnershipSnapshot();
		assertAllowedStatus(CardOwnershipService.Status.UNTRACKED,
			ownershipService.decide(CardEntityKind.ITEM, 999999, "Unknown item",
				ownership, null, null));
		assertAllowedStatus(CardOwnershipService.Status.CATALOG_MISMATCH,
			ownershipService.decide(CardEntityKind.ITEM, 999999, "Dragon axe",
				ownership, null, null));
		assertAllowedStatus(CardOwnershipService.Status.AMBIGUOUS,
			ownershipService.decide(CardEntityKind.NPC, 9000, "Ambiguous NPC",
				ownership, null, null));
	}

	@Test
	public void profileChangeDropsTheSimulatedV1Snapshot()
	{
		accept(payload(Collections.singletonList("Water rune pack"),
			Collections.singletonList(12730), Collections.emptyList(), "group-a"));
		assertTrue(collectionReader.hasApiData());

		interopService.onProfileChanged();

		assertFalse(collectionReader.hasApiData());
	}

	private void accept(Map<String, Object> data)
	{
		OsrsTcgInteropService.UpdateResult result = interopService.onPluginMessage(
			new PluginMessage("osrstcg", "owned-names-changed", data));
		assertTrue(result.isAccepted());
	}

	private static Map<String, Object> payload(Object names, Object itemIds,
		Object npcIds, Object groupKey)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("ownedNames", names);
		data.put("ownedItemIds", itemIds);
		data.put("ownedNpcIds", npcIds);
		data.put("groupKey", groupKey);
		return data;
	}

	private static void assertAllowedStatus(CardOwnershipService.Status status,
		CardOwnershipService.Decision decision)
	{
		assertStatus(status, decision);
		assertTrue(decision.isAllowed());
	}

	private static void assertStatus(CardOwnershipService.Status status,
		CardOwnershipService.Decision decision)
	{
		assertEquals(status, decision.getStatus());
	}
}

package com.bronzemantcg;

import com.bronzemantcg.catalog.RecipeCatalog;
import com.bronzemantcg.catalog.HerbloreRecipeStage;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class HerbloreRecipeDataTest
{
	@Test
	public void everyLogicalRecipeHasMatchingInteractionRules()
	{
		JsonArray recipes = loadRecipes();
		Map<String, Map<String, Integer>> signatures = new HashMap<>();
		Map<String, Integer> stageCounts = new HashMap<>();
		Set<String> triggerKeys = new HashSet<>();

		for (JsonElement element : recipes)
		{
			JsonObject recipe = element.getAsJsonObject();
			if (!"herblore".equals(recipe.get("category").getAsString()))
			{
				continue;
			}

			String stage = recipe.get("stage").getAsString();
			String kind = recipe.getAsJsonObject("trigger").get("kind").getAsString();
			stageCounts.merge(stage + "|" + kind, 1, Integer::sum);

			String output = recipe.get("output").isJsonNull()
				? "null" : recipe.get("output").getAsString();
			String signature = stage + "|" + output + "|" + recipe.get("inputs");
			signatures.computeIfAbsent(kind, ignored -> new HashMap<>())
				.merge(signature, 1, Integer::sum);

			JsonObject trigger = recipe.getAsJsonObject("trigger");
			for (JsonElement target : trigger.getAsJsonArray("targets"))
			{
				String key = kind + "|" + trigger.get("name").getAsString().toLowerCase()
					+ "|" + target.getAsString().toLowerCase();
				assertTrue("Duplicate Herblore trigger " + key, triggerKeys.add(key));
			}
		}

		assertEquals(Integer.valueOf(21), stageCounts.get("unfinished|item-on-item"));
		assertEquals(Integer.valueOf(21), stageCounts.get("unfinished|interface"));
		assertEquals(Integer.valueOf(41), stageCounts.get("finished|item-on-item"));
		assertEquals(Integer.valueOf(41), stageCounts.get("finished|interface"));
		assertEquals(Integer.valueOf(20), stageCounts.get("upgrade|item-on-item"));
		assertEquals(Integer.valueOf(20), stageCounts.get("upgrade|interface"));
		assertEquals(signatures.get("item-on-item"), signatures.get("interface"));
	}

	@Test
	public void catalogMatchesRealPotionItemForms()
	{
		RecipeCatalog catalog = new RecipeCatalog(new Gson());

		RecipeCatalog.Recipe unfinished = catalog.find(
			RecipeCatalog.KIND_INTERFACE, "Guam potion (unf)", "Vial of water");
		assertNotNull(unfinished);
		assertEquals(HerbloreRecipeStage.UNFINISHED, unfinished.herbloreStage);

		RecipeCatalog.Recipe finishedInventory = catalog.find(
			RecipeCatalog.KIND_ITEM_ON_ITEM, "Eye of newt", "Guam potion (unf)");
		assertNotNull(finishedInventory);
		assertEquals(HerbloreRecipeStage.FINISHED, finishedInventory.herbloreStage);

		RecipeCatalog.Recipe finishedInterface = catalog.find(
			RecipeCatalog.KIND_INTERFACE, "Attack potion(3)", "Eye of newt");
		assertNotNull(finishedInterface);
		assertEquals(HerbloreRecipeStage.FINISHED, finishedInterface.herbloreStage);

		assertNotNull(catalog.find(
			RecipeCatalog.KIND_INTERFACE, "Toadflax potion (unf)", "Vial of water"));
		assertNotNull(catalog.find(
			RecipeCatalog.KIND_INTERFACE, "Toadflax potion (unf)", "Coconut milk"));
	}

	private static JsonArray loadRecipes()
	{
		InputStream resource = HerbloreRecipeDataTest.class
			.getResourceAsStream("/nodes/recipe_nodes.json");
		assertNotNull(resource);
		return new JsonParser().parse(new InputStreamReader(resource,
			StandardCharsets.UTF_8))
			.getAsJsonObject()
			.getAsJsonArray("recipes");
	}
}

package com.bronzemantcg;

import com.bronzemantcg.catalog.ResourceNodeCatalog;
import com.bronzemantcg.ownership.BundledCardIdentityCatalog;
import com.bronzemantcg.ownership.CardOwnershipService;
import com.bronzemantcg.ownership.CardResolver;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.function.Predicate;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class RunecraftingModePolicyTest
{
	private ResourceNodeCatalog.Rule waterAltar;
	private CardOwnershipService ownershipService;

	@Before
	public void setUp()
	{
		waterAltar = new ResourceNodeCatalog(new Gson()).find(
			ResourceNodeCatalog.KIND_OBJECT, "Altar", "Craft-rune", 34762);
		assertNotNull(waterAltar);
		ownershipService = new CardOwnershipService(
			new CardResolver(new BundledCardIdentityCatalog(new Gson())));
	}

	@Test
	public void genericAltarNameRequiresAnExactObjectId()
	{
		ResourceNodeCatalog catalog = new ResourceNodeCatalog(new Gson());
		assertNull(catalog.find(ResourceNodeCatalog.KIND_OBJECT,
			"Altar", "Craft-rune"));
		assertNotNull(catalog.find(ResourceNodeCatalog.KIND_OBJECT,
			"Altar", "Craft-rune", 29631));
	}

	@Test
	public void runicAltarIdsResolveTheirOwnOutputRune()
	{
		ResourceNodeCatalog catalog = new ResourceNodeCatalog(new Gson());
		assertOutputRune(catalog, 34760, "Air rune");
		assertOutputRune(catalog, 34761, "Mind rune");
		assertOutputRune(catalog, 34762, "Water rune");
		assertOutputRune(catalog, 34763, "Earth rune");
		assertOutputRune(catalog, 34764, "Fire rune");
		assertOutputRune(catalog, 34765, "Body rune");
		assertOutputRune(catalog, 34766, "Cosmic rune");
		assertOutputRune(catalog, 34767, "Law rune");
		assertOutputRune(catalog, 34768, "Nature rune");
		assertOutputRune(catalog, 34769, "Chaos rune");
		assertOutputRune(catalog, 34770, "Death rune");
		assertOutputRune(catalog, 34771, "Astral rune");
		assertOutputRune(catalog, 34772, "Wrath rune");
		assertOutputRune(catalog, 27978, "Blood rune");
		assertOutputRune(catalog, 27980, "Soul rune");
		assertOutputRune(catalog, 43479, "Blood rune");

		ResourceNodeCatalog.Rule ourania = catalog.find(
			ResourceNodeCatalog.KIND_OBJECT, "Altar", "Craft-rune", 29631);
		assertNotNull(ourania);
		assertEquals(Collections.emptyList(),
			ourania.missingRequirementsForRole(Collections.emptySet(), "rune"));
	}

	@Test
	public void waterAcceptsSpecificOrElementalAccessCards()
	{
		assertAccessAllowed(waterAltar, "Water talisman");
		assertAccessAllowed(waterAltar, "Water tiara");
		assertAccessAllowed(waterAltar, "Elemental talisman");
		assertAccessAllowed(waterAltar, "Elemental tiara");
	}

	@Test
	public void catalyticAccessCardsWorkAtCatalyticAltars()
	{
		ResourceNodeCatalog.Rule natureAltar = new ResourceNodeCatalog(new Gson()).find(
			ResourceNodeCatalog.KIND_OBJECT, "Altar", "Craft-rune", 34768);
		assertNotNull(natureAltar);
		assertAccessAllowed(natureAltar, "Nature talisman");
		assertAccessAllowed(natureAltar, "Nature tiara");
		assertAccessAllowed(natureAltar, "Catalytic talisman");
		assertAccessAllowed(natureAltar, "Catalytic tiara");
	}

	@Test
	public void specialAltarsKeepTheirDistinctAccessRules()
	{
		ResourceNodeCatalog catalog = new ResourceNodeCatalog(new Gson());
		for (int objectId : new int[]{29631, 34771, 27978, 27980})
		{
			ResourceNodeCatalog.Rule rule = catalog.find(ResourceNodeCatalog.KIND_OBJECT,
				"Altar", "Craft-rune", objectId);
			assertNotNull(rule);
			assertEquals(Collections.emptyList(),
				rule.missingRequirementsForRole(Collections.emptySet(), "talisman"));
		}

		ResourceNodeCatalog.Rule trueBloodAltar = catalog.find(
			ResourceNodeCatalog.KIND_OBJECT, "Altar", "Craft-rune", 43479);
		assertNotNull(trueBloodAltar);
		assertAccessAllowed(trueBloodAltar, "Blood talisman");
		assertAccessAllowed(trueBloodAltar, "Blood tiara");
		assertAccessAllowed(trueBloodAltar, "Catalytic talisman");
		assertAccessAllowed(trueBloodAltar, "Catalytic tiara");
	}

	@Test
	public void inputOnlyExcludesRuneButInputAndOutputRequiresIt()
	{
		Predicate<String> betaOwnership = ownership(
			TcgOwnershipSnapshot.namesOnly(Set.of(
				"rune essence", "water talisman")));
		assertEquals(Collections.emptyList(), waterAltar.missingRequirements(
			betaOwnership, Collections.singleton("rune"), false));
		assertEquals(Collections.singletonList("Water rune"),
			waterAltar.missingRequirements(betaOwnership, Collections.emptySet(), false));
	}

	@Test
	public void gotrExcludesSuppliedAccessButStillRequiresOutputRune()
	{
		Predicate<String> noOwnership = ownership(
			TcgOwnershipSnapshot.namesOnly(Collections.emptySet()));
		assertEquals(Collections.singletonList("Water rune"),
			waterAltar.missingRequirements(noOwnership,
				Set.of("essence", "talisman"), false));

		Predicate<String> ownsRune = ownership(
			TcgOwnershipSnapshot.namesOnly(Collections.singleton("water rune")));
		assertEquals(Collections.emptyList(), waterAltar.missingRequirements(
			ownsRune, Set.of("essence", "talisman"), false));
	}

	@Test
	public void betaWaterRunePackIdNowGrantsWaterRuneParent()
	{
		TcgOwnershipSnapshot betaPack = TcgOwnershipSnapshot.fromApi(
			Collections.singletonList("Water rune pack"),
			Collections.singletonList(12730), Collections.emptyList(), null);
		assertEquals(Collections.emptyList(),
			waterAltar.missingRequirements(ownership(betaPack),
				Set.of("essence", "talisman"), false));
	}

	private Predicate<String> ownership(TcgOwnershipSnapshot snapshot)
	{
		return card -> ownershipService.decideCard(
			card, snapshot, Collections.emptySet(), Collections.emptySet()).isAllowed();
	}

	private static void assertOutputRune(ResourceNodeCatalog catalog, int objectId,
		String rune)
	{
		ResourceNodeCatalog.Rule rule = catalog.find(ResourceNodeCatalog.KIND_OBJECT,
			"Altar", "Craft-rune", objectId);
		assertNotNull(rule);
		assertEquals(Collections.singletonList(rune),
			rule.missingRequirementsForRole(Collections.emptySet(), "rune"));
	}

	private static void assertAccessAllowed(ResourceNodeCatalog.Rule rule, String accessCard)
	{
		assertEquals(Collections.emptyList(), rule.missingRequirementsForRole(
			Collections.singleton(accessCard.toLowerCase()), "talisman"));
	}
}

package com.bronzemantcg.panel;

