	}

	private static TcgOwnershipSnapshot emptyOwnership()
	{
		return TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), null);
	}

	private static void activate(ActiveCardIdentityCatalog active, CardIdentity... identities)
	{
		List<ImmutableCardIdentityCatalog.Entry> entries = Arrays.stream(identities)
			.map(identity -> new ImmutableCardIdentityCatalog.Entry(
				identity, Set.of(identity.getCardName())))
			.collect(Collectors.toList());
		active.activate(new ImmutableCardIdentityCatalog(entries), entries, "test-v1");
	}

	private static CardIdentity identity(CardEntityKind kind, String name,
		Set<String> legacyNames, Set<Integer> ids)
	{
		return new CardIdentity(kind, name, legacyNames, ids);
	}

	private static PanelCollectionViewModel.Category category(
		PanelCollectionViewModel.State state, String id)
	{
		return state.getSections().stream()
			.flatMap(section -> section.getCategories().stream())
			.filter(category -> category.getId().equals(id))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static PanelCollectionLayout.CollectionCard card(
		PanelCollectionViewModel view, CardEntityKind kind, String name)
	{
		return view.getSearchCards().stream()
			.map(PanelCollectionViewModel.SearchCard::getCard)
			.filter(card -> card.getKind() == kind && card.getCardName().equals(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static PanelCollectionLayout.CollectionCard card(
		PanelCollectionViewModel.State state, CardEntityKind kind, String name)
	{
		return state.getSearchCards().stream()
			.map(PanelCollectionViewModel.SearchCard::getCard)
			.filter(card -> card.getKind() == kind && card.getCardName().equals(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static PanelCollectionLayout.CollectionCard cardById(
		PanelCollectionViewModel.State state, int entityId)
	{
		return state.getSearchCards().stream()
			.map(PanelCollectionViewModel.SearchCard::getCard)
			.filter(card -> card.getEntityIds().contains(entityId))
			.findFirst().orElseThrow(AssertionError::new);
	}
}

package com.bronzemantcg.panel;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PanelNavigationModelTest
{
	@Test
	public void preV1KeepsCollectionHiddenAndOptionalTabsVisible()
	{
		PanelNavigationModel.State state = PanelNavigationModel.resolve(false, true, true);

		assertEquals(Arrays.asList(
			PanelNavigationModel.Tab.ACTIVITIES,
			PanelNavigationModel.Tab.SLAYER_PVM,
			PanelNavigationModel.Tab.RECENT,
			PanelNavigationModel.Tab.BETA,
			PanelNavigationModel.Tab.SHARED), state.getVisibleTabs());
		assertFalse(state.isVisible(PanelNavigationModel.Tab.COLLECTION));
	}

	@Test
	public void v1CapabilityAddsCollectionWithoutRemovingBetaHistory()
	{
		PanelNavigationModel.State state = PanelNavigationModel.resolve(true, true, true);

		assertEquals(Arrays.asList(
			PanelNavigationModel.Tab.ACTIVITIES,
			PanelNavigationModel.Tab.SLAYER_PVM,
			PanelNavigationModel.Tab.COLLECTION,
			PanelNavigationModel.Tab.RECENT,
			PanelNavigationModel.Tab.BETA,
			PanelNavigationModel.Tab.SHARED), state.getVisibleTabs());
	}

	@Test
	public void optionalTabsCanBeHiddenIndependently()
	{
		PanelNavigationModel.State state = PanelNavigationModel.resolve(false, false, false);

		assertFalse(state.isVisible(PanelNavigationModel.Tab.SHARED));
		assertFalse(state.isVisible(PanelNavigationModel.Tab.BETA));
		assertEquals(Arrays.asList(
			PanelNavigationModel.Tab.ACTIVITIES,
			PanelNavigationModel.Tab.SLAYER_PVM,
			PanelNavigationModel.Tab.RECENT), state.getVisibleTabs());
	}

	@Test
	public void hiddenBetaUsesCollectionOnlyWhenV1Capable()
	{
		PanelNavigationModel.State preV1 = PanelNavigationModel.resolve(false, true, false);
		PanelNavigationModel.State v1 = PanelNavigationModel.resolve(true, true, false);

		assertEquals(PanelNavigationModel.Tab.ACTIVITIES,
			preV1.selectionAfterHiding(PanelNavigationModel.Tab.BETA));
		assertEquals(PanelNavigationModel.Tab.COLLECTION,
			v1.selectionAfterHiding(PanelNavigationModel.Tab.BETA));
	}

	@Test
	public void capabilityLossUsesBetaWhenAvailableOtherwiseActivities()
	{
		PanelNavigationModel.State withBeta = PanelNavigationModel.resolve(false, true, true);
		PanelNavigationModel.State withoutBeta = PanelNavigationModel.resolve(false, true, false);

		assertEquals(PanelNavigationModel.Tab.BETA,
			withBeta.selectionAfterHiding(PanelNavigationModel.Tab.COLLECTION));
		assertEquals(PanelNavigationModel.Tab.ACTIVITIES,
			withoutBeta.selectionAfterHiding(PanelNavigationModel.Tab.COLLECTION));
		assertTrue(withBeta.isVisible(PanelNavigationModel.Tab.BETA));
	}

	@Test
	public void hiddenSharedAlwaysReturnsToActivities()
	{
		PanelNavigationModel.State state = PanelNavigationModel.resolve(true, false, true);

		assertEquals(PanelNavigationModel.Tab.ACTIVITIES,
			state.selectionAfterHiding(PanelNavigationModel.Tab.SHARED));
	}

	@Test
	public void preV1RowsKeepSharedFullWidth()
	{
		assertEquals(Arrays.asList(
			Arrays.asList(PanelNavigationModel.Tab.ACTIVITIES,
				PanelNavigationModel.Tab.SLAYER_PVM),
			Arrays.asList(PanelNavigationModel.Tab.RECENT,
				PanelNavigationModel.Tab.BETA),
			Arrays.asList(PanelNavigationModel.Tab.SHARED)),
			PanelNavigationModel.resolve(false, true, true).getRows());
		assertEquals(Arrays.asList(
			Arrays.asList(PanelNavigationModel.Tab.ACTIVITIES,
				PanelNavigationModel.Tab.SLAYER_PVM),
			Arrays.asList(PanelNavigationModel.Tab.RECENT),
			Arrays.asList(PanelNavigationModel.Tab.SHARED)),
			PanelNavigationModel.resolve(false, true, false).getRows());
	}

	@Test
	public void v1RowsUseApprovedPositionsForEveryOptionalCombination()
	{
		assertEquals(Arrays.asList(
			Arrays.asList(PanelNavigationModel.Tab.ACTIVITIES,
				PanelNavigationModel.Tab.SLAYER_PVM),
			Arrays.asList(PanelNavigationModel.Tab.COLLECTION,
				PanelNavigationModel.Tab.RECENT),
			Arrays.asList(PanelNavigationModel.Tab.BETA,
				PanelNavigationModel.Tab.SHARED)),
			PanelNavigationModel.resolve(true, true, true).getRows());
		assertEquals(Arrays.asList(
			Arrays.asList(PanelNavigationModel.Tab.ACTIVITIES,
				PanelNavigationModel.Tab.SLAYER_PVM),
			Arrays.asList(PanelNavigationModel.Tab.RECENT,
				PanelNavigationModel.Tab.BETA),
			Arrays.asList(PanelNavigationModel.Tab.COLLECTION)),
			PanelNavigationModel.resolve(true, false, true).getRows());
		assertEquals(Arrays.asList(
			Arrays.asList(PanelNavigationModel.Tab.ACTIVITIES,
				PanelNavigationModel.Tab.SLAYER_PVM),
			Arrays.asList(PanelNavigationModel.Tab.COLLECTION,
				PanelNavigationModel.Tab.RECENT),
			Arrays.asList(PanelNavigationModel.Tab.SHARED)),
			PanelNavigationModel.resolve(true, true, false).getRows());
		assertEquals(Arrays.asList(
			Arrays.asList(PanelNavigationModel.Tab.ACTIVITIES,
				PanelNavigationModel.Tab.SLAYER_PVM),
			Arrays.asList(PanelNavigationModel.Tab.COLLECTION,
				PanelNavigationModel.Tab.RECENT)),
			PanelNavigationModel.resolve(true, false, false).getRows());
	}

	@Test
	public void everyVisibilityCombinationPlacesEachVisibleTabOnce()
	{
		for (boolean v1Capable : Arrays.asList(false, true))
		{
			for (boolean sharedEnabled : Arrays.asList(false, true))
			{
				for (boolean showBeta : Arrays.asList(false, true))
				{
					PanelNavigationModel.State state = PanelNavigationModel.resolve(
						v1Capable, sharedEnabled, showBeta);
					List<PanelNavigationModel.Tab> flattened = new ArrayList<>();
					for (List<PanelNavigationModel.Tab> row : state.getRows())
					{
						assertTrue(row.size() == 1 || row.size() == 2);
						flattened.addAll(row);
					}
					assertEquals(state.getVisibleTabs().size(),
						new HashSet<>(flattened).size());
					assertEquals(new HashSet<>(state.getVisibleTabs()),
						new HashSet<>(flattened));
				}
			}
		}
	}
}

package com.bronzemantcg.panel;

import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class BronzemanTcgPanelSearchLayoutTest
{
	@Test
	public void resultHeightCollapsesAndStopsGrowingAfterTenRows()
	{
		JPanel results = new JPanel();
		assertEquals(0, BronzemanTcgPanel.visibleSearchResultsHeight(results, 10));

		addRows(results, 3, 20);
		assertEquals(60, BronzemanTcgPanel.visibleSearchResultsHeight(results, 10));

		addRows(results, 7, 20);
		assertEquals(200, BronzemanTcgPanel.visibleSearchResultsHeight(results, 10));

		addRows(results, 2, 20);
		assertEquals(200, BronzemanTcgPanel.visibleSearchResultsHeight(results, 10));
	}

	@Test
	public void invalidVisibleRowLimitCollapsesResults()
	{
		JPanel results = new JPanel();
		addRows(results, 1, 20);

		assertEquals(0, BronzemanTcgPanel.visibleSearchResultsHeight(results, 0));
		assertEquals(0, BronzemanTcgPanel.visibleSearchResultsHeight(results, -1));
		assertEquals(0, BronzemanTcgPanel.visibleSearchResultsHeight(null, 10));
	}

	@Test
	public void resultPaneUsesBoundedVerticalScrollingOnly()
	{
		JPanel results = new JPanel();
		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		addRows(results, 12, 20);
		JScrollPane scroll = new BronzemanTcgPanel.SearchResultsScrollPane(results, 10);
		scroll.setBorder(null);

		assertEquals(200, scroll.getPreferredSize().height);
		assertEquals(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
			scroll.getVerticalScrollBarPolicy());
		assertEquals(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER,
			scroll.getHorizontalScrollBarPolicy());
	}

	private static void addRows(JPanel results, int count, int height)
	{
		for (int i = 0; i < count; i++)
		{
			JPanel row = new JPanel();
			row.setPreferredSize(new Dimension(100, height));
			results.add(row);
		}
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.util.CacheFiles;
import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class RecentUnlocksCacheStoreTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void storesBothHistoriesUnderOnlyAHashedProfileFilename() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		RecentUnlocksCacheStore store = new RecentUnlocksCacheStore(new Gson(), directory);
		String profile = "rsprofile.player-name";

		store.save(profile,
			List.of(new RecentUnlocksTracker.Unlock(" Dragon Axe ", 20L)),
			List.of(new RecentUnlocksTracker.Unlock("Rune Axe", 10L, true)));

		Path expected = directory.resolve(CacheFiles.sha256Hex(profile) + ".json");
		assertTrue(Files.exists(expected));
		assertFalse(expected.getFileName().toString().contains("player"));
		String json = Files.readString(expected, StandardCharsets.UTF_8);
		assertTrue(json.contains("\"schemaVersion\":1"));
		assertFalse(json.contains(profile));

		RecentUnlocksCacheStore.Record loaded = store.load(profile);
		assertHistory(loaded.getPersonal(), "dragon axe", 20L, false);
		assertHistory(loaded.getShared(), "rune axe", 10L, true);
	}

	@Test
	public void profileFilesAreIsolatedAndAtomicReplacementLeavesNoTemporaryFile() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		RecentUnlocksCacheStore store = new RecentUnlocksCacheStore(new Gson(), directory);
		store.save("profile-a", List.of(
			new RecentUnlocksTracker.Unlock("dragon axe", 20L)), Collections.emptyList());
		store.save("profile-b", List.of(
			new RecentUnlocksTracker.Unlock("rune axe", 10L)), Collections.emptyList());
		store.save("profile-a", List.of(
			new RecentUnlocksTracker.Unlock("abyssal whip", 30L)), Collections.emptyList());

		assertFalse(store.fileForProfile("profile-a").equals(store.fileForProfile("profile-b")));
		assertHistory(store.load("profile-a").getPersonal(), "abyssal whip", 30L, false);
		assertHistory(store.load("profile-b").getPersonal(), "rune axe", 10L, false);
		try (java.util.stream.Stream<Path> files = Files.list(directory))
		{
			assertEquals(2L, files.count());
		}
	}

	@Test
	public void rejectsMalformedOversizedAndIncompleteCacheFiles() throws Exception
	{
		RecentUnlocksCacheStore store = new RecentUnlocksCacheStore(new Gson(),
			temporaryFolder.newFolder().toPath());
		Files.createDirectories(store.fileForProfile("profile").getParent());

		Files.writeString(store.fileForProfile("profile"), "{broken", StandardCharsets.UTF_8);
		assertThrows(Exception.class, () -> store.load("profile"));

		Files.writeString(store.fileForProfile("profile"),
			"{\"schemaVersion\":1,\"personal\":[]}", StandardCharsets.UTF_8);
		assertThrows(Exception.class, () -> store.load("profile"));

		Files.write(store.fileForProfile("profile"), new byte[256 * 1024 + 1]);
		assertThrows(Exception.class, () -> store.load("profile"));
	}

	@Test
	public void rejectsInvalidOrOversizedHistoriesBeforeWriting() throws Exception
	{
		RecentUnlocksCacheStore store = new RecentUnlocksCacheStore(new Gson(),
			temporaryFolder.newFolder().toPath());
		assertThrows(Exception.class, () -> store.save("null-name",
			List.of(new RecentUnlocksTracker.Unlock(null, 1L)), Collections.emptyList()));
		assertThrows(Exception.class, () -> store.save("control-name",
			List.of(new RecentUnlocksTracker.Unlock("bad\nname", 1L)), Collections.emptyList()));
		assertThrows(Exception.class, () -> store.save("negative-time",
			List.of(new RecentUnlocksTracker.Unlock("dragon axe", -1L)), Collections.emptyList()));
		assertThrows(Exception.class, () -> store.save("wrong-kind",
			List.of(new RecentUnlocksTracker.Unlock("dragon axe", 1L, true)),
			Collections.emptyList()));

		List<RecentUnlocksTracker.Unlock> tooMany = new ArrayList<>();
		for (int i = 0; i <= RecentUnlocksCacheStore.MAX_RECENT; i++)
		{
			tooMany.add(new RecentUnlocksTracker.Unlock("card " + i, i));
		}
		assertThrows(Exception.class, () -> store.save("too-many", tooMany,
			Collections.emptyList()));
		assertFalse(Files.exists(store.fileForProfile("too-many")));
	}

	private static void assertHistory(List<RecentUnlocksTracker.Unlock> history,
		String name, long time, boolean shared)
	{
		assertEquals(1, history.size());
		assertEquals(name, history.get(0).name);
		assertEquals(time, history.get(0).time);
		assertEquals(shared, history.get(0).shared);
	}
}

