		PanelPresentationCatalog.Data v1 = catalog.select(true);

		assertEquals(6, beta.getRumourRules().size());
		assertEquals(6, v1.getRumourRules().size());
		List<String> betaAco = ruleCards(rule(beta.getRumourRules(), "Guild Hunter Aco"));
		List<String> v1Aco = ruleCards(rule(v1.getRumourRules(), "Guild Hunter Aco"));
		assertTrue(betaAco.contains("Dark kebbit"));
		assertTrue(betaAco.contains("Sunlight antelope"));
		assertFalse(betaAco.contains("Kebbity tuft"));
		assertTrue(v1Aco.contains("Kebbity tuft"));
		assertTrue(v1Aco.contains("Antelope hoof shard"));
		assertFalse(v1Aco.contains("Dark kebbit"));
	}

	@Test
	public void slayerKeepsCurrentRowsAndOverridesAchtrynOnly()
	{
		PanelPresentationCatalog.Data beta = catalog.select(false);
		PanelPresentationCatalog.Data v1 = catalog.select(true);

		assertEquals(13, beta.getSlayerRules().size());
		assertEquals(13, v1.getSlayerRules().size());
		assertTrue(ruleCards(rule(beta.getSlayerRules(), "Achtryn")).contains("Achtryn"));
		assertFalse(ruleCards(rule(v1.getSlayerRules(), "Achtryn")).contains("Achtryn"));
		assertEquals(ruleCards(rule(beta.getSlayerRules(), "Vannaka")),
			ruleCards(rule(v1.getSlayerRules(), "Vannaka")));
	}

	private static List<String> cards(List<PanelPresentationCatalog.Checklist> rows,
		String name)
	{
		return rows.stream().filter(row -> row.name.equals(name)).findFirst()
			.orElseThrow(AssertionError::new).cards;
	}

	private static List<String> ruleCards(PanelPresentationCatalog.Rule rule)
	{
		return rule.groups.stream().flatMap(group -> group.displayCards.stream())
			.collect(Collectors.toList());
	}

	private static PanelPresentationCatalog.Rule rule(
		java.util.Map<String, PanelPresentationCatalog.Rule> rules, String name)
	{
		return rules.entrySet().stream()
			.filter(entry -> entry.getKey().equalsIgnoreCase(name))
			.map(java.util.Map.Entry::getValue).findFirst()
			.orElseThrow(AssertionError::new);
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.LiveV1CatalogTestSupport;
import com.bronzemantcg.catalog.QuestCatalog;
import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.ownership.BundledCardIdentityCatalog;
import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class QuestV1PresentationTest
{
	private final Gson gson = new Gson();
	private final QuestCatalog source = new QuestCatalog(gson);
	private final ActiveCardIdentityCatalog active = new ActiveCardIdentityCatalog(
		new BundledCardIdentityCatalog(gson));
	private final QuestV1Presentation presentation = new QuestV1Presentation(active);

	@Before
	public void activateMaintainedV1Capture()
	{
		LiveV1CatalogTestSupport.activate(active);
	}

	@Test
	public void canonicalizesDisplayAndAcceptsBothParentAndLegacyNames()
	{
		QuestV1Presentation.Data projected = presentation.project(source);
		QuestCatalog.Requirement zombie = requirement(
			quest(projected.getQuests(), "Defender of Varrock"),
			"Armoured zombie");

		assertEquals(List.of("Armoured zombie"), zombie.displayCards);
		assertTrue(zombie.isSatisfied(Set.of("armoured zombie")));
		assertTrue(zombie.isSatisfied(
			Set.of("armoured zombie (defender of varrock)")));
		assertEquals("enemy", zombie.type);
	}

	@Test
	public void canonicalSourceNeedsNoRetiredAlternativeProjection()
	{
		QuestV1Presentation.Data projected = presentation.project(source);
		QuestCatalog.QuestEntry digSite = quest(projected.getQuests(), "The Dig Site");
		QuestCatalog.QuestEntry wartface = quest(projected.getQuests(),
			"RFD - Wartface & Bentnoze");

		assertFalse(hasRequirement(digSite, "Cup of tea"));
		assertEquals(List.of("Blue dye", "Green dye", "Purple dye"),
			requirement(wartface, "Dye").displayCards);
		assertFalse(hasRequirement(quest(source.getQuests(), "The Dig Site"),
			"Cup of tea"));
		assertEquals(List.of("Armoured zombie"),
			requirement(quest(source.getQuests(), "Defender of Varrock"),
				"Armoured zombie").displayCards);
	}

	@Test
	public void preservesNestedTypesAndQuestRouteSelection()
	{
		QuestV1Presentation.Data projected = presentation.project(source);
		QuestCatalog.Requirement nestedAxe = requirement(
			quest(projected.getQuests(), "RFD - Sir Amik Varze"), "Any axe");
		assertEquals("item", nestedAxe.type);

		QuestCatalog.Requirement shieldRoute = requirement(
			quest(projected.getQuests(), "Shield of Arrav"),
			"Your Shield of Arrav gang route");
		assertTrue(shieldRoute.isSatisfied(Set.of("coins", "jonny the beard"),
			QuestCatalog.RouteSelection.PHOENIX));
		assertFalse(shieldRoute.isSatisfied(Set.of("coins", "jonny the beard"),
			QuestCatalog.RouteSelection.BLACK_ARM));
	}

	@Test
	public void typedNpcResolvesByKindWhileAmbiguousUntypedIdentityFailsOpen()
	{
		List<ImmutableCardIdentityCatalog.Entry> entries = Arrays.asList(
			entry(CardEntityKind.ITEM, "Icefiend item", "Icefiend", 1),
			entry(CardEntityKind.NPC, "Icefiend npc", "Icefiend", 2),
			entry(CardEntityKind.ITEM, "Guard item", "Guard", 3),
			entry(CardEntityKind.NPC, "Guard npc", "Guard", 4));
		ImmutableCardIdentityCatalog ambiguous = new ImmutableCardIdentityCatalog(entries);
		long revision = active.activate(ambiguous, entries, "ambiguous-test");

		QuestV1Presentation.Data projected = presentation.project(source);
		assertEquals(revision, projected.getRevision());
		assertFalse(hasRequirement(quest(projected.getQuests(), "RFD - Mountain Dwarf"),
			"Icefiend - For Rock Cake"));
		QuestCatalog.Requirement guard = requirement(
			quest(projected.getQuests(), "Children of the Sun"),
			"Guard (marked during the quest)");
		assertEquals("npc", guard.type);
		assertEquals(List.of("Guard npc"), guard.displayCards);
	}

	@Test
	public void mergedQuestAlternativesRemainTrackedAtMaintainedRevision()
	{
		QuestV1Presentation.Data projected = presentation.project(source);
		QuestCatalog.Requirement seeds = requirement(
			quest(projected.getMiniquests(), "Barbarian Training"), "Any Herb Seed");
		assertTrue(seeds.displayCards.contains("Cadantine seed"));
		assertTrue(seeds.displayCards.contains("Snapdragon seed"));
		assertFalse(seeds.displayCards.contains("Potato seed"));

		QuestCatalog.Requirement bars = requirement(
			quest(projected.getMiniquests(), "Barbarian Training"), "Two metal bars");
		assertTrue(bars.displayCards.contains("Adamantite bar"));
		assertTrue(bars.displayCards.contains("Runite bar"));

		assertTrue(hasRequirement(quest(projected.getMiniquests(), "Daddy's Home"),
			"Any nails"));
		assertTrue(hasRequirement(quest(projected.getMiniquests(), "Mage Arena I"),
			"Knife or slash weapon"));
		assertEquals(List.of("Oziach"), requirement(
			quest(projected.getQuests(), "Dragon Slayer I"), "Oziach").displayCards);
		assertEquals(List.of("Kolodion"), requirement(
			quest(projected.getMiniquests(), "Mage Arena I"), "Kolodion").displayCards);
		QuestCatalog.Requirement gertrude = requirement(
			quest(projected.getQuests(), "A Ruff Situation"), "Gertrude");
		assertEquals("npc", gertrude.type);
		assertEquals(List.of("Gertrude"), gertrude.displayCards);
	}

	private static ImmutableCardIdentityCatalog.Entry entry(CardEntityKind kind,
		String parent, String legacyName, int id)
	{
		CardIdentity identity = new CardIdentity(kind, parent,
			Set.of(legacyName), Set.of(id));
		return new ImmutableCardIdentityCatalog.Entry(identity, Set.of(parent));
	}

	private static QuestCatalog.QuestEntry quest(
		List<QuestCatalog.QuestEntry> entries, String name)
	{
		return entries.stream().filter(entry -> name.equals(entry.name))
			.findFirst().orElseThrow(() -> new AssertionError("Missing quest " + name));
	}

	private static boolean hasRequirement(QuestCatalog.QuestEntry entry, String label)
	{
		for (QuestCatalog.Requirement requirement : entry.requirements)
		{
			if (find(requirement, label) != null)
			{
				return true;
			}
		}
		return false;
	}

	private static QuestCatalog.Requirement requirement(
		QuestCatalog.QuestEntry entry, String label)
	{
		for (QuestCatalog.Requirement requirement : entry.requirements)
		{
			QuestCatalog.Requirement match = find(requirement, label);
			if (match != null)
			{
				return match;
			}
		}
		throw new AssertionError("Missing requirement " + label + " in " + entry.name);
	}

	private static QuestCatalog.Requirement find(
		QuestCatalog.Requirement requirement, String label)
	{
		if (label.equals(requirement.label))
		{
			return requirement;
		}
		for (QuestCatalog.Requirement child : requirement.children)
		{
			QuestCatalog.Requirement match = find(child, label);
			if (match != null)
			{
				return match;
			}
		}
		return null;
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.catalog.QuestCatalog;
import com.google.gson.Gson;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class QuestListPresentationTest
{
	private final QuestCatalog source = new QuestCatalog(new Gson());

	@Test
	public void removesNpcAndEnemyRequirementsWithoutMutatingSource()
	{
		List<QuestCatalog.QuestEntry> filtered =
			QuestListPresentation.hideNpcRequirements(source.getQuests());

		assertNoNpcRequirements(filtered);
		QuestCatalog.QuestEntry original = quest(source.getQuests(), "Defender of Varrock");
		QuestCatalog.QuestEntry projected = quest(filtered, "Defender of Varrock");
		assertTrue(projected.requirements.size() < original.requirements.size());
		assertNotNull(requirement(original, "Armoured zombie"));
		assertFalse(hasRequirement(projected, "Armoured zombie"));
	}

	@Test
	public void routedNpcOnlyPathBecomesSatisfiedWhileItemPathRemainsRequired()
	{
		QuestCatalog.Requirement original = requirement(
			quest(source.getQuests(), "Shield of Arrav"),
			"Your Shield of Arrav gang route");
		QuestCatalog.Requirement filtered = requirement(quest(
			QuestListPresentation.hideNpcRequirements(source.getQuests()),
			"Shield of Arrav"), "Your Shield of Arrav gang route");

		assertFalse(original.isSatisfied(Set.of(), QuestCatalog.RouteSelection.BLACK_ARM));
		assertTrue(filtered.isSatisfied(Set.of(), QuestCatalog.RouteSelection.BLACK_ARM));
		assertFalse(filtered.isSatisfied(Set.of(), QuestCatalog.RouteSelection.PHOENIX));
		assertTrue(filtered.isSatisfied(Set.of("coins"), QuestCatalog.RouteSelection.PHOENIX));
		assertFalse(hasRequirement(filtered, "Weaponsmaster"));
		assertFalse(hasRequirement(filtered, "Charlie the Tramp"));
		assertFalse(hasRequirement(filtered, "Jonny the Beard"));
		assertTrue(hasRequirement(filtered, "Coins"));
	}

	@Test
	public void appliesToMiniquestsAndDropsEmptyNpcSections()
	{
		List<QuestCatalog.QuestEntry> filtered =
			QuestListPresentation.hideNpcRequirements(source.getMiniquests());

		assertNoNpcRequirements(filtered);
		QuestCatalog.QuestEntry mageArena = quest(filtered, "Mage Arena I");
		assertFalse(hasRequirement(mageArena, "Kolodion"));
		assertFalse(mageArena.sections.stream().anyMatch(section ->
			"NPCs".equalsIgnoreCase(section.label) || "Enemies".equalsIgnoreCase(section.label)));
	}

	private static void assertNoNpcRequirements(List<QuestCatalog.QuestEntry> entries)
	{
		for (QuestCatalog.QuestEntry entry : entries)
		{
			for (QuestCatalog.Requirement requirement : entry.requirements)
			{
				assertNoNpcRequirements(requirement);
			}
		}
	}

	private static void assertNoNpcRequirements(QuestCatalog.Requirement requirement)
	{
		assertFalse(requirement.type, QuestListPresentation.isNpcRequirement(requirement));
		for (QuestCatalog.Requirement child : requirement.children)
		{
			assertNoNpcRequirements(child);
		}
	}

	private static QuestCatalog.QuestEntry quest(
		List<QuestCatalog.QuestEntry> entries, String name)
	{
		return entries.stream().filter(entry -> name.equals(entry.name))
			.findFirst().orElseThrow(() -> new AssertionError("Missing quest " + name));
	}

	private static boolean hasRequirement(QuestCatalog.QuestEntry entry, String label)
	{
		for (QuestCatalog.Requirement requirement : entry.requirements)
		{
			if (hasRequirement(requirement, label))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean hasRequirement(QuestCatalog.Requirement requirement, String label)
	{
		if (label.equals(requirement.label))
		{
			return true;
		}
		for (QuestCatalog.Requirement child : requirement.children)
		{
			if (hasRequirement(child, label))
			{
				return true;
			}
		}
		return false;
	}

	private static QuestCatalog.Requirement requirement(
		QuestCatalog.QuestEntry entry, String label)
	{
		for (QuestCatalog.Requirement requirement : entry.requirements)
		{
			QuestCatalog.Requirement match = requirement(requirement, label);
			if (match != null)
			{
				return match;
			}
		}
		throw new AssertionError("Missing requirement " + label + " in " + entry.name);
	}

	private static QuestCatalog.Requirement requirement(
		QuestCatalog.Requirement requirement, String label)
	{
		if (label.equals(requirement.label))
		{
			return requirement;
		}
		for (QuestCatalog.Requirement child : requirement.children)
		{
			QuestCatalog.Requirement match = requirement(child, label);
			if (match != null)
			{
				return match;
			}
		}
		return null;
	}
}

package com.bronzemantcg.panel;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class RecentUnlocksTrackerTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void recentDiffIgnoresBaselineSeenAndReconnects()
	{
		Set<String> baseline = set("dragon axe");
		Set<String> seen = set("dragon axe", "rune axe");
		assertEquals(Collections.singletonList("abyssal whip"),
			RecentUnlocksTracker.newSharedNames(
				set("dragon axe", "rune axe", "abyssal whip"), baseline, seen));
		assertTrue(RecentUnlocksTracker.newSharedNames(
			set("dragon axe", "rune axe"), Collections.emptySet(), seen).isEmpty());
	}

	@Test
	public void reloadMigratesBothLegacyHistoriesThenRemovesTheirKeys() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-one");
		profiles.put("recentUnlocks", gson.toJson(List.of(
			new RecentUnlocksTracker.Unlock("dragon axe", 20L))));
		profiles.put("recentSharedUnlocks", gson.toJson(List.of(
			new RecentUnlocksTracker.Unlock("rune axe", 10L, true))));
		RecentUnlocksCacheStore store = store(gson);
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson, store);

		tracker.reload();

		assertNull(profiles.get("recentUnlocks"));
		assertNull(profiles.get("recentSharedUnlocks"));
		assertTrue(Files.exists(store.fileForProfile("profile-one")));
		assertHistory(tracker.getRecent(), "dragon axe", 20L, false);
		assertHistory(tracker.getSharedRecent(), "rune axe", 10L, true);

		RecentUnlocksTracker reloaded = new RecentUnlocksTracker(profiles, gson, store);
		reloaded.reload();
		assertHistory(reloaded.getRecent(), "dragon axe", 20L, false);
		assertHistory(reloaded.getSharedRecent(), "rune axe", 10L, true);
	}

	@Test
	public void migrationMergesByNormalizedNameAndKeepsNewestTimestamp() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-one");
		RecentUnlocksCacheStore store = store(gson);
		store.save("profile-one", List.of(
			new RecentUnlocksTracker.Unlock("dragon axe", 20L),
			new RecentUnlocksTracker.Unlock("rune axe", 5L)), Collections.emptyList());
		profiles.put("recentUnlocks", gson.toJson(List.of(
			new RecentUnlocksTracker.Unlock(" Dragon Axe ", 30L),
			new RecentUnlocksTracker.Unlock("abyssal whip", 10L))));
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson, store);

		tracker.reload();

		List<RecentUnlocksTracker.Unlock> merged = tracker.getRecent();
		assertEquals(3, merged.size());
		assertUnlock(merged.get(0), "dragon axe", 30L, false);
		assertUnlock(merged.get(1), "abyssal whip", 10L, false);
		assertUnlock(merged.get(2), "rune axe", 5L, false);
		assertNull(profiles.get("recentUnlocks"));
		assertTrue(RecentUnlocksTracker.sameHistory(
			merged, store.load("profile-one").getPersonal()));
	}

	@Test
	public void invalidLegacyHistoryKeepsBothLegacyValuesAndExistingCache() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-one");
		String invalidPersonal = "{broken";
		String validShared = gson.toJson(List.of(
			new RecentUnlocksTracker.Unlock("rune axe", 10L, true)));
		profiles.put("recentUnlocks", invalidPersonal);
		profiles.put("recentSharedUnlocks", validShared);
		RecentUnlocksCacheStore store = store(gson);
		store.save("profile-one", List.of(
			new RecentUnlocksTracker.Unlock("dragon axe", 20L)), Collections.emptyList());
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson, store);

		tracker.reload();

		assertEquals(invalidPersonal, profiles.get("recentUnlocks"));
		assertEquals(validShared, profiles.get("recentSharedUnlocks"));
		assertHistory(tracker.getRecent(), "dragon axe", 20L, false);
		assertHistory(tracker.getSharedRecent(), "rune axe", 10L, true);
		assertHistory(store.load("profile-one").getPersonal(), "dragon axe", 20L, false);
		assertTrue(store.load("profile-one").getShared().isEmpty());
	}

	@Test
	public void failedCacheWriteKeepsTheValidLegacyValue() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-one");
		String legacy = gson.toJson(List.of(
			new RecentUnlocksTracker.Unlock("dragon axe", 20L)));
		profiles.put("recentUnlocks", legacy);
		Path nonDirectory = temporaryFolder.newFile().toPath();
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson,
			new RecentUnlocksCacheStore(gson, nonDirectory));

		tracker.reload();

		assertEquals(legacy, profiles.get("recentUnlocks"));
		assertHistory(tracker.getRecent(), "dragon axe", 20L, false);
	}

	@Test
	public void profileChangeAfterReadbackKeepsLegacyValue() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-one");
		String legacy = gson.toJson(List.of(
			new RecentUnlocksTracker.Unlock("dragon axe", 20L)));
		profiles.put("recentUnlocks", legacy);
		profiles.switchProfileOnCurrentCall(3, "profile-two");
		RecentUnlocksCacheStore store = store(gson);
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson, store);

		tracker.reload();

		assertEquals("profile-two", profiles.currentProfileKey());
		assertEquals(legacy, profiles.get("profile-one", "recentUnlocks"));
		assertTrue(Files.exists(store.fileForProfile("profile-one")));
	}

	@Test
	public void laterUnlocksWriteOnlyToTheLocalCache() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-one");
		RecentUnlocksCacheStore store = store(gson);
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson, store);
		tracker.reload();
		tracker.update(set("dragon axe"), true);

		assertTrue(tracker.update(set("dragon axe", "rune axe"), true));

		assertNull(profiles.get("recentUnlocks"));
		assertHistory(store.load("profile-one").getPersonal(), "rune axe",
			tracker.getRecent().get(0).time, false);
	}

	@Test
	public void profileAtoBtoAKeepsHistoriesIsolated() throws Exception
	{
		Gson gson = new Gson();
		TestProfileAccess profiles = new TestProfileAccess("profile-a");
		RecentUnlocksCacheStore store = store(gson);
		RecentUnlocksTracker tracker = new RecentUnlocksTracker(profiles, gson, store);

		tracker.reload();
		tracker.update(set("dragon axe"), true);
		assertTrue(tracker.update(set("dragon axe", "rune axe"), true));

		profiles.setProfile("profile-b");
		tracker.reload();
		tracker.update(set("abyssal whip"), true);
		assertTrue(tracker.update(set("abyssal whip", "dragon scimitar"), true));
		assertEquals("dragon scimitar", tracker.getRecent().get(0).name);

		profiles.setProfile("profile-a");
		tracker.reload();
		assertEquals("rune axe", tracker.getRecent().get(0).name);
		assertFalse(store.fileForProfile("profile-a").equals(store.fileForProfile("profile-b")));
	}

	private RecentUnlocksCacheStore store(Gson gson) throws Exception
	{
		return new RecentUnlocksCacheStore(gson, temporaryFolder.newFolder().toPath());
	}

	private static void assertHistory(List<RecentUnlocksTracker.Unlock> history,
		String name, long time, boolean shared)
	{
		assertEquals(1, history.size());
		assertUnlock(history.get(0), name, time, shared);
	}

	private static void assertUnlock(RecentUnlocksTracker.Unlock unlock,
		String name, long time, boolean shared)
	{
		assertEquals(name, unlock.name);
		assertEquals(time, unlock.time);
		assertEquals(shared, unlock.shared);
	}

	private static Set<String> set(String... values)
	{
		return new HashSet<>(Arrays.asList(values));
	}

	private static final class TestProfileAccess implements RecentUnlocksTracker.ProfileAccess
	{
		private final Map<String, Map<String, String>> values = new HashMap<>();
		private String profile;
		private int currentCalls;
		private int switchOnCall = -1;
		private String switchTo;

		private TestProfileAccess(String profile)
		{
			this.profile = profile;
		}

		@Override
		public String currentProfileKey()
		{
			currentCalls++;
			if (currentCalls == switchOnCall)
			{
				profile = switchTo;
			}
			return profile;
		}

		@Override
		public String loadConfiguration(String activeProfile, String key)
		{
			return values.getOrDefault(activeProfile, Collections.emptyMap()).get(key);
		}

		@Override
		public void unsetConfiguration(String activeProfile, String key)
		{
			values.computeIfAbsent(activeProfile, ignored -> new HashMap<>()).remove(key);
		}

		private void put(String key, String value)
		{
			values.computeIfAbsent(profile, ignored -> new HashMap<>()).put(key, value);
		}

		private String get(String key)
		{
			return loadConfiguration(profile, key);
		}

		private String get(String activeProfile, String key)
		{
			return loadConfiguration(activeProfile, key);
		}

		private void setProfile(String profile)
		{
			this.profile = profile;
			currentCalls = 0;
			switchOnCall = -1;
			switchTo = null;
		}

		private void switchProfileOnCurrentCall(int call, String profile)
		{
			switchOnCall = call;
			switchTo = profile;
		}
	}
}

