import java.util.Locale;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class CardResolverTest
{
	private CardIdentity item;
	private CardIdentity npc;
	private SyntheticCatalog catalog;
	private CardResolver resolver;

	@Before
	public void setUp()
	{
		item = identity(CardEntityKind.ITEM, "Test item", 100, 101, 102);
		npc = identity(CardEntityKind.NPC, "Test creature", 100, 103);
		catalog = new SyntheticCatalog()
			.add(item, "Test item", "Test item (charged)")
			.add(npc, "Test creature");
		resolver = new CardResolver(catalog);
	}

	@Test
	public void primaryAndVariantIdsResolveToOneParentIdentity()
	{
		assertTracked(CardEntityKind.ITEM, 100, "Test item", item);
		assertTracked(CardEntityKind.ITEM, 102, "Test item (2)", item);
	}

	@Test
	public void equalNumericIdsRemainSeparatedByKind()
	{
		assertTracked(CardEntityKind.ITEM, 100, "Test item", item);
		assertTracked(CardEntityKind.NPC, 100, "Test creature", npc);
	}

	@Test
	public void missingIdUsesReviewedNameAlias()
	{
		assertTracked(CardEntityKind.ITEM, -1, "Test item (charged)", item);
	}

	@Test
	public void unknownIdUnderKnownNameIsCatalogueMismatch()
	{
		CardResolver.Result result = resolver.resolve(CardEntityKind.ITEM, 999, "Test item");
		assertEquals(CardResolver.Status.CATALOG_MISMATCH, result.getStatus());
		assertFalse(result.isTracked());
		assertNull(result.getIdentity());
	}

	@Test
	public void unknownIdAndNameAreUntracked()
	{
		CardResolver.Result result = resolver.resolve(CardEntityKind.ITEM, 999, "Unknown item");
		assertEquals(CardResolver.Status.UNTRACKED, result.getStatus());
	}

	@Test
	public void duplicateIdFailsOpenAsAmbiguous()
	{
		catalog.add(identity(CardEntityKind.ITEM, "Conflicting item", 100), "Conflicting item");
		CardResolver.Result result = resolver.resolve(CardEntityKind.ITEM, 100, "Test item");
		assertEquals(CardResolver.Status.AMBIGUOUS, result.getStatus());
		assertFalse(result.isTracked());
	}

	@Test
	public void duplicateNameFailsOpenAsAmbiguousWithoutId()
	{
		catalog.add(identity(CardEntityKind.ITEM, "Other parent", 200), "Shared display name");
		catalog.alias(item, "Shared display name");
		CardResolver.Result result = resolver.resolve(CardEntityKind.ITEM, -1, "Shared display name");
		assertEquals(CardResolver.Status.AMBIGUOUS, result.getStatus());
	}

	@Test
	public void nullKindCannotResolveAcrossNamespaces()
	{
		assertEquals(CardResolver.Status.AMBIGUOUS,
			resolver.resolve(null, 100, "Test item").getStatus());
	}

	@Test
	public void parentCardNameHasDistinctLookup()
	{
		assertSame(item, resolver.resolveCardName(CardEntityKind.ITEM, "Test item").getIdentity());
		assertEquals(CardResolver.Status.UNTRACKED,
			resolver.resolveCardName(CardEntityKind.ITEM, "Test item (charged)").getStatus());
	}

	private void assertTracked(CardEntityKind kind, int id, String name, CardIdentity expected)
	{
		CardResolver.Result result = resolver.resolve(kind, id, name);
		assertEquals(CardResolver.Status.TRACKED, result.getStatus());
		assertTrue(result.isTracked());
		assertSame(expected, result.getIdentity());
	}

	private static CardIdentity identity(CardEntityKind kind, String name, Integer... ids)
	{
		return new CardIdentity(kind, name, new java.util.LinkedHashSet<>(Arrays.asList(ids)));
	}

	private static final class SyntheticCatalog implements CardIdentityCatalog
	{
		private final Map<String, List<CardIdentity>> byId = new HashMap<>();
		private final Map<String, List<CardIdentity>> byName = new HashMap<>();

		private SyntheticCatalog add(CardIdentity identity, String... names)
		{
			for (Integer id : identity.getEntityIds())
			{
				byId.computeIfAbsent(key(identity.getKind(), id), ignored -> new ArrayList<>())
					.add(identity);
			}
			for (String name : names)
			{
				alias(identity, name);
			}
			return this;
		}

		private void alias(CardIdentity identity, String name)
		{
			byName.computeIfAbsent(key(identity.getKind(), name), ignored -> new ArrayList<>())
				.add(identity);
		}

		@Override
		public List<CardIdentity> findById(CardEntityKind kind, int entityId)
		{
			return byId.getOrDefault(key(kind, entityId), Collections.emptyList());
		}

		@Override
		public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
		{
			return byName.getOrDefault(key(kind, entityName), Collections.emptyList());
		}

		@Override
		public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
		{
			return byName.getOrDefault(key(kind, cardName), Collections.emptyList()).stream()
				.filter(identity -> identity.getCardName().equalsIgnoreCase(cardName))
				.collect(java.util.stream.Collectors.toList());
		}

		private static String key(CardEntityKind kind, int id)
		{
			return kind + ":" + id;
		}

		private static String key(CardEntityKind kind, String name)
		{
			return kind + ":" + (name == null ? "" : name.trim().toLowerCase(Locale.ROOT));
		}
	}
}

package com.bronzemantcg.ownership;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SharedUnlockStoreTest
{
	@Test
	public void sourcesReplaceAndUnionWithoutDuplicates()
	{
		SharedUnlockStore store = new SharedUnlockStore();
		assertTrue(store.put("TCG Locked", Arrays.asList("Dragon axe", "Rune axe")));
		assertTrue(store.put("Other", Arrays.asList("Rune axe", "Abyssal whip")));
		assertEquals(set("dragon axe", "rune axe", "abyssal whip"),
			store.getSharedCardNamesLowerCase());

		assertTrue(store.put("TCG Locked", Collections.singletonList("Dragon pickaxe")));
		assertEquals(set("dragon pickaxe", "rune axe", "abyssal whip"),
			store.getSharedCardNamesLowerCase());
		assertFalse(store.put("TCG Locked", Collections.singletonList("Dragon pickaxe")));
	}

	@Test
	public void emptyPayloadWithdrawsOnlyItsSource()
	{
		SharedUnlockStore store = new SharedUnlockStore();
		store.put("TCG Locked", Collections.singletonList("Dragon axe"));
		store.put("Other", Collections.singletonList("Rune axe"));
		assertTrue(store.put("TCG Locked", Collections.emptyList()));
		assertEquals(Collections.singleton("rune axe"), store.getSharedCardNamesLowerCase());
	}

	@Test
	public void clearDropsEverySourceAndCanBeRepeated()
	{
		SharedUnlockStore store = new SharedUnlockStore();
		store.put("TCG Locked", Collections.singletonList("Dragon axe"));
		store.put("Other", Collections.singletonList("Rune axe"));

		store.clear();
		assertTrue(store.getSharedCardNamesLowerCase().isEmpty());

		store.clear();
		assertTrue(store.getSharedCardNamesLowerCase().isEmpty());
	}

	private static Set<String> set(String... values)
	{
		return new HashSet<>(Arrays.asList(values));
	}
}

package com.bronzemantcg.ownership;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TcgOwnershipSnapshotTest
{
	@Test
	public void normalizesConfirmedApiPayload()
	{
		TcgOwnershipSnapshot snapshot = TcgOwnershipSnapshot.fromApi(
			Arrays.asList(" Strength potion ", "STRENGTH POTION", null),
			Arrays.asList(113L, 119.0, -1, 2.5, "117"),
			Arrays.asList(2, 2L), " party-one ");

		assertEquals(Collections.singleton("strength potion"), snapshot.getOwnedCardNamesLowerCase());
		assertEquals(new LinkedHashSet<>(Arrays.asList(113, 119)), snapshot.getOwnedItemIds());
		assertEquals(Collections.singleton(2), snapshot.getOwnedNpcIds());
		assertEquals("party-one", snapshot.getGroupKey());
	}

	@Test
	public void parentOrVariantIdOwnsOneParentCard()
	{
		CardIdentity potion = new CardIdentity(CardEntityKind.ITEM, "Strength potion",
			new LinkedHashSet<>(Arrays.asList(113, 115, 117, 119)));
		assertTrue(potion.isOwnedBy(TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.singletonList(113), Collections.emptyList(), null)));
		assertTrue(potion.isOwnedBy(TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.singletonList(119), Collections.emptyList(), null)));
	}

	@Test
	public void itemAndNpcIdsStayInSeparateNamespaces()
	{
		TcgOwnershipSnapshot snapshot = TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.singletonList(2), Collections.emptyList(), null);
		assertTrue(snapshot.ownsEntityId(CardEntityKind.ITEM, 2));
		assertFalse(snapshot.ownsEntityId(CardEntityKind.NPC, 2));
	}

	@Test
	public void missingIdFieldsFallBackToNames()
	{
		CardIdentity potion = new CardIdentity(CardEntityKind.ITEM, "Strength potion",
			Collections.singleton(113));
		TcgOwnershipSnapshot oldApi = TcgOwnershipSnapshot.fromApi(
			Collections.singletonList("Strength potion"), null, null, null);
		assertFalse(oldApi.hasEntityIds(CardEntityKind.ITEM));
		assertTrue(potion.isOwnedBy(oldApi));
		assertNull(oldApi.getGroupKey());
	}

	@Test
	public void presentIdFieldIsAuthoritativeEvenWhenEmpty()
	{
		CardIdentity potion = new CardIdentity(CardEntityKind.ITEM, "Strength potion",
			Collections.singleton(113));
		TcgOwnershipSnapshot currentApi = TcgOwnershipSnapshot.fromApi(
			Collections.singletonList("Strength potion"), Collections.emptyList(),
			Collections.emptyList(), null);
		assertTrue(currentApi.hasEntityIds(CardEntityKind.ITEM));
		assertFalse(potion.isOwnedBy(currentApi));
	}

	@Test
	public void guardedIdRequiresSupportingAcceptedOwnedName()
	{
		CardIdentity juvenile = new CardIdentity(CardEntityKind.NPC,
			"Juvenile custodian stalker", Collections.emptySet(),
			new LinkedHashSet<>(Arrays.asList(14702, 14706)),
			Collections.singleton(14706));
		TcgOwnershipSnapshot betaStrangeCreature = TcgOwnershipSnapshot.fromApi(
			Collections.singletonList("Strange Creature"), Collections.emptyList(),
			Collections.singletonList(14706), null);
		assertFalse(juvenile.isOwnedBy(betaStrangeCreature));
		assertFalse(juvenile.isCollectedBy(betaStrangeCreature));

		TcgOwnershipSnapshot juvenileVariant = TcgOwnershipSnapshot.fromApi(
			Collections.singletonList("Juvenile custodian stalker"), Collections.emptyList(),
			Collections.singletonList(14706), null);
		assertTrue(juvenile.isOwnedBy(juvenileVariant));
		assertTrue(juvenile.isCollectedBy(juvenileVariant));

		TcgOwnershipSnapshot juvenileParent = TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.emptyList(),
			Collections.singletonList(14702), null);
		assertTrue(juvenile.isOwnedBy(juvenileParent));
	}
}

package com.bronzemantcg.ownership;

import com.bronzemantcg.util.CacheFiles;
import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class BetaCardCacheStoreTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void storesOnlyValidatedDataUnderAHashedProfileFilename() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		BetaCardCacheStore store = new BetaCardCacheStore(new Gson(), directory);
		String profile = "profile-key-with-player-name";

		store.save(profile, "TzTokKickCat", 5, 1234L,
			List.of("Water rune pack", "Coin pouch"));

		Path expected = directory.resolve(CacheFiles.sha256Hex(profile) + ".json");
		assertTrue(Files.exists(expected));
		assertFalse(expected.getFileName().toString().contains("player"));
		assertFalse(Files.readString(expected, StandardCharsets.UTF_8).contains(profile));
		BetaCardCacheStore.Record loaded = store.load(profile);
		assertEquals("TzTokKickCat", loaded.getDisplayName());
		assertEquals(5, loaded.getRevision());
		assertEquals(1234L, loaded.getSavedAtEpochMillis());
		assertEquals(List.of("Water rune pack", "Coin pouch"), loaded.getCardNames());
	}

	@Test
	public void validEmptyBetaCollectionRoundTrips() throws Exception
	{
		BetaCardCacheStore store = new BetaCardCacheStore(new Gson(),
			temporaryFolder.newFolder().toPath());

		store.save("profile", "Felmeme", 56, 1234L, Collections.emptyList());

		assertTrue(store.load("profile").getCardNames().isEmpty());
	}

	@Test
	public void invalidReplacementCannotOverwriteAValidCache() throws Exception
	{
		BetaCardCacheStore store = new BetaCardCacheStore(new Gson(),
			temporaryFolder.newFolder().toPath());
		store.save("profile", "Player", 1, 1L, List.of("Water rune"));

		assertThrows(Exception.class,
			() -> store.save("profile", "Player", 2, 2L,
				List.of("Water rune", "water RUNE")));

		assertEquals(List.of("Water rune"), store.load("profile").getCardNames());
		store.delete("profile");
		assertNull(store.load("profile"));
	}
}

package com.bronzemantcg.ownership;

import com.google.gson.Gson;
import com.google.inject.ImplementedBy;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class ActiveCardIdentityCatalogTest
{
	private BundledCardIdentityCatalog bundled;
	private ActiveCardIdentityCatalog active;

	@Before
	public void setUp()
	{
		bundled = new BundledCardIdentityCatalog(new Gson());
		active = new ActiveCardIdentityCatalog(bundled);
	}

	@Test
	public void cardIdentityBoundaryUsesAtomicActiveCatalog()
	{
		ImplementedBy binding = CardIdentityCatalog.class.getAnnotation(ImplementedBy.class);
		assertSame(ActiveCardIdentityCatalog.class, binding.value());
	}

	@Test
	public void fallbackViewExposesReviewedBetaEntriesButNotV1Availability()
	{
		assertFalse(active.isV1CatalogAvailable());
		assertFalse(active.getView().isV1CatalogAvailable());
		assertEquals(bundled.size(), active.getView().getCardIdentities().size());
		assertTrue(active.getView().getEntityToCardNames(CardEntityKind.ITEM)
			.containsKey("water rune"));
	}

	@Test
	public void startsBundledActivatesWholeRemoteRevisionAndRollsBack()
	{
		ImmutableCardIdentityCatalog remote = remote("Remote water", 555, "Remote water entity");
		long bundledRevision = active.getRevision();

		long remoteRevision = active.activate(remote, remote.getEntries(), "version-1");

		assertTrue(active.isRemoteActive());
		assertTrue(active.isV1CatalogAvailable());
		assertTrue(remoteRevision > bundledRevision);
		assertEquals("Remote water", active.findById(CardEntityKind.ITEM, 555).get(0).getCardName());
		assertEquals(Set.of("remote water"), active.getView()
			.getEntityToCardNames(CardEntityKind.ITEM).get("remote water entity"));

		long restoredRevision = active.useBundled();
		assertFalse(active.isRemoteActive());
		assertFalse(active.isV1CatalogAvailable());
		assertTrue(restoredRevision > remoteRevision);
		assertEquals("Water rune", active.findById(CardEntityKind.ITEM, 555).get(0).getCardName());
	}

	@Test
	public void reapplyingSameImmutableRevisionDoesNotInvalidateCachesAgain()
	{
		ImmutableCardIdentityCatalog remote = remote("Remote", 1, "Remote");
		long first = active.activate(remote, remote.getEntries(), "version-1");

		assertEquals(first, active.activate(remote, remote.getEntries(), "version-1"));
		assertEquals(first, active.getRevision());
	}

	@Test
	public void concurrentReadersSeeOnlyCompleteCatalogues() throws Exception
	{
		ImmutableCardIdentityCatalog remote = remote("Remote water", 555, "Water rune");
		CompletableFuture<Void> writer = CompletableFuture.runAsync(() ->
		{
			for (int i = 0; i < 250; i++)
			{
				active.activate(remote, remote.getEntries(), "version-" + i);
				active.useBundled();
			}
		});
		List<CompletableFuture<Void>> readers = new ArrayList<>();
		for (int thread = 0; thread < 4; thread++)
		{
			readers.add(CompletableFuture.runAsync(() ->
			{
				for (int i = 0; i < 5000; i++)
				{
					List<CardIdentity> matches = active.findById(CardEntityKind.ITEM, 555);
					assertEquals(1, matches.size());
					String name = matches.get(0).getCardName();
					assertTrue("Water rune".equals(name) || "Remote water".equals(name));
				}
			}));
		}
		readers.add(writer);
		CompletableFuture.allOf(readers.toArray(new CompletableFuture[0]))
			.get(5, TimeUnit.SECONDS);
	}

	private static ImmutableCardIdentityCatalog remote(String parent, int id, String entityName)
	{
		CardIdentity identity = new CardIdentity(CardEntityKind.ITEM, parent, Set.of(id));
		return new ImmutableCardIdentityCatalog(List.of(
			new ImmutableCardIdentityCatalog.Entry(identity, List.of(entityName))));
	}
}

package com.bronzemantcg.ownership;

import com.bronzemantcg.BronzemanTcgConfig;
import com.bronzemantcg.interop.BetaCardLookupClient;
import com.google.gson.Gson;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BetaCardCacheServiceTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	private final AtomicBoolean consent = new AtomicBoolean(true);
	private final AtomicBoolean disableBetaVariants = new AtomicBoolean(false);
	private final TestProfileAccess profiles = new TestProfileAccess("profile-one");
	private ScheduledExecutorService executor;
	private BetaCardCacheStore store;
	private FakeLookupClient lookup;
	private BetaCardCacheService service;

	@Before
	public void setUp() throws Exception
	{
		Gson gson = new Gson();
		executor = Executors.newSingleThreadScheduledExecutor();
		store = new BetaCardCacheStore(gson, temporaryFolder.newFolder().toPath());
		lookup = new FakeLookupClient();
		service = new BetaCardCacheService(null, null, config(), profiles, lookup, store,
			new BundledCardIdentityCatalog(gson), gson, executor, () -> 1234L);
	}

	@After
	public void tearDown() throws Exception
	{
		service.shutDown();
		executor.shutdownNow();
		executor.awaitTermination(2, TimeUnit.SECONDS);
	}

	@Test
	public void startupLoadsOnlyTheCurrentProfilesLocalCache() throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack"));

		service.startUp();

		assertEquals(0, lookup.requests);
		assertEquals(BetaCardCacheService.Status.CACHED, service.getState().getStatus());
		assertEquals(Set.of("water rune pack"), service.getState().getBetaNamesLowerCase());
		profiles.profile = "profile-two";
		service.onProfileChanged();
		assertEquals(BetaCardCacheService.Status.NO_CACHE, service.getState().getStatus());
		assertTrue(service.getBetaCardUnlocks().getParentNamesLowerCase().isEmpty());
	}

	@Test
	public void cachedBetaNamesProjectToReviewedParentsWithoutPluginMessage() throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack", "Teak logs", "Crawling hand",
				"Future beta card"));
		service.startUp();

		BetaCardUnlockSource.View unlocks = service.getBetaCardUnlocks();
		assertEquals(Set.of("water rune", "teak logs"),
			unlocks.getParentNamesLowerCase(CardEntityKind.ITEM));
		assertTrue(unlocks.getParentNamesLowerCase(CardEntityKind.NPC).isEmpty());
		assertFalse(unlocks.getParentNamesLowerCase().contains("crawling hand"));
		assertFalse(unlocks.getParentNamesLowerCase().contains("future beta card"));
	}

	@Test
	public void disablingBetaVariantsSuppressesGameplayUnlocksWithoutDeletingCache()
		throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack", "Teak logs", "Aberrant spectre"));
		service.startUp();

		assertEquals(Set.of("water rune", "teak logs"),
			service.getBetaCardUnlocks().getParentNamesLowerCase(CardEntityKind.ITEM));
		assertEquals(Set.of("aberrant spectre"),
			service.getBetaCardUnlocks().getParentNamesLowerCase(CardEntityKind.NPC));
		disableBetaVariants.set(true);
		assertTrue(service.getBetaCardUnlocks().getParentNamesLowerCase().isEmpty());
		assertEquals(BetaCardCacheService.Status.CACHED, service.getState().getStatus());
		assertEquals(Set.of("water rune pack", "teak logs", "aberrant spectre"),
			service.getState().getBetaNamesLowerCase());

		disableBetaVariants.set(false);
		assertEquals(Set.of("water rune", "teak logs"),
			service.getBetaCardUnlocks().getParentNamesLowerCase(CardEntityKind.ITEM));
		assertEquals(Set.of("aberrant spectre"),
			service.getBetaCardUnlocks().getParentNamesLowerCase(CardEntityKind.NPC));
	}

	@Test
	public void explicitRefreshAcceptsAnAuthoritativeEmptyCollection() throws Exception
	{
		service.startUp();

		service.beginRefresh("profile-one", "Felmeme");
		lookup.respond(200,
			"{\"displayName\":\"Felmeme\",\"revision\":56,\"cardNames\":[]}");
		waitForStatus(BetaCardCacheService.Status.CACHED);

		assertEquals(0, service.getState().getCachedCount());
		assertEquals(56, service.getState().getRevision());
		assertTrue(store.load("profile-one").getCardNames().isEmpty());
		assertTrue(service.getBetaCardUnlocks().getParentNamesLowerCase().isEmpty());
	}

	@Test
	public void failedRefreshKeepsThePreviousValidatedClassification() throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack"));
		service.startUp();

		service.beginRefresh("profile-one", "Player One");
		lookup.respond(200,
			"{\"displayName\":\"Someone Else\",\"revision\":8,\"cardNames\":[]}");
		waitForStatus(BetaCardCacheService.Status.FAILED);

		assertEquals(Set.of("water rune pack"), service.getState().getBetaNamesLowerCase());
		assertEquals(List.of("Water rune pack"), store.load("profile-one").getCardNames());
		assertEquals(Set.of("water rune"),
			service.getBetaCardUnlocks().getParentNamesLowerCase(CardEntityKind.ITEM));
	}

	@Test
	public void responseWithoutRevisionIsRejected() throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack"));
		service.startUp();

		service.beginRefresh("profile-one", "Player One");
		lookup.respond(200,
			"{\"displayName\":\"Player One\",\"cardNames\":[]}");
		waitForStatus(BetaCardCacheService.Status.FAILED);

		assertEquals(Set.of("water rune pack"), service.getState().getBetaNamesLowerCase());
		assertEquals(7, store.load("profile-one").getRevision());
	}

	@Test
	public void synchronousLookupFailureDoesNotRemainRefreshing()
	{
		service.startUp();
		lookup.failSynchronously = true;

		service.beginRefresh("profile-one", "Player One");

		assertEquals(BetaCardCacheService.Status.FAILED, service.getState().getStatus());
		assertTrue(service.getState().getMessage().contains("Could not start"));
	}

	@Test
	public void withdrawingConsentCancelsOnlyTheRequestAndKeepsCache() throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack"));
		service.startUp();
		service.beginRefresh("profile-one", "Player One");
		BetaCardLookupClient.FetchHandle handle = lookup.lastHandle;

		consent.set(false);
		service.onLookupConsentChanged();

		assertTrue(handle.isCancelled());
		assertEquals(BetaCardCacheService.Status.FAILED, service.getState().getStatus());
		assertFalse(service.getState().getBetaNamesLowerCase().isEmpty());
		assertEquals(Set.of("water rune"),
			service.getBetaCardUnlocks().getParentNamesLowerCase(CardEntityKind.ITEM));
	}

	@Test
	public void clearRemovesRawNamesAndProjectedUnlocks() throws Exception
	{
		store.save("profile-one", "Player One", 7, 999L,
			List.of("Water rune pack"));
		service.startUp();

		service.clear();

		assertEquals(BetaCardCacheService.Status.NO_CACHE, service.getState().getStatus());
		assertTrue(service.getState().getBetaNamesLowerCase().isEmpty());
		assertTrue(service.getBetaCardUnlocks().getParentNamesLowerCase().isEmpty());
		assertNull(store.load("profile-one"));
	}

	private void waitForStatus(BetaCardCacheService.Status expected) throws Exception
	{
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(2);
		while (service.getState().getStatus() != expected && System.nanoTime() < deadline)
		{
			Thread.sleep(10L);
		}
		assertEquals(expected, service.getState().getStatus());
	}

	private BronzemanTcgConfig config()
	{
		return (BronzemanTcgConfig) Proxy.newProxyInstance(
			BronzemanTcgConfig.class.getClassLoader(),
			new Class<?>[]{BronzemanTcgConfig.class}, (proxy, method, arguments) ->
			{
				if (method.getName().equals("allowBetaCardLookup"))
				{
					return consent.get();
				}
				if (method.getName().equals("disableBetaVariants"))
				{
					return disableBetaVariants.get();
				}
				if (method.getName().equals("toString"))
				{
					return "test config";
				}
				throw new UnsupportedOperationException(method.getName());
			});
	}

	private static final class TestProfileAccess implements BetaCardCacheService.ProfileAccess
	{
		private String profile;

		private TestProfileAccess(String profile)
		{
			this.profile = profile;
		}

		@Override
		public String currentProfileKey()
		{
			return profile;
		}
	}

	private static final class FakeLookupClient extends BetaCardLookupClient
	{
		private Listener listener;
		private int requests;
		private FetchHandle lastHandle;
		private boolean failSynchronously;

		private FakeLookupClient()
		{
			super(new OkHttpClient(), "https://example.test/api/v1/players", 1024 * 1024);
		}

		@Override
		public FetchHandle fetch(String displayName, Listener listener)
		{
			requests++;
			if (failSynchronously)
			{
				throw new IllegalStateException("test failure");
			}
			this.listener = listener;
			lastHandle = new FetchHandle();
			return lastHandle;
		}

		private void respond(int status, String json)
		{
			listener.onResponse(new LookupResponse(status,
				json.getBytes(StandardCharsets.UTF_8)));
		}
	}
}

