package com.bronzemantcg;

import com.bronzemantcg.catalog.QuestCatalog;
import com.google.gson.Gson;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

public class QuestCatalogTest
{
	@Test
	public void indexesQuestRelationshipsByCard()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());

		List<String> potionQuests = catalog.getQuestsForCard("Defence potion");
		Assert.assertTrue(potionQuests.contains("A Kingdom Divided"));
		Assert.assertEquals(potionQuests, catalog.getQuestsForCard("defence potion"));
		Assert.assertTrue(catalog.getQuestsForCard("Definitely not a card").isEmpty());
	}

	@Test
	public void loadsFullQuestsAndMiniquestsWithoutCountingLeadingTheForSorting()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());
		// 190, not 181: Recipe for Disaster is carried as its ten subquests, not one entry.
		Assert.assertEquals(190, catalog.getQuests().size());
		// 19: four miniquests removed from the game (Architectural Alliance, Lost Lover,
		// Rogue Trader, Spirit of Adventure) - none had a RuneLite Quest constant either.
		Assert.assertEquals(19, catalog.getMiniquests().size());
		assertSortedIgnoringThe(catalog.getQuests());
		assertSortedIgnoringThe(catalog.getMiniquests());
	}

	@Test
	public void preservesNestedSpellQuantitiesAndRecipeForDisasterSections()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());
		QuestCatalog.QuestEntry dragonSlayer = quest(catalog, "Dragon Slayer II");
		QuestCatalog.Requirement spells = requirement(dragonSlayer,
			"Fire Wave/Surge Runes");
		Assert.assertEquals(QuestCatalog.Logic.ANY, spells.logic);
		Assert.assertTrue(spells.displayCardsOnly);
		Assert.assertEquals(2, spells.children.size());
		Assert.assertEquals("Fire Wave", spells.children.get(0).label);
		Assert.assertEquals("Fire Surge", spells.children.get(1).label);
		// Quantities were stripped from the data and are read by nothing, so the tiers are
		// pinned by their catalytic rune instead - that is what makes them distinct spells.
		Assert.assertNotNull(child(spells.children.get(0), "Fire rune"));
		Assert.assertNotNull(child(spells.children.get(1), "Fire rune"));
		Assert.assertNotNull(child(spells.children.get(0), "Blood rune"));
		Assert.assertNotNull(child(spells.children.get(1), "Wrath rune"));
		Assert.assertEquals("Items", dragonSlayer.sections.get(0).label);
		Assert.assertNotNull(requirement(dragonSlayer, "Ghostspeak amulet"));
		assertNoQuestHelperSections(catalog.getQuests());
		assertNoQuestHelperSections(catalog.getMiniquests());

		// Recipe for Disaster is split into its ten subquests rather than carried as one
		// entry with ten sections. The display prefix is the owner's call, so accept
		// either the short or the full RuneLite form here.
		Assert.assertTrue(catalog.getQuests().stream()
			.noneMatch(entry -> "Recipe for Disaster".equals(entry.name)));
		Assert.assertEquals(10, catalog.getQuests().stream()
			.filter(entry -> entry.name.startsWith("RFD - ")
				|| entry.name.startsWith("Recipe for Disaster - "))
			.count());
		// A shortened display name must still resolve to RuneLite's own quest name, or
		// Hide completed and the quest-NPC index silently stop matching these entries.
		for (QuestCatalog.QuestEntry entry : catalog.getQuests())
		{
			if (entry.name.startsWith("RFD - "))
			{
				Assert.assertTrue(entry.name + " -> " + entry.questName,
					entry.questName.startsWith("Recipe for Disaster - "));
			}
		}
		QuestCatalog.QuestEntry awowogei = quest(catalog, "RFD - King Awowogei");
		Assert.assertEquals("Recipe for Disaster - King Awowogei", awowogei.questName);
		Assert.assertEquals("Items", awowogei.sections.get(0).label);
		Assert.assertEquals("Enemies", awowogei.sections.get(1).label);
		Assert.assertNotNull(requirement(awowogei, "Monkey greegree"));
	}

	@Test
	public void appliesTheRecordedShieldGangToSplitRoutes()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());
		QuestCatalog.Requirement shieldRoute = requirement(
			quest(catalog, "Shield of Arrav"), "Your Shield of Arrav gang route");
		Set<String> phoenixCards = Set.of("coins", "jonny the beard");
		Assert.assertTrue(shieldRoute.isSatisfied(phoenixCards,
			QuestCatalog.RouteSelection.UNKNOWN));
		Assert.assertTrue(shieldRoute.isSatisfied(phoenixCards,
			QuestCatalog.RouteSelection.PHOENIX));
		Assert.assertFalse(shieldRoute.isSatisfied(phoenixCards,
			QuestCatalog.RouteSelection.BLACK_ARM));

		QuestCatalog.Requirement heroesRoute = requirement(
			quest(catalog, "Heroes' Quest"), "Your Shield of Arrav gang route");
		Assert.assertTrue(heroesRoute.isSatisfied(Set.of("grip"),
			QuestCatalog.RouteSelection.PHOENIX));
		Assert.assertFalse(heroesRoute.isSatisfied(Set.of("grip"),
			QuestCatalog.RouteSelection.BLACK_ARM));
	}

	@Test
	public void retainsLocalQuestDataAndDoesNotIndexOldNotesAsCards()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());
		QuestCatalog.QuestEntry bloodMoon = quest(catalog, "The Blood Moon Rises");
		Assert.assertNotNull(requirement(bloodMoon, "Tinderbox"));
		Assert.assertTrue(catalog.getQuestsForCard(
			"Don't have to attack to complete quest").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Lyre Monsters - Check wiki").isEmpty());
	}

	@Test
	public void usesCanonicalV1QuestCardsAndDropsRetiredBetaRequirements()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());
		QuestCatalog.QuestEntry defender = quest(catalog, "Defender of Varrock");

		Assert.assertNotNull(requirement(defender, "Armoured zombie"));
		Assert.assertTrue(catalog.getQuestsForCard(
			"Armoured zombie (Defender of Varrock)").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Cup of tea").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Captain's log").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Ode to eternity").isEmpty());
	}

	@Test
	public void indexesExplicitNpcLabelsAndOmitsNonGatingMergedRequirements()
	{
		QuestCatalog catalog = new QuestCatalog(new Gson());
		List<String> dragonSlayerNpcs = catalog.getQuestMonsterCards()
			.get("Dragon Slayer I");

		Assert.assertTrue(dragonSlayerNpcs.contains("Oziach"));
		Assert.assertTrue(dragonSlayerNpcs.contains("General Bentnoze"));
		Assert.assertFalse(dragonSlayerNpcs.contains("Goblin generals"));
		Assert.assertTrue(catalog.getQuestsForCard("Cadantine seed")
			.contains("Barbarian Training"));
		Assert.assertTrue(catalog.getQuestsForCard("Adamantite bar")
			.contains("Barbarian Training"));
		Assert.assertTrue(catalog.getQuestsForCard("Adamantite nails")
			.contains("Daddy's Home"));
		Assert.assertTrue(catalog.getQuestsForCard("Oziach")
			.contains("Dragon Slayer I"));
		Assert.assertTrue(catalog.getQuestsForCard("Mithril dagger")
			.contains("Mage Arena I"));
		Assert.assertTrue(catalog.getQuestsForCard("Kolodion")
			.contains("Mage Arena I"));
		Assert.assertTrue(catalog.getQuestsForCard("Ghostspeak amulet")
			.contains("Dragon Slayer II"));
		Assert.assertTrue(catalog.getQuestMonsterCards().get("A Ruff Situation")
			.contains("Gertrude"));

		Assert.assertTrue(catalog.getQuestsForCard("Cadentine seed").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Adamant bar").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Oziarch").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Ring of shadows").isEmpty());
		Assert.assertTrue(catalog.getQuestsForCard("Wyson the gardener").isEmpty());
	}

	private static QuestCatalog.QuestEntry quest(QuestCatalog catalog, String name)
	{
		for (QuestCatalog.QuestEntry entry : catalog.getQuests())
		{
			if (entry.name.equals(name))
			{
				return entry;
			}
		}
		throw new AssertionError("Missing quest " + name);
	}

	private static QuestCatalog.Requirement requirement(
		QuestCatalog.QuestEntry entry, String label)
	{
		for (QuestCatalog.Requirement requirement : entry.requirements)
		{
			QuestCatalog.Requirement match = find(requirement, label);
			if (match != null)
			{
				return match;
			}
		}
		throw new AssertionError("Missing requirement " + label + " in " + entry.name);
	}

	private static QuestCatalog.Requirement child(
		QuestCatalog.Requirement parent, String label)
	{
		for (QuestCatalog.Requirement child : parent.children)
		{
			if (child.label.equals(label))
			{
				return child;
			}
		}
		throw new AssertionError("Missing child " + label);
	}

	private static QuestCatalog.Requirement find(
		QuestCatalog.Requirement requirement, String label)
	{
		if (requirement.label.equals(label))
		{
			return requirement;
		}
		for (QuestCatalog.Requirement child : requirement.children)
		{
			QuestCatalog.Requirement match = find(child, label);
			if (match != null)
			{
				return match;
			}
		}
		return null;
	}

	private static void assertSortedIgnoringThe(List<QuestCatalog.QuestEntry> entries)
	{
		String previous = "";
		for (QuestCatalog.QuestEntry entry : entries)
		{
			String current = entry.name.regionMatches(true, 0, "The ", 0, 4)
				? entry.name.substring(4) : entry.name;
			current = current.toLowerCase(Locale.ROOT);
			Assert.assertTrue(previous.compareTo(current) <= 0);
			previous = current;
		}
	}

	private static void assertNoQuestHelperSections(
		List<QuestCatalog.QuestEntry> entries)
	{
		for (QuestCatalog.QuestEntry entry : entries)
		{
			for (QuestCatalog.Section section : entry.sections)
			{
				Assert.assertNotEquals("Quest Helper details", section.label);
			}
		}
	}
}

package com.bronzemantcg.feature;

import com.bronzemantcg.BronzemanTcgConfig;
import com.bronzemantcg.restriction.LockState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.ScriptID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LockedItemMarkControllerTest
{
	@Test
	public void chosenModeReturnsWhenItemUsageIsRestrictedAgain()
	{
		assertFalse(LockedItemMarkController.isMarkingActive(
			LockState.UNLOCKED, LockedItemMarkMode.TRANSPARENT_ICON, false));
		assertTrue(LockedItemMarkController.isMarkingActive(
			LockState.LOCKED, LockedItemMarkMode.TRANSPARENT, false));
		assertTrue(LockedItemMarkController.isMarkingActive(
			LockState.LOCKED, LockedItemMarkMode.TRANSPARENT_ICON, false));
	}

	@Test
	public void onlyFadeAndIconModeEnablesTheBankFillerBadge()
	{
		assertFalse(LockedItemMarkController.isIconActive(
			LockState.LOCKED, LockedItemMarkMode.TRANSPARENT, false));
		assertTrue(LockedItemMarkController.isIconActive(
			LockState.LOCKED, LockedItemMarkMode.TRANSPARENT_ICON, false));
		assertFalse(LockedItemMarkController.isIconActive(
			LockState.LOCKED, LockedItemMarkMode.OFF, false));
		assertFalse(LockedItemMarkController.isIconActive(
			LockState.UNLOCKED, LockedItemMarkMode.TRANSPARENT_ICON, false));
		assertFalse(LockedItemMarkController.isIconActive(
			LockState.LOCKED, LockedItemMarkMode.TRANSPARENT_ICON, true));
	}

	@Test
	public void offAndBypassDisableMarking()
	{
		assertFalse(LockedItemMarkController.isMarkingActive(
			LockState.LOCKED, LockedItemMarkMode.OFF, false));
		assertFalse(LockedItemMarkController.isMarkingActive(
			LockState.LOCKED, LockedItemMarkMode.TRANSPARENT, true));
	}

	@Test
	public void lockedItemReceivesOwnedOpacitySignature()
	{
		assertEquals(LockedItemMarkController.LOCKED_ITEM_OPACITY,
			LockedItemMarkController.resolveOpacity(true, 0));
	}

	@Test
	public void onlyOwnedOpacitySignatureIsRestored()
	{
		assertEquals(0, LockedItemMarkController.resolveOpacity(
			false, LockedItemMarkController.LOCKED_ITEM_OPACITY));
		assertEquals(75, LockedItemMarkController.resolveOpacity(false, 75));
	}

	@Test
	public void inventoryAndBankRedrawScriptsTriggerRefresh()
	{
		assertTrue(LockedItemMarkController.isMarkRedrawScript(ScriptID.INVENTORY_DRAWITEM));
		assertTrue(LockedItemMarkController.isMarkRedrawScript(ScriptID.BANKMAIN_BUILD));
		assertFalse(LockedItemMarkController.isMarkRedrawScript(-1));
	}

	@Test
	public void shopGroupsTriggerRefresh()
	{
		assertTrue(LockedItemMarkController.isMarkContainerGroup(InterfaceID.SHOPMAIN));
		assertTrue(LockedItemMarkController.isMarkContainerGroup(InterfaceID.SHOPSIDE));
		assertFalse(LockedItemMarkController.isMarkContainerGroup(InterfaceID.BANKMAIN));
	}

	@Test
	public void onlyMarkingConfigChangesTriggerRefresh()
	{
		assertTrue(LockedItemMarkController.shouldRefreshForConfig(
			BronzemanTcgConfig.GROUP, "itemUsageMode"));
		assertTrue(LockedItemMarkController.shouldRefreshForConfig(
			BronzemanTcgConfig.GROUP, "lockedItemMarkMode"));
		assertFalse(LockedItemMarkController.shouldRefreshForConfig(
			BronzemanTcgConfig.GROUP, "tintLockedNpcs"));
		assertFalse(LockedItemMarkController.shouldRefreshForConfig(
			"other", "itemUsageMode"));
	}

	@Test
	public void periodicSweepRunsEveryFiveTicks()
	{
		for (int tick = 1; tick < 15; tick++)
		{
			assertEquals(tick % 5 == 0, LockedItemMarkController.isPeriodicRefreshTick(tick));
		}
		assertFalse(LockedItemMarkController.isPeriodicRefreshTick(0));
	}

	@Test
	public void catalogueRevisionChangeTriggersImmediateRefresh()
	{
		assertTrue(LockedItemMarkController.isCatalogRevisionChanged(4L, 5L));
		assertFalse(LockedItemMarkController.isCatalogRevisionChanged(5L, 5L));
	}
}

