package com.bronzemantcg.restriction;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardOwnershipService;
import com.bronzemantcg.ownership.CardResolver;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.bronzemantcg.support.SimulatedV1CardIdentityCatalog;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class RestrictionDecisionServiceTest
{
	@Test
	public void unavailableTutorialAndLmsStatesShareOneBypassDecision()
	{
		RestrictionDecisionTestSupport.Harness harness =
			RestrictionDecisionTestSupport.harness();
		RestrictionDecisionService service = harness.getService();

		assertFalse(service.isEnforcementBypassed());
		harness.stateAvailable(false);
		assertTrue(service.isEnforcementBypassed());
		harness.stateAvailable(true).tutorialProgress(670);
		assertTrue(service.isEnforcementBypassed());
		harness.tutorialProgress(0).lmsState(1);
		assertTrue(service.isEnforcementBypassed());
		harness.lmsState(0).mapRegions(13658);
		assertTrue(service.isEnforcementBypassed());
		harness.mapRegions(12850);
		assertFalse(service.isEnforcementBypassed());
	}

	@Test
	public void personalSharedAndExplicitItemOwnershipUseTheSameBoundary()
	{
		RestrictionDecisionTestSupport.Harness harness =
			RestrictionDecisionTestSupport.harness();
		RestrictionDecisionService service = harness.getService();

		assertTrue(service.isItemLocked(6739, "Dragon axe"));
		harness.ownership(TcgOwnershipSnapshot.namesOnly(Set.of("dragon axe")));
		assertFalse(service.isItemLocked(6739, "Dragon axe"));

		harness.ownership(emptyIds()).shared(Set.of("dragon axe"));
		assertFalse(service.isItemLocked(6739, "Dragon axe"));
		harness.acceptShared(false);
		assertTrue(service.isItemLocked(6739, "Dragon axe"));

		harness.configuredExempt(Set.of("dragon axe"));
		assertFalse(service.isItemLocked(6739, "Dragon axe"));
	}

	@Test
	public void onlyCoinsAndExplicitNamesEnterTheGlobalExemptionSet()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(emptyIds())
			.coinsExempt(true)
			.configuredExempt(Set.of("lobster"));
		RestrictionDecisionService service = harness.getService();

		assertFalse(service.isItemLocked(995, "Coins"));
		assertFalse(service.isItemLocked(379, "Lobster"));
		assertTrue(service.isItemLocked(121, "Attack potion(3)"));
		assertTrue(service.requirementOwnership(CardEntityKind.ITEM).test("Coins"));
		assertTrue(service.requirementOwnership().test("Lobster"));
		assertFalse(service.requirementOwnership().test("Attack potion"));
	}

	@Test
	public void coinPouchVariantReportsOnlyTheCoinsParent()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
				Collections.emptyList(), Collections.emptyList(), null));
		RestrictionDecisionService service = harness.getService();

		assertEquals("Coins", service.missingItemCardName(617, "Coin pouch"));
		harness.ownership(TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
			List.of(617), Collections.emptyList(), null));
		assertNull(service.missingItemCardName(617, "Coin pouch"));
	}

	@Test
	public void betaCoinPouchDoesNotUnlockV1Coins()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(TcgOwnershipSnapshot.namesOnly(Set.of("coin pouch")));
		RestrictionDecisionService service = harness.getService();

		assertEquals("Coins", service.missingItemCardName(22521, "Coin pouch"));
		harness.ownership(TcgOwnershipSnapshot.fromApi(List.of("Coin pouch"),
			List.of(22521), Collections.emptyList(), null));
		assertEquals("Coins", service.missingItemCardName(22521, "Coin pouch"));

		harness.ownership(TcgOwnershipSnapshot.fromApi(List.of("Coins"),
			List.of(22521), Collections.emptyList(), null));
		assertNull(service.missingItemCardName(22521, "Coin pouch"));
		harness.ownership(TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
			List.of(995), Collections.emptyList(), null));
		assertNull(service.missingItemCardName(995, "Coins"));
	}

	@Test
	public void npcChecksUseOnlyExplicitExemptions()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(emptyIds());
		RestrictionDecisionService service = harness.getService();

		assertTrue(service.isNpcLocked(2848, "Monkey"));
		harness.configuredExempt(Set.of("monkey (monster)"));
		assertFalse(service.isNpcLocked(2848, "Monkey"));
	}

	@Test
	public void betaParentsUnlockItemsVariantsNpcsAndRequirements()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(emptyIds())
			.betaItems(Set.of("sapphire"))
			.betaNpcs(Set.of("monkey"));
		RestrictionDecisionService service = harness.getService();

		assertFalse(service.isItemLocked(1607, "Sapphire"));
		assertFalse(service.isItemLocked(1623, "Uncut sapphire"));
		assertFalse(service.isNpcLocked(2848, "Monkey"));
		assertTrue(service.requirementOwnership(CardEntityKind.ITEM).test("Sapphire"));
		assertTrue(service.requirementOwnership().test("Monkey"));
	}

	@Test
	public void clearingBetaRelocksOnlyBetaDerivedOwnership()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(TcgOwnershipSnapshot.fromApi(Collections.singletonList("Dragon axe"),
				Collections.singletonList(6739), Collections.emptyList(), null))
			.betaItems(Set.of("sapphire"));
		RestrictionDecisionService service = harness.getService();

		assertFalse(service.isItemLocked(1607, "Sapphire"));
		assertFalse(service.isItemLocked(6739, "Dragon axe"));
		harness.betaItems(Collections.emptySet());
		assertTrue(service.isItemLocked(1607, "Sapphire"));
		assertFalse(service.isItemLocked(6739, "Dragon axe"));
	}

	@Test
	public void permanentNpcExemptionsBypassCardOwnership()
	{
		RestrictionDecisionService service = RestrictionDecisionTestSupport.harness()
			.ownership(emptyIds())
			.getService();

		assertFalse(service.isNpcLocked(2850, "Veos"));
		assertFalse(service.isNpcLocked(311, "Ironman tutor"));
		assertTrue(service.isNpcLocked(2848, "Monkey"));
	}

	@Test
	public void unknownAndNamelessEntitiesStillFailOpen()
	{
		RestrictionDecisionService service =
			RestrictionDecisionTestSupport.harness().getService();

		assertFalse(service.isItemLocked(999999, "Unknown item"));
		assertFalse(service.isItemLocked(999999, "Dragon axe"));
		assertFalse(service.isItemLocked(6739, ""));
		assertFalse(service.isNpcLocked(999999, "Unknown NPC"));
		assertFalse(service.isNpcLocked(2848, null));
	}

	@Test
	public void notedItemsUseTheirLinkedUnnotedIdentity()
	{
		int notedDragonAxe = 900_001;
		RestrictionDecisionTestSupport.Harness harness =
			RestrictionDecisionTestSupport.harness()
				.canonicalItemId(notedDragonAxe, 6739)
				.ownership(emptyIds());
		RestrictionDecisionService service = harness.getService();

		assertTrue(service.isItemLocked(notedDragonAxe, "Dragon axe"));
		harness.ownership(TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
			List.of(6739), Collections.emptyList(), null));
		assertFalse(service.isItemLocked(notedDragonAxe, "Dragon axe"));
	}

	@Test
	public void onlyConfirmedNotesCanonicalizeToTheirLinkedItem()
	{
		assertEquals(6739,
			RestrictionDecisionService.canonicalizeNotedItemId(900_001, 799, 6739));
		assertEquals(900_001,
			RestrictionDecisionService.canonicalizeNotedItemId(900_001, -1, 6739));
		assertEquals(900_001,
			RestrictionDecisionService.canonicalizeNotedItemId(900_001, 799, -1));
	}

	@Test
	public void ambiguousEntitiesAndParentRequirementsFailOpen()
	{
		CardOwnershipService ownershipService = new CardOwnershipService(
			new CardResolver(new SimulatedV1CardIdentityCatalog()));
		RestrictionDecisionService service = RestrictionDecisionTestSupport
			.harness(ownershipService).ownership(emptyIds()).getService();

		assertFalse(service.isNpcLocked(9000, "Ambiguous NPC"));
		assertTrue(service.requirementOwnership().test("Crawling Hand"));
	}

	@Test
	public void itemContextStaysStableUntilADecisionSourceChanges()
	{
		RestrictionDecisionTestSupport.Harness harness =
			RestrictionDecisionTestSupport.harness();
		RestrictionDecisionService service = harness.getService();
		RestrictionDecisionService.ItemContext first = service.getItemContext();

		assertSame(first, service.getItemContext());
		harness.shared(Set.of("dragon axe"));
		assertNotSame(first, service.getItemContext());
	}

	@Test
	public void itemIdCacheInvalidatesWithTheContext()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.itemName(6739, "Dragon axe");
		RestrictionDecisionService service = harness.getService();

		assertTrue(service.isItemLocked(6739));
		assertTrue(service.isItemLocked(6739));
		assertEquals(1, harness.getItemNameCalls());

		harness.ownership(TcgOwnershipSnapshot.namesOnly(Set.of("dragon axe")));
		assertFalse(service.isItemLocked(6739));
		assertEquals(2, harness.getItemNameCalls());
	}

	@Test
	public void itemIdCacheInvalidatesWithBetaRevision()
	{
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport.harness()
			.ownership(emptyIds())
			.itemName(1607, "Sapphire");
		RestrictionDecisionService service = harness.getService();

		assertTrue(service.isItemLocked(1607));
		assertEquals(1, harness.getItemNameCalls());

		harness.betaItems(Set.of("sapphire"));
		assertFalse(service.isItemLocked(1607));
		assertEquals(2, harness.getItemNameCalls());
	}

	@Test
	public void itemContextAndIdCacheInvalidateWithCatalogueRevision()
	{
		AtomicLong revision = new AtomicLong();
		CardOwnershipService ownershipService = new CardOwnershipService(
			new CardResolver(new SimulatedV1CardIdentityCatalog()));
		RestrictionDecisionTestSupport.Harness harness = RestrictionDecisionTestSupport
			.harness(ownershipService, revision::get)
			.itemName(6739, "Dragon axe");
		RestrictionDecisionService service = harness.getService();

		assertTrue(service.isItemLocked(6739));
		assertEquals(1, harness.getItemNameCalls());

		revision.incrementAndGet();
		assertTrue(service.isItemLocked(6739));
		assertEquals(2, harness.getItemNameCalls());
	}

	private static TcgOwnershipSnapshot emptyIds()
	{
		return TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), null);
	}
}

package com.bronzemantcg.restriction;

import com.bronzemantcg.catalog.RecipeCatalog;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.List;
import net.runelite.api.MenuAction;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ItemInteractionServiceTest
{
	@Test
	public void groundItemsOnlyRestrictTakeOrTelegrabWhileLocked()
	{
		assertTrue(ItemInteractionService.isGroundInteractionRestricted(
			LockState.LOCKED, MenuAction.GROUND_ITEM_FIRST_OPTION, "Take"));
		assertTrue(ItemInteractionService.isGroundInteractionRestricted(
			LockState.LOCKED, MenuAction.WIDGET_TARGET_ON_GROUND_ITEM, "Cast"));
		assertFalse(ItemInteractionService.isGroundInteractionRestricted(
			LockState.LOCKED, MenuAction.GROUND_ITEM_FIRST_OPTION, "Examine"));
		assertFalse(ItemInteractionService.isGroundInteractionRestricted(
			LockState.UNLOCKED, MenuAction.GROUND_ITEM_FIRST_OPTION, "Take"));
	}

	@Test
	public void bankModesRetainTheirDepositAndWithdrawMatrix()
	{
		assertTrue(ItemInteractionService.isBankInteractionRestricted(
			LockState.LOCKED, BankingMode.OFF, "Withdraw-1"));
		assertTrue(ItemInteractionService.isBankInteractionRestricted(
			LockState.LOCKED, BankingMode.OFF, "Deposit-1"));
		assertTrue(ItemInteractionService.isBankInteractionRestricted(
			LockState.LOCKED, BankingMode.DEPOSIT_ONLY, "Withdraw-All"));
		assertFalse(ItemInteractionService.isBankInteractionRestricted(
			LockState.LOCKED, BankingMode.DEPOSIT_ONLY, "Deposit-All"));
		assertFalse(ItemInteractionService.isBankInteractionRestricted(
			LockState.LOCKED, BankingMode.FULL, "Withdraw-X"));
		assertFalse(ItemInteractionService.isBankInteractionRestricted(
			LockState.UNLOCKED, BankingMode.OFF, "Deposit-1"));
	}

	@Test
	public void inventoryUsageKeepsOnlyExplicitDisposalActions()
	{
		assertFalse(ItemInteractionService.isInventoryUsageRestricted(
			LockState.LOCKED, "Drop"));
		assertFalse(ItemInteractionService.isInventoryUsageRestricted(
			LockState.LOCKED, "Destroy"));
		assertTrue(ItemInteractionService.isInventoryUsageRestricted(
			LockState.LOCKED, "Wear"));
		assertTrue(ItemInteractionService.isInventoryUsageRestricted(
			LockState.LOCKED, "Drink"));
		assertFalse(ItemInteractionService.isInventoryUsageRestricted(
			LockState.UNLOCKED, "Wear"));
	}

	@Test
	public void foodSettingsApplyOnlyToExactEatAndDrinkActions()
	{
		assertTrue(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.LOCKED, "Eat"));
		assertTrue(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.LOCKED, "Drink"));

		assertFalse(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.FOOD_ONLY, "EAT"));
		assertTrue(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.FOOD_ONLY, "Drink"));

		assertTrue(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.POTS_ONLY, "Eat"));
		assertFalse(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.POTS_ONLY, "drink"));

		assertFalse(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.UNLOCKED, "Eat"));
		assertFalse(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.UNLOCKED, "Drink"));

		assertTrue(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.UNLOCKED, "Wear"));
		assertTrue(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.UNLOCKED, "Guzzle"));
		assertFalse(ItemInteractionService.requiresInventoryCard(
			LockState.LOCKED, FoodSettingsMode.LOCKED, "Drop"));
		assertFalse(ItemInteractionService.requiresInventoryCard(
			LockState.UNLOCKED, FoodSettingsMode.LOCKED, "Eat"));
	}

	@Test
	public void usedOnTargetsAreSplitAtTheLastArrow()
	{
		assertArrayEquals(new String[]{"Raw shrimps", "Fire"},
			ItemInteractionService.splitUsedOn("Raw shrimps -> Fire"));
		assertArrayEquals(new String[]{"A -> B", "C"},
			ItemInteractionService.splitUsedOn("A -> B -> C"));
		assertNull(ItemInteractionService.splitUsedOn("No target pair"));
	}

	@Test
	public void onlyEnchantSpellsEnterJewelleryRecipeRouting()
	{
		assertTrue(ItemInteractionService.isEnchantSpellLabel("Cast Lvl-3 Enchant"));
		assertTrue(ItemInteractionService.isEnchantSpellLabel("Cast",
			"<col=00ff00>Lvl-4 Enchant</col>", ""));
		assertFalse(ItemInteractionService.isEnchantSpellLabel("Cast Low Level Alchemy"));
		assertFalse(ItemInteractionService.isEnchantSpellLabel("Cast",
			"High Level Alchemy", ""));
		assertFalse(ItemInteractionService.isEnchantSpellLabel("Cast Telekinetic Grab"));
	}

	@Test
	public void productQuantityNormalisationPreservesRealNumericNames()
	{
		assertEquals("arrow shafts",
			ItemInteractionService.stripProductQuantity("45 arrow shafts"));
		assertEquals("Arrow shafts",
			ItemInteractionService.stripProductQuantity("45 x Arrow shafts"));
		assertEquals("Arrow shafts",
			ItemInteractionService.stripProductQuantity("Arrow shafts x45"));
		assertEquals("3rd age pickaxe",
			ItemInteractionService.stripProductQuantity("3rd age pickaxe"));
		assertEquals("", ItemInteractionService.stripProductQuantity(null));
	}

	@Test
	public void productionVerbPrefixesCoverQuantityVariants()
	{
		assertTrue(ItemInteractionService.isMakeVerb("smelt-1"));
		assertTrue(ItemInteractionService.isMakeVerb("make-all"));
		assertTrue(ItemInteractionService.isMakeVerb("fletch-10"));
		assertFalse(ItemInteractionService.isMakeVerb("withdraw-1"));
		assertFalse(ItemInteractionService.isMakeVerb(null));
	}

	@Test
	public void rememberedMaterialUsesExactRecipeAndExpiresAfterOneHundredTicks()
	{
		ItemInteractionService service = serviceForMaterialMemory();
		service.rememberMaterialPair("Knife", "Oak logs", 100);

		assertEquals("Oak logs", service.resolveInterfaceMaterial("Crossbow stock", 200));
		assertNull(service.resolveInterfaceMaterial("Crossbow stock", 201));
		assertNull(service.resolveInterfaceMaterial("Unrelated product", 100));
	}

	@Test
	public void onlyWoodcuttingWorldObjectsHideTheirBlockedOption()
	{
		assertTrue(ItemInteractionService.shouldHideWorldObjectCategory("woodcutting"));
		assertFalse(ItemInteractionService.shouldHideWorldObjectCategory("mining"));
		assertFalse(ItemInteractionService.shouldHideWorldObjectCategory(null));
	}

	@Test
	public void shopBuyingRequiresCoinsAndTheCanonicalItemParent()
	{
		RestrictionDecisionTestSupport.Harness harness =
			RestrictionDecisionTestSupport.harness().ownership(v1Items());
		ItemInteractionService service = serviceForShop(harness);

		assertEquals(List.of("Coins", "Dragon axe"),
			service.evaluateShopItem(6739, "Dragon axe", true).getMissingCards());

		harness.ownership(v1Items(617));
		assertEquals(List.of("Dragon axe"),
			service.evaluateShopItem(6739, "Dragon axe", true).getMissingCards());

		harness.ownership(v1Items(6739));
		assertEquals(List.of("Coins"),
			service.evaluateShopItem(6739, "Dragon axe", true).getMissingCards());

		harness.ownership(v1Items(617, 6739));
		assertFalse(service.evaluateShopItem(6739, "Dragon axe", true).isBlocked());
	}

	@Test
	public void shopSellingRequiresOnlyTheSoldItemAndCoinsExemptionAppliesToBuying()
	{
		RestrictionDecisionTestSupport.Harness harness =
			RestrictionDecisionTestSupport.harness().ownership(v1Items());
		ItemInteractionService service = serviceForShop(harness);

		assertEquals(List.of("Dragon axe"),
			service.evaluateShopItem(6739, "Dragon axe", false).getMissingCards());
		harness.ownership(v1Items(6739));
		assertFalse(service.evaluateShopItem(6739, "Dragon axe", false).isBlocked());
		assertEquals(List.of("Coins"),
			service.evaluateShopItem(6739, "Dragon axe", true).getMissingCards());
		harness.coinsExempt(true);
		assertFalse(service.evaluateShopItem(6739, "Dragon axe", true).isBlocked());
	}

	private static ItemInteractionService serviceForMaterialMemory()
	{
		return new ItemInteractionService(null, null, null, null, null, null, null,
			new RecipeCatalog(new Gson()));
	}

	private static ItemInteractionService serviceForShop(
		RestrictionDecisionTestSupport.Harness harness)
	{
		return new ItemInteractionService(null, null, null, harness.getService(),
			null, null, null, new RecipeCatalog(new Gson()));
	}

	private static TcgOwnershipSnapshot v1Items(Integer... itemIds)
	{
		return TcgOwnershipSnapshot.fromApi(Collections.emptyList(),
			List.of(itemIds), Collections.emptyList(), null);
	}
}

package com.bronzemantcg.restriction;

import com.bronzemantcg.catalog.CardRequirement;
