		String json = "{\"items\":[],\"npcs\":[]}";
		OkHttpClient httpClient = clientReturning(200, json, "version-7");
		OsrsTcgCatalogClient client = new OsrsTcgCatalogClient(httpClient, ENDPOINT, 1024);

		OsrsTcgCatalogClient.CatalogResponse response = fetch(client);

		assertArrayEquals(json.getBytes(StandardCharsets.UTF_8), response.getBody());
		assertEquals("version-7", response.getVersion());
		assertEquals("\"version-7\"", response.getEtag());
	}

	@Test
	public void bypassesSharedHttpCacheAndUsesEtagValidation() throws Exception
	{
		AtomicInteger requests = new AtomicInteger();
		OkHttpClient httpClient = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.incrementAndGet();
				assertTrue(chain.request().cacheControl().noCache());
				assertTrue(chain.request().cacheControl().noStore());
				assertEquals("\"etag-7\"", chain.request().header("If-None-Match"));
				return response(chain.request(), 304, "", null);
			})
			.build();
		OsrsTcgCatalogClient client = new OsrsTcgCatalogClient(httpClient, ENDPOINT, 1024);

		OsrsTcgCatalogClient.CatalogResponse response = fetch(client, "\"etag-7\"");

		assertEquals(1, requests.get());
		assertTrue(response.isNotModified());
		assertEquals(0, response.getBody().length);
	}

	@Test
	public void rejectsNotModifiedWithoutAValidator()
	{
		OsrsTcgCatalogClient client = new OsrsTcgCatalogClient(
			clientReturning(304, "", null), ENDPOINT, 1024);

		ExecutionException exception = assertThrows(ExecutionException.class,
			() -> fetch(client));

		assertTrue(exception.getCause().getMessage().contains(
			"304 without a cached catalogue validator"));
	}

	@Test
	public void reportsNetworkFailureWithoutASecondCacheRequest()
	{
		AtomicInteger requests = new AtomicInteger();
		OkHttpClient httpClient = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.incrementAndGet();
				throw new IOException("offline");
			})
			.build();
		OsrsTcgCatalogClient client = new OsrsTcgCatalogClient(httpClient, ENDPOINT, 1024);

		ExecutionException exception = assertThrows(ExecutionException.class,
			() -> fetch(client));
		assertTrue(exception.getCause().getMessage().contains("offline"));
		assertEquals(1, requests.get());
	}

	@Test
	public void rejectsResponsesAboveTheConfiguredLimit()
	{
		OkHttpClient httpClient = clientReturning(200, "12345", null);
		OsrsTcgCatalogClient client = new OsrsTcgCatalogClient(httpClient, ENDPOINT, 4);

		ExecutionException exception = assertThrows(ExecutionException.class,
			() -> fetch(client));
		assertTrue(exception.getCause().getMessage().contains("exceeds 4 bytes"));
	}

	@Test
	public void cancellationSuppressesLateCallbacks() throws Exception
	{
		CompletableFuture<Void> entered = new CompletableFuture<>();
		CompletableFuture<Void> release = new CompletableFuture<>();
		OkHttpClient httpClient = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				entered.complete(null);
				try
				{
					release.get(2, TimeUnit.SECONDS);
				}
				catch (InterruptedException exception)
				{
					Thread.currentThread().interrupt();
					throw new IOException("interrupted", exception);
				}
				catch (ExecutionException | TimeoutException exception)
				{
					throw new IOException("test gate failed", exception);
				}
				return response(chain.request(), 200, "late", null);
			})
			.build();
		OsrsTcgCatalogClient client = new OsrsTcgCatalogClient(httpClient, ENDPOINT, 1024);
		CompletableFuture<OsrsTcgCatalogClient.CatalogResponse> result = new CompletableFuture<>();
		OsrsTcgCatalogClient.FetchHandle handle = client.fetch(listener(result));
		entered.get(2, TimeUnit.SECONDS);

		handle.cancel();
		release.complete(null);

		assertTrue(handle.isCancelled());
		assertThrows(TimeoutException.class, () -> result.get(250, TimeUnit.MILLISECONDS));
	}

	private static OsrsTcgCatalogClient.CatalogResponse fetch(OsrsTcgCatalogClient client)
		throws InterruptedException, ExecutionException, TimeoutException
	{
		return fetch(client, null);
	}

	private static OsrsTcgCatalogClient.CatalogResponse fetch(OsrsTcgCatalogClient client,
		String currentEtag)
		throws InterruptedException, ExecutionException, TimeoutException
	{
		CompletableFuture<OsrsTcgCatalogClient.CatalogResponse> future = new CompletableFuture<>();
		client.fetch(currentEtag, listener(future));
		return future.get(2, TimeUnit.SECONDS);
	}

	private static OsrsTcgCatalogClient.Listener listener(
		CompletableFuture<OsrsTcgCatalogClient.CatalogResponse> future)
	{
		return new OsrsTcgCatalogClient.Listener()
		{
			@Override
			public void onSuccess(OsrsTcgCatalogClient.CatalogResponse response)
			{
				future.complete(response);
			}

			@Override
			public void onFailure(String reason, Throwable cause)
			{
				future.completeExceptionally(new IOException(reason, cause));
			}
		};
	}

	private static OkHttpClient clientReturning(int code, String body, String version)
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain -> response(chain.request(), code, body, version))
			.build();
	}

	private static Response response(okhttp3.Request request, int code,
		String body, String version)
	{
		Response.Builder builder = new Response.Builder()
			.request(request)
			.protocol(Protocol.HTTP_1_1)
			.code(code)
			.message(code == 200 ? "OK" : "Unavailable")
			.body(ResponseBody.create(MediaType.parse("application/json"), body));
		if (version != null)
		{
			builder.header("X-Catalog-Version", version);
			builder.header("ETag", "\"" + version + "\"");
		}
		return builder.build();
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.ownership.BundledCardIdentityCatalog;
import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.CardOwnershipService;
import com.bronzemantcg.ownership.CardResolver;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class RemoteCatalogCacheStoreTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void roundTripsOnlyTheValidatedIdentitySnapshotAndEtag() throws Exception
	{
		Gson gson = new Gson();
		OsrsTcgCatalogSnapshot snapshot = fixture(gson);
		Path file = temporaryFolder.newFolder().toPath().resolve("catalogue.json");
		RemoteCatalogCacheStore store = new RemoteCatalogCacheStore(gson, file);

		store.save(snapshot, "sha256:old", "\"sha256:old\"", 1000L);
		store.save(snapshot, "sha256:test", "\"sha256:test\"", 1234L);
		RemoteCatalogCacheStore.CachedCatalog loaded = store.load();

		assertEquals("sha256:test", loaded.getVersion());
		assertEquals("\"sha256:test\"", loaded.getEtag());
		assertEquals(1234L, loaded.getSavedAtEpochMillis());
		assertEquals(snapshot.size(), loaded.getSnapshot().size());
		assertEquals("Water rune", loaded.getSnapshot()
			.findById(CardEntityKind.ITEM, 12730).get(0).getCardName());
		String cacheJson = Files.readString(file, StandardCharsets.UTF_8);
		assertFalse(cacheJson.contains("imagePath"));
		assertFalse(cacheJson.contains("examine"));
		assertTrue(cacheJson.contains("ownedNameRequiredEntityIds"));
	}

	@Test
	public void rejectsMalformedCacheWithoutCreatingAReplacement() throws Exception
	{
		Path file = temporaryFolder.newFolder().toPath().resolve("catalogue.json");
		Files.writeString(file, "{broken", StandardCharsets.UTF_8);
		RemoteCatalogCacheStore store = new RemoteCatalogCacheStore(new Gson(), file);

		assertThrows(CatalogValidationException.class, store::load);
		assertEquals("{broken", Files.readString(file, StandardCharsets.UTF_8));
	}

	@Test
	public void rejectsCachedEntityIdAssignedToTwoParents() throws Exception
	{
		Gson gson = new Gson();
		CardIdentity first = new CardIdentity(CardEntityKind.ITEM, "First",
			Set.of(42));
		CardIdentity second = new CardIdentity(CardEntityKind.ITEM, "Second",
			Set.of(42));
		OsrsTcgCatalogSnapshot ambiguous = new OsrsTcgCatalogSnapshot(List.of(
			new ImmutableCardIdentityCatalog.Entry(first, Set.of("First")),
			new ImmutableCardIdentityCatalog.Entry(second, Set.of("Second"))));
		Path file = temporaryFolder.newFolder().toPath().resolve("catalogue.json");
		RemoteCatalogCacheStore store = new RemoteCatalogCacheStore(gson, file);
		store.save(ambiguous, "sha256:ambiguous", null, 1234L);

		assertThrows(CatalogValidationException.class, store::load);
	}

	@Test
	public void cachedTeakIdentityPreservesMainParentAndVariantOwnership() throws Exception
	{
		Gson gson = new Gson();
		CardIdentity teak = new CardIdentity(CardEntityKind.ITEM, "Teak logs",
			Collections.emptySet(), Set.of(6333, 6211));
		OsrsTcgCatalogSnapshot snapshot = new OsrsTcgCatalogSnapshot(List.of(
			new ImmutableCardIdentityCatalog.Entry(teak,
				Set.of("Teak logs", "Teak pyre logs"))));
		Path file = temporaryFolder.newFolder().toPath().resolve("catalogue.json");
		RemoteCatalogCacheStore store = new RemoteCatalogCacheStore(gson, file);
		store.save(snapshot, "sha256:teak", "\"sha256:teak\"", 1234L);
		RemoteCatalogCacheStore.CachedCatalog loaded = store.load();

		ActiveCardIdentityCatalog active = new ActiveCardIdentityCatalog(
			new BundledCardIdentityCatalog(gson));
		active.activate(loaded.getSnapshot(), loaded.getSnapshot().getEntries(),
			loaded.getVersion());
		CardOwnershipService ownership = new CardOwnershipService(new CardResolver(active));
		TcgOwnershipSnapshot empty = TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), null);

		assertStatus(CardOwnershipService.Status.LOCKED,
			ownership.decide(CardEntityKind.ITEM, 6333, "Teak logs", empty, null, null));
		assertStatus(CardOwnershipService.Status.LOCKED,
			ownership.decide(CardEntityKind.ITEM, 6211, "Teak pyre logs",
				empty, null, null));

		TcgOwnershipSnapshot parentOwned = TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.singletonList(6333),
			Collections.emptyList(), null);
		assertStatus(CardOwnershipService.Status.OWNED,
			ownership.decide(CardEntityKind.ITEM, 6211, "Teak pyre logs",
				parentOwned, null, null));

		TcgOwnershipSnapshot variantOwned = TcgOwnershipSnapshot.fromApi(
			Collections.emptyList(), Collections.singletonList(6211),
			Collections.emptyList(), null);
		assertStatus(CardOwnershipService.Status.OWNED,
			ownership.decide(CardEntityKind.ITEM, 6333, "Teak logs",
				variantOwned, null, null));
	}

	private static void assertStatus(CardOwnershipService.Status expected,
		CardOwnershipService.Decision decision)
	{
		assertEquals(expected, decision.getStatus());
	}

	private static OsrsTcgCatalogSnapshot fixture(Gson gson) throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(
			RemoteCatalogCacheStoreTest.class.getResourceAsStream(
				"/osrs-tcg-live-catalog-fixture.json"), StandardCharsets.UTF_8))
		{
			return new OsrsTcgCatalogParser(gson).parse(reader);
		}
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class OsrsTcgCatalogParserTest
{
	private OsrsTcgCatalogParser parser;

	@Before
	public void setUp()
	{
		parser = new OsrsTcgCatalogParser(new Gson());
	}

	@Test
	public void parsesParentAndVariantIdsAndNames() throws Exception
	{
		OsrsTcgCatalogSnapshot snapshot = fixture();
		assertEquals(7, snapshot.size());
		assertSingleParent(snapshot.findById(CardEntityKind.ITEM, 555), "Water rune");
		assertSingleParent(snapshot.findById(CardEntityKind.ITEM, 12730), "Water rune");
		assertSingleParent(snapshot.findByName(CardEntityKind.ITEM, "Water rune pack"),
			"Water rune");
		assertSingleParent(snapshot.findByCardName(CardEntityKind.ITEM, "Water rune pack"),
			"Water rune");
	}

	@Test
	public void reflectsCurrentUnfinishedPotionParentMerge() throws Exception
	{
		OsrsTcgCatalogSnapshot snapshot = fixture();
		assertSingleParent(snapshot.findById(CardEntityKind.ITEM, 91), "Guam leaf");
		assertSingleParent(snapshot.findByName(CardEntityKind.ITEM, "Grimy guam leaf"),
			"Guam leaf");
	}

	@Test
	public void sameNpcNameCanResolveByDistinctIds() throws Exception
	{
		OsrsTcgCatalogSnapshot snapshot = fixture();
		assertEquals(2,
			snapshot.findByName(CardEntityKind.NPC, "strange creature").size());
		assertSingleParent(snapshot.findById(CardEntityKind.NPC, 12063), "Phantom Muspah");
		assertSingleParent(snapshot.findById(CardEntityKind.NPC, 14706),
			"Juvenile custodian stalker");
	}

	@Test
	public void equalNamesAndIdsRemainSeparatedByNamespace() throws Exception
	{
		OsrsTcgCatalogSnapshot snapshot = fixture();
		assertSingleParent(snapshot.findByName(CardEntityKind.ITEM, "Crawling hand"),
			"Crawling hand");
		assertSingleParent(snapshot.findByName(CardEntityKind.NPC, "Crawling hand"),
			"Crawling Hand");
		assertSingleParent(snapshot.findById(CardEntityKind.NPC, 0), "Tool Leprechaun");
		assertEquals(0, snapshot.getAmbiguousIdCount(CardEntityKind.ITEM));
		assertEquals(0, snapshot.getAmbiguousIdCount(CardEntityKind.NPC));
	}

	@Test
	public void derivesImmutableTrackedEntityViews() throws Exception
	{
		OsrsTcgCatalogSnapshot snapshot = fixture();
		Map<String, Set<String>> npcs = snapshot.getCardNamesByEntityName(CardEntityKind.NPC);
		assertEquals(Set.of("Phantom Muspah", "Juvenile custodian stalker"),
			npcs.get("strange creature"));
		assertThrows(UnsupportedOperationException.class,
			() -> npcs.put("new", Set.of("New")));
		assertThrows(UnsupportedOperationException.class,
			() -> npcs.get("strange creature").clear());
	}

	@Test
	public void betaAliasOverlayAddsNamesWithoutFallbackEntityAuthority() throws Exception
	{
		OsrsTcgCatalogSnapshot live = fixture();
		CardIdentity fallback = new CardIdentity(CardEntityKind.ITEM, "Water rune",
			Set.of("Historical water card"), Set.of(999999));
		OsrsTcgCatalogSnapshot enriched = live.withLegacyAliases(List.of(
			new ImmutableCardIdentityCatalog.Entry(fallback, Set.of("fallback entity"))));

		assertSingleParent(enriched.findByCardName(
			CardEntityKind.ITEM, "Historical water card"), "Water rune");
		assertTrue(enriched.findById(CardEntityKind.ITEM, 999999).isEmpty());
		assertTrue(enriched.findByName(CardEntityKind.ITEM, "fallback entity").isEmpty());
		assertSingleParent(enriched.findById(CardEntityKind.ITEM, 555), "Water rune");
	}

	@Test
	public void rejectsMissingNamespacesAndMalformedJson()
	{
		assertInvalid("{}", "items");
		assertInvalid("{\"items\":[{\"id\":1,\"name\":\"Item\",\"tcg\":{}}]}", "NPCs");
		assertInvalid("{", "malformed");
	}

	@Test
	public void rejectsInvalidParentsAndVariants()
	{
		assertInvalid(catalogue("{\"id\":-1,\"name\":\"Item\",\"tcg\":{}}",
			validNpc()), "invalid ID");
		assertInvalid(catalogue("{\"id\":1,\"name\":\" \",\"tcg\":{}}",
			validNpc()), "missing name");
		assertInvalid(catalogue("{\"id\":1,\"name\":\"Item\"}", validNpc()),
			"no tcg data");
		assertInvalid(catalogue("{\"id\":1,\"name\":\"Item\",\"tcg\":{\"variants\":[null]}}",
			validNpc()), "variant");
	}

	@Test
	public void rejectsIdsAssignedToDifferentParents()
	{
		String items = "{\"id\":1,\"name\":\"First\",\"tcg\":{}},"
			+ "{\"id\":2,\"name\":\"Second\",\"tcg\":{\"variants\":["
			+ "{\"id\":1,\"name\":\"Second variant\"}]}}";
		assertInvalid("{\"items\":[" + items + "],\"npcs\":[" + validNpc() + "]}",
			"reuses entity ID 1");
	}

	@Test
	public void harmlessDuplicateIdsWithinOneParentAreDeduplicated() throws Exception
	{
		String item = "{\"id\":1,\"name\":\"Item\",\"tcg\":{\"variants\":["
			+ "{\"id\":1,\"name\":\"Item\"},{\"id\":2,\"name\":\"Variant\"},"
			+ "{\"id\":2,\"name\":\"Variant\"}]}}";
		OsrsTcgCatalogSnapshot snapshot = parser.parse(new StringReader(
			catalogue(item, validNpc())));
		assertSingleParent(snapshot.findById(CardEntityKind.ITEM, 1), "Item");
		assertSingleParent(snapshot.findById(CardEntityKind.ITEM, 2), "Item");
	}

	@Test
	public void coinPouchRemainsAnEntityAliasButCannotOwnCoins() throws Exception
	{
		String coins = "{\"id\":617,\"name\":\"Coins\",\"tcg\":{\"variants\":["
			+ "{\"id\":995,\"name\":\"Coins\"},"
			+ "{\"id\":22521,\"name\":\"Coin pouch\"}]}}";
		OsrsTcgCatalogSnapshot snapshot = parser.parse(new StringReader(
			catalogue(coins, validNpc())));
		CardIdentity identity = snapshot.findById(CardEntityKind.ITEM, 22521).get(0);

		assertSingleParent(snapshot.findByName(CardEntityKind.ITEM, "Coin pouch"), "Coins");
		assertTrue(snapshot.findByCardName(CardEntityKind.ITEM, "Coin pouch").isEmpty());
		assertTrue(identity.getOwnedNameRequiredEntityIds().contains(22521));
		assertFalse(identity.isOwnedBy(TcgOwnershipSnapshot.namesOnly(Set.of("Coin pouch"))));
		assertFalse(identity.isOwnedBy(TcgOwnershipSnapshot.fromApi(List.of("Coin pouch"),
			List.of(22521), List.of(), null)));
		assertTrue(identity.isOwnedBy(TcgOwnershipSnapshot.fromApi(List.of("Coins"),
			List.of(22521), List.of(), null)));
		assertTrue(identity.isOwnedBy(TcgOwnershipSnapshot.fromApi(List.of(),
			List.of(995), List.of(), null)));
	}

	private OsrsTcgCatalogSnapshot fixture() throws Exception
	{
		InputStream stream = getClass().getResourceAsStream("/osrs-tcg-live-catalog-fixture.json");
		if (stream == null)
		{
			throw new AssertionError("fixture missing");
		}
		try (InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			return parser.parse(reader);
		}
	}

	private void assertInvalid(String json, String expectedMessage)
	{
		CatalogValidationException exception = assertThrows(CatalogValidationException.class,
			() -> parser.parse(new StringReader(json)));
		assertTrue(exception.getMessage(), exception.getMessage().contains(expectedMessage));
	}

	private static String catalogue(String items, String npcs)
	{
		return "{\"items\":[" + items + "],\"npcs\":[" + npcs + "]}";
	}

	private static String validNpc()
	{
		return "{\"id\":1,\"name\":\"NPC\",\"tcg\":{}}";
	}

	private static void assertSingleParent(List<CardIdentity> matches, String parentName)
	{
		assertEquals(1, matches.size());
		assertEquals(parentName, matches.get(0).getCardName());
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.ownership.BundledCardIdentityCatalog;
import com.bronzemantcg.ownership.CardEntityKind;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class RemoteCatalogServiceTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	private FakeClient client;
	private ActiveCardIdentityCatalog active;
	private RemoteCatalogService service;
	private RemoteCatalogCacheStore cacheStore;
	private AtomicInteger notifications;

	@Before
	public void setUp() throws Exception
	{
		Gson gson = new Gson();
		BundledCardIdentityCatalog bundled = new BundledCardIdentityCatalog(gson);
		active = new ActiveCardIdentityCatalog(bundled);
		client = new FakeClient();
		notifications = new AtomicInteger();
		cacheStore = new RemoteCatalogCacheStore(gson,
			Path.of(temporaryFolder.newFolder().getPath(), "catalogue.json"));
		service = new RemoteCatalogService(client, new OsrsTcgCatalogParser(gson),
			new RemoteCatalogValidator(1, 1, Map.of()), bundled, active,
			cacheStore);
		service.setListener((revision, available) -> notifications.incrementAndGet());
	}

	@Test
	public void startupRequiresExplicitEnablementAndLiveV1CapabilityBeforeFetching()
		throws Exception
	{
		service.startUp();
		assertFalse(active.isRemoteActive());
		assertEquals(0, client.fetches);

		service.setV1Capable(true);
		assertEquals(0, client.fetches);

		service.setEnabled(true);
		assertEquals(1, client.fetches);
		client.succeed(fixture(), "version-1");

		assertTrue(active.isRemoteActive());
		assertTrue(active.isV1CatalogAvailable());
		assertTrue(active.findById(CardEntityKind.ITEM, 12730).size() == 1);
		assertTrue(notifications.get() > 0);
	}

	@Test
	public void repeatedCapabilityMessagesStartOnlyOneFetch() throws Exception
	{
		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		service.setV1Capable(true);
		service.setV1Capable(true);

		assertEquals(1, client.fetches);
		client.succeed(fixture(), "version-1");

		assertTrue(active.isRemoteActive());
		assertTrue(notifications.get() > 0);
	}

	@Test
	public void losingCapabilityReturnsToBundleButKeepsValidatedPendingRevision()
		throws Exception
	{
		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		client.succeed(fixture(), "version-1");
		assertTrue(active.isRemoteActive());

		service.setV1Capable(false);
		assertFalse(active.isRemoteActive());
		assertFalse(active.isV1CatalogAvailable());

		service.setV1Capable(true);
		assertTrue(active.isRemoteActive());
		assertEquals(1, client.fetches);
		assertTrue(notifications.get() >= 3);
	}

	@Test
	public void responseWhileCapabilityIsLostRemainsPendingWithoutRefetching()
		throws Exception
	{
		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		service.setV1Capable(false);
		client.succeed(fixture(), "version-1");

		assertFalse(active.isRemoteActive());
		service.setV1Capable(true);

		assertTrue(active.isRemoteActive());
		assertEquals(1, client.fetches);
	}

	@Test
	public void invalidResponseAndLateShutdownCallbackNeverActivate()
	{
		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		client.succeed("{}".getBytes(StandardCharsets.UTF_8), "invalid");
		assertFalse(active.isRemoteActive());

		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		service.shutDown();
		client.succeed("{}".getBytes(StandardCharsets.UTF_8), "late");
		assertFalse(active.isRemoteActive());
	}

	@Test
	public void disablingCancelsFetchRejectsLateResponseAndAllowsRefetch() throws Exception
	{
		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		OsrsTcgCatalogClient.FetchHandle firstHandle = client.handles.get(0);

		service.setEnabled(false);

		assertTrue(firstHandle.isCancelled());
		assertFalse(active.isRemoteActive());
		client.succeed(0, fixture(), "cancelled-version");
		assertFalse(active.isRemoteActive());

		service.setEnabled(true);
		assertEquals(2, client.fetches);
		client.succeed(1, fixture(), "enabled-version");
		assertTrue(active.isRemoteActive());
	}

	@Test
	public void restartActivatesCompactCacheAndConditionallyValidatesItsEtag()
		throws Exception
	{
		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		client.succeed(fixture(), "version-1");
		service.shutDown();

		Gson gson = new Gson();
		BundledCardIdentityCatalog bundled = new BundledCardIdentityCatalog(gson);
		active = new ActiveCardIdentityCatalog(bundled);
		client = new FakeClient();
		service = new RemoteCatalogService(client, new OsrsTcgCatalogParser(gson),
			new RemoteCatalogValidator(1, 1, Map.of()), bundled, active, cacheStore);
		service.startUp();
		assertFalse(active.isRemoteActive());

		service.setEnabled(true);
		assertFalse(active.isRemoteActive());
		assertEquals(0, client.fetches);

		service.setV1Capable(true);

		assertTrue(active.isRemoteActive());
		assertEquals(1, client.fetches);
		assertEquals("\"version-1\"", client.etags.get(0));
		client.notModified("version-1");
		assertTrue(active.isRemoteActive());

		service.setEnabled(false);
		assertFalse(active.isRemoteActive());
		service.setEnabled(true);
		assertTrue(active.isRemoteActive());
		assertEquals(2, client.fetches);
		assertEquals("\"version-1\"", client.etags.get(1));
		client.fail("offline");
		assertTrue(active.isRemoteActive());
	}

	@Test
	public void malformedCacheRemainsInactiveAndIsNotUsedForConditionalFetch()
		throws Exception
	{
		Files.writeString(cacheStore.getCacheFile(), "{broken", StandardCharsets.UTF_8);

		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);

		assertFalse(active.isRemoteActive());
		assertEquals(1, client.fetches);
		assertNull(client.etags.get(0));

		client.succeed(fixture(), "replacement");
		assertTrue(active.isRemoteActive());
		assertEquals("replacement", cacheStore.load().getVersion());
	}

	@Test
	public void validatedResponseRemainsActiveWhenCacheWriteFails() throws Exception
	{
		Path cacheTarget = temporaryFolder.newFolder().toPath().resolve("catalogue.json");
		Files.createDirectory(cacheTarget);
		Gson gson = new Gson();
		BundledCardIdentityCatalog bundled = new BundledCardIdentityCatalog(gson);
		active = new ActiveCardIdentityCatalog(bundled);
		client = new FakeClient();
		service = new RemoteCatalogService(client, new OsrsTcgCatalogParser(gson),
			new RemoteCatalogValidator(1, 1, Map.of()), bundled, active,
			new RemoteCatalogCacheStore(gson, cacheTarget));

		service.startUp();
		service.setEnabled(true);
		service.setV1Capable(true);
		client.succeed(fixture(), "session-only");

		assertTrue(active.isRemoteActive());
	}

	private static byte[] fixture() throws IOException
	{
		try (InputStream stream = RemoteCatalogServiceTest.class
			.getResourceAsStream("/osrs-tcg-live-catalog-fixture.json"))
		{
			if (stream == null)
			{
				throw new IOException("fixture missing");
			}
			return stream.readAllBytes();
		}
	}

	private static final class FakeClient extends OsrsTcgCatalogClient
	{
		private final List<Listener> listeners = new ArrayList<>();
		private final List<FetchHandle> handles = new ArrayList<>();
		private final List<String> etags = new ArrayList<>();
		private int fetches;

		private FakeClient()
		{
			super(new OkHttpClient());
		}

		@Override
		public FetchHandle fetch(String currentEtag, Listener listener)
		{
			fetches++;
			listeners.add(listener);
			etags.add(currentEtag);
			FetchHandle handle = new FetchHandle();
			handles.add(handle);
			return handle;
		}

		private void succeed(byte[] body, String version)
		{
			succeed(listeners.size() - 1, body, version);
		}

		private void succeed(int index, byte[] body, String version)
		{
			listeners.get(index).onSuccess(new CatalogResponse(body, version,
				"\"" + version + "\""));
		}

		private void notModified(String version)
		{
			listeners.get(listeners.size() - 1).onSuccess(
				CatalogResponse.notModified(version, "\"" + version + "\""));
		}

		private void fail(String reason)
		{
			listeners.get(listeners.size() - 1).onFailure(reason,
				new IOException(reason));
		}
	}
}

