package com.bronzemantcg;

import com.bronzemantcg.catalog.QuestCatalog;
import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.panel.collection.PanelCollectionLayout;
import com.bronzemantcg.panel.collection.PanelCollectionOwnership;
import com.bronzemantcg.panel.collection.PanelCollectionViewModel;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PvmV1CatalogTest
{
	private final Gson gson = new Gson();
	private final PanelCollectionLayout collectionCatalog =
		new PanelCollectionLayout(gson);
	private final PanelCollectionViewModel collectionViewModel;

	public PvmV1CatalogTest()
	{
		com.bronzemantcg.ownership.ActiveCardIdentityCatalog active =
			new com.bronzemantcg.ownership.ActiveCardIdentityCatalog(
				new com.bronzemantcg.ownership.BundledCardIdentityCatalog(gson));
		LiveV1CatalogTestSupport.activate(active);
		collectionViewModel = new PanelCollectionViewModel(collectionCatalog,
			new PanelCollectionOwnership(collectionCatalog), active);
	}

	@Test
	public void pvmContentContainsOnlyUniqueCanonicalV1NpcParents()
	{
		assertCanonical(contentResource().contents);
	}

	@Test
	public void tombsOfAmascutUsesTheTwentyReviewedV1Parents()
	{
		Group tombs = contentResource().contents.stream()
			.filter(group -> group.name.equals("Tombs of Amascut"))
			.findFirst().orElseThrow(AssertionError::new);

		assertEquals(20, tombs.monsterCards.size());
		assertTrue(tombs.monsterCards.containsAll(
			Arrays.asList("Akkha", "Scarab", "The Wardens")));
		assertFalse(tombs.monsterCards.contains("Akkha's Shadow"));
		assertFalse(tombs.monsterCards.contains("Akkha's Phantom"));
		assertFalse(tombs.monsterCards.contains("Ba-Ba's Phantom"));
		assertFalse(tombs.monsterCards.contains("Kephri's Phantom"));
		assertFalse(tombs.monsterCards.contains("Elidinis' Warden"));
		assertFalse(tombs.monsterCards.contains("Tumeken's Warden"));
		assertFalse(tombs.monsterCards.contains("Scarab (Tombs of Amascut)"));
	}

	@Test
	public void reviewedBetaNamesSatisfyTheirCanonicalPvmParent()
	{
		assertAliasSatisfies("Akkha", "Akkha's Shadow");
		assertAliasSatisfies("The Wardens", "Elidinis' Warden");
		assertAliasSatisfies("The Wardens", "Tumeken's Warden");
		assertAliasSatisfies("Scarab", "Scarab (Tombs of Amascut)");
	}

	private void assertCanonical(List<Group> groups)
	{
		for (Group group : groups)
		{
			Set<String> unique = new LinkedHashSet<>(group.monsterCards);
			assertEquals(group.name + " contains a duplicate parent",
				group.monsterCards.size(), unique.size());
			for (String name : group.monsterCards)
			{
				PanelCollectionLayout.CollectionCard card = collectionViewModel
					.findCard(CardEntityKind.NPC, name)
					.orElseThrow(() -> new AssertionError(
						group.name + " does not use a v1 NPC parent: " + name));
				assertEquals(card.getCardName(), name);
			}
		}
	}

	private void assertAliasSatisfies(String parentName, String ownedName)
	{
		PanelCollectionLayout.CollectionCard card = collectionViewModel
			.findCard(CardEntityKind.NPC, parentName)
			.orElseThrow(AssertionError::new);
		QuestCatalog.Requirement requirement = new QuestCatalog.Requirement(
			card.getCardName(), new ArrayList<>(card.getAcceptedNamesLowerCase()));

		assertTrue(requirement.isSatisfied(
			Collections.singleton(ownedName.toLowerCase(java.util.Locale.ROOT))));
		assertTrue(requirement.isSatisfied(
			Collections.singleton(parentName.toLowerCase(java.util.Locale.ROOT))));
	}

	private ContentSnapshot contentResource()
	{
		try (InputStream stream = Objects.requireNonNull(
			PvmV1CatalogTest.class.getResourceAsStream("/panel/content_cards.json"),
			"Missing test resource: /panel/content_cards.json"))
		{
			return gson.fromJson(new InputStreamReader(stream, StandardCharsets.UTF_8),
				ContentSnapshot.class);
		}
		catch (IOException ex)
		{
			throw new AssertionError("Unable to close content resource", ex);
		}
	}

	@SuppressWarnings({"unused", "MismatchedQueryAndUpdateOfCollection"})
	private static final class ContentSnapshot
	{
		private List<Group> contents;
	}

	@SuppressWarnings({"unused", "MismatchedQueryAndUpdateOfCollection"})
	private static final class Group
	{
		private String name;
		private List<String> monsterCards;
	}
}

package com.bronzemantcg;

import com.bronzemantcg.catalog.QuestCatalog;
import com.bronzemantcg.catalog.QuestRequirementCatalog;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class QuestRequirementCatalogTest
{
	private final QuestRequirementCatalog catalog = new QuestRequirementCatalog(new Gson());
	private final QuestCatalog questCatalog = new QuestCatalog(new Gson());

	private static int[] levels(Skill skill, int level)
	{
		int[] values = new int[Skill.values().length];
		values[skill.ordinal()] = level;
		return values;
	}

	@Test
	public void everyEntryNamesAKnownQuest()
	{
		Set<String> known = new HashSet<>();
		for (QuestCatalog.QuestEntry entry : questCatalog.getQuests())
		{
			known.add(entry.name.toLowerCase(Locale.ROOT));
		}
		for (QuestCatalog.QuestEntry entry : questCatalog.getMiniquests())
		{
			known.add(entry.name.toLowerCase(Locale.ROOT));
		}
		int matched = 0;
		for (String name : known)
		{
			if (catalog.get(name) != null)
			{
				matched++;
			}
		}
		// Every requirement entry must correspond to a quest we actually display,
		// otherwise the filter silently gates nothing.
		assertEquals(catalog.size(), matched);
	}

	@Test
	public void skillPrerequisiteAndQuestPointGatesAreLoaded()
	{
		QuestRequirementCatalog.Requirements mm2 = catalog.get("Monkey Madness II");
		assertNotNull(mm2);
		assertTrue(mm2.skills.stream()
			.anyMatch(s -> s.skill == Skill.SLAYER && s.level == 69));
		assertTrue(mm2.quests.stream()
			.anyMatch(q -> q.quest == Quest.RECIPE_FOR_DISASTER__KING_AWOWOGEI));

		QuestRequirementCatalog.Requirements dragonSlayer = catalog.get("Dragon Slayer I");
		assertNotNull(dragonSlayer);
		assertEquals(32, dragonSlayer.questPoints);
	}

	@Test
	public void lookupIsCaseInsensitiveAndAbsentQuestsAreUnrestricted()
	{
		assertNotNull(catalog.get("dragon slayer i"));
		assertNull(catalog.get("Cook's Assistant"));
		assertNull(catalog.get("no such quest"));
	}

	@Test
	public void unknownLevelsLeaveTheFilterInert()
	{
		QuestRequirementCatalog.Requirements mm2 = catalog.get("Monkey Madness II");
		// Logged out: levels are null, so nothing may be hidden.
		assertTrue(mm2.isMet(null, 0, Collections.emptySet()));
	}

	@Test
	public void strictLevelsAndPrerequisitesAreEnforced()
	{
		QuestRequirementCatalog.Requirements enterTheAbyss = catalog.get("Enter the Abyss");
		assertNotNull(enterTheAbyss);
		int[] noLevels = new int[Skill.values().length];
		assertFalse(enterTheAbyss.isMet(noLevels, 0, Collections.emptySet()));
		assertTrue(enterTheAbyss.isMet(noLevels, 0,
			Collections.singleton(Quest.RUNE_MYSTERIES.getName().toLowerCase(Locale.ROOT))));

		QuestRequirementCatalog.Requirements dragonSlayer = catalog.get("Dragon Slayer I");
		assertFalse(dragonSlayer.isMet(noLevels, 31, Collections.emptySet()));
		assertTrue(dragonSlayer.isMet(noLevels, 32, Collections.emptySet()));
	}

	@Test
	public void boostsAreNotHonoured()
	{
		QuestRequirementCatalog.Requirements coldWar = catalog.get("Cold War");
		assertNotNull(coldWar);
		QuestRequirementCatalog.SkillRequirement first = coldWar.skills.get(0);
		assertFalse(coldWar.isMet(levels(first.skill, first.level - 1), 0,
			Collections.emptySet()));
	}

	@Test
	public void displayOnlyNotesNeverAffectTheFilter()
	{
		QuestRequirementCatalog.Requirements boneVoyage = catalog.get("Bone Voyage");
		assertNotNull(boneVoyage);
		assertFalse(boneVoyage.other.isEmpty());
		// The Kudos gate is display-only: owning the prerequisite quest is enough.
		assertTrue(boneVoyage.isMet(new int[Skill.values().length], 0,
			Collections.singleton(Quest.THE_DIG_SITE.getName().toLowerCase(Locale.ROOT))));
	}
}

package com.bronzemantcg.overlay;

import com.bronzemantcg.BronzemanTcgConfig;
import com.bronzemantcg.feature.GroundItemLockTracker;
import com.bronzemantcg.restriction.RestrictionDecisionService;
import com.bronzemantcg.restriction.NpcVisibilityMode;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Marks NPCs whose card hasn't been collected with a grey model outline (the same
 * silhouette-hugging renderer NPC Indicators uses, in "disabled grey" rather than a
 * highlight colour). Runs on the client thread each frame and delegates the lock decision
 * to the same ID-aware boundary as NPC enforcement.
 */
@Singleton
public class BronzemanTcgOverlay extends Overlay
{
	private final Client client;
	private final BronzemanTcgConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;
	private final RestrictionDecisionService restrictionDecisionService;
	private final GroundItemLockTracker groundItemLockTracker;

	@Inject
	public BronzemanTcgOverlay(Client client, BronzemanTcgConfig config,
		ModelOutlineRenderer modelOutlineRenderer,
		RestrictionDecisionService restrictionDecisionService,
		GroundItemLockTracker groundItemLockTracker)
	{
		this.client = client;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		this.restrictionDecisionService = restrictionDecisionService;
		this.groundItemLockTracker = groundItemLockTracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Hidden entities never render, so outlining them would just draw over scenery.
		boolean outlineNpcs = config.tintLockedNpcs()
			&& config.npcVisibilityMode() != NpcVisibilityMode.HIDE
			&& !restrictionDecisionService.isEnforcementBypassed();
		// Deliberately not gated on groundItemsMode: the outline says "you do not own this
		// card", which stays true and useful even when pickup itself is allowed.
		boolean outlineGroundItems = config.tintLockedGroundItems()
			&& !restrictionDecisionService.isEnforcementBypassed();
		if (!outlineNpcs && !outlineGroundItems)
		{
			return null;
		}

		// NPCs live on the WorldView now (multi-world support); the old Client.getNpcs()
		// is a deprecated pass-through. Top level = the player's own world. Null before
		// the world exists (login screen), where there is nothing to outline anyway.
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}
		Color color = config.lockedOutlineColor();
		int width = config.lockedOutlineWidth();
		int feather = config.lockedOutlineFeather();
		if (outlineNpcs)
		{
			for (NPC npc : worldView.npcs())
			{
				if (!restrictionDecisionService.isNpcLocked(npc))
				{
					continue;
				}
				modelOutlineRenderer.drawOutline(npc, width, color, feather);
			}
		}

		if (outlineGroundItems)
		{
			// blocked is precomputed, so this does no name lookups or allocation per frame.
			for (Map.Entry<TileItem, GroundItemLockTracker.TrackedGroundItem> entry
				: groundItemLockTracker.getTrackedItems().entrySet())
			{
				GroundItemLockTracker.TrackedGroundItem tracked = entry.getValue();
				if (!tracked.isBlocked() || tracked.getTile() == null
					|| tracked.getTile().getItemLayer() == null)
				{
					continue;
				}
				modelOutlineRenderer.drawOutline(
					tracked.getTile().getItemLayer(), entry.getKey(), width, color, feather);
			}
		}
		return null;
	}
}

package com.bronzemantcg.overlay;

import com.bronzemantcg.feature.LockedItemMarkController;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Draws a small bank-filler badge centred on locked items when the mark mode asks
 * for it. The badge rides on top of the widget-opacity fade applied by the marking
 * controller; this overlay draws and never mutates widgets.
 */
@Singleton
public class LockedItemIconOverlay extends WidgetItemOverlay
{
	// Owner's spec: centred, ~60% of the sprite so the faded item stays identifiable.
	private static final double ICON_SCALE = 0.6;

	private final LockedItemMarkController lockedItemMarkController;
	private final ItemManager itemManager;

	@Inject
	public LockedItemIconOverlay(LockedItemMarkController lockedItemMarkController, ItemManager itemManager)
	{
		this.lockedItemMarkController = lockedItemMarkController;
		this.itemManager = itemManager;
		showOnInventory();
		showOnBank();
		showOnInterfaces(
			net.runelite.api.gameval.InterfaceID.SHOPMAIN,
			net.runelite.api.gameval.InterfaceID.SHOPSIDE);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!lockedItemMarkController.shouldDrawIcon(itemId))
		{
			return;
		}
		// Item sprites carry their own transparency, so this drops straight on top.
		// AsyncBufferedImage draws blank until the sprite loads; it self-corrects
		// on a later frame, so no load callback is needed.
		BufferedImage icon = itemManager.getImage(ItemID.BANK_FILLER);
		if (icon == null)
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		int w = (int) (bounds.width * ICON_SCALE);
		int h = (int) (bounds.height * ICON_SCALE);
		graphics.drawImage(icon,
			bounds.x + (bounds.width - w) / 2,
			bounds.y + (bounds.height - h) / 2,
			w, h, null);
	}
}

package com.bronzemantcg.interop;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/** Coordinates the read-only PluginMessage ownership API exposed by OSRS TCG. */
@Slf4j
@Singleton
public final class OsrsTcgInteropService
{
	private static final String API_NAMESPACE = "osrstcg";
	private static final String API_QUERY = "query-owned-names";
	private static final String API_REPLY = "owned-names";
	private static final String API_CHANGED = "owned-names-changed";
	private static final String API_NAMES_KEY = "ownedNames";
	private static final String API_ITEM_IDS_KEY = "ownedItemIds";
	private static final String API_NPC_IDS_KEY = "ownedNpcIds";
	private static final String API_GROUP_KEY = "groupKey";
	// ~60s between retries while unanswered. Older OSRS TCG versions simply never answer,
	// and TcgCollectionReader continues serving their persisted-state fallback.
	private static final int QUERY_RETRY_TICKS = 100;

	private final TcgCollectionReader collectionReader;
	private final EventBus eventBus;

	private int queryTicks = -1;

	@Inject
	public OsrsTcgInteropService(TcgCollectionReader collectionReader, EventBus eventBus)
	{
		this.collectionReader = collectionReader;
		this.eventBus = eventBus;
	}

	/**
	 * Drops any API snapshot retained from a previous run and arms the first query. The
	 * query is posted from a tick because this plugin's subscribers are registered only
	 * after startUp returns, and EventBus posting is synchronous.
	 */
	public void startUp()
	{
		resetForCurrentProfile();
	}

	/** Drops the previous profile's ownership and asks OSRS TCG for the new profile. */
	public void onProfileChanged()
	{
		resetForCurrentProfile();
	}

	/** Posts the initial/retry query and stops polling once an API payload is accepted. */
	public void onGameTick()
	{
		if (queryTicks < 0 || --queryTicks >= 0)
		{
			return;
		}

		if (!collectionReader.hasApiData())
		{
			eventBus.post(new PluginMessage(API_NAMESPACE, API_QUERY));
		}
		// EventBus.post is synchronous, so an answered query has already installed API
		// data by this point. Push updates keep it current after the first reply.
		queryTicks = collectionReader.hasApiData() ? -1 : QUERY_RETRY_TICKS;
	}

	/** Validates and applies an OSRS TCG ownership reply or unsolicited push. */
	public UpdateResult onPluginMessage(PluginMessage event)
	{
		if (event == null || !API_NAMESPACE.equals(event.getNamespace())
			|| (!API_REPLY.equals(event.getName()) && !API_CHANGED.equals(event.getName())))
		{
			return UpdateResult.IGNORED;
		}

		Map<String, Object> data = event.getData();
		Object names = data == null ? null : data.get(API_NAMES_KEY);
		if (!(names instanceof List))
		{
			return UpdateResult.IGNORED;
		}

		boolean firstPayload = !collectionReader.hasApiData();
		Object itemIds = data.get(API_ITEM_IDS_KEY);
		Object npcIds = data.get(API_NPC_IDS_KEY);
		Object groupKey = data.get(API_GROUP_KEY);
		collectionReader.onApiOwnership((List<?>) names,
			itemIds instanceof List ? (List<?>) itemIds : null,
			npcIds instanceof List ? (List<?>) npcIds : null,
			groupKey instanceof String ? (String) groupKey : null);

		if (firstPayload)
		{
			log.info("osrs-tcg PluginMessage API active; collection now push-updated.");
			return UpdateResult.FIRST_UPDATE;
		}
		return UpdateResult.UPDATED;
	}

	private void resetForCurrentProfile()
	{
		collectionReader.invalidate();
		queryTicks = 0;
	}

	public enum UpdateResult
	{
		IGNORED(false, false),
		UPDATED(true, false),
		FIRST_UPDATE(true, true);

		private final boolean accepted;
		private final boolean firstPayload;

		UpdateResult(boolean accepted, boolean firstPayload)
		{
			this.accepted = accepted;
			this.firstPayload = firstPayload;
		}

		public boolean isAccepted()
		{
			return accepted;
		}

		public boolean isFirstPayload()
		{
			return firstPayload;
		}
	}
}

