package com.bronzemantcg.interop;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** One explicit, privacy-sensitive lookup against the OSRS TCG player API. */
@Singleton
public class BetaCardLookupClient
{
	static final String PLAYERS_URL = "https://osrs-tcg.net/api/v1/players";
	static final int MAX_RESPONSE_BYTES = 1024 * 1024;
	private static final CacheControl NO_STORAGE =
		new CacheControl.Builder().noCache().noStore().build();

	private final OkHttpClient httpClient;
	private final HttpUrl playersUrl;
	private final int maximumResponseBytes;

	@Inject
	public BetaCardLookupClient(OkHttpClient httpClient)
	{
		this(httpClient, PLAYERS_URL, MAX_RESPONSE_BYTES);
	}

	protected BetaCardLookupClient(OkHttpClient httpClient, String playersUrl,
		int maximumResponseBytes)
	{
		if (httpClient == null || playersUrl == null || maximumResponseBytes <= 0)
		{
			throw new IllegalArgumentException("HTTP client, endpoint and size limit are required");
		}
		this.httpClient = httpClient.newBuilder().callTimeout(20, TimeUnit.SECONDS).build();
		this.playersUrl = HttpUrl.get(playersUrl);
		this.maximumResponseBytes = maximumResponseBytes;
	}

	public FetchHandle fetch(String displayName, Listener listener)
	{
		if (displayName == null || displayName.trim().isEmpty() || listener == null)
		{
			throw new IllegalArgumentException("display name and listener are required");
		}
		HttpUrl url = playersUrl.newBuilder()
			.addPathSegment(displayName.trim())
			.addPathSegment("beta-names")
			.build();
		Request request = new Request.Builder().url(url).get().cacheControl(NO_STORAGE).build();
		FetchHandle handle = new FetchHandle();
		Call call = httpClient.newCall(request);
		handle.setCall(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call failedCall, @Nonnull IOException exception)
			{
				if (!handle.isCancelled())
				{
					listener.onFailure(exception);
				}
			}

			@Override
			public void onResponse(@Nonnull Call completedCall, @Nonnull Response response)
			{
				try (Response closeable = response)
				{
					if (handle.isCancelled())
					{
						return;
					}
					ResponseBody body = response.body();
					byte[] bytes = body == null ? new byte[0] : readBounded(body);
					if (!handle.isCancelled())
					{
						listener.onResponse(new LookupResponse(response.code(), bytes));
					}
				}
				catch (IOException exception)
				{
					if (!handle.isCancelled())
					{
						listener.onFailure(exception);
					}
				}
			}
		});
		return handle;
	}

	private byte[] readBounded(ResponseBody body) throws IOException
	{
		long contentLength = body.contentLength();
		if (contentLength > maximumResponseBytes)
		{
			throw new IOException("player response exceeds size limit");
		}
		try (InputStream input = body.byteStream();
			ByteArrayOutputStream output = new ByteArrayOutputStream(
				contentLength > 0 ? (int) contentLength : 4096))
		{
			byte[] buffer = new byte[8192];
			int total = 0;
			int read;
			while ((read = input.read(buffer)) != -1)
			{
				total += read;
				if (total > maximumResponseBytes)
				{
					throw new IOException("player response exceeds size limit");
				}
				output.write(buffer, 0, read);
			}
			return output.toByteArray();
		}
	}

	public interface Listener
	{
		void onResponse(LookupResponse response);

		void onFailure(Throwable cause);
	}

	public static final class LookupResponse
	{
		private final int statusCode;
		private final byte[] body;

		public LookupResponse(int statusCode, byte[] body)
		{
			this.statusCode = statusCode;
			this.body = body.clone();
		}

		public int getStatusCode()
		{
			return statusCode;
		}

		public byte[] getBody()
		{
			return body.clone();
		}
	}

	public static final class FetchHandle
	{
		private final AtomicBoolean cancelled = new AtomicBoolean();
		private final AtomicReference<Call> call = new AtomicReference<>();

		public void cancel()
		{
			cancelled.set(true);
			Call active = call.getAndSet(null);
			if (active != null)
			{
				active.cancel();
			}
		}

		public boolean isCancelled()
		{
			return cancelled.get();
		}

		private void setCall(Call active)
		{
			call.set(active);
			if (cancelled.get() && call.compareAndSet(active, null))
			{
				active.cancel();
			}
		}
	}
}

package com.bronzemantcg.interop;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Objects;
import java.util.zip.GZIPInputStream;
import lombok.extern.slf4j.Slf4j;

/**
 * Mirrors osrs-tcg's TcgStateStorageEncoding decode routine.
 * Reimplemented here (not imported) so this plugin has no compile-time
 * dependency on the osrs-tcg plugin. The encoding is a simple, fixed,
 * publicly-known transform. Legacy v2 uses gzip -> XOR -> base64, while v3
 * uses gzip -> base64. There is nothing secret being reversed here; these
 * are osrs-tcg's own persisted formats.
 */
@Slf4j
public final class TcgStateDecoder
{
	static final String STORAGE_PREFIX_V2 = "RLTCG_v2:";
	static final String STORAGE_PREFIX_V3 = "RLTCG_v3:";
	private static final int MAX_STORED_CHARS = 16 * 1024 * 1024;
	private static final int MAX_DECODED_BYTES = 16 * 1024 * 1024;

	// Must match osrs-tcg's TcgStateStorageEncoding.XOR_SALT exactly.
	private static final byte[] XOR_SALT = {
		(byte) 0x52, (byte) 0x4c, (byte) 0x54, (byte) 0x43, (byte) 0x47,
		(byte) 0x7c, (byte) 0x6f, (byte) 0x73, (byte) 0x72, (byte) 0x73,
		(byte) 0x2d, (byte) 0x74, (byte) 0x63, (byte) 0x67, (byte) 0x21,
	};

	private TcgStateDecoder()
	{
	}

	/**
	 * @param stored the raw string from ConfigManager.getRSProfileConfiguration("osrstcg", "state")
	 * @return decoded plain JSON, or empty string if missing/corrupt/wrong format
	 */
	public static String decode(String stored)
	{
		String s = Objects.requireNonNullElse(stored, "");
		if (s.length() > MAX_STORED_CHARS)
		{
			return "";
		}

		try
		{
			byte[] compressed;
			if (s.startsWith(STORAGE_PREFIX_V3))
			{
				compressed = Base64.getDecoder().decode(s.substring(STORAGE_PREFIX_V3.length()));
			}
			else if (s.startsWith(STORAGE_PREFIX_V2))
			{
				compressed = Base64.getDecoder().decode(s.substring(STORAGE_PREFIX_V2.length()));
				xorWithSalt(compressed);
			}
			else
			{
				return "";
			}
			return gzipDecompress(compressed);
		}
		catch (IllegalArgumentException | IOException ex)
		{
			log.debug("Failed to decode osrs-tcg state (format may have changed upstream)", ex);
			return "";
		}
	}

	private static String gzipDecompress(byte[] compressed) throws IOException
	{
		try (GZIPInputStream gzis = new GZIPInputStream(new ByteArrayInputStream(compressed)))
		{
			ByteArrayOutputStream output = new ByteArrayOutputStream();
			byte[] buffer = new byte[8192];
			int total = 0;
			int read;
			while ((read = gzis.read(buffer)) >= 0)
			{
				total += read;
				if (total > MAX_DECODED_BYTES)
				{
					throw new IOException("decoded osrs-tcg state exceeds size limit");
				}
				output.write(buffer, 0, read);
			}
			return output.toString(StandardCharsets.UTF_8);
		}
	}

	private static void xorWithSalt(byte[] data)
	{
		for (int i = 0; i < data.length; i++)
		{
			data[i] ^= XOR_SALT[i % XOR_SALT.length];
		}
	}
}

package com.bronzemantcg.interop;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Single source of truth for the player's osrs-tcg collection, with two ways in:
 *
 * 1. Preferred: osrs-tcg's PluginMessage API. The plugin forwards "owned-names" /
 *    "owned-names-changed" payloads here via {@link #onApiOwnership}, giving an
 *    already-decoded, push-updated snapshot with no polling.
 * 2. Fallback: decoding osrs-tcg's persisted ConfigManager state, for hub versions
 *    that predate the API. No compile-time dependency either way - just published
 *    config group/key names (the standard pattern for unrelated Hub plugins).
 *
 * Once any API payload arrives, it wins until {@link #invalidate()} (profile switch),
 * after which we fall back to config until the next payload.
 *
 * The fallback is cached and refreshed lazily rather than decoded on every menu click,
 * since gzip decode on every single click would be wasteful. A short cache window is
 * fine here: worst case you can attack something you *just* unlocked for a few seconds
 * longer than necessary, which is a harmless direction to be stale in.
 */
@Slf4j
@Singleton
public class TcgCollectionReader
{
	private static final String TCG_CONFIG_GROUP = "osrstcg";
	private static final String TCG_STATE_KEY = "state";
	private static final long CACHE_MILLIS = 5_000L;

	private final ConfigManager configManager;
	private final Gson gson;

	private Set<String> cachedOwnedLowerCaseNames = Collections.emptySet();
	private TcgOwnershipSnapshot cachedFallbackOwnership =
		TcgOwnershipSnapshot.namesOnly(Collections.emptySet());
	private boolean stateAvailable;
	private long lastRefreshMs = 0L;
	// Null until the first API payload lands; non-null means the API path is live.
	private TcgOwnershipSnapshot apiOwnership;

	@Inject
	public TcgCollectionReader(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * @return lower-cased set of every card name the player currently owns (foil or not,
	 *         collapsed - owning either counts as "collected" for restriction purposes).
	 */
	public synchronized Set<String> getOwnedCardNamesLowerCase()
	{
		if (apiOwnership != null)
		{
			return apiOwnership.getOwnedCardNamesLowerCase();
		}
		ensureFresh();
		return cachedOwnedLowerCaseNames;
	}

	/** False when osrs-tcg has no readable state (not installed, no data yet, or decode failure). */
	public synchronized boolean isStateAvailable()
	{
		if (apiOwnership != null)
		{
			return true;
		}
		ensureFresh();
		return stateAvailable;
	}

	/** True once an API payload has arrived; the plugin stops re-querying at that point. */
	public synchronized boolean hasApiData()
	{
		return apiOwnership != null;
	}

	/** A live v1-capable payload supplies both ID namespaces; empty lists are valid. */
	public synchronized boolean hasLiveV1Capability()
	{
		return apiOwnership != null
			&& apiOwnership.hasEntityIds(CardEntityKind.ITEM)
			&& apiOwnership.hasEntityIds(CardEntityKind.NPC);
	}

	/**
	 * Feed in the ownership payload from osrs-tcg's PluginMessage API. Elements are
	 * validated individually rather than trusting the cast - the data map is untyped, and
	 * a malformed payload should degrade to the config fallback, not throw on a click.
	 */
	public synchronized void onApiOwnership(List<?> names, List<?> itemIds,
		List<?> npcIds, String groupKey)
	{
		if (names == null)
		{
			return;
		}
		apiOwnership = TcgOwnershipSnapshot.fromApi(names, itemIds, npcIds, groupKey);
	}

	/** Current API snapshot, or a name-only view of the persisted-state fallback. */
	public synchronized TcgOwnershipSnapshot getOwnershipSnapshot()
	{
		if (apiOwnership != null)
		{
			return apiOwnership;
		}
		ensureFresh();
		return cachedFallbackOwnership;
	}

	private void ensureFresh()
	{
		if (System.currentTimeMillis() - lastRefreshMs >= CACHE_MILLIS)
		{
			refresh();
		}
	}

	/**
	 * Call after profile switches / logins so a stale cache from a different account never
	 * lingers. Drops API data too - it described the previous profile's collection - so we
	 * serve the config fallback until the re-query for the new profile is answered.
	 */
	public synchronized void invalidate()
	{
		lastRefreshMs = 0L;
		apiOwnership = null;
	}

	private void refresh()
	{
		lastRefreshMs = System.currentTimeMillis();
		try
		{
			String raw = configManager.getRSProfileConfiguration(TCG_CONFIG_GROUP, TCG_STATE_KEY);
			PersistedState parsed = parsePersistedState(raw, gson);
			String json = parsed.json;
			if (json.isEmpty())
			{
				cachedOwnedLowerCaseNames = Collections.emptySet();
				cachedFallbackOwnership = TcgOwnershipSnapshot.namesOnly(cachedOwnedLowerCaseNames);
				stateAvailable = false;
				return;
			}

			if (!parsed.collectionPresent)
			{
				cachedOwnedLowerCaseNames = Collections.emptySet();
				cachedFallbackOwnership = TcgOwnershipSnapshot.namesOnly(cachedOwnedLowerCaseNames);
				stateAvailable = false;
				return;
			}
			stateAvailable = true;

			Set<String> names = new HashSet<>(parsed.ownedNames);
			cachedOwnedLowerCaseNames = Collections.unmodifiableSet(names);
			cachedFallbackOwnership = TcgOwnershipSnapshot.namesOnly(cachedOwnedLowerCaseNames);
		}
		catch (Exception ex)
		{
			// osrs-tcg not installed, no data yet, or its storage format changed upstream.
			// Fail safe to "own nothing known" rather than crash the client.
			log.debug("Could not read osrs-tcg collection state", ex);
			cachedOwnedLowerCaseNames = Collections.emptySet();
			cachedFallbackOwnership = TcgOwnershipSnapshot.namesOnly(cachedOwnedLowerCaseNames);
			stateAvailable = false;
		}
	}

	static PersistedState parsePersistedState(String raw, Gson gson)
	{
		String json = TcgStateDecoder.decode(raw);
		if (json.isEmpty() || gson == null)
		{
			return PersistedState.unavailable();
		}

		TcgStateDto dto = gson.fromJson(json, TcgStateDto.class);
		if (dto == null)
		{
			return PersistedState.unavailable();
		}

		Set<String> ownedNames = new HashSet<>();
		boolean collectionPresent;
		if (dto.cardEntries != null
			&& (!dto.cardEntries.isEmpty() || dto.cardInstances == null))
		{
			collectionPresent = true;
			for (TcgStateDto.CardEntryDto entry : dto.cardEntries)
			{
				String name = normalizedName(entry == null ? null : entry.cardName);
				if (name == null || entry.variants == null)
				{
					continue;
				}
				boolean owned = false;
				for (TcgStateDto.CardVariantDto variant : entry.variants)
				{
					if (variant == null || (variant.quantity != null && variant.quantity <= 0))
					{
						continue;
					}
					owned = true;
				}
				if (owned)
				{
					ownedNames.add(name);
				}
			}
		}
		else if (dto.cardInstances != null)
		{
			collectionPresent = true;
			for (TcgStateDto.OwnedCardInstanceDto instance : dto.cardInstances)
			{
				String name = normalizedName(instance == null ? null : instance.cardName);
				if (name == null)
				{
					continue;
				}
				ownedNames.add(name);
			}
		}
		else
		{
			collectionPresent = false;
		}

		return new PersistedState(json, collectionPresent, ownedNames);
	}

	private static String normalizedName(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return null;
		}
		return value.trim().toLowerCase(Locale.ROOT);
	}

	static final class PersistedState
	{
		private final String json;
		private final boolean collectionPresent;
		private final Set<String> ownedNames;

		private PersistedState(String json, boolean collectionPresent,
			Set<String> ownedNames)
		{
			this.json = json;
			this.collectionPresent = collectionPresent;
			this.ownedNames = Collections.unmodifiableSet(new HashSet<>(ownedNames));
		}

		private static PersistedState unavailable()
		{
			return new PersistedState("", false, Collections.emptySet());
		}

		boolean isCollectionPresent()
		{
			return collectionPresent;
		}

		Set<String> getOwnedNames()
		{
			return ownedNames;
		}

	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.BronzemanTcgConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Remembers that the current RuneScape profile has received a v1-capable OSRS TCG payload.
 * This controls panel presentation only; live ownership and remote-catalogue activation must
 * continue to use the current PluginMessage payload.
 */
@Slf4j
@Singleton
public final class V1PresentationState
{
	static final String CONFIG_KEY = "v1PresentationActive";

	private final Persistence persistence;

	@Inject
	public V1PresentationState(ConfigManager configManager)
	{
		this(new ConfigPersistence(configManager));
	}

	V1PresentationState(Persistence persistence)
	{
		this.persistence = persistence;
	}

	/** Current live capability always wins, even if profile persistence is unavailable. */
	public boolean isActive(boolean liveV1Capable)
	{
		return liveV1Capable || readPersisted();
	}

	/**
	 * Permanently activates v1 presentation for this profile after its first capable payload.
	 *
	 * @return true when this call newly persisted the presentation state
	 */
	public boolean observeLiveCapability(boolean liveV1Capable)
	{
		if (!liveV1Capable || readPersisted())
		{
			return false;
		}
		try
		{
			persistence.write("true");
			return true;
		}
		catch (RuntimeException ex)
		{
			log.warn("Unable to persist v1 panel presentation for this profile", ex);
			return false;
		}
	}

	private boolean readPersisted()
	{
		try
		{
			return Boolean.parseBoolean(persistence.read());
		}
		catch (RuntimeException ex)
		{
			log.warn("Unable to read v1 panel presentation for this profile", ex);
			return false;
		}
	}

	interface Persistence
	{
		String read();

		void write(String value);
	}

	private static final class ConfigPersistence implements Persistence
	{
		private final ConfigManager configManager;

		private ConfigPersistence(ConfigManager configManager)
		{
			this.configManager = configManager;
		}

		@Override
		public String read()
		{
			return configManager.getRSProfileConfiguration(
				BronzemanTcgConfig.GROUP, CONFIG_KEY);
		}

		@Override
		public void write(String value)
		{
			configManager.setRSProfileConfiguration(
				BronzemanTcgConfig.GROUP, CONFIG_KEY, value);
		}
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.util.CacheFiles;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;

/** Versioned profile-keyed persistence for the two bounded Recent Unlocks histories. */
@Singleton
public final class RecentUnlocksCacheStore
{
	private static final int SCHEMA_VERSION = 1;
	private static final int MAX_CACHE_BYTES = 256 * 1024;
	static final int MAX_RECENT = 200;
	private static final int MAX_NAME_LENGTH = 256;

	private final Gson gson;
	private final Path cacheDirectory;

	@Inject
	public RecentUnlocksCacheStore(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve("bronzeman-tcg")
			.resolve("recent-unlocks"));
	}

	RecentUnlocksCacheStore(Gson gson, Path cacheDirectory)
	{
		this.gson = gson;
		this.cacheDirectory = cacheDirectory;
	}

	public Record load(String profileKey) throws IOException
	{
		Path file = fileForProfile(profileKey);
		if (!Files.exists(file))
		{
			return null;
		}
		long size = Files.size(file);
		if (size <= 0 || size > MAX_CACHE_BYTES)
		{
			throw new IOException("Recent Unlocks cache has an invalid size");
		}
		CacheDto dto;
		try
		{
			dto = gson.fromJson(Files.readString(file, StandardCharsets.UTF_8), CacheDto.class);
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			throw new IOException("Recent Unlocks cache JSON is malformed", ex);
		}
		if (dto == null || dto.schemaVersion != SCHEMA_VERSION)
		{
			throw new IOException("Recent Unlocks cache envelope is invalid");
		}
		return new Record(fromDtos(dto.personal, false), fromDtos(dto.shared, true));
	}

	public void save(String profileKey, List<RecentUnlocksTracker.Unlock> personal,
		List<RecentUnlocksTracker.Unlock> shared) throws IOException
	{
		List<RecentUnlocksTracker.Unlock> validPersonal = validateHistory(personal, false);
		List<RecentUnlocksTracker.Unlock> validShared = validateHistory(shared, true);
		CacheDto dto = new CacheDto();
		dto.schemaVersion = SCHEMA_VERSION;
		dto.personal = toDtos(validPersonal);
		dto.shared = toDtos(validShared);
		byte[] bytes = gson.toJson(dto).getBytes(StandardCharsets.UTF_8);
		if (bytes.length > MAX_CACHE_BYTES)
		{
			throw new IOException("Recent Unlocks cache exceeds size limit");
		}
		CacheFiles.writeAtomically(fileForProfile(profileKey), bytes);
	}

	Path fileForProfile(String profileKey)
	{
		return cacheDirectory.resolve(CacheFiles.sha256Hex(profileKey) + ".json");
	}

	static List<RecentUnlocksTracker.Unlock> validateHistory(
		List<RecentUnlocksTracker.Unlock> source, boolean shared) throws IOException
	{
		if (source == null || source.size() > MAX_RECENT)
		{
			throw new IOException("Recent Unlocks history has an invalid size");
		}
		List<RecentUnlocksTracker.Unlock> result = new ArrayList<>(source.size());
		for (RecentUnlocksTracker.Unlock unlock : source)
		{
			String name = unlock == null || unlock.name == null
				? "" : unlock.name.trim().toLowerCase(Locale.ROOT);
			if (name.isEmpty() || unlock.name.length() > MAX_NAME_LENGTH
				|| name.chars().anyMatch(Character::isISOControl) || unlock.time < 0
				|| unlock.shared != shared)
			{
				throw new IOException("Recent Unlocks history contains an invalid entry");
			}
			result.add(new RecentUnlocksTracker.Unlock(name, unlock.time, shared));
		}
		return Collections.unmodifiableList(result);
	}

	private List<RecentUnlocksTracker.Unlock> fromDtos(List<UnlockDto> source,
		boolean shared) throws IOException
	{
		if (source == null)
		{
			throw new IOException("Recent Unlocks cache is missing a history");
		}
		List<RecentUnlocksTracker.Unlock> result = new ArrayList<>(source.size());
		for (UnlockDto dto : source)
		{
			if (dto == null)
			{
				throw new IOException("Recent Unlocks cache contains an invalid entry");
			}
			result.add(new RecentUnlocksTracker.Unlock(dto.name, dto.time, shared));
		}
		return validateHistory(result, shared);
	}

	private static List<UnlockDto> toDtos(List<RecentUnlocksTracker.Unlock> source)
	{
		List<UnlockDto> result = new ArrayList<>(source.size());
		for (RecentUnlocksTracker.Unlock unlock : source)
		{
			UnlockDto dto = new UnlockDto();
			dto.name = unlock.name;
			dto.time = unlock.time;
			result.add(dto);
		}
		return result;
	}

	public static final class Record
	{
		private final List<RecentUnlocksTracker.Unlock> personal;
		private final List<RecentUnlocksTracker.Unlock> shared;

		private Record(List<RecentUnlocksTracker.Unlock> personal,
			List<RecentUnlocksTracker.Unlock> shared)
		{
			this.personal = personal;
			this.shared = shared;
		}

		public List<RecentUnlocksTracker.Unlock> getPersonal()
		{
			return personal;
		}

		public List<RecentUnlocksTracker.Unlock> getShared()
		{
			return shared;
		}
	}

	@SuppressWarnings("unused")
	private static final class CacheDto
	{
		private int schemaVersion;
		private List<UnlockDto> personal;
		private List<UnlockDto> shared;
	}

	@SuppressWarnings("unused")
	private static final class UnlockDto
	{
		private String name;
		private long time;
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.catalog.QuestRequirementCatalog;
import java.util.Locale;
import java.util.Set;

/** Pure visibility policy for the independent quest-panel filters. */
final class QuestFilterModel
{
	private QuestFilterModel()
	{
	}

	static boolean isVisible(boolean completed, boolean hideCompleted,
		boolean cardsMet, boolean requireCards,
		QuestRequirementCatalog.Requirements requirements,
		int[] realSkillLevels, int questPoints, Set<String> completedQuests,
		boolean requireQuestPoints, boolean requireSkillLevels,
		boolean requirePrerequisiteQuests)
	{
		if (hideCompleted && completed)
		{
			return false;
		}
		if (requireCards && !cardsMet)
		{
			return false;
		}
		if (requirements == null || realSkillLevels == null)
		{
			return true;
		}
		if (requireQuestPoints && questPoints < requirements.questPoints)
		{
			return false;
		}
		if (requireSkillLevels)
		{
			for (QuestRequirementCatalog.SkillRequirement requirement : requirements.skills)
			{
				int ordinal = requirement.skill.ordinal();
				if (ordinal >= realSkillLevels.length
					|| realSkillLevels[ordinal] < requirement.level)
				{
					return false;
				}
			}
		}
		if (requirePrerequisiteQuests)
		{
			for (QuestRequirementCatalog.QuestRequirement requirement : requirements.quests)
			{
				if (!completedQuests.contains(
					requirement.quest.getName().toLowerCase(Locale.ROOT)))
				{
					return false;
				}
			}
		}
		return true;
	}
}

package com.bronzemantcg.panel;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Pure payload/config-driven navigation state shared by the Swing panel and its tests. */
public final class PanelNavigationModel
{
	private PanelNavigationModel()
	{
	}

	public static State resolve(boolean v1Capable, boolean sharedEnabled,
		boolean showBetaTab)
	{
		List<List<Tab>> rows = new ArrayList<>();
		rows.add(pair(Tab.ACTIVITIES, Tab.SLAYER_PVM));
		if (!v1Capable)
		{
			rows.add(showBetaTab
				? pair(Tab.RECENT, Tab.BETA)
				: Collections.singletonList(Tab.RECENT));
			if (sharedEnabled)
			{
				rows.add(Collections.singletonList(Tab.SHARED));
			}
		}
		else
		{
			if (showBetaTab && !sharedEnabled)
			{
				rows.add(pair(Tab.RECENT, Tab.BETA));
				rows.add(Collections.singletonList(Tab.COLLECTION));
			}
			else
			{
				rows.add(pair(Tab.COLLECTION, Tab.RECENT));
				if (showBetaTab)
				{
					rows.add(pair(Tab.BETA, Tab.SHARED));
				}
				else if (sharedEnabled)
				{
					rows.add(Collections.singletonList(Tab.SHARED));
				}
			}
		}

		List<Tab> visible = new ArrayList<>();
		for (List<Tab> row : rows)
		{
			visible.addAll(row);
		}
		return new State(v1Capable, visible, rows);
	}

	private static List<Tab> pair(Tab left, Tab right)
	{
		List<Tab> pair = new ArrayList<>();
		pair.add(left);
		pair.add(right);
		return pair;
	}

	public enum Tab
	{
		ACTIVITIES,
		SLAYER_PVM,
		RECENT,
		COLLECTION,
		SHARED,
		BETA
	}

	public static final class State
	{
		private final boolean v1Capable;
		private final List<Tab> visibleTabs;
		private final List<List<Tab>> rows;

		private State(boolean v1Capable, List<Tab> visibleTabs, List<List<Tab>> rows)
		{
			this.v1Capable = v1Capable;
			this.visibleTabs = Collections.unmodifiableList(new ArrayList<>(visibleTabs));
			List<List<Tab>> rowCopy = new ArrayList<>();
			for (List<Tab> row : rows)
			{
				rowCopy.add(Collections.unmodifiableList(new ArrayList<>(row)));
			}
			this.rows = Collections.unmodifiableList(rowCopy);
		}

		public boolean isVisible(Tab tab)
		{
			return visibleTabs.contains(tab);
		}

		public List<Tab> getVisibleTabs()
		{
			return visibleTabs;
		}

		/** Approved one- or two-button rows for the fixed-width side panel. */
		public List<List<Tab>> getRows()
		{
			return rows;
		}

		/** Returns the approved safe destination when a selected tab becomes hidden. */
		public Tab selectionAfterHiding(Tab hiddenTab)
		{
			if (hiddenTab == Tab.BETA && v1Capable && isVisible(Tab.COLLECTION))
			{
				return Tab.COLLECTION;
			}
			if (hiddenTab == Tab.COLLECTION && isVisible(Tab.BETA))
			{
				return Tab.BETA;
			}
			return Tab.ACTIVITIES;
		}
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.catalog.QuestCatalog;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Presentation-only projection which removes NPC-backed quest requirements. */
final class QuestListPresentation
{
	private QuestListPresentation()
	{
	}

	static List<QuestCatalog.QuestEntry> hideNpcRequirements(
		List<QuestCatalog.QuestEntry> entries)
	{
		List<QuestCatalog.QuestEntry> projected = new ArrayList<>();
		for (QuestCatalog.QuestEntry entry : entries)
		{
			List<QuestCatalog.Section> sections = new ArrayList<>();
			for (QuestCatalog.Section section : entry.sections)
			{
				List<QuestCatalog.Requirement> requirements = new ArrayList<>();
				for (QuestCatalog.Requirement requirement : section.requirements)
				{
					Projection result = project(requirement);
					if (!result.hidden)
					{
						requirements.add(result.requirement);
					}
				}
				if (!requirements.isEmpty())
				{
					sections.add(section.withRequirements(requirements));
				}
			}
			projected.add(entry.withSections(sections));
		}
		return Collections.unmodifiableList(projected);
	}

	static boolean isNpcRequirement(QuestCatalog.Requirement requirement)
	{
		return requirement != null
			&& ("npc".equals(requirement.type) || "enemy".equals(requirement.type));
	}

	private static Projection project(QuestCatalog.Requirement source)
	{
		if (isNpcRequirement(source))
		{
			return Projection.hidden();
		}

		List<QuestCatalog.Requirement> children = new ArrayList<>();
		boolean hiddenChild = false;
		boolean visibleChild = false;
		boolean routed = !source.selector.isEmpty();
		for (QuestCatalog.Requirement child : source.children)
		{
			Projection projected = project(child);
			if (projected.hidden)
			{
				hiddenChild = true;
				if (routed)
				{
					// Retain an empty route marker so selecting a route whose only
					// requirements were hidden remains satisfied.
					children.add(child.withProjection(Collections.emptyList(),
						Collections.emptyList(), Collections.emptyList()));
				}
			}
			else
			{
				visibleChild = true;
				children.add(projected.requirement);
			}
		}

		if (!source.children.isEmpty())
		{
			if (routed && hiddenChild && !visibleChild)
			{
				return Projection.hidden();
			}
			if (!routed && ((source.logic == QuestCatalog.Logic.ANY && hiddenChild)
				|| (source.logic == QuestCatalog.Logic.ALL && children.isEmpty())))
			{
				return Projection.hidden();
			}
			return Projection.visible(source.withProjection(
				source.displayCards, source.lowerCards, children));
		}
		return Projection.visible(source);
	}

	private static final class Projection
	{
		private final QuestCatalog.Requirement requirement;
		private final boolean hidden;

		private Projection(QuestCatalog.Requirement requirement, boolean hidden)
		{
			this.requirement = requirement;
			this.hidden = hidden;
		}

		private static Projection visible(QuestCatalog.Requirement requirement)
		{
			return new Projection(requirement, false);
		}

		private static Projection hidden()
		{
			return new Projection(null, true);
		}
	}
}

package com.bronzemantcg.panel.collection;

import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Projects TCG Locked names through the current Collection or reviewed Beta layout. */
@Singleton
public final class PanelSharedCardsViewModel
{
	private static final String OTHER_CARDS = "Other Cards";

	private final PanelCollectionLayout catalog;
	private final PanelCollectionOwnership ownership;
	private final ActiveCardIdentityCatalog activeCatalog;
	private final Map<String, List<PanelCollectionLayout.BetaCollectionCard>> betaCardsByCategory;

	@Inject
	public PanelSharedCardsViewModel(PanelCollectionLayout catalog,
		PanelCollectionOwnership ownership, ActiveCardIdentityCatalog activeCatalog)
	{
		this.catalog = catalog;
		this.ownership = ownership;
		this.activeCatalog = activeCatalog;
		Map<String, List<PanelCollectionLayout.BetaCollectionCard>> byCategory = new HashMap<>();
		for (PanelCollectionLayout.BetaCollectionCard card : catalog.getBetaCollectionCards())
		{
			if (!card.isVisible())
			{
				continue;
			}
			for (String categoryId : card.getCategoryIds())
			{
				byCategory.computeIfAbsent(categoryId, ignored -> new ArrayList<>()).add(card);
			}
		}
		Map<String, List<PanelCollectionLayout.BetaCollectionCard>> frozen =
			new LinkedHashMap<>();
		for (Map.Entry<String, List<PanelCollectionLayout.BetaCollectionCard>> entry
			: byCategory.entrySet())
		{
			frozen.put(entry.getKey(), List.copyOf(entry.getValue()));
		}
		betaCardsByCategory = Collections.unmodifiableMap(frozen);
	}

	public State prepare(Set<String> sharedCardNames,
		PanelCollectionViewModel.State collectionState)
	{
		Set<String> remaining = normalizeNames(sharedCardNames);
		List<Category> categories = collectionState != null
			&& collectionState.isCatalogAvailable()
			? currentCategories(collectionState, remaining)
			: betaCategories(remaining);
		if (!remaining.isEmpty())
		{
			List<String> other = new ArrayList<>();
			for (String cardName : remaining)
			{
				other.add(displayCardName(cardName));
			}
			other.sort(String.CASE_INSENSITIVE_ORDER);
			categories.add(new Category(OTHER_CARDS, other, Collections.emptyMap()));
		}
		return new State(categories);
	}

	public String displayCardName(String cardName)
	{
		String displayName = activeCatalog.findDisplayCardName(cardName);
		if (displayName != null)
		{
			return displayName;
		}
		String normalized = normalize(cardName);
		return normalized.isEmpty() ? normalized
			: Character.toUpperCase(normalized.charAt(0)) + normalized.substring(1);
	}

	private List<Category> currentCategories(PanelCollectionViewModel.State state,
		Set<String> remaining)
	{
		List<Category> result = new ArrayList<>();
		Set<PanelCollectionLayout.CollectionCard> placed = new HashSet<>();
		for (PanelCollectionViewModel.Section section : state.getSections())
		{
			Map<String, List<String>> subcategories = new LinkedHashMap<>();
			for (PanelCollectionViewModel.Category category : section.getCategories())
			{
				List<String> cards = new ArrayList<>();
				for (PanelCollectionLayout.CollectionCard card : category.getCards())
				{
					Set<String> matches = state.matchingSharedNames(card, remaining);
					if (state.getStatus(card) == PanelCollectionViewModel.Status.SHARED
						&& !matches.isEmpty() && placed.add(card))
					{
						cards.add(card.getCardName());
						remaining.removeAll(matches);
					}
				}
				if (!cards.isEmpty())
				{
					subcategories.put(category.getName(), cards);
				}
			}
			if (!subcategories.isEmpty())
			{
				result.add(new Category(section.getName(), Collections.emptyList(),
					subcategories));
			}
		}
		return result;
	}

	private List<Category> betaCategories(Set<String> remaining)
	{
		List<Category> result = new ArrayList<>();
		Set<String> placed = new HashSet<>();
		for (PanelCollectionLayout.Section section : catalog.getSections())
		{
			if (!section.isVisible())
			{
				continue;
			}
			Map<String, List<String>> subcategories = new LinkedHashMap<>();
			for (PanelCollectionLayout.Category category : section.getCategories())
			{
				if (!category.isVisible())
				{
					continue;
				}
				List<String> cards = new ArrayList<>();
				for (PanelCollectionLayout.BetaCollectionCard card
					: betaCardsByCategory.getOrDefault(category.getId(), Collections.emptyList()))
				{
					for (PanelCollectionLayout.BetaVariant variant : card.getVariants())
					{
						String normalized = normalize(variant.getName());
						if (remaining.contains(normalized) && placed.add(normalized)
							&& ownership.isBetaVariantOwnedByNames(variant, remaining))
						{
							cards.add(variant.getName());
							remaining.remove(normalized);
						}
					}
				}
				if (!cards.isEmpty())
				{
					subcategories.put(category.getName(), cards);
				}
			}
			if (!subcategories.isEmpty())
			{
				result.add(new Category(section.getName(), Collections.emptyList(),
					subcategories));
			}
		}
		return result;
	}

	private static Set<String> normalizeNames(Set<String> names)
	{
		Set<String> result = new LinkedHashSet<>();
		if (names != null)
		{
			for (String name : names)
			{
				String normalized = normalize(name);
				if (!normalized.isEmpty())
				{
					result.add(normalized);
				}
			}
		}
		return result;
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	public static final class State
	{
		private final List<Category> categories;

		private State(List<Category> categories)
		{
			this.categories = List.copyOf(categories);
		}

		public List<Category> getCategories()
		{
			return categories;
		}
	}

	public static final class Category
	{
		private final String name;
		private final List<String> items;
		private final Map<String, List<String>> subcategories;

		public Category(String name, List<String> items,
			Map<String, List<String>> subcategories)
		{
			this.name = name;
			this.items = List.copyOf(items);
			Map<String, List<String>> frozen = new LinkedHashMap<>();
			for (Map.Entry<String, List<String>> entry : subcategories.entrySet())
			{
				frozen.put(entry.getKey(), List.copyOf(entry.getValue()));
			}
			this.subcategories = Collections.unmodifiableMap(frozen);
		}

		public String getName()
		{
			return name;
		}

		public List<String> getItems()
		{
			return items;
		}

		public Map<String, List<String>> getSubcategories()
		{
			return subcategories;
		}

		public int size()
		{
			int count = items.size();
			for (List<String> values : subcategories.values())
			{
				count += values.size();
			}
			return count;
		}
	}
}

package com.bronzemantcg.panel.collection;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.BetaCardUnlockSource;
import com.bronzemantcg.ownership.TcgOwnershipSnapshot;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Ownership rules shared by the v1 Collection and Beta Collection views. */
@Singleton
public final class PanelCollectionOwnership
{
	private final PanelCollectionLayout layout;

	@Inject
	public PanelCollectionOwnership(PanelCollectionLayout layout)
	{
		this.layout = layout;
	}

	boolean isPersonallyCollected(PanelCollectionLayout.CollectionCard card,
		TcgOwnershipSnapshot personalOwnership, BetaCardUnlockSource.View betaUnlocks,
		PanelCollectionProjection projection)
	{
		if (card == null)
		{
			return false;
		}
		if (betaUnlocks != null && containsUniqueCollectionName(card,
			betaUnlocks.getParentNamesLowerCase(card.getKind()), projection))
		{
			return true;
		}
		if (personalOwnership == null)
		{
			return false;
		}
		if (!personalOwnership.hasEntityIds(card.getKind()))
		{
			return containsUniqueCollectionName(
				card, personalOwnership.getOwnedCardNamesLowerCase(), projection);
		}
		for (Integer entityId : card.getEntityIds())
		{
			if (personalOwnership.ownsEntityId(card.getKind(), entityId)
				&& (isCollectionEntityIdUnique(projection, card.getKind(), entityId)
					|| containsUniqueCollectionName(
						card, personalOwnership.getOwnedCardNamesLowerCase(), projection)))
			{
				return true;
			}
		}
		return containsUniqueLegacyCollectionName(card,
			personalOwnership.getOwnedCardNamesLowerCase(), projection);
	}

	public boolean isBetaVariantOwnedByNames(PanelCollectionLayout.BetaVariant variant,
		Set<String> betaNames)
	{
		if (variant == null)
		{
			return false;
		}
		String name = normalize(variant.getName());
		return layout.isBetaVariantNameUnique(name) && containsName(betaNames, name);
	}

	boolean isSharedCollectionCard(PanelCollectionLayout.CollectionCard card,
		Set<String> sharedCardNames, PanelCollectionProjection projection)
	{
		return card != null && containsUniqueCollectionName(
			card, sharedCardNames, projection);
	}

	private static boolean containsName(Set<String> names, String normalized)
	{
		if (names == null)
		{
			return false;
		}
		if (names.contains(normalized))
		{
			return true;
		}
		for (String name : names)
		{
			if (name != null && normalize(name).equals(normalized))
			{
				return true;
			}
		}
		return false;
	}

	private boolean containsUniqueCollectionName(
		PanelCollectionLayout.CollectionCard card, Set<String> names,
		PanelCollectionProjection projection)
	{
		if (names == null || names.isEmpty())
		{
			return false;
		}
		for (String acceptedName : card.getAcceptedNamesLowerCase())
		{
			if (isCollectionAcceptedNameUnique(projection, acceptedName)
				&& containsName(names, acceptedName))
			{
				return true;
			}
		}
		return false;
	}

	/** Mirrors the accepted gameplay bridge: a canonical v1 name cannot override an ID miss. */
	private boolean containsUniqueLegacyCollectionName(
		PanelCollectionLayout.CollectionCard card, Set<String> names,
		PanelCollectionProjection projection)
	{
		String canonicalName = normalize(card.getCardName());
		for (String acceptedName : card.getAcceptedNamesLowerCase())
		{
			if (!canonicalName.equals(acceptedName)
				&& isCollectionAcceptedNameUnique(projection, acceptedName)
				&& containsName(names, acceptedName))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isCollectionEntityIdUnique(PanelCollectionProjection projection,
		CardEntityKind kind, int entityId)
	{
		return projection.isEntityIdUnique(kind, entityId);
	}

	private boolean isCollectionAcceptedNameUnique(
		PanelCollectionProjection projection, String name)
	{
		return projection.isAcceptedNameUnique(name);
	}

	private static String normalize(String value)
	{
		return value.trim().toLowerCase(Locale.ROOT);
	}
}

package com.bronzemantcg.panel.collection;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Owner-curated placement model for the v1 Collection and Beta Collection tabs.
 * Active v1 identities are deliberately absent: they come only from the validated API catalogue.
 * This class has no Swing dependency, so layout validation and ownership remain
 * independently testable.
 */
@Slf4j
@Singleton
@SuppressWarnings("LombokGetterMayBeUsed")
public final class PanelCollectionLayout
{
	private static final String DEFAULT_RESOURCE = "/panel/collection_layout.json";

	private final List<Section> sections;
	private final List<CollectionPlacement> collectionPlacements;
	private final List<BetaCollectionCard> betaCollectionCards;
	private final Map<CardEntityKind, Map<Integer, Integer>> betaIdUseCounts;
	private final Map<String, Integer> betaNameUseCounts;
	private final String organiserFingerprint;
	private final String organiserProjectSha256;

	@Inject
	public PanelCollectionLayout(Gson gson)
	{
		this(gson, DEFAULT_RESOURCE);
	}

	PanelCollectionLayout(Gson gson, String resourcePath)
	{
		Loaded loaded = load(gson, resourcePath);
		sections = loaded.sections;
		collectionPlacements = loaded.collectionPlacements;
		betaCollectionCards = loaded.betaCollectionCards;
		betaIdUseCounts = loaded.betaIdUseCounts;
		betaNameUseCounts = loaded.betaNameUseCounts;
		organiserFingerprint = loaded.organiserFingerprint;
		organiserProjectSha256 = loaded.organiserProjectSha256;
	}

	public List<Section> getSections()
	{
		return sections;
	}

	public List<CollectionPlacement> getCollectionPlacements()
	{
		return collectionPlacements;
	}

	public List<BetaCollectionCard> getBetaCollectionCards()
	{
		return betaCollectionCards;
	}

	public String getOrganiserFingerprint()
	{
		return organiserFingerprint;
	}

	public String getOrganiserProjectSha256()
	{
		return organiserProjectSha256;
	}

	public boolean isBetaEntityIdUnique(CardEntityKind kind, int entityId)
	{
		Map<Integer, Integer> counts = betaIdUseCounts.get(kind);
		return counts != null && counts.getOrDefault(entityId, 0) == 1;
	}

	public boolean isBetaVariantNameUnique(String name)
	{
		return name != null && betaNameUseCounts.getOrDefault(normalize(name), 0) == 1;
	}

	private static Loaded load(Gson gson, String resourcePath)
	{
		if (gson == null || resourcePath == null)
		{
			return Loaded.empty();
		}
		try (InputStream stream = PanelCollectionLayout.class.getResourceAsStream(resourcePath))
		{
			if (stream == null)
			{
				log.warn("{} missing from classpath; future collection tabs will remain empty.",
					resourcePath);
				return Loaded.empty();
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			return validate(snapshot);
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Failed to load {}; future collection tabs will remain empty.",
				resourcePath, ex);
			return Loaded.empty();
		}
	}

	private static Loaded validate(Snapshot snapshot)
	{
		if (snapshot == null || snapshot.schemaVersion != 1 || snapshot.sections == null
			|| snapshot.collectionPlacements == null || snapshot.betaCollectionCards == null)
		{
			throw new IllegalArgumentException("panel collection layout must use schema version 1");
		}

		Set<String> sectionIds = new HashSet<>();
		Set<String> categoryIds = new LinkedHashSet<>();
		List<String> categoryIdsByIndex = new ArrayList<>();
		List<Section> sections = new ArrayList<>();
		for (SectionDto section : snapshot.sections)
		{
			if (section == null)
			{
				throw new IllegalArgumentException("section is required");
			}
			String sectionId = required(section.id, "section id");
			String sectionName = required(section.name, "section name");
			if (!sectionIds.add(sectionId))
			{
				throw new IllegalArgumentException("duplicate section id: " + sectionId);
			}
			if (section.categories == null || section.categories.isEmpty())
			{
				throw new IllegalArgumentException("section has no categories: " + sectionId);
			}
			List<Category> categories = new ArrayList<>();
			for (CategoryDto category : section.categories)
			{
				if (category == null)
				{
					throw new IllegalArgumentException("category is required");
				}
				String categoryId = required(category.id, "category id");
				String categoryName = required(category.name, "category name");
				if (!categoryIds.add(categoryId))
				{
					throw new IllegalArgumentException("duplicate category id: " + categoryId);
				}
				categoryIdsByIndex.add(categoryId);
				categories.add(new Category(categoryId, categoryName, category.visible));
			}
			sections.add(new Section(sectionId, sectionName, section.visible, categories));
		}

		List<CollectionPlacement> collectionPlacements = new ArrayList<>();
		Set<String> collectionKeys = new HashSet<>();
		for (CollectionPlacementDto card : snapshot.collectionPlacements)
		{
			if (card == null)
			{
				throw new IllegalArgumentException("collection placement is required");
			}
			CardEntityKind kind = kind(card.kind);
			String cardName = required(card.cardName, "collection card name");
			String key = kind + "\0" + normalize(cardName);
			if (!collectionKeys.add(key))
			{
				throw new IllegalArgumentException("duplicate collection card: " + cardName);
			}
			Set<String> placementCategories = categories(
				card.categoryIndexes, categoryIdsByIndex, cardName);
			if (placementCategories.isEmpty())
			{
				throw new IllegalArgumentException("collection placement has no category: " + cardName);
			}
			collectionPlacements.add(new CollectionPlacement(kind, cardName,
				placementCategories));
		}

		List<BetaCollectionCard> betaCards = new ArrayList<>();
		Set<String> betaKeys = new HashSet<>();
		Map<CardEntityKind, Map<Integer, Integer>> idCounts = new EnumMap<>(CardEntityKind.class);
		Map<String, Integer> nameCounts = new HashMap<>();
		for (CardEntityKind kind : CardEntityKind.values())
		{
			idCounts.put(kind, new HashMap<>());
		}
		for (BetaCardDto card : snapshot.betaCollectionCards)
		{
			if (card == null)
			{
				throw new IllegalArgumentException("beta card is required");
			}
			String rowKey = required(card.key, "beta row key");
			if (!betaKeys.add(rowKey))
			{
				throw new IllegalArgumentException("duplicate beta row key: " + rowKey);
			}
			CardEntityKind kind = kind(card.kind);
			String parentName = required(card.parentName, "beta parent name");
			if (card.variants == null || card.variants.isEmpty())
			{
				throw new IllegalArgumentException("beta parent has no variants: " + parentName);
			}
			List<BetaVariant> variants = new ArrayList<>();
			Set<String> variantNames = new HashSet<>();
			for (BetaVariantDto variant : card.variants)
			{
				if (variant == null)
				{
					throw new IllegalArgumentException("beta variant is required");
				}
				String name = required(variant.name, "beta variant name");
				if (!variantNames.add(normalize(name)))
				{
					throw new IllegalArgumentException("duplicate beta variant: " + name);
				}
				nameCounts.merge(normalize(name), 1, Integer::sum);
				Set<Integer> entityIds = validIds(variant.entityIds);
				for (Integer entityId : entityIds)
				{
					idCounts.get(kind).merge(entityId, 1, Integer::sum);
				}
				variants.add(new BetaVariant(kind, name, entityIds));
			}
			Set<String> betaCategories = categories(
				card.categoryIndexes, categoryIdsByIndex, parentName);
			if (betaCategories.isEmpty())
			{
				throw new IllegalArgumentException("beta parent has no category: " + parentName);
			}
			betaCards.add(new BetaCollectionCard(rowKey, kind, parentName, card.betaOnly,
				card.visible, betaCategories, variants));
		}

		return new Loaded(sections, collectionPlacements, betaCards,
			freezeCounts(idCounts),
			Collections.unmodifiableMap(new LinkedHashMap<>(nameCounts)),
			snapshot.source == null ? null : snapshot.source.organiserFingerprint,
			snapshot.source == null ? null : snapshot.source.organiserProjectSha256);
	}

	private static Set<String> categories(List<Integer> values, List<String> known, String cardName)
	{
		if (values == null)
		{
			throw new IllegalArgumentException("card categories are missing: " + cardName);
		}
		LinkedHashSet<String> result = new LinkedHashSet<>();
		for (Integer value : values)
		{
			if (value == null || value < 0 || value >= known.size())
			{
				throw new IllegalArgumentException("unknown category index: " + value);
			}
			result.add(known.get(value));
		}
		return Collections.unmodifiableSet(result);
	}

	private static Set<Integer> validIds(List<Integer> values)
	{
		LinkedHashSet<Integer> result = new LinkedHashSet<>();
		if (values != null)
		{
			for (Integer value : values)
			{
				if (value == null || value < 0)
				{
					throw new IllegalArgumentException("invalid beta entity ID");
				}
				result.add(value);
			}
		}
		return Collections.unmodifiableSet(result);
	}

	private static CardEntityKind kind(String value)
	{
		try
		{
			return CardEntityKind.valueOf(required(value, "card kind").toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException ex)
		{
			throw new IllegalArgumentException("invalid card kind: " + value, ex);
		}
	}

	private static String required(String value, String label)
	{
		if (value == null || value.trim().isEmpty())
		{
			throw new IllegalArgumentException(label + " is required");
		}
		return value.trim();
	}

	private static String normalize(String value)
	{
		return value.trim().toLowerCase(Locale.ROOT);
	}

	private static Map<CardEntityKind, Map<Integer, Integer>> freezeCounts(
		Map<CardEntityKind, Map<Integer, Integer>> source)
	{
		Map<CardEntityKind, Map<Integer, Integer>> result = new EnumMap<>(CardEntityKind.class);
		for (Map.Entry<CardEntityKind, Map<Integer, Integer>> entry : source.entrySet())
		{
			result.put(entry.getKey(), Collections.unmodifiableMap(
				new LinkedHashMap<>(entry.getValue())));
		}
		return Collections.unmodifiableMap(result);
	}

	public static final class Section
	{
		private final String id;
		private final String name;
		private final boolean visible;
		private final List<Category> categories;

		private Section(String id, String name, boolean visible, List<Category> categories)
		{
			this.id = id;
			this.name = name;
			this.visible = visible;
			this.categories = List.copyOf(categories);
		}

		public String getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public boolean isVisible()
		{
			return visible;
		}

		public List<Category> getCategories()
		{
			return categories;
		}
	}

	public static final class Category
	{
		private final String id;
		private final String name;
		private final boolean visible;

		private Category(String id, String name, boolean visible)
		{
			this.id = id;
			this.name = name;
			this.visible = visible;
		}

		public String getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public boolean isVisible()
		{
			return visible;
		}
	}

	/** A stable owner-curated category key, without any bundled v1 identity data. */
	public static final class CollectionPlacement
	{
		private final CardEntityKind kind;
		private final String cardName;
		private final Set<String> categoryIds;

		private CollectionPlacement(CardEntityKind kind, String cardName,
			Set<String> categoryIds)
		{
			this.kind = kind;
			this.cardName = cardName;
			this.categoryIds = categoryIds;
		}

		public CardEntityKind getKind()
		{
			return kind;
		}

		public String getCardName()
		{
			return cardName;
		}

		public Set<String> getCategoryIds()
		{
			return categoryIds;
		}
	}

	/** Runtime-only Collection identity projected from the active v1 API catalogue. */
	public static final class CollectionCard
	{
		private final CardEntityKind kind;
		private final String cardName;
		private final Set<String> categoryIds;
		private final Set<String> acceptedNamesLowerCase;
		private final Set<Integer> entityIds;

		private CollectionCard(CardEntityKind kind, String cardName, Set<String> categoryIds,
			Set<String> acceptedNamesLowerCase, Set<Integer> entityIds)
		{
			this.kind = kind;
			this.cardName = cardName;
			this.categoryIds = categoryIds;
			this.acceptedNamesLowerCase = acceptedNamesLowerCase;
			this.entityIds = entityIds;
		}

		static CollectionCard fromIdentity(CardIdentity identity, Set<String> categoryIds)
		{
			LinkedHashSet<String> acceptedNames = new LinkedHashSet<>();
			acceptedNames.add(normalize(identity.getCardName()));
			for (String legacyName : identity.getLegacyCardNames())
			{
				acceptedNames.add(normalize(legacyName));
			}
			return new CollectionCard(identity.getKind(), identity.getCardName(),
				Collections.unmodifiableSet(new LinkedHashSet<>(categoryIds)),
				Collections.unmodifiableSet(acceptedNames), identity.getEntityIds());
		}

		public CardEntityKind getKind()
		{
			return kind;
		}

		public String getCardName()
		{
			return cardName;
		}

		public Set<String> getCategoryIds()
		{
			return categoryIds;
		}

		public Set<String> getAcceptedNamesLowerCase()
		{
