package com.bronzemantcg.panel.collection;

import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** One immutable set of Collection parents projected onto the owner-curated panel layout. */
final class PanelCollectionProjection
{
	private final long revision;
	private final boolean remote;
	private final List<PanelCollectionLayout.CollectionCard> cards;
	private final Map<CardEntityKind, Map<Integer, Integer>> idUseCounts;
	private final Map<String, Integer> nameUseCounts;

	private PanelCollectionProjection(long revision, boolean remote,
		List<PanelCollectionLayout.CollectionCard> cards)
	{
		this.revision = revision;
		this.remote = remote;
		this.cards = List.copyOf(cards);
		Map<CardEntityKind, Map<Integer, Integer>> ids = new EnumMap<>(CardEntityKind.class);
		Map<String, Integer> names = new HashMap<>();
		for (CardEntityKind kind : CardEntityKind.values())
		{
			ids.put(kind, new HashMap<>());
		}
		for (PanelCollectionLayout.CollectionCard card : cards)
		{
			for (Integer id : card.getEntityIds())
			{
				ids.get(card.getKind()).merge(id, 1, Integer::sum);
			}
			for (String name : card.getAcceptedNamesLowerCase())
			{
				names.merge(normalize(name), 1, Integer::sum);
			}
		}
		idUseCounts = freezeCounts(ids);
		nameUseCounts = Collections.unmodifiableMap(new LinkedHashMap<>(names));
	}

	static PanelCollectionProjection unavailable(long revision)
	{
		return new PanelCollectionProjection(revision, false, Collections.emptyList());
	}

	static PanelCollectionProjection fromActive(PanelCollectionLayout layout,
		ActiveCardIdentityCatalog.View active)
	{
		if (!active.isV1CatalogAvailable())
		{
			return unavailable(active.getRevision());
		}

		Map<CardEntityKind, Map<String, PanelCollectionLayout.CollectionPlacement>> exact =
			new EnumMap<>(CardEntityKind.class);
		Map<CardEntityKind, Map<String, Set<PanelCollectionLayout.CollectionPlacement>>> aliases =
			new EnumMap<>(CardEntityKind.class);
		Map<PanelCollectionLayout.CollectionPlacement, Integer> layoutOrder = new HashMap<>();
		for (CardEntityKind kind : CardEntityKind.values())
		{
			exact.put(kind, new HashMap<>());
			aliases.put(kind, new HashMap<>());
		}
		int order = 0;
		for (PanelCollectionLayout.CollectionPlacement placement : layout.getCollectionPlacements())
		{
			layoutOrder.put(placement, order++);
			exact.get(placement.getKind()).put(
				normalize(placement.getCardName()), placement);
		}
		for (PanelCollectionLayout.BetaCollectionCard beta : layout.getBetaCollectionCards())
		{
			PanelCollectionLayout.CollectionPlacement placement = exact.get(beta.getKind())
				.get(normalize(beta.getParentName()));
			if (placement == null)
			{
				continue;
			}
			for (PanelCollectionLayout.BetaVariant variant : beta.getVariants())
			{
				aliases.get(beta.getKind())
					.computeIfAbsent(normalize(variant.getName()),
						ignored -> new LinkedHashSet<>())
					.add(placement);
			}
		}

		List<RankedCard> ranked = new ArrayList<>();
		for (CardIdentity identity : active.getCardIdentities())
		{
			PanelCollectionLayout.CollectionPlacement placement = exact.get(identity.getKind())
				.get(normalize(identity.getCardName()));
			if (placement == null)
			{
				LinkedHashSet<PanelCollectionLayout.CollectionPlacement> candidates =
					new LinkedHashSet<>();
				for (String legacyName : identity.getLegacyCardNames())
				{
					PanelCollectionLayout.CollectionPlacement match = exact.get(identity.getKind())
						.get(normalize(legacyName));
					if (match != null)
					{
						candidates.add(match);
					}
					candidates.addAll(aliases.get(identity.getKind()).getOrDefault(
						normalize(legacyName), Collections.emptySet()));
				}
				if (candidates.size() == 1)
				{
					placement = candidates.iterator().next();
				}
			}
			Set<String> categories = placement == null
				? Collections.emptySet() : placement.getCategoryIds();
			ranked.add(new RankedCard(PanelCollectionLayout.CollectionCard.fromIdentity(
				identity, categories), placement == null
					? Integer.MAX_VALUE : layoutOrder.get(placement)));
		}
		ranked.sort(Comparator.comparingInt(RankedCard::getOrder)
			.thenComparing(card -> card.card.getKind())
			.thenComparing(card -> card.card.getCardName(), String.CASE_INSENSITIVE_ORDER));
		List<PanelCollectionLayout.CollectionCard> projected = new ArrayList<>();
		for (RankedCard card : ranked)
		{
			projected.add(card.card);
		}
		return new PanelCollectionProjection(active.getRevision(), true, projected);
	}

	long getRevision()
	{
		return revision;
	}

	boolean isRemote()
	{
		return remote;
	}

	List<PanelCollectionLayout.CollectionCard> getCards()
	{
		return cards;
	}

	boolean isEntityIdUnique(CardEntityKind kind, int entityId)
	{
		return idUseCounts.getOrDefault(kind, Collections.emptyMap())
			.getOrDefault(entityId, 0) == 1;
	}

	boolean isAcceptedNameUnique(String name)
	{
		return name != null && nameUseCounts.getOrDefault(normalize(name), 0) == 1;
	}

	private static Map<CardEntityKind, Map<Integer, Integer>> freezeCounts(
		Map<CardEntityKind, Map<Integer, Integer>> source)
	{
		Map<CardEntityKind, Map<Integer, Integer>> result =
			new EnumMap<>(CardEntityKind.class);
		for (Map.Entry<CardEntityKind, Map<Integer, Integer>> entry : source.entrySet())
		{
			result.put(entry.getKey(), Collections.unmodifiableMap(
				new LinkedHashMap<>(entry.getValue())));
		}
		return Collections.unmodifiableMap(result);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	private static final class RankedCard
	{
		private final PanelCollectionLayout.CollectionCard card;
		private final int order;

		private RankedCard(PanelCollectionLayout.CollectionCard card, int order)
		{
			this.card = card;
			this.order = order;
		}

		private int getOrder()
		{
			return order;
		}
	}
}

package com.bronzemantcg.panel.collection;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.BetaCardCacheService;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Prepared hierarchy and exact variant ownership for the Beta Collection tab. */
@Singleton
public final class PanelBetaCollectionViewModel
{
	private final PanelCollectionOwnership ownership;
	private final List<Section> sections;
	private final List<PanelCollectionLayout.BetaCollectionCard> parents;
	private final Map<PanelCollectionLayout.BetaCollectionCard, String> displayNames;
	private final int variantTotal;

	@Inject
	public PanelBetaCollectionViewModel(PanelCollectionLayout catalog,
		PanelCollectionOwnership ownership)
	{
		this.ownership = ownership;
		Map<String, CategoryBuilder> categories = new LinkedHashMap<>();
		List<SectionBuilder> sectionBuilders = new ArrayList<>();
		for (PanelCollectionLayout.Section sourceSection : catalog.getSections())
		{
			if (!sourceSection.isVisible())
			{
				continue;
			}
			SectionBuilder section = new SectionBuilder(
				sourceSection.getId(), sourceSection.getName());
			for (PanelCollectionLayout.Category sourceCategory : sourceSection.getCategories())
			{
				if (sourceCategory.isVisible())
				{
					CategoryBuilder category = new CategoryBuilder(
						sourceCategory.getId(), sourceCategory.getName());
					section.categories.add(category);
					categories.put(category.id, category);
				}
			}
			sectionBuilders.add(section);
		}

		List<PanelCollectionLayout.BetaCollectionCard> visibleParents = new ArrayList<>();
		int variants = 0;
		for (PanelCollectionLayout.BetaCollectionCard card : catalog.getBetaCollectionCards())
		{
			if (!card.isVisible())
			{
				continue;
			}
			visibleParents.add(card);
			variants += card.getVariants().size();
			for (String categoryId : card.getCategoryIds())
			{
				CategoryBuilder category = categories.get(categoryId);
				if (category != null)
				{
					category.cards.add(card);
				}
			}
		}

		List<Section> builtSections = new ArrayList<>();
		for (SectionBuilder section : sectionBuilders)
		{
			Section built = section.build();
			if (!built.getCategories().isEmpty())
			{
				builtSections.add(built);
			}
		}
		sections = List.copyOf(builtSections);
		parents = List.copyOf(visibleParents);
		variantTotal = variants;
		displayNames = buildDisplayNames(visibleParents);
	}

	public List<Section> getSections()
	{
		return sections;
	}

	public List<PanelCollectionLayout.BetaCollectionCard> getParents()
	{
		return parents;
	}

	public int getParentTotal()
	{
		return parents.size();
	}

	public int getVariantTotal()
	{
		return variantTotal;
	}

	public String getDisplayName(PanelCollectionLayout.BetaCollectionCard card)
	{
		return displayNames.getOrDefault(card, card.getParentName());
	}

	public boolean parentNameMatches(PanelCollectionLayout.BetaCollectionCard card, String query)
	{
		return normalize(card.getParentName()).contains(normalize(query));
	}

	/** True when expanding the parent explains more than repeating the same card name. */
	public boolean hasVariantBreakdown(PanelCollectionLayout.BetaCollectionCard card)
	{
		List<PanelCollectionLayout.BetaVariant> variants = card.getVariants();
		if (variants.size() != 1)
		{
			return variants.size() > 1;
		}
		return !normalize(variants.get(0).getName())
			.equals(normalize(card.getParentName()));
	}

	public List<PanelCollectionLayout.BetaVariant> matchingVariants(
		PanelCollectionLayout.BetaCollectionCard card, String query)
	{
		if (!hasVariantBreakdown(card))
		{
			return Collections.emptyList();
		}
		String normalized = normalize(query);
		List<PanelCollectionLayout.BetaVariant> matches = new ArrayList<>();
		for (PanelCollectionLayout.BetaVariant variant : card.getVariants())
		{
			if (normalize(variant.getName()).contains(normalized))
			{
				matches.add(variant);
			}
		}
		return matches;
	}

	public State prepare(Set<String> cachedBetaNames,
		BetaCardCacheService.Status cacheStatus)
	{
		Set<String> safeNames = cachedBetaNames == null
			? Collections.emptySet() : cachedBetaNames;
		Map<PanelCollectionLayout.BetaCollectionCard, PanelCollectionViewModel.Status>
			parentStates = new LinkedHashMap<>();
		Map<PanelCollectionLayout.BetaVariant, PanelCollectionViewModel.Status>
			variantStates = new LinkedHashMap<>();
		int ownedParents = 0;
		Set<String> unmatched = new java.util.TreeSet<>(safeNames);
		for (PanelCollectionLayout.BetaCollectionCard parent : parents)
		{
			boolean parentOwned = false;
			for (PanelCollectionLayout.BetaVariant variant : parent.getVariants())
			{
				unmatched.remove(normalize(variant.getName()));
				boolean variantOwned = ownership.isBetaVariantOwnedByNames(
					variant, safeNames);
				PanelCollectionViewModel.Status status = variantOwned
					? PanelCollectionViewModel.Status.OWNED
					: PanelCollectionViewModel.Status.LOCKED;
				parentOwned |= variantOwned;
				variantStates.put(variant, status);
			}
			PanelCollectionViewModel.Status parentStatus = parentOwned
				? PanelCollectionViewModel.Status.OWNED
				: PanelCollectionViewModel.Status.LOCKED;
			if (parentOwned)
			{
				ownedParents++;
			}
			parentStates.put(parent, parentStatus);
		}
		return new State(parentStates, variantStates, ownedParents, cacheStatus, unmatched);
	}

	private static Map<PanelCollectionLayout.BetaCollectionCard, String> buildDisplayNames(
		List<PanelCollectionLayout.BetaCollectionCard> cards)
	{
		Map<String, Integer> nameCounts = new HashMap<>();
		for (PanelCollectionLayout.BetaCollectionCard card : cards)
		{
			nameCounts.merge(normalize(card.getParentName()), 1, Integer::sum);
		}
		Map<PanelCollectionLayout.BetaCollectionCard, String> result = new LinkedHashMap<>();
		for (PanelCollectionLayout.BetaCollectionCard card : cards)
		{
			String displayName = card.getParentName();
			if (nameCounts.getOrDefault(normalize(displayName), 0) > 1)
			{
				displayName += card.getKind() == CardEntityKind.ITEM ? " (item)" : " (npc)";
			}
			result.put(card, displayName);
		}
		return Collections.unmodifiableMap(result);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	public static final class State
	{
		private final Map<PanelCollectionLayout.BetaCollectionCard,
			PanelCollectionViewModel.Status> parentStates;
		private final Map<PanelCollectionLayout.BetaVariant,
			PanelCollectionViewModel.Status> variantStates;
		private final int ownedParents;
		private final BetaCardCacheService.Status cacheStatus;
		private final Set<String> unmatchedNames;

		private State(Map<PanelCollectionLayout.BetaCollectionCard,
			PanelCollectionViewModel.Status> parentStates,
			Map<PanelCollectionLayout.BetaVariant,
				PanelCollectionViewModel.Status> variantStates,
			int ownedParents, BetaCardCacheService.Status cacheStatus,
			Set<String> unmatchedNames)
		{
			this.parentStates = Collections.unmodifiableMap(new LinkedHashMap<>(parentStates));
			this.variantStates = Collections.unmodifiableMap(new LinkedHashMap<>(variantStates));
			this.ownedParents = ownedParents;
			this.cacheStatus = cacheStatus;
			this.unmatchedNames = Collections.unmodifiableSet(new LinkedHashSet<>(unmatchedNames));
		}

		public Set<String> getUnmatchedNames()
		{
			return unmatchedNames;
		}

		public PanelCollectionViewModel.Status getParentStatus(
			PanelCollectionLayout.BetaCollectionCard card)
		{
			return parentStates.getOrDefault(card, PanelCollectionViewModel.Status.LOCKED);
		}

		public PanelCollectionViewModel.Status getVariantStatus(
			PanelCollectionLayout.BetaVariant variant)
		{
			return variantStates.getOrDefault(variant, PanelCollectionViewModel.Status.LOCKED);
		}

		public int getOwnedParents()
		{
			return ownedParents;
		}

		public BetaCardCacheService.Status getCacheStatus()
		{
			return cacheStatus;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof State))
			{
				return false;
			}
			State state = (State) other;
			return ownedParents == state.ownedParents
				&& cacheStatus == state.cacheStatus
				&& unmatchedNames.equals(state.unmatchedNames)
				&& parentStates.equals(state.parentStates)
				&& variantStates.equals(state.variantStates);
		}

		@Override
		public int hashCode()
		{
			int result = parentStates.hashCode();
			result = 31 * result + variantStates.hashCode();
			result = 31 * result + ownedParents;
			result = 31 * result + cacheStatus.hashCode();
			return 31 * result + unmatchedNames.hashCode();
		}
	}

	public static final class Section
	{
		private final String id;
		private final String name;
		private final List<Category> categories;
		private final List<PanelCollectionLayout.BetaCollectionCard> cards;

		private Section(String id, String name, List<Category> categories)
		{
			this.id = id;
			this.name = name;
			this.categories = List.copyOf(categories);
			LinkedHashSet<PanelCollectionLayout.BetaCollectionCard> values =
				new LinkedHashSet<>();
			for (Category category : categories)
			{
				values.addAll(category.getCards());
			}
			cards = List.copyOf(values);
		}

		public String getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public List<Category> getCategories()
		{
			return categories;
		}

		public List<PanelCollectionLayout.BetaCollectionCard> getCards()
		{
			return cards;
		}
	}

	public static final class Category
	{
		private final String id;
		private final String name;
		private final List<PanelCollectionLayout.BetaCollectionCard> cards;

		private Category(String id, String name,
			List<PanelCollectionLayout.BetaCollectionCard> cards)
		{
			this.id = id;
			this.name = name;
			this.cards = List.copyOf(cards);
		}

		public String getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public List<PanelCollectionLayout.BetaCollectionCard> getCards()
		{
			return cards;
		}
	}

	private static final class SectionBuilder
	{
		private final String id;
		private final String name;
		private final List<CategoryBuilder> categories = new ArrayList<>();

		private SectionBuilder(String id, String name)
		{
			this.id = id;
			this.name = name;
		}

		private Section build()
		{
			List<Category> built = new ArrayList<>();
			for (CategoryBuilder category : categories)
			{
				if (!category.cards.isEmpty())
				{
					built.add(category.build());
				}
			}
			return new Section(id, name, built);
		}
	}

	private static final class CategoryBuilder
	{
		private final String id;
		private final String name;
		private final List<PanelCollectionLayout.BetaCollectionCard> cards = new ArrayList<>();

		private CategoryBuilder(String id, String name)
		{
			this.id = id;
			this.name = name;
		}

		private Category build()
		{
			return new Category(id, name, cards);
		}
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.catalog.ContentCatalog;
import com.bronzemantcg.catalog.QuestCatalog;
import com.bronzemantcg.catalog.ResourceNodeCatalog;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Selects informational side-panel rows for old name-only and v1-capable OSRS TCG payloads.
 * The pre-v1 resource contains presentation overrides only; restriction catalogues always keep
 * using their current data.
 */
@Slf4j
@Singleton
public class PanelPresentationCatalog
{
	private static final String RESOURCE = "/panel/pre_v1_presentation_overrides.json";
	private static final int SCHEMA_VERSION = 1;
	private static final Set<String> PRE_V1_NODE_NAMES = Set.of(
		"guild hunter aco", "guild hunter cervus", "guild hunter teco",
		"guild hunter wolf", "huntmaster gilman", "achtryn");

	private final Data current;
	private final Data preV1;

	@Inject
	public PanelPresentationCatalog(Gson gson, ContentCatalog contentCatalog,
		ResourceNodeCatalog nodeCatalog)
	{
		current = currentData(contentCatalog, nodeCatalog);
		preV1 = loadPreV1(gson, current);
	}

	public Data select(boolean v1Capable)
	{
		return v1Capable ? current : preV1;
	}

	private Data loadPreV1(Gson gson, Data base)
	{
		try (InputStream stream = getClass().getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				throw new IllegalArgumentException("missing " + RESOURCE);
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			validate(snapshot);

			List<Checklist> contents = replace(base.contents,
				checklists(snapshot.contents));
			Map<String, Rule> slayer = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
			slayer.putAll(base.slayerRules);
			Map<String, Rule> rumours = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
			rumours.putAll(base.rumourRules);
			for (NodeDto node : snapshot.nodes)
			{
				Map<String, Rule> destination = "slayer".equals(node.category)
					? slayer : rumours;
				destination.put(node.name.trim(), rule(node));
			}
			log.info("Loaded pre-v1 panel presentation overrides from {}", snapshot.sourceCommit);
			return new Data(contents, slayer, rumours);
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Could not load pre-v1 panel presentation; using current data", ex);
			return base;
		}
	}

	private static Data currentData(ContentCatalog contentCatalog,
		ResourceNodeCatalog nodeCatalog)
	{
		List<Checklist> contents = new ArrayList<>();
		for (QuestCatalog.QuestEntry entry : contentCatalog.getContents())
		{
			List<String> cards = new ArrayList<>();
			for (QuestCatalog.Requirement requirement : entry.requirements)
			{
				cards.add(requirement.label);
			}
			contents.add(new Checklist(entry.name, cards, entry.notes));
		}
		return new Data(contents, rules(nodeCatalog, "slayer"),
			rules(nodeCatalog, "hunter-rumours"));
	}

	private static Map<String, Rule> rules(ResourceNodeCatalog catalog, String category)
	{
		Map<String, Rule> result = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Map.Entry<String, ResourceNodeCatalog.Rule> entry
			: catalog.getRuleEntries().entrySet())
		{
			if (!category.equals(entry.getValue().category))
			{
				continue;
			}
			String[] parts = entry.getKey().split("\\|", 3);
			String name = parts.length > 1 ? parts[1] : entry.getKey();
			List<Group> groups = new ArrayList<>();
			for (ResourceNodeCatalog.CardGroup group : entry.getValue().groups)
			{
				groups.add(new Group(group.displayCards, group.role, group.label));
			}
			result.put(name, new Rule(groups));
		}
		return result;
	}

	private static Rule rule(NodeDto node)
	{
		List<Group> groups = new ArrayList<>();
		for (int i = 0; i < node.requiredCardGroups.size(); i++)
		{
			List<String> cards = node.requiredCardGroups.get(i);
			String role = lowerValueAt(node.groupRoles, i);
			String label = valueAt(node.groupLabels, i);
			if (label == null && cards != null && !cards.isEmpty())
			{
				label = cards.get(0);
			}
			groups.add(new Group(cards, role, label));
		}
		return new Rule(groups);
	}

	private static String valueAt(List<String> values, int index)
	{
		if (values == null || index >= values.size() || values.get(index) == null
			|| values.get(index).trim().isEmpty())
		{
			return null;
		}
		return values.get(index).trim();
	}

	private static String lowerValueAt(List<String> values, int index)
	{
		String value = valueAt(values, index);
		return value == null ? null : value.toLowerCase(Locale.ROOT);
	}

	private static List<Checklist> checklists(List<ChecklistDto> source)
	{
		List<Checklist> result = new ArrayList<>();
		for (ChecklistDto entry : source)
		{
			result.add(new Checklist(entry.name, entry.monsterCards, entry.notes));
		}
		return result;
	}

	private static List<Checklist> replace(List<Checklist> base,
		List<Checklist> overrides)
	{
		Map<String, Checklist> replacements = new LinkedHashMap<>();
		for (Checklist entry : overrides)
		{
			replacements.put(entry.name.toLowerCase(Locale.ROOT), entry);
		}
		List<Checklist> result = new ArrayList<>();
		for (Checklist entry : base)
		{
			result.add(replacements.getOrDefault(
				entry.name.toLowerCase(Locale.ROOT), entry));
		}
		if (!replacements.keySet().stream().allMatch(key -> result.stream()
			.anyMatch(entry -> entry.name.equalsIgnoreCase(key))))
		{
			throw new IllegalArgumentException("pre-v1 override does not match current row");
		}
		return result;
	}

	private static void validate(Snapshot snapshot)
	{
		if (snapshot == null || snapshot.schemaVersion != SCHEMA_VERSION
			|| snapshot.sourceCommit == null || snapshot.sourceCommit.trim().isEmpty()
			|| snapshot.contents == null || snapshot.contents.size() != 1
			|| snapshot.nodes == null || snapshot.nodes.size() != 6)
		{
			throw new IllegalArgumentException("invalid pre-v1 presentation snapshot");
		}
		Set<String> names = new java.util.HashSet<>();
		for (NodeDto node : snapshot.nodes)
		{
			if (node == null || node.name == null || node.category == null
				|| node.requiredCardGroups == null
				|| !("slayer".equals(node.category)
					|| "hunter-rumours".equals(node.category))
				|| !names.add(node.name.trim().toLowerCase(Locale.ROOT)))
			{
				throw new IllegalArgumentException("invalid pre-v1 presentation node");
			}
		}
		if (!names.equals(PRE_V1_NODE_NAMES))
		{
			throw new IllegalArgumentException("unexpected pre-v1 presentation nodes");
		}
	}

	public static final class Data
	{
		private final List<Checklist> contents;
		private final Map<String, Rule> slayerRules;
		private final Map<String, Rule> rumourRules;

		private Data(List<Checklist> contents, Map<String, Rule> slayerRules,
			Map<String, Rule> rumourRules)
		{
			this.contents = List.copyOf(contents);
			Map<String, Rule> slayerCopy = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
			slayerCopy.putAll(slayerRules);
			this.slayerRules = Collections.unmodifiableMap(slayerCopy);
			Map<String, Rule> rumourCopy = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
			rumourCopy.putAll(rumourRules);
			this.rumourRules = Collections.unmodifiableMap(rumourCopy);
		}

		public List<Checklist> getContents()
		{
			return contents;
		}

		public Map<String, Rule> getSlayerRules()
