	/**
	 * Same look with an explicit left inset. The side-panel tabs nest four levels deep
	 * where the settings view only nests two, so they carry their own indentation while
	 * sharing these colours - keep this the single definition of the bronze row style.
	 */
	public static void styleHierarchyRow(JPanel row, boolean expanded, boolean nested,
		int leftPadding)
	{
		Color bronze = nested ? new Color(138, 94, 52) : new Color(153, 102, 51);
		Color background = expanded ? new Color(62, 50, 40)
			: ColorScheme.DARKER_GRAY_COLOR;
		int verticalPadding = nested ? 3 : 5;
		row.setBackground(background);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(bronze),
			BorderFactory.createEmptyBorder(
				verticalPadding, leftPadding, verticalPadding, nested ? 5 : 7)));
	}

	/** Swing mouse events do not bubble from child labels. */
	public static void makeClickable(Component component, Runnable action)
	{
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent event)
			{
				action.run();
			}
		});
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				makeClickable(child, action);
			}
		}
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.catalog.QuestCatalog;
import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.CardResolver;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Projects the pinned pre-v1 quest checklist onto one active v1 identity revision. */
@Singleton
public final class QuestV1Presentation
{
	private final ActiveCardIdentityCatalog activeCatalog;

	@Inject
	public QuestV1Presentation(ActiveCardIdentityCatalog activeCatalog)
	{
		this.activeCatalog = activeCatalog;
	}

	public long getRevision()
	{
		return activeCatalog.getRevision();
	}

	public Data project(QuestCatalog source)
	{
		ActiveCardIdentityCatalog.View view = activeCatalog.getView();
		CardResolver resolver = new CardResolver(view);
		return new Data(view.getRevision(), project(source.getQuests(), resolver),
			project(source.getMiniquests(), resolver));
	}

	private static List<QuestCatalog.QuestEntry> project(
		List<QuestCatalog.QuestEntry> entries, CardResolver resolver)
	{
		List<QuestCatalog.QuestEntry> projected = new ArrayList<>();
		for (QuestCatalog.QuestEntry entry : entries)
		{
			List<QuestCatalog.Section> sections = new ArrayList<>();
			for (QuestCatalog.Section section : entry.sections)
			{
				List<QuestCatalog.Requirement> requirements = new ArrayList<>();
				for (QuestCatalog.Requirement requirement : section.requirements)
				{
					Projection result = project(requirement, resolver);
					if (!result.unrestricted)
					{
						requirements.add(result.requirement);
					}
				}
				sections.add(section.withRequirements(requirements));
			}
			projected.add(entry.withSections(sections));
		}
		return Collections.unmodifiableList(projected);
	}

	private static Projection project(QuestCatalog.Requirement source,
		CardResolver resolver)
	{
		List<QuestCatalog.Requirement> children = new ArrayList<>();
		boolean unrestrictedChild = false;
		boolean restrictedChild = false;
		boolean routed = !source.selector.isEmpty();
		for (QuestCatalog.Requirement child : source.children)
		{
			Projection projected = project(child, resolver);
			if (projected.unrestricted)
			{
				unrestrictedChild = true;
				if (routed)
				{
					children.add(child.withProjection(Collections.emptyList(),
						Collections.emptyList(), Collections.emptyList()));
				}
			}
			else
			{
				restrictedChild = true;
				children.add(projected.requirement);
			}
		}

		if (!source.children.isEmpty())
		{
			if (routed && unrestrictedChild && !restrictedChild)
			{
				return Projection.unrestricted();
			}
			if (!routed && ((source.logic == QuestCatalog.Logic.ANY && unrestrictedChild)
				|| (source.logic == QuestCatalog.Logic.ALL && children.isEmpty())))
			{
				return Projection.unrestricted();
			}
			MappedCards display = mapCards(source.displayCards, source.type, resolver);
			return Projection.restricted(source.withProjection(
				display.displayCards, display.acceptedCards, children));
		}

		MappedCards cards = mapCards(source.displayCards, source.type, resolver);
		if (cards.untrackedAlternative || cards.acceptedCards.isEmpty())
		{
			return Projection.unrestricted();
		}
		return Projection.restricted(source.withProjection(
			cards.displayCards, cards.acceptedCards, Collections.emptyList()));
	}

	private static MappedCards mapCards(List<String> sourceCards, String type,
		CardResolver resolver)
	{
		Map<String, String> display = new LinkedHashMap<>();
		Map<String, String> accepted = new LinkedHashMap<>();
		boolean untracked = false;
		for (String sourceCard : sourceCards)
		{
			CardIdentity identity = resolve(sourceCard, type, resolver);
			if (identity == null)
			{
				untracked = true;
				continue;
			}
			display.putIfAbsent(normalize(identity.getCardName()), identity.getCardName());
			accepted.putIfAbsent(normalize(identity.getCardName()), identity.getCardName());
			for (String legacyName : identity.getLegacyCardNames())
			{
				accepted.putIfAbsent(normalize(legacyName), legacyName);
			}
		}
		return new MappedCards(new ArrayList<>(display.values()),
			new ArrayList<>(accepted.values()), untracked);
	}

	private static CardIdentity resolve(String card, String type, CardResolver resolver)
	{
		if ("item".equals(type))
		{
			return tracked(resolver.resolveCardName(CardEntityKind.ITEM, card));
		}
		if ("enemy".equals(type) || "npc".equals(type))
		{
			return tracked(resolver.resolveCardName(CardEntityKind.NPC, card));
		}
		CardIdentity item = tracked(
			resolver.resolveCardName(CardEntityKind.ITEM, card));
		CardIdentity npc = tracked(
			resolver.resolveCardName(CardEntityKind.NPC, card));
		return item == null ? npc : npc == null ? item : null;
	}

	private static CardIdentity tracked(CardResolver.Result result)
	{
		return result.isTracked() ? result.getIdentity() : null;
	}

	private static String normalize(String value)
	{
		return value.trim().toLowerCase(Locale.ROOT);
	}

	public static final class Data
	{
		private final long revision;
		private final List<QuestCatalog.QuestEntry> quests;
		private final List<QuestCatalog.QuestEntry> miniquests;

		private Data(long revision, List<QuestCatalog.QuestEntry> quests,
			List<QuestCatalog.QuestEntry> miniquests)
		{
			this.revision = revision;
			this.quests = quests;
			this.miniquests = miniquests;
		}

		public long getRevision()
		{
			return revision;
		}

		public List<QuestCatalog.QuestEntry> getQuests()
		{
			return quests;
		}

		public List<QuestCatalog.QuestEntry> getMiniquests()
		{
			return miniquests;
		}
	}

	private static final class Projection
	{
		private final QuestCatalog.Requirement requirement;
		private final boolean unrestricted;

		private Projection(QuestCatalog.Requirement requirement, boolean unrestricted)
		{
			this.requirement = requirement;
			this.unrestricted = unrestricted;
		}

		private static Projection restricted(QuestCatalog.Requirement requirement)
		{
			return new Projection(requirement, false);
		}

		private static Projection unrestricted()
		{
			return new Projection(null, true);
		}
	}

	private static final class MappedCards
	{
		private final List<String> displayCards;
		private final List<String> acceptedCards;
		private final boolean untrackedAlternative;

		private MappedCards(List<String> displayCards, List<String> acceptedCards,
			boolean untrackedAlternative)
		{
			this.displayCards = displayCards;
			this.acceptedCards = acceptedCards;
			this.untrackedAlternative = untrackedAlternative;
		}
	}
}

package com.bronzemantcg.panel;

import com.bronzemantcg.BronzemanTcgConfig;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Records first-time card unlocks for the panel. The first readable collection per
 * profile is a silent baseline, so existing players do not receive a history flood.
 * Later additions are kept newest-first, independent of card pulls (duplicates do not
 * change the owned-name set), and persisted in a profile-hashed local cache.
 */
@Slf4j
@Singleton
public class RecentUnlocksTracker
{
	private static final String KEY = "recentUnlocks";
	private static final String SHARED_KEY = "recentSharedUnlocks";
	private static final int MAX_RECENT = RecentUnlocksCacheStore.MAX_RECENT;
	private final ProfileAccess profileAccess;
	private final Gson gson;
	private final RecentUnlocksCacheStore cacheStore;
	private List<Unlock> recent = new ArrayList<>();
	private List<Unlock> sharedRecent = new ArrayList<>();
	private Set<String> baseline;
	private Set<String> sharedBaseline;
	private Set<String> sharedSeen = new HashSet<>();
	private String loadedProfile;
	private boolean cleanPersonalLegacy;
	private boolean cleanSharedLegacy;

	@Inject
	public RecentUnlocksTracker(ConfigManager configManager, Gson gson,
		RecentUnlocksCacheStore cacheStore)
	{
		this(new ConfigManagerProfileAccess(configManager), gson, cacheStore);
	}

	RecentUnlocksTracker(ProfileAccess profileAccess, Gson gson,
		RecentUnlocksCacheStore cacheStore)
	{
		this.profileAccess = profileAccess;
		this.gson = gson;
		this.cacheStore = cacheStore;
	}

	/** Reload persisted history and await the current profile's first readable collection. */
	public synchronized void reload()
	{
		baseline = null;
		sharedBaseline = null;
		sharedSeen = new HashSet<>();
		recent = new ArrayList<>();
		sharedRecent = new ArrayList<>();
		cleanPersonalLegacy = false;
		cleanSharedLegacy = false;
		loadedProfile = profileAccess.currentProfileKey();
		if (loadedProfile == null || loadedProfile.trim().isEmpty())
		{
			return;
		}

		RecentUnlocksCacheStore.Record cached = loadCache(loadedProfile);
		List<Unlock> cachedPersonal = cached == null
			? Collections.emptyList() : cached.getPersonal();
		List<Unlock> cachedShared = cached == null
			? Collections.emptyList() : cached.getShared();

		LegacyHistory personalLegacy = loadLegacy(loadedProfile, KEY, false);
		LegacyHistory sharedLegacy = loadLegacy(loadedProfile, SHARED_KEY, true);
		if (personalLegacy.invalid || sharedLegacy.invalid)
		{
			recent = mergeHistory(cachedPersonal, personalLegacy.invalid
				? Collections.emptyList() : personalLegacy.history, false);
			sharedRecent = mergeHistory(cachedShared, sharedLegacy.invalid
				? Collections.emptyList() : sharedLegacy.history, true);
			rebuildSharedSeen();
			return;
		}
		cleanPersonalLegacy = personalLegacy.present;
		cleanSharedLegacy = sharedLegacy.present;
		recent = mergeHistory(cachedPersonal, personalLegacy.history, false);
		sharedRecent = mergeHistory(cachedShared, sharedLegacy.history, true);
		if (personalLegacy.present || sharedLegacy.present)
		{
			persist();
		}
		rebuildSharedSeen();
	}

	private RecentUnlocksCacheStore.Record loadCache(String profile)
	{
		try
		{
			return cacheStore.load(profile);
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Could not load the local Recent Unlocks cache", ex);
			return null;
		}
	}

	private LegacyHistory loadLegacy(String profile, String key, boolean shared)
	{
		try
		{
			String raw = profileAccess.loadConfiguration(profile, key);
			if (raw == null || raw.isEmpty())
			{
				return LegacyHistory.missing();
			}
			Unlock[] loaded = gson.fromJson(raw, Unlock[].class);
			List<Unlock> history = loaded == null
				? Collections.emptyList() : Arrays.asList(loaded);
			return LegacyHistory.present(
				RecentUnlocksCacheStore.validateHistory(history, shared));
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Could not migrate a stored Recent Unlocks history; it was kept", ex);
			return LegacyHistory.invalid();
		}
	}

	/**
	 * The API is authoritative over the config fallback. When it first arrives, take its
	 * complete collection as the baseline too, rather than mistaking a stale fallback
	 * snapshot for a batch of new unlocks.
	 */
	public synchronized void resetBaseline()
	{
		baseline = null;
	}

	/**
	 * @return true only when this observation records one or more genuinely new cards.
	 */
	public synchronized boolean update(Set<String> owned, boolean stateAvailable)
	{
		if (!stateAvailable)
		{
			return false;
		}
		if (baseline == null)
		{
			baseline = new HashSet<>(owned);
			return false;
		}

		List<String> added = owned.stream()
			.filter(name -> !baseline.contains(name))
			.sorted()
			.collect(Collectors.toList());
		baseline = new HashSet<>(owned);
		if (added.isEmpty())
		{
			return false;
		}

		long now = System.currentTimeMillis();
		for (int i = added.size() - 1; i >= 0; i--)
		{
			recent.add(0, new Unlock(added.get(i), now));
		}
		while (recent.size() > MAX_RECENT)
		{
			recent.remove(recent.size() - 1);
		}
		persist();
		return true;
	}

	public synchronized List<Unlock> getRecent()
	{
		return Collections.unmodifiableList(new ArrayList<>(recent));
	}

	/**
	 * Observe the current effective shared set. The first payload is a silent baseline; later,
	 * genuinely unseen additions are persisted newest-first. Cards withdrawn and re-offered in
	 * the same session are not presented as new again.
	 */
	public synchronized boolean updateShared(Set<String> shared)
	{
		if (sharedBaseline == null)
		{
			sharedBaseline = new HashSet<>(shared);
			sharedSeen.addAll(shared);
			return false;
		}

		List<String> added = newSharedNames(shared, sharedBaseline, sharedSeen);
		sharedBaseline = new HashSet<>(shared);
		sharedSeen.addAll(shared);
		if (added.isEmpty())
		{
			return false;
		}

		long now = System.currentTimeMillis();
		for (int i = added.size() - 1; i >= 0; i--)
		{
			sharedRecent.add(0, new Unlock(added.get(i), now, true));
		}
		while (sharedRecent.size() > MAX_RECENT)
		{
			sharedRecent.remove(sharedRecent.size() - 1);
		}
		persist();
		return true;
	}

	private void persist()
	{
		String currentProfile = profileAccess.currentProfileKey();
		if (loadedProfile == null || !Objects.equals(loadedProfile, currentProfile))
		{
			return;
		}
		try
		{
			cacheStore.save(loadedProfile, recent, sharedRecent);
			RecentUnlocksCacheStore.Record verified = cacheStore.load(loadedProfile);
			if (verified == null || !sameHistory(recent, verified.getPersonal())
				|| !sameHistory(sharedRecent, verified.getShared()))
			{
				throw new IOException("Recent Unlocks cache verification failed");
			}
			if (!Objects.equals(loadedProfile, profileAccess.currentProfileKey()))
			{
				return;
			}
			cleanupLegacyValues();
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Could not save the local Recent Unlocks cache or finish migration", ex);
		}
	}

	private void rebuildSharedSeen()
	{
		sharedSeen.clear();
		for (Unlock unlock : sharedRecent)
		{
			sharedSeen.add(unlock.name);
		}
	}

	private void cleanupLegacyValues()
	{
		if (cleanPersonalLegacy)
		{
			profileAccess.unsetConfiguration(loadedProfile, KEY);
			cleanPersonalLegacy = false;
		}
		if (cleanSharedLegacy)
		{
			profileAccess.unsetConfiguration(loadedProfile, SHARED_KEY);
			cleanSharedLegacy = false;
		}
	}

	static List<Unlock> mergeHistory(List<Unlock> cached, List<Unlock> legacy,
		boolean shared)
	{
		Map<String, Unlock> newestByName = new LinkedHashMap<>();
		mergeInto(newestByName, cached, shared);
		mergeInto(newestByName, legacy, shared);
		List<Unlock> merged = new ArrayList<>(newestByName.values());
		merged.sort(Comparator.comparingLong((Unlock unlock) -> unlock.time).reversed()
			.thenComparing(unlock -> unlock.name));
		if (merged.size() > MAX_RECENT)
		{
			merged = new ArrayList<>(merged.subList(0, MAX_RECENT));
		}
		return merged;
	}

	private static void mergeInto(Map<String, Unlock> newestByName, List<Unlock> history,
		boolean shared)
	{
		for (Unlock unlock : history)
		{
			String name = unlock.name.trim().toLowerCase(java.util.Locale.ROOT);
			Unlock current = newestByName.get(name);
			if (current == null || unlock.time > current.time)
			{
				newestByName.put(name, new Unlock(name, unlock.time, shared));
			}
		}
	}

	static boolean sameHistory(List<Unlock> left, List<Unlock> right)
	{
		if (left.size() != right.size())
		{
			return false;
		}
		for (int i = 0; i < left.size(); i++)
		{
			Unlock a = left.get(i);
			Unlock b = right.get(i);
			if (!a.name.equals(b.name) || a.time != b.time || a.shared != b.shared)
			{
				return false;
			}
		}
		return true;
	}

	static List<String> newSharedNames(Set<String> shared, Set<String> baseline, Set<String> seen)
	{
		return shared.stream()
			.filter(name -> !baseline.contains(name) && !seen.contains(name))
			.sorted()
			.collect(Collectors.toList());
	}

	public synchronized List<Unlock> getSharedRecent()
	{
		return Collections.unmodifiableList(new ArrayList<>(sharedRecent));
	}

	/** One locally observed unlock. The name is normalized just like TcgCollectionReader. */
	public static class Unlock
	{
		final String name;
		final long time;
		final boolean shared;

		Unlock(String name, long time)
		{
			this(name, time, false);
		}

		Unlock(String name, long time, boolean shared)
		{
			this.name = name;
			this.time = time;
			this.shared = shared;
		}
	}

	interface ProfileAccess
	{
		String currentProfileKey();

		String loadConfiguration(String profile, String key);

		void unsetConfiguration(String profile, String key);
	}

	private static final class ConfigManagerProfileAccess implements ProfileAccess
	{
		private final ConfigManager configManager;

		private ConfigManagerProfileAccess(ConfigManager configManager)
		{
			this.configManager = configManager;
		}

		@Override
		public String currentProfileKey()
		{
			return configManager.getRSProfileKey();
		}

		@Override
		public String loadConfiguration(String profile, String key)
		{
			return configManager.getConfiguration(BronzemanTcgConfig.GROUP, profile, key);
		}

		@Override
		public void unsetConfiguration(String profile, String key)
		{
			configManager.unsetConfiguration(BronzemanTcgConfig.GROUP, profile, key);
		}
	}

	private static final class LegacyHistory
	{
		private final boolean present;
		private final boolean invalid;
		private final List<Unlock> history;

		private LegacyHistory(boolean present, boolean invalid, List<Unlock> history)
		{
			this.present = present;
			this.invalid = invalid;
			this.history = history;
		}

		private static LegacyHistory missing()
		{
			return new LegacyHistory(false, false, Collections.emptyList());
		}

		private static LegacyHistory present(List<Unlock> history)
		{
			return new LegacyHistory(true, false, history);
		}

		private static LegacyHistory invalid()
		{
			return new LegacyHistory(true, true, Collections.emptyList());
		}
	}
}

package com.bronzemantcg.ownership;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Shared immutable indexes used by bundled and remotely parsed card identities. */
public final class ImmutableCardIdentityCatalog implements CardIdentityCatalog
{
	private final List<Entry> entries;
	private final Map<CardEntityKind, Map<Integer, List<CardIdentity>>> byId;
	private final Map<CardEntityKind, Map<String, List<CardIdentity>>> byEntityName;
	private final Map<CardEntityKind, Map<String, List<CardIdentity>>> byCardName;
	private final Map<CardEntityKind, Integer> ambiguousIdCounts;

	public ImmutableCardIdentityCatalog(Iterable<Entry> sourceEntries)
	{
		Map<CardEntityKind, Map<Integer, List<CardIdentity>>> idIndex = enumIndex();
		Map<CardEntityKind, Map<String, List<CardIdentity>>> entityNameIndex = enumIndex();
		Map<CardEntityKind, Map<String, List<CardIdentity>>> cardNameIndex = enumIndex();
		List<Entry> loaded = new ArrayList<>();
		if (sourceEntries != null)
		{
			for (Entry entry : sourceEntries)
			{
				if (entry == null)
				{
					continue;
				}
				loaded.add(entry);
				CardIdentity identity = entry.identity;
				CardEntityKind kind = identity.getKind();
				addName(cardNameIndex.get(kind), normalize(identity.getCardName()), identity);
				for (String legacyCardName : identity.getLegacyCardNames())
				{
					addName(cardNameIndex.get(kind), normalize(legacyCardName), identity);
				}
				for (String entityName : entry.entityNames)
				{
					addName(entityNameIndex.get(kind), normalize(entityName), identity);
				}
				for (Integer entityId : identity.getEntityIds())
				{
					addId(idIndex.get(kind), entityId, identity);
				}
			}
		}
		entries = Collections.unmodifiableList(loaded);
		byId = freeze(idIndex);
		byEntityName = freeze(entityNameIndex);
		byCardName = freeze(cardNameIndex);
		Map<CardEntityKind, Integer> counts = new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			counts.put(kind, countAmbiguous(byId.get(kind)));
		}
		ambiguousIdCounts = Collections.unmodifiableMap(counts);
	}

	@Override
	public List<CardIdentity> findById(CardEntityKind kind, int entityId)
	{
		Map<Integer, List<CardIdentity>> index = byId.get(kind);
		return index == null ? Collections.emptyList()
			: index.getOrDefault(entityId, Collections.emptyList());
	}

	@Override
	public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
	{
		return find(byEntityName, kind, entityName);
	}

	@Override
	public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
	{
		return find(byCardName, kind, cardName);
	}

	public List<Entry> getEntries()
	{
		return entries;
	}

	public int size()
	{
		return entries.size();
	}

	public int getAmbiguousIdCount(CardEntityKind kind)
	{
		return ambiguousIdCounts.getOrDefault(kind, 0);
	}

	private static List<CardIdentity> find(
		Map<CardEntityKind, Map<String, List<CardIdentity>>> indexes,
		CardEntityKind kind, String value)
	{
		Map<String, List<CardIdentity>> index = indexes.get(kind);
		if (index == null)
		{
			return Collections.emptyList();
		}
		return index.getOrDefault(normalize(value), Collections.emptyList());
	}

	private static void addName(Map<String, List<CardIdentity>> index, String key,
		CardIdentity identity)
	{
		if (!key.isEmpty())
		{
			index.computeIfAbsent(key, ignored -> new ArrayList<>()).add(identity);
		}
	}

	private static void addId(Map<Integer, List<CardIdentity>> index, Integer key,
		CardIdentity identity)
	{
		if (key != null)
		{
			index.computeIfAbsent(key, ignored -> new ArrayList<>()).add(identity);
		}
	}

	private static int countAmbiguous(Map<Integer, List<CardIdentity>> index)
	{
		if (index == null)
		{
			return 0;
		}
		int count = 0;
		for (List<CardIdentity> matches : index.values())
		{
			if (matches.size() > 1)
			{
				count++;
			}
		}
		return count;
	}

	private static <K> Map<CardEntityKind, Map<K, List<CardIdentity>>> freeze(
		Map<CardEntityKind, Map<K, List<CardIdentity>>> source)
	{
		Map<CardEntityKind, Map<K, List<CardIdentity>>> result =
			new EnumMap<>(CardEntityKind.class);
		for (Map.Entry<CardEntityKind, Map<K, List<CardIdentity>>> kindEntry
			: source.entrySet())
		{
			Map<K, List<CardIdentity>> values = new LinkedHashMap<>();
			for (Map.Entry<K, List<CardIdentity>> entry : kindEntry.getValue().entrySet())
			{
				values.put(entry.getKey(), List.copyOf(entry.getValue()));
			}
			result.put(kindEntry.getKey(), Collections.unmodifiableMap(values));
		}
		return Collections.unmodifiableMap(result);
	}

	private static <K> Map<CardEntityKind, Map<K, List<CardIdentity>>> enumIndex()
	{
		Map<CardEntityKind, Map<K, List<CardIdentity>>> index =
			new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			index.put(kind, new LinkedHashMap<>());
		}
		return index;
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	/** One identity plus every in-game entity name which can resolve to it. */
	public static final class Entry
	{
		private final CardIdentity identity;
		private final Set<String> entityNames;

		public Entry(CardIdentity identity, Iterable<String> entityNames)
		{
			if (identity == null)
			{
				throw new IllegalArgumentException("identity is required");
			}
			this.identity = identity;
			Map<String, String> validNames = new LinkedHashMap<>();
			if (entityNames != null)
			{
				for (String entityName : entityNames)
				{
					String normalized = normalize(entityName);
					if (!normalized.isEmpty())
					{
						validNames.putIfAbsent(normalized, entityName.trim());
					}
				}
			}
			this.entityNames = Collections.unmodifiableSet(
				new LinkedHashSet<>(validNames.values()));
		}

		public CardIdentity getIdentity()
		{
			return identity;
		}

		public Set<String> getEntityNames()
		{
			return entityNames;
		}
	}
}

package com.bronzemantcg.ownership;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Atomically switches identity readers between the reviewed bundle and one validated revision. */
@Singleton
public final class ActiveCardIdentityCatalog implements CardIdentityCatalog
{
	private final BundledCardIdentityCatalog bundledCatalog;
	private final AtomicLong revisionSequence = new AtomicLong();
	private final AtomicReference<View> active;

	@Inject
	public ActiveCardIdentityCatalog(BundledCardIdentityCatalog bundledCatalog)
	{
		if (bundledCatalog == null)
		{
			throw new IllegalArgumentException("bundledCatalog is required");
		}
		this.bundledCatalog = bundledCatalog;
		active = new AtomicReference<>(new View(0L, "beta-fallback", false,
			bundledCatalog, bundledCatalog.getEntries()));
	}

	@Override
	public List<CardIdentity> findById(CardEntityKind kind, int entityId)
	{
		return active.get().catalog.findById(kind, entityId);
	}

	@Override
	public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
	{
		return active.get().catalog.findByName(kind, entityName);
	}

	@Override
	public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
	{
		return active.get().catalog.findByCardName(kind, cardName);
	}

	public synchronized long activate(CardIdentityCatalog catalog,
		List<ImmutableCardIdentityCatalog.Entry> entries, String version)
	{
		if (catalog == null || entries == null)
		{
			throw new IllegalArgumentException("validated catalogue and entries are required");
		}
		String cleanVersion = cleanVersion(version);
		View current = active.get();
		if (current.catalog == catalog && current.version.equals(cleanVersion))
		{
			return current.revision;
		}
		long revision = revisionSequence.incrementAndGet();
		active.set(new View(revision, cleanVersion, true, catalog, entries));
		return revision;
	}

	public synchronized long useBundled()
	{
		View current = active.get();
		if (!current.remote)
		{
			return current.revision;
		}
		long revision = revisionSequence.incrementAndGet();
		active.set(new View(revision, "beta-fallback", false,
			bundledCatalog, bundledCatalog.getEntries()));
		return revision;
	}

	public long getRevision()
	{
		return active.get().revision;
	}

	public boolean isRemoteActive()
	{
		return active.get().remote;
	}

	public boolean isV1CatalogAvailable()
	{
		return active.get().v1CatalogAvailable;
	}

	public View getView()
	{
		return active.get();
	}

	public String findDisplayCardName(String cardName)
	{
		return active.get().findDisplayCardName(cardName);
	}

	private static String cleanVersion(String version)
	{
		return version == null || version.trim().isEmpty() ? "unknown" : version.trim();
	}

	private static Map<CardEntityKind, Map<String, Set<String>>> projectEntityNames(
		List<ImmutableCardIdentityCatalog.Entry> entries)
	{
		Map<CardEntityKind, Map<String, Set<String>>> mutable =
			new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			mutable.put(kind, new LinkedHashMap<>());
		}
		for (ImmutableCardIdentityCatalog.Entry entry : entries)
		{
			if (entry == null)
			{
				continue;
			}
			CardIdentity identity = entry.getIdentity();
			String parent = normalize(identity.getCardName());
			for (String entityName : entry.getEntityNames())
			{
				String entity = normalize(entityName);
				if (!entity.isEmpty())
				{
					mutable.get(identity.getKind())
						.computeIfAbsent(entity, ignored -> new LinkedHashSet<>())
						.add(parent);
				}
			}
		}
		Map<CardEntityKind, Map<String, Set<String>>> frozen =
			new EnumMap<>(CardEntityKind.class);
		for (Map.Entry<CardEntityKind, Map<String, Set<String>>> kindEntry
			: mutable.entrySet())
		{
			Map<String, Set<String>> names = new LinkedHashMap<>();
			for (Map.Entry<String, Set<String>> nameEntry : kindEntry.getValue().entrySet())
			{
				names.put(nameEntry.getKey(), Collections.unmodifiableSet(
					new LinkedHashSet<>(nameEntry.getValue())));
			}
			frozen.put(kindEntry.getKey(), Collections.unmodifiableMap(names));
		}
		return Collections.unmodifiableMap(frozen);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	/** One self-consistent revision and its entity-name projection for dependent caches. */
	public static final class View implements CardIdentityCatalog
	{
		private final long revision;
		private final String version;
		private final boolean remote;
		private final boolean v1CatalogAvailable;
		private final CardIdentityCatalog catalog;
		private final List<CardIdentity> cardIdentities;
		private final Map<CardEntityKind, Map<String, Set<String>>> entityToCardNames;
		private final List<ImmutableCardIdentityCatalog.Entry> entries;
		private final Map<String, String> displayCardNames;

		private View(long revision, String version, boolean remote,
			CardIdentityCatalog catalog, List<ImmutableCardIdentityCatalog.Entry> entries)
		{
			this.revision = revision;
			this.version = version;
			this.remote = remote;
			this.v1CatalogAvailable = remote;
			this.catalog = catalog;
			this.entries = List.copyOf(entries);
			List<CardIdentity> identities = new ArrayList<>();
			Map<String, String> displayNames = new LinkedHashMap<>();
			for (ImmutableCardIdentityCatalog.Entry entry : entries)
			{
				if (entry != null)
				{
					CardIdentity identity = entry.getIdentity();
					identities.add(identity);
					displayNames.putIfAbsent(normalize(identity.getCardName()),
						identity.getCardName());
					for (String legacyName : identity.getLegacyCardNames())
					{
						displayNames.putIfAbsent(normalize(legacyName), legacyName);
					}
				}
			}
			this.cardIdentities = List.copyOf(identities);
			this.displayCardNames = Collections.unmodifiableMap(displayNames);
			this.entityToCardNames = projectEntityNames(entries);
		}

		public long getRevision()
		{
			return revision;
		}

		public boolean isRemote()
		{
			return remote;
		}

		public boolean isV1CatalogAvailable()
		{
			return v1CatalogAvailable;
		}

		public List<CardIdentity> getCardIdentities()
		{
			return cardIdentities;
		}

		public List<ImmutableCardIdentityCatalog.Entry> getEntries()
		{
			return entries;
		}

		public String findDisplayCardName(String cardName)
		{
			return displayCardNames.get(normalize(cardName));
		}

		@Override
		public List<CardIdentity> findById(CardEntityKind kind, int entityId)
		{
			return catalog.findById(kind, entityId);
		}

		@Override
		public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
		{
			return catalog.findByName(kind, entityName);
		}

		@Override
		public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
		{
			return catalog.findByCardName(kind, cardName);
		}

		public Map<String, Set<String>> getEntityToCardNames(CardEntityKind kind)
		{
			return entityToCardNames.getOrDefault(kind, Collections.emptyMap());
		}
	}
}

package com.bronzemantcg.ownership;

import com.google.inject.ImplementedBy;
import java.util.List;

/**
 * Boundary between the restriction code and whichever reviewed catalogue source is active.
 * Implementations own entity-name aliases and ID indexes; the resolver never loads data itself.
 */
@ImplementedBy(ActiveCardIdentityCatalog.class)
public interface CardIdentityCatalog
{
	List<CardIdentity> findById(CardEntityKind kind, int entityId);

	List<CardIdentity> findByName(CardEntityKind kind, String entityName);

	List<CardIdentity> findByCardName(CardEntityKind kind, String cardName);
}

package com.bronzemantcg.ownership;

import java.util.Collections;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** One fail-open ownership decision boundary shared by future enforcement and visuals. */
@Slf4j
@Singleton
public final class CardOwnershipService
{
	private static final BetaCardUnlockSource.View NO_BETA_UNLOCKS =
		new BetaCardUnlockSource.View(0L, Collections.emptySet(), Collections.emptySet());
	private final CardResolver resolver;
	private final Set<String> reportedFailOpenDecisions = ConcurrentHashMap.newKeySet();

	@Inject
	public CardOwnershipService(CardResolver resolver)
	{
		this.resolver = resolver;
	}

	public Decision decide(CardEntityKind kind, int entityId, String entityName,
		TcgOwnershipSnapshot personalOwnership, Set<String> sharedCardNames,
		Set<String> exemptCardNames)
	{
		return decide(kind, entityId, entityName, personalOwnership, NO_BETA_UNLOCKS,
			sharedCardNames, exemptCardNames);
	}

	public Decision decide(CardEntityKind kind, int entityId, String entityName,
		TcgOwnershipSnapshot personalOwnership, BetaCardUnlockSource.View betaUnlocks,
		Set<String> sharedCardNames, Set<String> exemptCardNames)
	{
		CardResolver.Result resolved = resolver.resolve(kind, entityId, entityName);
		return decideResolved(resolved, personalOwnership, betaUnlocks, sharedCardNames,
			exemptCardNames, kind, entityId, entityName);
	}

	/**
	 * Decides one name-authored parent-card requirement across the separate item and NPC
	 * namespaces. Exactly one reviewed identity is required; missing or conflicting catalogue
	 * data fails open just like direct entity resolution.
	 */
	public Decision decideCard(String cardName, TcgOwnershipSnapshot personalOwnership,
		Set<String> sharedCardNames, Set<String> exemptCardNames)
	{
		return decideCard(cardName, personalOwnership, NO_BETA_UNLOCKS,
			sharedCardNames, exemptCardNames);
	}

	public Decision decideCard(String cardName, TcgOwnershipSnapshot personalOwnership,
		BetaCardUnlockSource.View betaUnlocks, Set<String> sharedCardNames,
		Set<String> exemptCardNames)
	{
		CardResolver.Result item = resolver.resolveCardName(CardEntityKind.ITEM, cardName);
		CardResolver.Result npc = resolver.resolveCardName(CardEntityKind.NPC, cardName);
		if (item.getStatus() == CardResolver.Status.AMBIGUOUS
			|| npc.getStatus() == CardResolver.Status.AMBIGUOUS
			|| (item.isTracked() && npc.isTracked()))
		{
			logRequirementFailOpenOnce(cardName, Status.AMBIGUOUS);
			return new Decision(Status.AMBIGUOUS, null);
		}
		CardResolver.Result resolved = item.isTracked() ? item : npc;
		if (!resolved.isTracked())
		{
			logRequirementFailOpenOnce(cardName, Status.UNTRACKED);
			return new Decision(Status.UNTRACKED, null);
		}
		return decideIdentity(resolved.getIdentity(), personalOwnership, betaUnlocks,
			sharedCardNames, exemptCardNames);
	}

	/** Decides one parent-card requirement inside an explicit item or NPC namespace. */
	public Decision decideCard(CardEntityKind kind, String cardName,
		TcgOwnershipSnapshot personalOwnership, Set<String> sharedCardNames,
		Set<String> exemptCardNames)
	{
		return decideCard(kind, cardName, personalOwnership, NO_BETA_UNLOCKS,
			sharedCardNames, exemptCardNames);
	}

	public Decision decideCard(CardEntityKind kind, String cardName,
		TcgOwnershipSnapshot personalOwnership, BetaCardUnlockSource.View betaUnlocks,
		Set<String> sharedCardNames, Set<String> exemptCardNames)
	{
		CardResolver.Result resolved = resolver.resolveCardName(kind, cardName);
		if (!resolved.isTracked())
		{
			Status status = map(resolved.getStatus());
			logRequirementFailOpenOnce(kind, cardName, status);
			return new Decision(status, null);
		}
		return decideIdentity(resolved.getIdentity(), personalOwnership, betaUnlocks,
			sharedCardNames, exemptCardNames);
	}

	/**
	 * Additive ownership for collection and readiness displays. Unlike enforcement, unresolved
	 * catalogue data is not treated as collected; only an exact owned/shared name may satisfy an
	 * unresolved row.
	 */
	public boolean isCollectedCard(String cardName, TcgOwnershipSnapshot personalOwnership,
		Set<String> sharedCardNames)
	{
		return isCollectedCard(cardName, personalOwnership, NO_BETA_UNLOCKS, sharedCardNames);
	}

	public boolean isCollectedCard(String cardName, TcgOwnershipSnapshot personalOwnership,
		BetaCardUnlockSource.View betaUnlocks, Set<String> sharedCardNames)
	{
		String normalizedCardName = normalizeCardName(cardName);
		if (normalizedCardName.isEmpty())
		{
			return false;
		}
		if (personalOwnership != null
			&& personalOwnership.getOwnedCardNamesLowerCase().contains(normalizedCardName))
		{
			return true;
		}
		if (containsCardName(sharedCardNames, normalizedCardName))
		{
			return true;
		}

		CardResolver.Result item = resolver.resolveCardName(CardEntityKind.ITEM, cardName);
		CardResolver.Result npc = resolver.resolveCardName(CardEntityKind.NPC, cardName);
		if (item.getStatus() == CardResolver.Status.AMBIGUOUS
			|| npc.getStatus() == CardResolver.Status.AMBIGUOUS
			|| (item.isTracked() && npc.isTracked()))
		{
			return false;
		}
		CardResolver.Result resolved = item.isTracked() ? item : npc;
		if (!resolved.isTracked())
		{
			return false;
		}
		CardIdentity identity = resolved.getIdentity();
		return identity.isCollectedBy(personalOwnership)
			|| isBetaOwned(identity, betaUnlocks)
			|| acceptsUnambiguousSharedName(identity, sharedCardNames);
	}

	/**
	 * Collection/readiness lookup for a row whose item or NPC namespace is known. IDs remain
	 * authoritative when that namespace is present, apart from the same reviewed legacy-name
	 * compatibility rule used by enforcement.
	 */
	public boolean isCollectedCard(CardEntityKind kind, String cardName,
		TcgOwnershipSnapshot personalOwnership, Set<String> sharedCardNames)
	{
		return isCollectedCard(kind, cardName, personalOwnership, NO_BETA_UNLOCKS,
			sharedCardNames);
	}

	public boolean isCollectedCard(CardEntityKind kind, String cardName,
		TcgOwnershipSnapshot personalOwnership, BetaCardUnlockSource.View betaUnlocks,
		Set<String> sharedCardNames)
	{
		String normalizedCardName = normalizeCardName(cardName);
		if (normalizedCardName.isEmpty())
		{
			return false;
		}
		CardResolver.Result resolved = resolver.resolveCardName(kind, cardName);
		if (!resolved.isTracked())
		{
			return false;
		}
		CardIdentity identity = resolved.getIdentity();
		return identity.isOwnedBy(personalOwnership)
			|| acceptsUnambiguousPersonalLegacyName(identity, personalOwnership)
			|| isBetaOwned(identity, betaUnlocks)
			|| acceptsUnambiguousSharedName(identity, sharedCardNames);
	}

	private void logRequirementFailOpenOnce(String cardName, Status status)
	{
		String diagnosticKey = "CARD|" + cardName + "|" + status;
		if (reportedFailOpenDecisions.add(diagnosticKey))
		{
			log.debug("Failing open for parent-card requirement '{}': {}", cardName, status);
		}
	}

	private void logRequirementFailOpenOnce(CardEntityKind kind, String cardName, Status status)
	{
		String diagnosticKey = "CARD|" + kind + "|" + cardName + "|" + status;
		if (reportedFailOpenDecisions.add(diagnosticKey))
		{
			log.debug("Failing open for {} parent-card requirement '{}': {}",
				kind, cardName, status);
		}
	}

	private Decision decideResolved(CardResolver.Result resolved,
		TcgOwnershipSnapshot personalOwnership, BetaCardUnlockSource.View betaUnlocks,
		Set<String> sharedCardNames, Set<String> exemptCardNames, CardEntityKind kind,
		int entityId, String entityName)
	{
		if (!resolved.isTracked())
		{
			if (resolved.getStatus() == CardResolver.Status.AMBIGUOUS
				|| resolved.getStatus() == CardResolver.Status.CATALOG_MISMATCH)
			{
				String diagnosticKey = kind + "|" + entityId + "|" + resolved.getStatus();
				if (reportedFailOpenDecisions.add(diagnosticKey))
				{
					log.debug("Failing open for {} id={} name='{}': {}",
						kind, entityId, entityName, resolved.getStatus());
				}
			}
			return new Decision(map(resolved.getStatus()), null);
		}
		return decideIdentity(resolved.getIdentity(), personalOwnership, betaUnlocks,
			sharedCardNames, exemptCardNames);
	}

	private Decision decideIdentity(CardIdentity identity,
		TcgOwnershipSnapshot personalOwnership, BetaCardUnlockSource.View betaUnlocks,
		Set<String> sharedCardNames, Set<String> exemptCardNames)
	{
		if (identity.acceptsAnyCardName(exemptCardNames))
		{
			return new Decision(Status.EXEMPT, identity);
		}
		if (identity.isOwnedBy(personalOwnership)
			|| acceptsUnambiguousPersonalLegacyName(identity, personalOwnership)
			|| isBetaOwned(identity, betaUnlocks))
		{
			return new Decision(Status.OWNED, identity);
		}
		if (acceptsUnambiguousSharedName(identity, sharedCardNames))
		{
			return new Decision(Status.SHARED, identity);
		}
		return new Decision(Status.LOCKED, identity);
	}

	private boolean isBetaOwned(CardIdentity identity, BetaCardUnlockSource.View betaUnlocks)
	{
		if (identity == null || betaUnlocks == null)
		{
			return false;
		}
		Set<String> betaParents = betaUnlocks.getParentNamesLowerCase(identity.getKind());
		if (isMatchingBetaParent(identity, betaParents, identity.getCardName()))
		{
			return true;
		}
		for (String legacyName : identity.getLegacyCardNames())
		{
			if (isMatchingBetaParent(identity, betaParents, legacyName))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isMatchingBetaParent(CardIdentity identity, Set<String> betaParents,
		String acceptedParentName)
	{
		if (!containsCardName(betaParents, normalizeCardName(acceptedParentName)))
		{
			return false;
		}
		CardResolver.Result parent = resolver.resolveCardName(
			identity.getKind(), acceptedParentName);
		return parent.isTracked() && sameIdentity(identity, parent.getIdentity());
	}

	/**
	 * The current OSRS TCG payload includes historical Beta-owned card names, but it can only
	 * publish entity IDs for names which still resolve in its v1 catalogue. Bridge that narrow
	 * gap without weakening normal v1 ID authority: only a reviewed legacy card-name alias may
	 * satisfy the already-resolved parent, and only when it is unambiguous across both kinds.
	 */
	private boolean acceptsUnambiguousPersonalLegacyName(CardIdentity identity,
		TcgOwnershipSnapshot personalOwnership)
	{
		if (identity == null || personalOwnership == null
			|| !personalOwnership.hasEntityIds(identity.getKind()))
		{
			return false;
		}

		Set<String> ownedNames = personalOwnership.getOwnedCardNamesLowerCase();
		CardEntityKind otherKind = identity.getKind() == CardEntityKind.ITEM
			? CardEntityKind.NPC : CardEntityKind.ITEM;
		for (String legacyCardName : identity.getLegacyCardNames())
		{
			String normalized = normalizeCardName(legacyCardName);
			if (!containsCardName(ownedNames, normalized))
			{
				continue;
			}

			CardResolver.Result sameKind = resolver.resolveCardName(
				identity.getKind(), legacyCardName);
			if (!sameKind.isTracked()
				|| !sameIdentity(identity, sameKind.getIdentity())
				|| resolver.resolveCardName(otherKind, legacyCardName).getStatus()
					!= CardResolver.Status.UNTRACKED)
			{
				continue;
			}
			return true;
		}
		return false;
	}

	/** Names-only shared ownership cannot safely choose between equal item and NPC card names. */
	private boolean acceptsUnambiguousSharedName(CardIdentity identity, Set<String> sharedCardNames)
	{
		if (!identity.acceptsAnyCardName(sharedCardNames))
		{
			return false;
		}
		CardEntityKind otherKind = identity.getKind() == CardEntityKind.ITEM
			? CardEntityKind.NPC : CardEntityKind.ITEM;
		if (containsCardName(sharedCardNames, normalizeCardName(identity.getCardName()))
			&& resolver.resolveCardName(otherKind, identity.getCardName()).getStatus()
				== CardResolver.Status.UNTRACKED)
		{
			return true;
		}
		for (String legacyCardName : identity.getLegacyCardNames())
		{
			if (containsCardName(sharedCardNames, normalizeCardName(legacyCardName))
				&& resolver.resolveCardName(otherKind, legacyCardName).getStatus()
					== CardResolver.Status.UNTRACKED)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean containsCardName(Set<String> names, String lowerCaseCardName)
	{
		if (names == null || names.isEmpty())
		{
			return false;
		}
		// SharedUnlockStore and ExemptionList already provide lower-case sets, so the normal
		// render/menu path remains one hash lookup with no allocation.
		if (names.contains(lowerCaseCardName))
		{
			return true;
		}
		for (String name : names)
		{
			if (name != null && lowerCaseCardName.equals(name.trim().toLowerCase(Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean sameIdentity(CardIdentity first, CardIdentity second)
	{
		return first != null && second != null
			&& first.getKind() == second.getKind()
			&& normalizeCardName(first.getCardName())
				.equals(normalizeCardName(second.getCardName()));
	}

	private static String normalizeCardName(String cardName)
	{
		return cardName == null ? "" : cardName.trim().toLowerCase(Locale.ROOT);
	}

	private static Status map(CardResolver.Status status)
	{
		switch (status)
		{
			case AMBIGUOUS:
				return Status.AMBIGUOUS;
			case CATALOG_MISMATCH:
				return Status.CATALOG_MISMATCH;
			default:
				return Status.UNTRACKED;
		}
	}

	public enum Status
	{
		OWNED(true),
		SHARED(true),
		EXEMPT(true),
		LOCKED(false),
		UNTRACKED(true),
		AMBIGUOUS(true),
		CATALOG_MISMATCH(true);

		private final boolean allowed;

		Status(boolean allowed)
		{
			this.allowed = allowed;
		}

		public boolean isAllowed()
		{
			return allowed;
		}
	}

	public static final class Decision
	{
		private final Status status;
		private final CardIdentity identity;

		private Decision(Status status, CardIdentity identity)
		{
			this.status = status;
			this.identity = identity;
		}

		public Status getStatus()
		{
			return status;
		}

		public boolean isAllowed()
		{
			return status.isAllowed();
		}

		public CardIdentity getIdentity()
		{
			return identity;
		}
	}
}

package com.bronzemantcg.ownership;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/** Reviewed v1 parent unlocks derived from the active profile's Beta-name cache. */
public interface BetaCardUnlockSource
{
	View getBetaCardUnlocks();

	final class View
	{
		private final long revision;
		private final Map<CardEntityKind, Set<String>> parentNamesLowerCase;
		private final Set<String> allParentNamesLowerCase;

		public View(long revision, Set<String> itemParentNamesLowerCase,
			Set<String> npcParentNamesLowerCase)
		{
			this.revision = revision;
			Map<CardEntityKind, Set<String>> names = new EnumMap<>(CardEntityKind.class);
			names.put(CardEntityKind.ITEM, freeze(itemParentNamesLowerCase));
			names.put(CardEntityKind.NPC, freeze(npcParentNamesLowerCase));
			parentNamesLowerCase = Collections.unmodifiableMap(names);
			Set<String> all = new LinkedHashSet<>(names.get(CardEntityKind.ITEM));
			all.addAll(names.get(CardEntityKind.NPC));
			allParentNamesLowerCase = Collections.unmodifiableSet(all);
		}

		public long getRevision()
		{
			return revision;
		}

		public Set<String> getParentNamesLowerCase()
		{
			return allParentNamesLowerCase;
		}

		public Set<String> getParentNamesLowerCase(CardEntityKind kind)
		{
			return parentNamesLowerCase.getOrDefault(kind, Collections.emptySet());
		}

		private static Set<String> freeze(Set<String> names)
		{
			return names == null || names.isEmpty()
				? Collections.emptySet()
				: Collections.unmodifiableSet(new LinkedHashSet<>(names));
		}
	}
}

package com.bronzemantcg.ownership;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/** Immutable, locally cached view of the ownership payload published by OSRS TCG. */
public final class TcgOwnershipSnapshot
{
	private final Set<String> ownedCardNamesLowerCase;
	private final Set<Integer> ownedItemIds;
	private final Set<Integer> ownedNpcIds;
	private final boolean itemIdsAvailable;
	private final boolean npcIdsAvailable;
	private final String groupKey;

	private TcgOwnershipSnapshot(Set<String> ownedCardNamesLowerCase,
		Set<Integer> ownedItemIds, Set<Integer> ownedNpcIds,
		boolean itemIdsAvailable, boolean npcIdsAvailable, String groupKey)
	{
		this.ownedCardNamesLowerCase = ownedCardNamesLowerCase;
		this.ownedItemIds = ownedItemIds;
		this.ownedNpcIds = ownedNpcIds;
		this.itemIdsAvailable = itemIdsAvailable;
		this.npcIdsAvailable = npcIdsAvailable;
		this.groupKey = groupKey;
	}

	public static TcgOwnershipSnapshot fromApi(List<?> names, List<?> itemIds,
		List<?> npcIds, String groupKey)
	{
		return new TcgOwnershipSnapshot(normalizeNames(names), normalizeIds(itemIds),
			normalizeIds(npcIds), itemIds != null, npcIds != null, cleanGroupKey(groupKey));
	}

	public static TcgOwnershipSnapshot namesOnly(Set<String> lowerCaseNames)
	{
		Set<String> names = lowerCaseNames == null
			? Collections.emptySet() : Collections.unmodifiableSet(new LinkedHashSet<>(lowerCaseNames));
		return new TcgOwnershipSnapshot(names, Collections.emptySet(), Collections.emptySet(),
			false, false, null);
	}

	public Set<String> getOwnedCardNamesLowerCase()
	{
		return ownedCardNamesLowerCase;
	}

	public Set<Integer> getOwnedItemIds()
	{
		return ownedItemIds;
	}

	public Set<Integer> getOwnedNpcIds()
	{
		return ownedNpcIds;
	}

	public String getGroupKey()
	{
		return groupKey;
	}

	public boolean hasEntityIds(CardEntityKind kind)
	{
		return kind == CardEntityKind.ITEM ? itemIdsAvailable
			: kind == CardEntityKind.NPC && npcIdsAvailable;
	}

	public boolean ownsEntityId(CardEntityKind kind, int id)
	{
		if (id < 0 || kind == null)
		{
			return false;
		}
		return kind == CardEntityKind.ITEM ? ownedItemIds.contains(id) : ownedNpcIds.contains(id);
	}

	private static Set<String> normalizeNames(List<?> values)
	{
		if (values == null)
		{
			return Collections.emptySet();
		}
		Set<String> normalized = new LinkedHashSet<>();
		for (Object value : values)
		{
			if (value instanceof String && !((String) value).trim().isEmpty())
			{
				normalized.add(((String) value).trim().toLowerCase(Locale.ROOT));
			}
		}
		return Collections.unmodifiableSet(normalized);
	}

	private static Set<Integer> normalizeIds(List<?> values)
	{
		if (values == null)
		{
			return Collections.emptySet();
		}
		Set<Integer> normalized = new LinkedHashSet<>();
		for (Object value : values)
		{
			if (!(value instanceof Number))
			{
				continue;
			}
			Number number = (Number) value;
			long integer = number.longValue();
			double decimal = number.doubleValue();
			if (integer >= 0 && integer <= Integer.MAX_VALUE && Double.isFinite(decimal)
				&& decimal == integer)
			{
				normalized.add((int) integer);
			}
		}
		return Collections.unmodifiableSet(normalized);
	}

	private static String cleanGroupKey(String value)
	{
		return value == null || value.trim().isEmpty() ? null : value.trim();
	}
}

package com.bronzemantcg.ownership;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Reviewed identity for one parent TCG card. The IDs contain the parent RuneScape entity and
 * every variant which should count as that same card; this class carries no catalogue data by
 * itself.
 */
public final class CardIdentity
{
	private final CardEntityKind kind;
	private final String cardName;
	private final Set<String> legacyCardNames;
	private final Set<String> acceptedCardNamesLowerCase;
	private final Set<Integer> entityIds;
	private final Set<Integer> ownedNameRequiredEntityIds;

	public CardIdentity(CardEntityKind kind, String cardName, Set<Integer> entityIds)
	{
		this(kind, cardName, Collections.emptySet(), entityIds);
	}

	public CardIdentity(CardEntityKind kind, String cardName,
		Set<String> legacyCardNames, Set<Integer> entityIds)
	{
		this(kind, cardName, legacyCardNames, entityIds, Collections.emptySet());
	}

	public CardIdentity(CardEntityKind kind, String cardName,
		Set<String> legacyCardNames, Set<Integer> entityIds,
		Set<Integer> ownedNameRequiredEntityIds)
	{
		if (kind == null)
		{
			throw new IllegalArgumentException("kind is required");
		}
		if (cardName == null || cardName.trim().isEmpty())
		{
			throw new IllegalArgumentException("cardName is required");
		}
		this.kind = kind;
		this.cardName = cardName.trim();
		String cardNameLowerCase = this.cardName.toLowerCase(Locale.ROOT);
		Map<String, String> validLegacyNames = new LinkedHashMap<>();
		if (legacyCardNames != null)
		{
			for (String legacyName : legacyCardNames)
			{
				if (legacyName == null || legacyName.trim().isEmpty())
				{
					continue;
				}
				String trimmed = legacyName.trim();
				String lowerCase = trimmed.toLowerCase(Locale.ROOT);
				if (!cardNameLowerCase.equals(lowerCase))
				{
					validLegacyNames.putIfAbsent(lowerCase, trimmed);
				}
			}
		}
		this.legacyCardNames = Collections.unmodifiableSet(
			new LinkedHashSet<>(validLegacyNames.values()));
		LinkedHashSet<String> acceptedNames = new LinkedHashSet<>();
		acceptedNames.add(cardNameLowerCase);
		acceptedNames.addAll(validLegacyNames.keySet());
		this.acceptedCardNamesLowerCase = Collections.unmodifiableSet(acceptedNames);
		LinkedHashSet<Integer> validIds = new LinkedHashSet<>();
		if (entityIds != null)
		{
			for (Integer id : entityIds)
			{
				if (id != null && id >= 0)
				{
					validIds.add(id);
				}
			}
		}
		this.entityIds = Collections.unmodifiableSet(validIds);
		LinkedHashSet<Integer> guardedIds = new LinkedHashSet<>();
		if (ownedNameRequiredEntityIds != null)
		{
			for (Integer id : ownedNameRequiredEntityIds)
			{
				if (validIds.contains(id))
				{
					guardedIds.add(id);
				}
			}
		}
		this.ownedNameRequiredEntityIds = Collections.unmodifiableSet(guardedIds);
	}

	public CardEntityKind getKind()
	{
		return kind;
	}

	public String getCardName()
	{
		return cardName;
	}

	public Set<Integer> getEntityIds()
	{
		return entityIds;
	}

	public Set<String> getLegacyCardNames()
	{
		return legacyCardNames;
	}

	public Set<Integer> getOwnedNameRequiredEntityIds()
	{
		return ownedNameRequiredEntityIds;
	}

	/**
	 * IDs are authoritative when the installed OSRS TCG version supplies that namespace.
	 * Card-name fallback is reserved for the older name-only PluginMessage/config contract.
	 */
	public boolean isOwnedBy(TcgOwnershipSnapshot ownership)
	{
		if (ownership == null)
		{
			return false;
		}
		if (ownership.hasEntityIds(kind))
		{
			for (Integer id : entityIds)
			{
				if (ownsEntityId(ownership, id))
				{
					return true;
				}
			}
			return false;
		}
		return ownsAcceptedName(ownership);
	}

	/**
	 * Display/readiness ownership is additive. Exact current or legacy names still count when
	 * the API also supplies IDs, while a reviewed variant ID can collect the canonical parent.
	 */
	public boolean isCollectedBy(TcgOwnershipSnapshot ownership)
	{
		if (ownership == null)
		{
			return false;
		}
		for (Integer id : entityIds)
		{
			if (ownsEntityId(ownership, id))
			{
				return true;
			}
		}
		return ownsAcceptedName(ownership);
	}

	boolean acceptsAnyCardName(Set<String> names)
	{
		if (names == null || names.isEmpty())
		{
			return false;
		}
		for (String acceptedName : acceptedCardNamesLowerCase)
		{
			if (containsNormalized(names, acceptedName))
			{
				return true;
			}
		}
		return false;
	}

	private boolean ownsEntityId(TcgOwnershipSnapshot ownership, int entityId)
	{
		return ownership.ownsEntityId(kind, entityId)
			&& (!ownedNameRequiredEntityIds.contains(entityId)
				|| ownsAcceptedName(ownership));
	}

	private boolean ownsAcceptedName(TcgOwnershipSnapshot ownership)
	{
		Set<String> ownedNames = ownership.getOwnedCardNamesLowerCase();
		for (String acceptedName : acceptedCardNamesLowerCase)
		{
			if (ownedNames.contains(acceptedName))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean containsNormalized(Set<String> names, String lowerCaseName)
	{
		if (names.contains(lowerCaseName))
		{
			return true;
		}
		for (String name : names)
		{
			if (name != null && lowerCaseName.equals(name.trim().toLowerCase(Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}
}

package com.bronzemantcg.ownership;

import com.bronzemantcg.util.CacheFiles;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;

/** Versioned profile-keyed disk persistence for validated historical Beta ownership names. */
@Singleton
public final class BetaCardCacheStore
{
	private static final int SCHEMA_VERSION = 1;
	private static final int MAX_CACHE_BYTES = 1024 * 1024;
	private static final int MAX_CARD_NAMES = 10_000;

	private final Gson gson;
	private final Path cacheDirectory;

	@Inject
	public BetaCardCacheStore(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve("bronzeman-tcg")
			.resolve("beta-cards"));
	}

	BetaCardCacheStore(Gson gson, Path cacheDirectory)
	{
		this.gson = gson;
		this.cacheDirectory = cacheDirectory;
	}

	public Record load(String profileKey) throws IOException
	{
		Path file = fileForProfile(profileKey);
		if (!Files.exists(file))
		{
			return null;
		}
		long size = Files.size(file);
		if (size <= 0 || size > MAX_CACHE_BYTES)
		{
			throw new IOException("Beta cache has an invalid size");
		}
		CacheDto dto;
		try
		{
			dto = gson.fromJson(Files.readString(file, StandardCharsets.UTF_8), CacheDto.class);
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			throw new IOException("Beta cache JSON is malformed", ex);
		}
		if (dto == null || dto.schemaVersion != SCHEMA_VERSION
			|| dto.savedAtEpochMillis <= 0 || dto.revision < 0
			|| blank(dto.displayName))
		{
			throw new IOException("Beta cache envelope is invalid");
		}
		return new Record(dto.displayName.trim(), dto.revision, dto.savedAtEpochMillis,
			validateNames(dto.cardNames));
	}

	public void save(String profileKey, String displayName, long revision,
		long savedAtEpochMillis, List<String> cardNames) throws IOException
	{
		if (blank(profileKey) || blank(displayName) || revision < 0 || savedAtEpochMillis <= 0)
		{
			throw new IllegalArgumentException("profile, player, revision and saved time are required");
		}
		CacheDto dto = new CacheDto();
		dto.schemaVersion = SCHEMA_VERSION;
		dto.displayName = displayName.trim();
		dto.revision = revision;
		dto.savedAtEpochMillis = savedAtEpochMillis;
		dto.cardNames = validateNames(cardNames);
		byte[] bytes = gson.toJson(dto).getBytes(StandardCharsets.UTF_8);
		if (bytes.length > MAX_CACHE_BYTES)
		{
			throw new IOException("Beta cache exceeds size limit");
		}
		CacheFiles.writeAtomically(fileForProfile(profileKey), bytes);
	}

	public void delete(String profileKey) throws IOException
	{
		Files.deleteIfExists(fileForProfile(profileKey));
	}

	Path fileForProfile(String profileKey)
	{
		return cacheDirectory.resolve(CacheFiles.sha256Hex(profileKey) + ".json");
	}

	private static List<String> validateNames(List<String> source) throws IOException
	{
		if (source == null || source.size() > MAX_CARD_NAMES)
		{
			throw new IOException("Beta cache card names are missing or invalid");
		}
		List<String> names = new ArrayList<>(source.size());
		Set<String> normalized = new HashSet<>();
		for (String name : source)
		{
			if (blank(name) || name.length() > 256)
			{
				throw new IOException("Beta cache contains an invalid card name");
			}
			String trimmed = name.trim();
			if (!normalized.add(trimmed.toLowerCase(Locale.ROOT)))
			{
				throw new IOException("Beta cache contains duplicate card names");
			}
			names.add(trimmed);
		}
		return List.copyOf(names);
	}

	private static boolean blank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	public static final class Record
	{
		private final String displayName;
		private final long revision;
		private final long savedAtEpochMillis;
		private final List<String> cardNames;

		private Record(String displayName, long revision, long savedAtEpochMillis,
			List<String> cardNames)
		{
			this.displayName = displayName;
			this.revision = revision;
			this.savedAtEpochMillis = savedAtEpochMillis;
			this.cardNames = cardNames;
		}

		public String getDisplayName()
		{
			return displayName;
		}

		public long getRevision()
		{
			return revision;
		}

		public long getSavedAtEpochMillis()
		{
			return savedAtEpochMillis;
		}

		public List<String> getCardNames()
		{
			return cardNames;
		}
	}

	@SuppressWarnings("unused")
	private static final class CacheDto
	{
		private int schemaVersion;
		private String displayName;
		private long revision;
		private long savedAtEpochMillis;
		private List<String> cardNames;
	}
}

package com.bronzemantcg.ownership;

import com.bronzemantcg.BronzemanTcgConfig;
import com.bronzemantcg.interop.BetaCardLookupClient;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

/** Profile-scoped historical Beta ownership backed only by explicit player refreshes. */
@Singleton
public final class BetaCardCacheService implements BetaCardUnlockSource
{
	static final String PRIVATE_ALBUM_MESSAGE = "Please turn on public album sharing in OSRS TCG, "
		+ "then refresh again. You can turn sharing off after Bronzeman saves the Beta names.";
	private static final BetaCardUnlockSource.View DISABLED_GAMEPLAY_VIEW =
		new BetaCardUnlockSource.View(0L, Collections.emptySet(), Collections.emptySet());

	private final Client client;
	private final ClientThread clientThread;
	private final BronzemanTcgConfig config;
	private final ProfileAccess profileAccess;
	private final BetaCardLookupClient lookupClient;
	private final BetaCardCacheStore cacheStore;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final LongSupplier clock;
	private final Map<String, ParentResolution> parentByBetaName;
	private final AtomicReference<BetaCardLookupClient.FetchHandle> activeFetch =
		new AtomicReference<>();

	private boolean running;
	private long generation;
	private String loadedProfile;
	private State state = State.noProfile();
	private BetaCardUnlockSource.View gameplayView;
	private volatile Listener listener = Listener.NONE;

	@Inject
	public BetaCardCacheService(Client client, ClientThread clientThread,
		BronzemanTcgConfig config, ConfigManager configManager,
		BetaCardLookupClient lookupClient, BetaCardCacheStore cacheStore,
		BundledCardIdentityCatalog bundledCatalog, Gson gson,
		ScheduledExecutorService executor)
	{
		this(client, clientThread, config, new ConfigManagerProfileAccess(configManager),
			lookupClient, cacheStore, bundledCatalog, gson, executor,
			System::currentTimeMillis);
	}

	BetaCardCacheService(Client client, ClientThread clientThread,
		BronzemanTcgConfig config, ProfileAccess profileAccess,
		BetaCardLookupClient lookupClient, BetaCardCacheStore cacheStore,
		BundledCardIdentityCatalog bundledCatalog, Gson gson,
		ScheduledExecutorService executor, LongSupplier clock)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.profileAccess = profileAccess;
		this.lookupClient = lookupClient;
		this.cacheStore = cacheStore;
		this.gson = gson;
		this.executor = executor;
		this.clock = clock;
		this.parentByBetaName = buildParentIndex(bundledCatalog);
		this.gameplayView = emptyGameplayView(0L);
	}

	public void setListener(Listener listener)
	{
		this.listener = listener == null ? Listener.NONE : listener;
	}

	/** Loads the active profile's cache without making a network request. */
	public void startUp()
	{
		synchronized (this)
		{
			running = true;
		}
		reloadForCurrentProfile();
	}

	public void onProfileChanged()
	{
		reloadForCurrentProfile();
	}

	public void shutDown()
	{
		synchronized (this)
		{
			running = false;
			generation++;
			loadedProfile = null;
			state = State.noProfile();
			gameplayView = emptyGameplayView(generation);
		}
		cancelActiveFetch();
	}

	public void onLookupConsentChanged()
	{
		if (config.allowBetaCardLookup())
		{
			return;
		}
		boolean changed = false;
		synchronized (this)
		{
			if (state.status == Status.REFRESHING)
			{
				generation++;
				state = state.failed("Beta refresh was cancelled because lookup consent "
					+ "was disabled. The previous cache was kept.");
				changed = true;
			}
		}
		cancelActiveFetch();
		if (changed)
		{
			notifyChanged();
		}
	}

	private void reloadForCurrentProfile()
	{
		String profile = currentProfileKey();
		cancelActiveFetch();
		synchronized (this)
		{
			generation++;
			loadedProfile = profile;
			if (!running || blank(profile))
			{
				state = State.noProfile();
				gameplayView = emptyGameplayView(generation);
			}
			else
			{
				try
				{
					BetaCardCacheStore.Record record = cacheStore.load(profile);
					state = record == null ? State.noCache() : State.cached(record);
					gameplayView = record == null
						? emptyGameplayView(generation)
						: projectGameplayView(state.betaNamesLowerCase, generation);
				}
				catch (IOException | RuntimeException ex)
				{
					state = State.corrupt();
					gameplayView = emptyGameplayView(generation);
				}
			}
		}
		notifyChanged();
	}

	/** Captures the logged-in identity on RuneLite's client thread, then starts one request. */
	public void refresh()
	{
		if (!config.allowBetaCardLookup())
		{
			setFailure("Enable the Beta player lookup privacy setting before refreshing.");
			return;
		}
		clientThread.invokeLater(() ->
		{
			Player local = client.getGameState() == GameState.LOGGED_IN
				? client.getLocalPlayer() : null;
			String displayName = local == null ? null : local.getName();
			String profile = currentProfileKey();
			if (blank(displayName) || blank(profile))
			{
				setFailure("Log in to RuneScape before refreshing Beta cards.");
				return;
			}
			beginRefresh(profile, displayName.trim());
		});
	}

	void beginRefresh(String profile, String displayName)
	{
		long requestGeneration;
		synchronized (this)
		{
			if (!running || !config.allowBetaCardLookup()
				|| !profile.equals(loadedProfile))
			{
				return;
			}
			generation++;
			requestGeneration = generation;
			state = state.refreshing();
		}
		notifyChanged();
		cancelActiveFetch();
		BetaCardLookupClient.FetchHandle handle;
		try
		{
			handle = lookupClient.fetch(displayName, new BetaCardLookupClient.Listener()
			{
				@Override
				public void onResponse(BetaCardLookupClient.LookupResponse response)
				{
					executor.execute(() -> handleResponse(requestGeneration, profile,
						displayName, response));
				}

				@Override
				public void onFailure(Throwable cause)
				{
					executor.execute(() -> finishFailure(requestGeneration,
						"Could not reach osrs-tcg.net. The previous Beta cache was kept."));
				}
			});
		}
		catch (RuntimeException ex)
		{
			finishFailure(requestGeneration,
				"Could not start the Beta lookup. The previous Beta cache was kept.");
			return;
		}
		activeFetch.set(handle);
		if (!isCurrent(requestGeneration, profile))
		{
			handle.cancel();
		}
	}

	private void handleResponse(long requestGeneration, String profile, String requestedName,
		BetaCardLookupClient.LookupResponse response)
	{
		if (!isCurrent(requestGeneration, profile))
		{
			return;
		}
		if (response.getStatusCode() == 404 && isPlayerNotFound(response.getBody()))
		{
			finishFailure(requestGeneration, PRIVATE_ALBUM_MESSAGE);
			return;
		}
		if (response.getStatusCode() != 200)
		{
			finishFailure(requestGeneration,
				"OSRS TCG could not return the Beta names. The previous cache was kept.");
			return;
		}

		ValidatedLookup lookup;
		try
		{
			LookupDto dto = gson.fromJson(new String(response.getBody(), StandardCharsets.UTF_8),
				LookupDto.class);
			lookup = validateLookup(dto, requestedName);
		}
		catch (JsonParseException | IllegalStateException | LookupValidationException ex)
		{
			finishFailure(requestGeneration,
				"OSRS TCG returned invalid Beta names. The previous cache was kept.");
			return;
		}

		long savedAt = clock.getAsLong();
		synchronized (this)
		{
			if (!isCurrentLocked(requestGeneration, profile))
			{
				return;
			}
			try
			{
				cacheStore.save(profile, lookup.displayName, lookup.revision,
					savedAt, lookup.cardNames);
			}
			catch (IOException | RuntimeException ex)
			{
				state = state.failed("Bronzeman could not save the Beta names. "
					+ "The previous cache was kept.");
				notifyChanged();
				return;
			}
			generation++;
			state = State.cached(lookup.displayName, lookup.revision,
				savedAt, lookup.cardNames);
			gameplayView = projectGameplayView(state.betaNamesLowerCase, generation);
		}
		notifyChanged();
	}

	/** Clears only Bronzeman's replaceable local historical Beta ownership cache. */
	public void clear()
	{
		String profile;
		synchronized (this)
		{
			profile = loadedProfile;
			if (!running || blank(profile))
			{
				return;
			}
			generation++;
			cancelActiveFetch();
			try
			{
				cacheStore.delete(profile);
				state = State.noCache("Cached Beta names were cleared.");
				gameplayView = emptyGameplayView(generation);
			}
			catch (IOException | RuntimeException ex)
			{
				state = state.failed("Bronzeman could not clear the Beta cache.");
			}
		}
		notifyChanged();
	}

	public synchronized State getState()
	{
		return state;
	}

	@Override
	public synchronized BetaCardUnlockSource.View getBetaCardUnlocks()
	{
		return config.disableBetaVariants() ? DISABLED_GAMEPLAY_VIEW : gameplayView;
	}

	private BetaCardUnlockSource.View projectGameplayView(Set<String> betaNames,
		long revision)
	{
		Map<CardEntityKind, Set<String>> parents = new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			parents.put(kind, new LinkedHashSet<>());
		}
		for (String betaName : betaNames)
		{
			ParentResolution resolution = parentByBetaName.get(normalizeCardName(betaName));
			if (resolution != null)
			{
				parents.get(resolution.kind).add(resolution.parentNameLowerCase);
			}
		}
		return new BetaCardUnlockSource.View(revision,
			parents.get(CardEntityKind.ITEM), parents.get(CardEntityKind.NPC));
	}

	private BetaCardUnlockSource.View emptyGameplayView(long revision)
	{
		return new BetaCardUnlockSource.View(revision,
			Collections.emptySet(), Collections.emptySet());
	}

	private static Map<String, ParentResolution> buildParentIndex(
		BundledCardIdentityCatalog catalog)
	{
		if (catalog == null)
		{
			throw new IllegalArgumentException("bundledCatalog is required");
		}
		Map<String, ParentResolution> index = new HashMap<>();
		Set<String> ambiguous = new HashSet<>();
		for (ImmutableCardIdentityCatalog.Entry entry : catalog.getEntries())
		{
			CardIdentity identity = entry.getIdentity();
			addParentName(index, ambiguous, identity.getCardName(), identity);
			for (String legacyName : identity.getLegacyCardNames())
			{
				addParentName(index, ambiguous, legacyName, identity);
			}
		}
		for (String name : ambiguous)
		{
			index.remove(name);
		}
		return Collections.unmodifiableMap(index);
	}

	private static void addParentName(Map<String, ParentResolution> index,
		Set<String> ambiguous, String betaName, CardIdentity identity)
	{
		String normalized = normalizeCardName(betaName);
		if (normalized.isEmpty() || ambiguous.contains(normalized))
		{
			return;
		}
		ParentResolution resolution = new ParentResolution(identity.getKind(),
			normalizeCardName(identity.getCardName()));
		ParentResolution previous = index.putIfAbsent(normalized, resolution);
		if (previous != null && !previous.equals(resolution))
		{
			ambiguous.add(normalized);
			index.remove(normalized);
		}
	}

	private ValidatedLookup validateLookup(LookupDto dto, String requestedName)
		throws LookupValidationException
	{
		if (dto == null || blank(dto.displayName) || dto.revision == null
			|| dto.revision < 0
			|| dto.cardNames == null || !samePlayer(requestedName, dto.displayName)
			|| dto.cardNames.size() > 10_000)
		{
			throw new LookupValidationException();
		}
		Set<String> seen = new HashSet<>();
		List<String> names = new ArrayList<>(dto.cardNames.size());
		for (String name : dto.cardNames)
		{
			if (blank(name) || name.length() > 256)
			{
				throw new LookupValidationException();
			}
			String trimmed = name.trim();
			if (!seen.add(normalizeCardName(trimmed)))
			{
				throw new LookupValidationException();
			}
			names.add(trimmed);
		}
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return new ValidatedLookup(dto.displayName.trim(), dto.revision, names);
	}

	private boolean isPlayerNotFound(byte[] bytes)
	{
		try
		{
			ErrorRootDto dto = gson.fromJson(new String(bytes, StandardCharsets.UTF_8),
				ErrorRootDto.class);
			return dto != null && dto.error != null
				&& "player_not_found".equals(dto.error.code);
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			return false;
		}
	}

	private void finishFailure(long requestGeneration, String message)
	{
		synchronized (this)
		{
			if (requestGeneration != generation)
			{
				return;
			}
			state = state.failed(message);
		}
		notifyChanged();
	}

	private void setFailure(String message)
	{
		synchronized (this)
		{
			state = state.failed(message);
		}
		notifyChanged();
	}

	private synchronized boolean isCurrent(long requestGeneration, String profile)
	{
		return isCurrentLocked(requestGeneration, profile);
	}

	private boolean isCurrentLocked(long requestGeneration, String profile)
	{
		return running && requestGeneration == generation && profile.equals(loadedProfile);
	}

	private void cancelActiveFetch()
	{
		BetaCardLookupClient.FetchHandle handle = activeFetch.getAndSet(null);
		if (handle != null)
		{
			handle.cancel();
		}
	}

	private String currentProfileKey()
	{
		try
		{
			return profileAccess.currentProfileKey();
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	private void notifyChanged()
	{
		try
		{
			listener.onBetaCacheChanged();
		}
		catch (RuntimeException ignored)
		{
			// A presentation listener must never invalidate cached Beta ownership state.
		}
	}

	private static boolean samePlayer(String expected, String actual)
	{
		return normalizePlayerName(expected).equals(normalizePlayerName(actual));
	}

	private static String normalizePlayerName(String value)
	{
		return value == null ? "" : value.trim().replace('_', ' ')
			.replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	private static String normalizeCardName(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	private static boolean blank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	public enum Status
	{
		NO_PROFILE,
		NO_CACHE,
		CACHED,
		REFRESHING,
		FAILED,
		CORRUPT
	}

	public static final class State
	{
		private final Status status;
		private final String displayName;
		private final long revision;
		private final Set<String> betaNamesLowerCase;
		private final long savedAtEpochMillis;
		private final String message;

		private State(Status status, String displayName, long revision,
			Set<String> betaNamesLowerCase, long savedAtEpochMillis, String message)
		{
			this.status = status;
			this.displayName = displayName;
			this.revision = revision;
			this.betaNamesLowerCase = Collections.unmodifiableSet(
				new LinkedHashSet<>(betaNamesLowerCase));
			this.savedAtEpochMillis = savedAtEpochMillis;
			this.message = message;
		}

		private static State noProfile()
		{
			return new State(Status.NO_PROFILE, null, -1, Collections.emptySet(), 0,
				"Log in to load or refresh Beta names.");
		}

		private static State noCache()
		{
			return noCache("No cached Beta names for this profile.");
		}

		private static State noCache(String message)
		{
			return new State(Status.NO_CACHE, null, -1, Collections.emptySet(), 0, message);
		}

		private static State corrupt()
		{
			return new State(Status.CORRUPT, null, -1, Collections.emptySet(), 0,
				"The cached Beta names are invalid. Refresh to replace them safely.");
		}

		private static State cached(BetaCardCacheStore.Record record)
		{
			return cached(record.getDisplayName(), record.getRevision(),
				record.getSavedAtEpochMillis(), record.getCardNames());
		}

		private static State cached(String displayName, long revision, long savedAt,
			List<String> names)
		{
			Set<String> normalized = new LinkedHashSet<>();
			for (String name : names)
			{
				normalized.add(normalizeCardName(name));
			}
			return new State(Status.CACHED, displayName, revision, normalized, savedAt, null);
		}

		private State refreshing()
		{
			return new State(Status.REFRESHING, displayName, revision, betaNamesLowerCase,
				savedAtEpochMillis, "Refreshing Beta names...");
		}

		private State failed(String message)
		{
			return new State(Status.FAILED, displayName, revision, betaNamesLowerCase,
				savedAtEpochMillis, message);
		}

		public Status getStatus()
		{
			return status;
		}

		public String getDisplayName()
		{
			return displayName;
		}

		public long getRevision()
		{
			return revision;
		}

		public Set<String> getBetaNamesLowerCase()
		{
			return betaNamesLowerCase;
		}

		public int getCachedCount()
		{
			return betaNamesLowerCase.size();
		}

		public long getSavedAtEpochMillis()
		{
			return savedAtEpochMillis;
		}

		public Instant getSavedAt()
		{
			return savedAtEpochMillis <= 0 ? null : Instant.ofEpochMilli(savedAtEpochMillis);
		}

		public String getMessage()
		{
			return message;
		}
	}

	public interface Listener
	{
		Listener NONE = () -> { };

		void onBetaCacheChanged();
	}

	interface ProfileAccess
	{
		String currentProfileKey();
	}

	private static final class ConfigManagerProfileAccess implements ProfileAccess
	{
		private final ConfigManager configManager;

		private ConfigManagerProfileAccess(ConfigManager configManager)
		{
			this.configManager = configManager;
		}

		@Override
		public String currentProfileKey()
		{
			return configManager.getRSProfileKey();
		}
	}

	private static final class ValidatedLookup
	{
		private final String displayName;
		private final long revision;
		private final List<String> cardNames;

		private ValidatedLookup(String displayName, long revision, List<String> cardNames)
		{
			this.displayName = displayName;
			this.revision = revision;
			this.cardNames = List.copyOf(cardNames);
		}
	}

	private static final class ParentResolution
	{
		private final CardEntityKind kind;
		private final String parentNameLowerCase;

		private ParentResolution(CardEntityKind kind, String parentNameLowerCase)
		{
			this.kind = kind;
			this.parentNameLowerCase = parentNameLowerCase;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof ParentResolution))
			{
				return false;
			}
			ParentResolution resolution = (ParentResolution) other;
			return kind == resolution.kind
				&& parentNameLowerCase.equals(resolution.parentNameLowerCase);
		}

		@Override
		public int hashCode()
		{
			return 31 * kind.hashCode() + parentNameLowerCase.hashCode();
		}
	}

	@SuppressWarnings("unused")
	private static final class LookupDto
	{
		private String displayName;
		private Long revision;
		private List<String> cardNames;
	}

	@SuppressWarnings("unused")
	private static final class ErrorRootDto
	{
		private ErrorDto error;
	}

	@SuppressWarnings("unused")
	private static final class ErrorDto
	{
		private String code;
	}

	private static final class LookupValidationException extends Exception
	{
	}
}

package com.bronzemantcg.ownership;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;

/**
 * Card names a sibling plugin has told us to treat as unlocked, on top of the player's own
 * collection. Group modes live outside this plugin - a party plugin can decide that a card owned by
 * any member counts for everyone - but the restriction engine is here, so without a way in, those
 * unlocks simply do not apply and the group mode silently does nothing.
 *
 * <p>Kept per source plugin rather than in one pile so several can contribute independently and a
 * source that goes quiet (or shuts down) can be dropped without disturbing the others. Each message
 * carries that source's complete set, so a payload replaces what it sent before rather than adding
 * to it - senders do not have to track deltas, and a stale set cannot accumulate.</p>
 *
 * <p>The union is rebuilt only when something changes and handed out as the same instance until it
 * does, because the effective-owned cache in the plugin compares by identity and the menu-hide path
 * asks for it many times per frame.</p>
 *
 * <p>Reads are lock-free for that reason: the union is replaced wholesale rather than mutated, so a
 * reader either sees the old set or the new one, never a half-built one. Writes arrive from
 * PluginMessage handlers and are rare, so they take the lock; the render and menu paths must not.</p>
 */
@Singleton
public class SharedUnlockStore
{
	private final Map<String, Set<String>> bySource = new HashMap<>();
	private volatile Set<String> union = Collections.emptySet();

	/**
	 * Replaces everything {@code source} previously contributed.
	 *
	 * @param source     identifier of the sending plugin; blank payloads are ignored
	 * @param cardNames  that plugin's full set of extra unlocked card names, validated per element
	 *                   because the payload map is untyped and a malformed one must not throw
	 *                   mid-click
	 * @return true if the effective set changed
	 */
	public synchronized boolean put(String source, List<?> cardNames)
	{
		String key = key(source);
		if (key.isEmpty())
		{
			return false;
		}
		Set<String> names = new HashSet<>();
		if (cardNames != null)
		{
			for (Object name : cardNames)
			{
				if (name instanceof String)
				{
					String trimmed = ((String) name).trim();
					if (!trimmed.isEmpty())
					{
						names.add(trimmed.toLowerCase(Locale.ROOT));
					}
				}
			}
		}
		if (names.isEmpty())
		{
			return remove(key);
		}
		if (names.equals(bySource.get(key)))
		{
			return false;
		}
		bySource.put(key, names);
		rebuild();
		return true;
	}

	/** Drops a source's contribution when it withdraws by sending an empty set. */
	private boolean remove(String source)
	{
		String key = key(source);
		if (key.isEmpty() || bySource.remove(key) == null)
		{
			return false;
		}
		rebuild();
		return true;
	}

	/** Drops every contribution; used on profile switches so one account's group never carries over. */
	public synchronized void clear()
	{
		if (bySource.isEmpty())
		{
			return;
		}
		bySource.clear();
		rebuild();
	}

	/**
	 * @return the union of every source's card names, lower-cased. The same instance is returned
	 * until the contents change, so callers may cache against it by identity. Called from the
	 * render and menu paths, so it takes no lock.
	 */
	public Set<String> getSharedCardNamesLowerCase()
	{
		return union;
	}

	private void rebuild()
	{
		if (bySource.isEmpty())
		{
			union = Collections.emptySet();
			return;
		}
		Set<String> combined = new HashSet<>();
		for (Set<String> names : bySource.values())
		{
			combined.addAll(names);
		}
		union = Collections.unmodifiableSet(combined);
	}

	private static String key(String source)
	{
		return source == null ? "" : source.trim().toLowerCase(Locale.ROOT);
	}
}

package com.bronzemantcg.ownership;

import com.bronzemantcg.catalog.CardNames;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Resolves one RuneScape entity to a reviewed parent-card identity. */
@Singleton
public final class CardResolver
{
	private final CardIdentityCatalog catalog;

	@Inject
	public CardResolver(CardIdentityCatalog catalog)
	{
		if (catalog == null)
		{
			throw new IllegalArgumentException("catalog is required");
		}
		this.catalog = catalog;
	}

	/** Resolves a reviewed parent-card name without treating it as an entity alias. */
	public Result resolveCardName(CardEntityKind kind, String cardName)
	{
		if (kind == null)
		{
			return Result.of(Status.AMBIGUOUS);
		}
		List<CardIdentity> matches = unique(catalog.findByCardName(kind, cardName));
		if (matches.isEmpty())
		{
			return Result.of(Status.UNTRACKED);
		}
		return matches.size() == 1
			? Result.tracked(matches.get(0)) : Result.of(Status.AMBIGUOUS);
	}

	/**
	 * A supplied ID is authoritative. If the ID is unknown but its name is known, the catalogue
	 * and RuneScape disagree and the result is a mismatch rather than a silent name guess. Name
	 * fallback is used only when the interaction genuinely exposes no usable ID.
	 */
	public Result resolve(CardEntityKind kind, int entityId, String entityName)
	{
		if (kind == null)
		{
			return Result.of(Status.AMBIGUOUS);
		}
		if (entityId >= 0)
		{
			List<CardIdentity> idMatches = unique(catalog.findById(kind, entityId));
			if (idMatches.size() > 1)
			{
				return Result.of(Status.AMBIGUOUS);
			}
			if (idMatches.size() == 1)
			{
				return Result.tracked(idMatches.get(0));
			}
			return unique(catalog.findByName(kind, normalizeEntityName(kind, entityName))).isEmpty()
				? Result.of(Status.UNTRACKED) : Result.of(Status.CATALOG_MISMATCH);
		}

		List<CardIdentity> nameMatches = unique(
			catalog.findByName(kind, normalizeEntityName(kind, entityName)));
		if (nameMatches.isEmpty())
		{
			return Result.of(Status.UNTRACKED);
		}
		return nameMatches.size() == 1
			? Result.tracked(nameMatches.get(0)) : Result.of(Status.AMBIGUOUS);
	}

	private static String normalizeEntityName(CardEntityKind kind, String entityName)
	{
		return kind == CardEntityKind.ITEM && entityName != null
			? CardNames.stripDoseSuffix(entityName) : entityName;
	}

	private static List<CardIdentity> unique(List<CardIdentity> matches)
	{
		if (matches == null || matches.isEmpty())
		{
			return Collections.emptyList();
		}
		Map<String, CardIdentity> unique = new LinkedHashMap<>();
		for (CardIdentity identity : matches)
		{
			if (identity != null)
			{
				String key = identity.getKind().name() + '\u0000'
					+ identity.getCardName().toLowerCase(Locale.ROOT);
				unique.putIfAbsent(key, identity);
			}
		}
		return List.copyOf(unique.values());
	}

	public enum Status
	{
		TRACKED,
		UNTRACKED,
		AMBIGUOUS,
		CATALOG_MISMATCH
	}

	public static final class Result
	{
		private final Status status;
		private final CardIdentity identity;

		private Result(Status status, CardIdentity identity)
		{
			this.status = status;
			this.identity = identity;
		}

		private static Result tracked(CardIdentity identity)
		{
			return new Result(Status.TRACKED, identity);
		}

		private static Result of(Status status)
		{
			return new Result(status, null);
		}

		public Status getStatus()
		{
			return status;
		}

		public boolean isTracked()
		{
			return status == Status.TRACKED;
		}

		public CardIdentity getIdentity()
		{
			return identity;
		}
	}
}

package com.bronzemantcg.ownership;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Reviewed Beta parent-card fallback and its RuneScape entity aliases/IDs. */
@Slf4j
@Singleton
public final class BundledCardIdentityCatalog implements CardIdentityCatalog
{
	private static final String DEFAULT_RESOURCE = "/beta/beta_card_identity_catalog.json";

	private final ImmutableCardIdentityCatalog catalog;

	@Inject
	public BundledCardIdentityCatalog(Gson gson)
	{
		this(gson, DEFAULT_RESOURCE);
	}

	BundledCardIdentityCatalog(Gson gson, String resourcePath)
	{
		catalog = new ImmutableCardIdentityCatalog(load(gson, resourcePath));
		log.info("Loaded {} reviewed Beta fallback identities "
			+ "({} ambiguous item IDs, {} ambiguous NPC IDs)",
			catalog.size(), catalog.getAmbiguousIdCount(CardEntityKind.ITEM),
			catalog.getAmbiguousIdCount(CardEntityKind.NPC));
	}

	@Override
	public List<CardIdentity> findById(CardEntityKind kind, int entityId)
	{
		return catalog.findById(kind, entityId);
	}

	@Override
	public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
	{
		return catalog.findByName(kind, entityName);
	}

	@Override
	public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
	{
		return catalog.findByCardName(kind, cardName);
	}

	public int size()
	{
		return catalog.size();
	}

	public List<ImmutableCardIdentityCatalog.Entry> getEntries()
	{
		return catalog.getEntries();
	}

	public int getAmbiguousIdCount(CardEntityKind kind)
	{
		return catalog.getAmbiguousIdCount(kind);
	}

	private static List<ImmutableCardIdentityCatalog.Entry> load(Gson gson, String resourcePath)
	{
		List<ImmutableCardIdentityCatalog.Entry> entries = new ArrayList<>();
		if (gson == null || resourcePath == null)
		{
			return entries;
		}
		try (InputStream stream = BundledCardIdentityCatalog.class.getResourceAsStream(resourcePath))
		{
			if (stream == null)
			{
				log.warn("{} missing from classpath; ID-aware restrictions will fail open.", resourcePath);
				return entries;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.identities == null)
			{
				return entries;
			}
			for (IdentityRow row : snapshot.identities)
			{
				ImmutableCardIdentityCatalog.Entry entry = parse(row);
				if (entry != null)
				{
					entries.add(entry);
				}
			}
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Failed to load {}; ID-aware restrictions will fail open.", resourcePath, ex);
		}
		return entries;
	}

	private static ImmutableCardIdentityCatalog.Entry parse(IdentityRow row)
	{
		if (row == null || row.kind == null)
		{
			return null;
		}
		CardEntityKind kind;
		try
		{
			kind = CardEntityKind.valueOf(row.kind.trim().toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
		try
		{
			CardIdentity identity = new CardIdentity(kind, row.cardName,
				row.legacyCardNames == null ? Collections.emptySet()
					: new LinkedHashSet<>(row.legacyCardNames),
				row.entityIds == null ? Collections.emptySet()
					: new LinkedHashSet<>(row.entityIds),
				row.ownedNameRequiredEntityIds == null ? Collections.emptySet()
					: new LinkedHashSet<>(row.ownedNameRequiredEntityIds));
			return new ImmutableCardIdentityCatalog.Entry(identity,
				row.entityNames == null ? Collections.emptyList() : row.entityNames);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	private static final class Snapshot
	{
		private List<IdentityRow> identities;
	}

	private static final class IdentityRow
	{
		private String kind;
		private String cardName;
		private List<String> legacyCardNames;
		private List<String> entityNames;
		private List<Integer> entityIds;
		private List<Integer> ownedNameRequiredEntityIds;
	}
}

package com.bronzemantcg.ownership;


/** Keeps equal numeric item and NPC IDs in separate ownership namespaces. */
public enum CardEntityKind
{
	ITEM,
	NPC
}

package com.bronzemantcg.feature;

import com.bronzemantcg.BronzemanTcgConfig;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;


@Slf4j
@Singleton
public final class DuelistCityController
{
	private static final int MYSTIC_CARDS_ITEM_ID = ItemID.LEAGUE_3_CARDTHROW;

	private static final int[] MYSTIC_STANCE =
			{9847, 9849, 9850, 823, 823, 9851, 9852, 820};

	private final Client client;
	private final BronzemanTcgConfig config;
	private final Map<Integer, int[]> realEquipmentByPlayer = new HashMap<>();

	private int[] lastLoggedStance;

	@Inject
	public DuelistCityController(Client client, BronzemanTcgConfig config)
	{
		this.client = client;
		this.config = config;
	}

	private static void applyStance(Player player, int[] stance)
	{
		player.setIdlePoseAnimation(stance[0]);
		player.setWalkAnimation(stance[1]);
		player.setRunAnimation(stance[2]);
		player.setIdleRotateLeft(stance[3]);
		player.setIdleRotateRight(stance[4]);
		player.setWalkRotateLeft(stance[5]);
		player.setWalkRotateRight(stance[6]);
		player.setWalkRotate180(stance[7]);
	}

	private void applyDuelistCards(Player player)
	{
		if (player == null)
		{
			return;
		}

		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return;
		}
		int[] equipmentIds = composition.getEquipmentIds();

		int weaponIndex = KitType.WEAPON.getIndex();
		int shieldIndex = KitType.SHIELD.getIndex();

		int fakeWeapon = MYSTIC_CARDS_ITEM_ID + PlayerComposition.ITEM_OFFSET;

		if (equipmentIds[weaponIndex] != fakeWeapon)
		{
			int[] realAppearance =
					{
							equipmentIds[weaponIndex],
							equipmentIds[shieldIndex],
							player.getIdlePoseAnimation(),
							player.getWalkAnimation(),
							player.getRunAnimation(),
							player.getIdleRotateLeft(),
							player.getIdleRotateRight(),
							player.getWalkRotateLeft(),
							player.getWalkRotateRight(),
							player.getWalkRotate180()
					};

			realEquipmentByPlayer.put(player.getId(), realAppearance);
		}
		equipmentIds[weaponIndex] = fakeWeapon;
		equipmentIds[shieldIndex] = 0;

		composition.setHash();
		applyStance(player, MYSTIC_STANCE);
	}

	private void restoreDuelistCards(Player player)
	{
		if (player == null)
		{
			return;
		}

		PlayerComposition composition = player.getPlayerComposition();

		int[] realAppearance =
				realEquipmentByPlayer.remove(player.getId());

		if (composition == null || realAppearance == null)
		{
			return;
		}
		int[] equipmentIds = composition.getEquipmentIds();

		equipmentIds[KitType.WEAPON.getIndex()] = realAppearance[0];
		equipmentIds[KitType.SHIELD.getIndex()] = realAppearance[1];

		composition.setHash();
		int[] realStance =
				Arrays.copyOfRange(realAppearance, 2, realAppearance.length);

		applyStance(player, realStance);
	}

	public void onPlayerSpawned(Player player)
	{
		if (config.duelistCityMode())
		{
			applyDuelistCards(player);
		}
	}

	public void onPlayerChanged(Player player)
	{
		if (config.duelistCityMode())
		{
			applyDuelistCards(player);
		}
	}

	public void onPlayerDespawned(Player player)
	{
		if (player == null)
		{
			return;
		}

		realEquipmentByPlayer.remove(player.getId());
	}

	public void setEnabled(boolean enabled)
	{
		WorldView worldView = client.getTopLevelWorldView();

		if (worldView == null)
		{
			return;
		}
		for (Player player : worldView.players())
		{
			if (enabled)
			{
				applyDuelistCards(player);
			} else
			{
				restoreDuelistCards(player);
			}
		}
	}

	public void shutDown()
	{
		setEnabled(false);
		realEquipmentByPlayer.clear();
	}

	private void logLocalStanceOnChange()
	{
		if (!log.isDebugEnabled())
		{
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}
		int[] currentStance =
				{
						localPlayer.getIdlePoseAnimation(),
						localPlayer.getWalkAnimation(),
						localPlayer.getRunAnimation(),
						localPlayer.getIdleRotateLeft(),
						localPlayer.getIdleRotateRight(),
						localPlayer.getWalkRotateLeft(),
						localPlayer.getWalkRotateRight(),
						localPlayer.getWalkRotate180()
				};

		if (Arrays.equals(currentStance, lastLoggedStance))
		{
			return;
		}

		lastLoggedStance = currentStance;
		log.debug(
				"local stance: idle={} walk={} run={} idleRotL={} idleRotR={} "
						+ "walkRotL={} walkRotR={} walkRot180={}",
				currentStance[0],
				currentStance[1],
				currentStance[2],
				currentStance[3],
				currentStance[4],
				currentStance[5],
				currentStance[6],
				currentStance[7]
		);
	}

	public void onGameTick()
	{
		logLocalStanceOnChange();
	}

}

package com.bronzemantcg.feature;

import com.bronzemantcg.BronzemanTcgConfig;
import com.bronzemantcg.interop.TcgCollectionReader;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

@Singleton
public final class PluginNoticeController
{
	// Game ticks are 600ms. ~9s clears the login chat burst; ~30min between reminders
	// is often enough to notice, rare enough not to nag.
	private static final int WELCOME_DELAY_TICKS = 15;
	private static final int REMINDER_TICKS = 3000;
	// ~60s. Required-plugin and live-catalogue settings can quietly leave the player on
	// stale or fallback data, so surface them faster than the general health reminder.
	private static final int HEALTH_NOTICE_TICKS = 100;
	// OSRS TCG's PluginDescriptor name. Checking PluginManager keeps this independent
	// from whichever collection transport is currently available.
	private static final String REQUIRED_PLUGIN = "OSRS TCG";

	private final Client client;
	private final ChatFeedbackService chatFeedbackService;
	private final TcgCollectionReader collectionReader;
	private final PluginManager pluginManager;
	private final BronzemanTcgConfig config;

	private boolean welcomeShown;
	// Countdowns in game ticks; negative means idle.
	private int welcomeDelayTicks = -1;
	private int reminderTicks = -1;
	private int healthNoticeTicks = -1;

	@Inject
	public PluginNoticeController(Client client, ChatFeedbackService chatFeedbackService,
		TcgCollectionReader collectionReader, PluginManager pluginManager,
		BronzemanTcgConfig config)
	{
		this.client = client;
		this.chatFeedbackService = chatFeedbackService;
		this.collectionReader = collectionReader;
		this.pluginManager = pluginManager;
		this.config = config;
	}

	public void startUp()
	{
		welcomeShown = false;
		welcomeDelayTicks = -1;
		reminderTicks = -1;
		healthNoticeTicks = -1;
		scheduleWelcome();
	}

	public void onGameStateChanged(GameState gameState)
	{
		switch (gameState)
		{
			case LOGGED_IN:
				scheduleWelcome();
				break;
			case LOGIN_SCREEN:
				// Re-arm for the next login. World hops run HOPPING -> LOADING -> LOGGED_IN
				// without passing through the login screen, so hopping never re-greets.
				welcomeShown = false;
				welcomeDelayTicks = -1;
				break;
			default:
				break;
		}
	}

	/**
	 * Drives the delayed greeting and recurring health notices. Game ticks only arrive
	 * while logged in, so a logged-out session never counts down.
	 */
	public void onGameTick()
	{
		if (welcomeDelayTicks >= 0 && --welcomeDelayTicks < 0)
		{
			// The greeting posts every notice itself, so nothing else runs this tick.
			showWelcomeMessage();
			return;
		}
		if (reminderTicks >= 0 && --reminderTicks < 0)
		{
			postPeriodicNotices();
		}
		if (healthNoticeTicks >= 0 && --healthNoticeTicks < 0)
		{
			healthNoticeTicks = HEALTH_NOTICE_TICKS;
			postHealthNotices();
		}
	}

	/**
	 * Arm the greeting countdown. Firing on the login event itself buries the message
	 * under the client's own login spam - clan broadcasts, welcome text and other
	 * plugins all post in the first few seconds - so it waits them out instead.
	 */
	private void scheduleWelcome()
	{
		if (welcomeShown || welcomeDelayTicks >= 0 || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		welcomeDelayTicks = WELCOME_DELAY_TICKS;
	}

	/** One greeting per login, once the login chat has settled. Not optional - it is a
	 * single line that confirms the plugin loaded and shows collection progress. */
	private void showWelcomeMessage()
	{
		welcomeShown = true;
		reminderTicks = REMINDER_TICKS;
		healthNoticeTicks = HEALTH_NOTICE_TICKS;

		if (collectionReader.isStateAvailable())
		{
			chatFeedbackService.queueChat("[Bronzeman TCG] Plugin is active - Good luck on the pulls!");
			if (!collectionReader.hasApiData())
			{
				// Fallback path (pre-API OSRS TCG, or its API has not answered yet): the config
				// read lags behind card pulls, so nudge the player to relog. Self-retiring once
				// the API connects.
				chatFeedbackService.queueChat("[Bronzeman TCG] Not Connected to OSRS TCG API - Please relog if you are "
					+ "missing new card unlocks. Last known collection still active. Check OSRS TCG is enabled.");
			}
		}
		else
		{
			// Greeting with zero collected would misreport an unread collection as empty.
			warnCollectionUnreadable();
		}
		postHealthNotices();
	}

	/** Re-checks periodically so the collection warning keeps surfacing while it applies. */
	private void postPeriodicNotices()
	{
		reminderTicks = REMINDER_TICKS;
		warnCollectionUnreadable();
		// Configuration health notices deliberately use their own faster timer.
	}

	private void postHealthNotices()
	{
		warnRequiredPluginDisabled();
		warnLiveCatalogDisabled();
	}

	/**
	 * Enforcement stands down when the collection cannot be read, so the player has to
	 * be told. The notice repeats because its usual cause needs the player to act.
	 */
	private void warnCollectionUnreadable()
	{
		if (collectionReader.isStateAvailable())
		{
			return;
		}
		chatFeedbackService.queueChat("[Bronzeman TCG] - Can't read your OSRS TCG collection, so restrictions are "
			+ "OFF. Check that the OSRS TCG plugin is installed and up to date, and that you've "
			+ "opened at least one pack.");
	}

	/**
	 * Disabling OSRS TCG leaves its stored collection intact, so restrictions keep using
	 * it. The player still needs telling because they have stopped earning new cards.
	 */
	private void warnRequiredPluginDisabled()
	{
		// An unreadable collection already gets its own, more urgent warning.
		if (isRequiredPluginEnabled() || !collectionReader.isStateAvailable())
		{
			return;
		}
		chatFeedbackService.queueChat("[Bronzeman TCG] - The OSRS TCG plugin is turned off. Restrictions are still "
			+ "active using your last known collection, but you won't earn any new cards until "
			+ "you turn it back on.");
	}

	private void warnLiveCatalogDisabled()
	{
		if (config.allowRemoteCatalog())
		{
			return;
		}
		chatFeedbackService.queueChat("[Bronzeman TCG] - Download live catalogue is turned off. "
			+ "Enable it in the Bronzeman TCG settings to use the current OSRS TCG catalogue.");
	}

	/**
	 * Several plugin instances can share a display name (a disabled hub copy alongside a
	 * sideloaded dev build), so every match is checked rather than trusting the first one.
	 */
	private boolean isRequiredPluginEnabled()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			if (descriptor != null && REQUIRED_PLUGIN.equals(descriptor.name())
				&& pluginManager.isPluginEnabled(plugin))
			{
				return true;
			}
		}
		return false;
	}
}

package com.bronzemantcg.feature;

import com.bronzemantcg.BronzemanTcgConfig;
import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.restriction.LockState;
import com.bronzemantcg.restriction.RestrictionDecisionService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.ScriptID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

/**
 * Coordinates locked-item opacity and the shared decision used by the item-icon overlay.
 * RuneLite event subscribers stay in the plugin; this class owns visual marking policy,
 * refresh coalescing and widget mutation.
 */
@Singleton
public final class LockedItemMarkController
{
	// Widget opacity runs 0 (solid) to 255 (invisible). This value is also our
	// signature when restoring, so another plugin's opacity is never cleared.
	static final int LOCKED_ITEM_OPACITY = 140;
	private static final int PERIODIC_REFRESH_TICKS = 5;
	private static final int[] MARK_CONTAINERS = {
		InterfaceID.Inventory.ITEMS, InterfaceID.Bankmain.ITEMS, InterfaceID.Bankside.ITEMS,
		InterfaceID.Shopmain.ITEMS, InterfaceID.Shopside.ITEMS};

	private final Client client;
	private final ClientThread clientThread;
	private final BronzemanTcgConfig config;
	private final RestrictionDecisionService restrictionDecisionService;
	private final ActiveCardIdentityCatalog activeCatalog;
	private final AtomicBoolean refreshQueued = new AtomicBoolean();
	private final AtomicLong generation = new AtomicLong();

	private volatile boolean running;
	private int tickCounter;
	private long catalogRevision;

	@Inject
	public LockedItemMarkController(Client client, ClientThread clientThread,
		BronzemanTcgConfig config, RestrictionDecisionService restrictionDecisionService,
		ActiveCardIdentityCatalog activeCatalog)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.restrictionDecisionService = restrictionDecisionService;
		this.activeCatalog = activeCatalog;
	}

	public void startUp()
	{
		generation.incrementAndGet();
		refreshQueued.set(false);
		tickCounter = 0;
		catalogRevision = activeCatalog.getRevision();
		running = true;
	}

	public void shutDown()
	{
		running = false;
		long stoppedGeneration = generation.incrementAndGet();
		refreshQueued.set(false);
		clientThread.invoke(() ->
		{
			if (!running && generation.get() == stoppedGeneration)
			{
				clearMarks();
			}
		});
	}

	public void onGameTick()
	{
		if (!running)
		{
			return;
		}
		long currentRevision = activeCatalog.getRevision();
		boolean catalogChanged = isCatalogRevisionChanged(
			catalogRevision, currentRevision);
		catalogRevision = currentRevision;
		int tick = ++tickCounter;
		if (catalogChanged || isPeriodicRefreshTick(tick))
		{
			scheduleRefresh();
		}
	}

	public void onScriptPostFired(int scriptId)
	{
		if (isMarkRedrawScript(scriptId))
		{
			scheduleRefresh();
		}
	}

	public void onWidgetLoaded(int groupId)
	{
		if (isMarkContainerGroup(groupId))
		{
			scheduleRefresh();
		}
	}

	public void onConfigChanged(String group, String key)
	{
		if (shouldRefreshForConfig(group, key))
		{
			scheduleRefresh();
		}
	}

	/** Used only by the drawing overlay; fading is handled independently by {@link #applyMarks()}. */
	public boolean shouldDrawIcon(int itemId)
	{
		return running && isIconActive(config.itemUsageMode(), config.lockedItemMarkMode(),
			restrictionDecisionService.isEnforcementBypassed())
			&& itemId > 0 && restrictionDecisionService.isItemLocked(itemId);
	}

	private void scheduleRefresh()
	{
		if (!running || !refreshQueued.compareAndSet(false, true))
		{
			return;
		}
		long queuedGeneration = generation.get();
		clientThread.invokeAtTickEnd(() ->
		{
			if (generation.get() != queuedGeneration)
			{
				return;
			}
			refreshQueued.set(false);
			if (running)
			{
				applyMarks();
			}
		});
	}

	private void applyMarks()
	{
		boolean marking = isMarkingActive(config.itemUsageMode(), config.lockedItemMarkMode(),
			restrictionDecisionService.isEnforcementBypassed());
		for (int componentId : MARK_CONTAINERS)
		{
			Widget container = client.getWidget(componentId);
			Widget[] children = container == null ? null : container.getChildren();
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child == null || child.getItemId() <= 0)
				{
					continue;
				}
				boolean markItem = marking && restrictionDecisionService.isItemLocked(child.getItemId());
				int opacity = resolveOpacity(markItem, child.getOpacity());
				if (opacity != child.getOpacity())
				{
					child.setOpacity(opacity);
				}
			}
		}
	}

	private void clearMarks()
	{
		for (int componentId : MARK_CONTAINERS)
		{
			Widget container = client.getWidget(componentId);
			Widget[] children = container == null ? null : container.getChildren();
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child != null && child.getOpacity() == LOCKED_ITEM_OPACITY)
				{
					child.setOpacity(0);
				}
			}
		}
	}

	public static boolean isMarkingActive(LockState itemUsageMode,
		LockedItemMarkMode markMode, boolean enforcementBypassed)
	{
		return itemUsageMode == LockState.LOCKED
			&& markMode != LockedItemMarkMode.OFF
			&& !enforcementBypassed;
	}

	static boolean isIconActive(LockState itemUsageMode,
		LockedItemMarkMode markMode, boolean enforcementBypassed)
	{
		return isMarkingActive(itemUsageMode, markMode, enforcementBypassed)
			&& markMode == LockedItemMarkMode.TRANSPARENT_ICON;
	}

	static int resolveOpacity(boolean markItem, int currentOpacity)
	{
		if (markItem)
		{
			return LOCKED_ITEM_OPACITY;
		}
		return currentOpacity == LOCKED_ITEM_OPACITY ? 0 : currentOpacity;
	}

	static boolean isPeriodicRefreshTick(int tick)
	{
		return tick > 0 && tick % PERIODIC_REFRESH_TICKS == 0;
	}

	static boolean isCatalogRevisionChanged(long previous, long current)
	{
		return previous != current;
	}

	static boolean isMarkRedrawScript(int scriptId)
	{
		return scriptId == ScriptID.INVENTORY_DRAWITEM || scriptId == ScriptID.BANKMAIN_BUILD;
	}

	static boolean isMarkContainerGroup(int groupId)
	{
		return groupId == InterfaceID.SHOPMAIN || groupId == InterfaceID.SHOPSIDE;
	}

	static boolean shouldRefreshForConfig(String group, String key)
	{
		return BronzemanTcgConfig.GROUP.equals(group)
			&& ("itemUsageMode".equals(key) || "lockedItemMarkMode".equals(key));
	}
}

package com.bronzemantcg.feature;

import com.bronzemantcg.restriction.RestrictionDecisionService;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;

/**
 * Tracks visible ground items and caches their central ownership decision for the scene overlay.
 * RuneLite events remain subscribed in the plugin; this collaborator owns only lifecycle state.
 */
@Singleton
public final class GroundItemLockTracker
{
	private final RestrictionDecisionService restrictionDecisionService;
	private final Map<TileItem, TrackedGroundItem> trackedItems = new HashMap<>();
	private final Map<TileItem, TrackedGroundItem> trackedItemsView =
		Collections.unmodifiableMap(trackedItems);
	private RestrictionDecisionService.ItemContext itemContext;

	@Inject
	public GroundItemLockTracker(RestrictionDecisionService restrictionDecisionService)
	{
		this.restrictionDecisionService = restrictionDecisionService;
	}

	public void track(TileItem item, Tile tile, String name)
	{
		if (item == null)
		{
			return;
		}
		TrackedGroundItem tracked = new TrackedGroundItem(item.getId(), tile, name);
		RestrictionDecisionService.ItemContext current =
			restrictionDecisionService.getItemContext();
		tracked.blocked = isLocked(tracked, current);
		trackedItems.put(item, tracked);
	}

	public void untrack(TileItem item)
	{
		if (item != null)
		{
			trackedItems.remove(item);
		}
	}

	public void clear()
	{
		trackedItems.clear();
		itemContext = null;
	}

	/** Re-evaluate only when one of the immutable/identity-stable decision sources changes. */
	public void refresh()
	{
		RestrictionDecisionService.ItemContext current =
			restrictionDecisionService.getItemContext();
		if (current == itemContext)
		{
			return;
		}
		itemContext = current;
		for (TrackedGroundItem tracked : trackedItems.values())
		{
			tracked.blocked = isLocked(tracked, current);
		}
	}

	public Map<TileItem, TrackedGroundItem> getTrackedItems()
	{
		return trackedItemsView;
	}

	private boolean isLocked(TrackedGroundItem tracked,
		RestrictionDecisionService.ItemContext context)
	{
		if (tracked.name == null || tracked.name.isEmpty())
		{
			return false;
		}
		return restrictionDecisionService.isItemLocked(
			tracked.itemId, tracked.name, context);
	}

	public static final class TrackedGroundItem
	{
		private final int itemId;
		private final Tile tile;
		private final String name;
		private boolean blocked;

		private TrackedGroundItem(int itemId, Tile tile, String name)
		{
			this.itemId = itemId;
			this.tile = tile;
			this.name = name;
		}

		public Tile getTile()
		{
			return tile;
		}

		public boolean isBlocked()
		{
			return blocked;
		}
	}
}

package com.bronzemantcg.feature;

import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

@Singleton
public final class ChatFeedbackService
{
	private static final long CHAT_THROTTLE_MS = 1_200L;
	private static final int MAX_LISTED_MISSING_CARDS = 4;

	private final ChatMessageManager chatMessageManager;

	private long lastBlockMessageMs;

	@Inject
	public ChatFeedbackService(ChatMessageManager chatMessageManager)
	{
		this.chatMessageManager = chatMessageManager;
	}

	public void sendBlockedMessage(String entityName)
	{
		if (!reserveBlockedMessage())
		{
			return;
		}

		queueChat(String.format(Locale.US,
			"[Bronzeman TCG] You haven't collected the %s card yet - open more packs!",
			entityName));
	}

	public void sendBlockedCardsMessage(List<String> missingCards)
	{
		if (missingCards.size() == 1)
		{
			sendBlockedMessage(missingCards.get(0));
			return;
		}

		if (!reserveBlockedMessage())
		{
			return;
		}

		// Insanity mode can be missing dozens of seeds; keep the chat line readable.
		String listed = String.join(", ", missingCards.subList(
			0, Math.min(missingCards.size(), MAX_LISTED_MISSING_CARDS)));

		if (missingCards.size() > MAX_LISTED_MISSING_CARDS)
		{
			listed += String.format(Locale.US, " and %d more",
				missingCards.size() - MAX_LISTED_MISSING_CARDS);
		}

		queueChat(String.format(Locale.US,
			"[Bronzeman TCG] You haven't collected these cards yet: %s - open more packs!",
			listed));
	}

	/**
	 * CONSOLE type via the chat manager: raw GAMEMESSAGEs from addChatMessage get hidden
	 * when the player's Game chat tab is set to "Filter".
	 */
	public void queueChat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private boolean reserveBlockedMessage()
	{
		long now = System.currentTimeMillis();
		if (now - lastBlockMessageMs < CHAT_THROTTLE_MS)
		{
			return false;
		}

		lastBlockMessageMs = now;
		return true;
	}
}

