package com.bronzemantcg.catalog;


import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Informational PvM content readiness data for the side panel: the monster cards needed
 * to fight everything in each piece of instanced content (Fight Caves, Inferno, raids...).
 * Loaded from resources/panel/content_cards.json; reuses the quest checklist model since the
 * panel renders both identically.
 */
@Slf4j
@Singleton
public class ContentCatalog
{
	private List<QuestCatalog.QuestEntry> contents = Collections.emptyList();

	@Inject
	public ContentCatalog(Gson gson)
	{
		load(gson);
	}

	public List<QuestCatalog.QuestEntry> getContents()
	{
		return contents;
	}

	private void load(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream(
			"/panel/content_cards.json"))
		{
			if (stream == null)
			{
				log.info("content_cards.json not present; PvM content panel section will be empty.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.contents == null)
			{
				return;
			}
			List<QuestCatalog.QuestEntry> loaded = new ArrayList<>();
			for (ContentDto dto : snapshot.contents)
			{
				if (dto == null || dto.name == null || dto.name.trim().isEmpty())
				{
					continue;
				}
				List<QuestCatalog.Requirement> requirements = new ArrayList<>();
				if (dto.monsterCards != null)
				{
					for (String card : dto.monsterCards)
					{
						if (card != null && !card.trim().isEmpty())
						{
							requirements.add(new QuestCatalog.Requirement(card.trim(),
								Collections.singletonList(card.trim())));
						}
					}
				}
				loaded.add(new QuestCatalog.QuestEntry(dto.name.trim(), false, requirements,
					dto.notes == null ? "" : dto.notes.trim()));
			}
			contents = Collections.unmodifiableList(loaded);
			log.info("Loaded {} PvM content rosters from snapshot", contents.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load content_cards.json", ex);
		}
	}

	private static class Snapshot
	{
		List<ContentDto> contents;
	}

	private static class ContentDto
	{
		String name;
		List<String> monsterCards;
		String notes;
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Rejects structurally valid responses which are too incomplete to activate safely. */
@Singleton
public final class RemoteCatalogValidator
{
	static final int MINIMUM_ITEM_PARENTS = 3000;
	static final int MINIMUM_NPC_PARENTS = 1000;

	private final int minimumItemParents;
	private final int minimumNpcParents;
	private final Map<CardEntityKind, Set<String>> sentinelParents;

	@Inject
	public RemoteCatalogValidator()
	{
		this(MINIMUM_ITEM_PARENTS, MINIMUM_NPC_PARENTS, productionSentinels());
	}

	RemoteCatalogValidator(int minimumItemParents, int minimumNpcParents,
		Map<CardEntityKind, Set<String>> sentinelParents)
	{
		this.minimumItemParents = minimumItemParents;
		this.minimumNpcParents = minimumNpcParents;
		Map<CardEntityKind, Set<String>> copy = new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			copy.put(kind, Set.copyOf(sentinelParents.getOrDefault(kind, Set.of())));
		}
		this.sentinelParents = Map.copyOf(copy);
	}

	public void validate(OsrsTcgCatalogSnapshot snapshot) throws CatalogValidationException
	{
		if (snapshot == null)
		{
			throw new CatalogValidationException("catalogue snapshot is required");
		}
		Map<CardEntityKind, Integer> counts = new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			counts.put(kind, 0);
		}
		for (ImmutableCardIdentityCatalog.Entry entry : snapshot.getEntries())
		{
			CardEntityKind kind = entry.getIdentity().getKind();
			counts.put(kind, counts.get(kind) + 1);
		}
		requireCoverage(CardEntityKind.ITEM, counts.get(CardEntityKind.ITEM),
			minimumItemParents);
		requireCoverage(CardEntityKind.NPC, counts.get(CardEntityKind.NPC),
			minimumNpcParents);
		for (Map.Entry<CardEntityKind, Set<String>> entry : sentinelParents.entrySet())
		{
			for (String parent : entry.getValue())
			{
				if (snapshot.findByCardName(entry.getKey(), parent).size() != 1)
				{
					throw new CatalogValidationException("catalogue is missing "
						+ entry.getKey() + " sentinel parent " + parent);
				}
			}
		}
	}

	private static void requireCoverage(CardEntityKind kind, int actual, int minimum)
		throws CatalogValidationException
	{
		if (actual < minimum)
		{
			throw new CatalogValidationException("catalogue has only " + actual + " "
				+ kind + " parents; expected at least " + minimum);
		}
	}

	private static Map<CardEntityKind, Set<String>> productionSentinels()
	{
		Map<CardEntityKind, Set<String>> sentinels = new EnumMap<>(CardEntityKind.class);
		sentinels.put(CardEntityKind.ITEM,
			new LinkedHashSet<>(Set.of("Coins", "Water rune")));
		sentinels.put(CardEntityKind.NPC,
			new LinkedHashSet<>(Set.of("Goblin", "Zulrah")));
		return sentinels;
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import com.bronzemantcg.util.CacheFiles;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;

/** Persists the compact, validated identity projection of the public live catalogue. */
@Singleton
public final class RemoteCatalogCacheStore
{
	private static final int SCHEMA_VERSION = 1;
	private static final int MAX_CACHE_BYTES = 4 * 1024 * 1024;
	private static final String CACHE_FILE = "live-catalogue-v1.json";

	private final Gson gson;
	private final Path cacheFile;

	@Inject
	public RemoteCatalogCacheStore(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve("bronzeman-tcg")
			.resolve("catalogue").resolve(CACHE_FILE));
	}

	RemoteCatalogCacheStore(Gson gson, Path cacheFile)
	{
		if (gson == null || cacheFile == null)
		{
			throw new IllegalArgumentException("gson and cacheFile are required");
		}
		this.gson = gson;
		this.cacheFile = cacheFile;
	}

	public CachedCatalog load() throws IOException, CatalogValidationException
	{
		if (!Files.exists(cacheFile))
		{
			return null;
		}
		long size = Files.size(cacheFile);
		if (size <= 0 || size > MAX_CACHE_BYTES)
		{
			throw new CatalogValidationException("catalogue cache has an invalid size");
		}
		CacheDto dto;
		try
		{
			dto = gson.fromJson(Files.readString(cacheFile, StandardCharsets.UTF_8), CacheDto.class);
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			throw new CatalogValidationException("catalogue cache JSON is malformed", ex);
		}
		if (dto == null || dto.schemaVersion != SCHEMA_VERSION || dto.entries == null
			|| dto.entries.isEmpty() || !validVersion(dto.version)
			|| !validEtag(dto.etag) || dto.savedAtEpochMillis <= 0)
		{
			throw new CatalogValidationException("catalogue cache envelope is invalid");
		}
		List<ImmutableCardIdentityCatalog.Entry> entries = new ArrayList<>();
		for (int index = 0; index < dto.entries.size(); index++)
		{
			EntryDto entry = dto.entries.get(index);
			if (entry == null || entry.kind == null || blank(entry.cardName)
				|| entry.entityIds == null || entry.entityIds.isEmpty()
				|| entry.entityNames == null || entry.entityNames.isEmpty())
			{
				throw new CatalogValidationException("catalogue cache entry is invalid at " + index);
			}
			Set<Integer> entityIds = strictIds(entry.entityIds, "entity", index);
			Set<Integer> guardedIds = strictIds(entry.ownedNameRequiredEntityIds,
				"guarded", index);
			if (!entityIds.containsAll(guardedIds))
			{
				throw new CatalogValidationException(
					"catalogue cache guarded ID is unknown at " + index);
			}
			Set<String> entityNames = strictNames(entry.entityNames, "entity", index);
			Set<String> legacyNames = strictNames(entry.legacyCardNames, "legacy", index);
			CardIdentity identity = new CardIdentity(entry.kind, entry.cardName,
				legacyNames, entityIds, guardedIds);
			entries.add(new ImmutableCardIdentityCatalog.Entry(identity, entityNames));
		}
		OsrsTcgCatalogSnapshot snapshot = new OsrsTcgCatalogSnapshot(entries);
		if (snapshot.getAmbiguousIdCount(CardEntityKind.ITEM) != 0
			|| snapshot.getAmbiguousIdCount(CardEntityKind.NPC) != 0)
		{
			throw new CatalogValidationException(
				"catalogue cache contains ambiguous entity IDs");
		}
		return new CachedCatalog(snapshot, dto.version.trim(), trimToNull(dto.etag),
			dto.savedAtEpochMillis);
	}

	public void save(OsrsTcgCatalogSnapshot snapshot, String version, String etag,
		long savedAtEpochMillis) throws IOException
	{
		if (snapshot == null || !validVersion(version) || !validEtag(etag)
			|| savedAtEpochMillis <= 0)
		{
			throw new IllegalArgumentException("catalogue cache envelope is invalid");
		}
		CacheDto dto = new CacheDto();
		dto.schemaVersion = SCHEMA_VERSION;
		dto.version = version.trim();
		dto.etag = trimToNull(etag);
		dto.savedAtEpochMillis = savedAtEpochMillis;
		dto.entries = new ArrayList<>();
		for (ImmutableCardIdentityCatalog.Entry source : snapshot.getEntries())
		{
			CardIdentity identity = source.getIdentity();
			EntryDto entry = new EntryDto();
			entry.kind = identity.getKind();
			entry.cardName = identity.getCardName();
			entry.legacyCardNames = new ArrayList<>(identity.getLegacyCardNames());
			entry.entityNames = new ArrayList<>(source.getEntityNames());
			entry.entityIds = new ArrayList<>(identity.getEntityIds());
			entry.ownedNameRequiredEntityIds =
				new ArrayList<>(identity.getOwnedNameRequiredEntityIds());
			dto.entries.add(entry);
		}
		byte[] bytes = gson.toJson(dto).getBytes(StandardCharsets.UTF_8);
		if (bytes.length > MAX_CACHE_BYTES)
		{
			throw new IOException("compact catalogue cache exceeds size limit");
		}
		CacheFiles.writeAtomically(cacheFile, bytes);
	}

	Path getCacheFile()
	{
		return cacheFile;
	}

	private static Set<Integer> strictIds(List<Integer> values, String label, int index)
		throws CatalogValidationException
	{
		Set<Integer> result = new LinkedHashSet<>();
		if (values == null)
		{
			return result;
		}
		for (Integer value : values)
		{
			if (value == null || value < 0 || !result.add(value))
			{
				throw new CatalogValidationException("catalogue cache " + label
					+ " ID is invalid at " + index);
			}
		}
		return result;
	}

	private static Set<String> strictNames(List<String> values, String label, int index)
		throws CatalogValidationException
	{
		Set<String> result = new LinkedHashSet<>();
		if (values == null)
		{
			return result;
		}
		for (String value : values)
		{
			if (blank(value) || !result.add(value.trim()))
			{
				throw new CatalogValidationException("catalogue cache " + label
					+ " name is invalid at " + index);
			}
		}
		return result;
	}

	private static boolean blank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static String trimToNull(String value)
	{
		return blank(value) ? null : value.trim();
	}

	private static boolean validVersion(String value)
	{
		return !blank(value) && value.trim().length() <= 256
			&& value.indexOf('\r') < 0 && value.indexOf('\n') < 0;
	}

	private static boolean validEtag(String value)
	{
		if (blank(value))
		{
			return true;
		}
		String trimmed = value.trim();
		int quote = trimmed.startsWith("W/\"") ? 2 : 0;
		return trimmed.length() > quote + 1 && trimmed.length() <= 256
			&& trimmed.charAt(quote) == '"'
			&& trimmed.endsWith("\"")
			&& trimmed.substring(quote + 1, trimmed.length() - 1).indexOf('"') < 0
			&& trimmed.indexOf('\r') < 0 && trimmed.indexOf('\n') < 0;
	}

	public static final class CachedCatalog
	{
		private final OsrsTcgCatalogSnapshot snapshot;
		private final String version;
		private final String etag;
		private final long savedAtEpochMillis;

		private CachedCatalog(OsrsTcgCatalogSnapshot snapshot, String version, String etag,
			long savedAtEpochMillis)
		{
			this.snapshot = snapshot;
			this.version = version;
			this.etag = etag;
			this.savedAtEpochMillis = savedAtEpochMillis;
		}

		public OsrsTcgCatalogSnapshot getSnapshot()
		{
			return snapshot;
		}

		public String getVersion()
		{
			return version;
		}

		public String getEtag()
		{
			return etag;
		}

		public long getSavedAtEpochMillis()
		{
			return savedAtEpochMillis;
		}
	}

	@SuppressWarnings("unused")
	private static final class CacheDto
	{
		private int schemaVersion;
		private String version;
		private String etag;
		private long savedAtEpochMillis;
		private List<EntryDto> entries;
	}

	@SuppressWarnings({"unused", "MismatchedQueryAndUpdateOfCollection"})
	private static final class EntryDto
	{
		private CardEntityKind kind;
		private String cardName;
		private List<String> legacyCardNames;
		private List<String> entityNames;
		private List<Integer> entityIds;
		private List<Integer> ownedNameRequiredEntityIds;
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Strict parser for {@code /api/v1/catalog/cards/live}; it never returns a partial snapshot. */
@Singleton
public final class OsrsTcgCatalogParser
{
	private final Gson gson;

	@Inject
	public OsrsTcgCatalogParser(Gson gson)
	{
		this.gson = gson;
	}

	public OsrsTcgCatalogSnapshot parse(Reader reader) throws CatalogValidationException
	{
		if (reader == null)
		{
			throw new CatalogValidationException("catalogue reader is required");
		}
		RootDto root;
		try
		{
			root = gson.fromJson(reader, RootDto.class);
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			throw new CatalogValidationException("catalogue JSON is malformed", ex);
		}
		if (root == null)
		{
			throw new CatalogValidationException("catalogue response is empty");
		}
		if (root.items == null || root.items.isEmpty())
		{
			throw new CatalogValidationException("catalogue items are missing or empty");
		}
		if (root.npcs == null || root.npcs.isEmpty())
		{
			throw new CatalogValidationException("catalogue NPCs are missing or empty");
		}

		List<ImmutableCardIdentityCatalog.Entry> entries = new ArrayList<>();
		Map<CardEntityKind, Map<Integer, String>> parentsById = new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			parentsById.put(kind, new LinkedHashMap<>());
		}
		parseRows(CardEntityKind.ITEM, root.items, entries, parentsById.get(CardEntityKind.ITEM));
		parseRows(CardEntityKind.NPC, root.npcs, entries, parentsById.get(CardEntityKind.NPC));
		OsrsTcgCatalogSnapshot snapshot = new OsrsTcgCatalogSnapshot(entries);
		if (snapshot.getAmbiguousIdCount(CardEntityKind.ITEM) != 0
			|| snapshot.getAmbiguousIdCount(CardEntityKind.NPC) != 0)
		{
			throw new CatalogValidationException("catalogue contains ambiguous entity IDs");
		}
		return snapshot;
	}

	private static void parseRows(CardEntityKind kind, List<ParentDto> rows,
		List<ImmutableCardIdentityCatalog.Entry> entries, Map<Integer, String> parentsById)
		throws CatalogValidationException
	{
		for (int index = 0; index < rows.size(); index++)
		{
			ParentDto row = rows.get(index);
			String location = kind + " parent at index " + index;
			if (row == null)
			{
				throw new CatalogValidationException(location + " is null");
			}
			int parentId = requireId(row.id, location);
			String parentName = requireName(row.name, location);
			if (row.tcg == null)
			{
				throw new CatalogValidationException(location + " has no tcg data");
			}

			Set<Integer> entityIds = new LinkedHashSet<>();
			Set<Integer> ownedNameRequiredEntityIds = new LinkedHashSet<>();
			Set<String> entityNames = new LinkedHashSet<>();
			Set<String> legacyCardNames = new LinkedHashSet<>();
			entityIds.add(parentId);
			entityNames.add(parentName);
			claimId(parentsById, parentId, parentName, location);

			List<VariantDto> variants = row.tcg.variants == null
				? Collections.emptyList() : row.tcg.variants;
			for (int variantIndex = 0; variantIndex < variants.size(); variantIndex++)
			{
				VariantDto variant = variants.get(variantIndex);
				String variantLocation = location + " variant at index " + variantIndex;
				if (variant == null)
				{
					throw new CatalogValidationException(variantLocation + " is null");
				}
				int variantId = requireId(variant.id, variantLocation);
				String variantName = requireName(variant.name, variantLocation);
				claimId(parentsById, variantId, parentName, variantLocation);
				entityIds.add(variantId);
				entityNames.add(variantName);
				if (requiresParentOwnershipName(kind, parentName, variantName))
				{
					ownedNameRequiredEntityIds.add(variantId);
				}
				else if (!normalize(parentName).equals(normalize(variantName)))
				{
					legacyCardNames.add(variantName);
				}
			}

			CardIdentity identity = new CardIdentity(kind, parentName, legacyCardNames,
				entityIds, ownedNameRequiredEntityIds);
			entries.add(new ImmutableCardIdentityCatalog.Entry(identity, entityNames));
		}
	}

	private static boolean requiresParentOwnershipName(CardEntityKind kind,
		String parentName, String variantName)
	{
		return kind == CardEntityKind.ITEM
			&& "coins".equals(normalize(parentName))
			&& "coin pouch".equals(normalize(variantName));
	}

	private static void claimId(Map<Integer, String> parentsById, int entityId,
		String parentName, String location) throws CatalogValidationException
	{
		String existing = parentsById.putIfAbsent(entityId, parentName);
		if (existing != null && !normalize(existing).equals(normalize(parentName)))
		{
			throw new CatalogValidationException(location + " reuses entity ID " + entityId
				+ " already assigned to " + existing);
		}
	}

	private static int requireId(Integer id, String location) throws CatalogValidationException
	{
		if (id == null || id < 0)
		{
			throw new CatalogValidationException(location + " has an invalid ID");
		}
		return id;
	}

	private static String requireName(String name, String location)
		throws CatalogValidationException
	{
		if (name == null || name.trim().isEmpty())
		{
			throw new CatalogValidationException(location + " has a missing name");
		}
		return name.trim();
	}

	private static String normalize(String value)
	{
		return value.trim().toLowerCase(Locale.ROOT);
	}

	@SuppressWarnings("unused")
	private static final class RootDto
	{
		private List<ParentDto> items;
		private List<ParentDto> npcs;
	}

	@SuppressWarnings("unused")
	private static final class ParentDto
	{
		private Integer id;
		private String name;
		private TcgDto tcg;
	}

	@SuppressWarnings("unused")
	private static final class TcgDto
	{
		private List<VariantDto> variants;
	}

	@SuppressWarnings("unused")
	private static final class VariantDto
	{
		private Integer id;
		private String name;
	}
}

package com.bronzemantcg.catalog.remote;

/** A remote catalogue response was malformed or unsafe to activate as one complete snapshot. */
public final class CatalogValidationException extends Exception
{
	private static final long serialVersionUID = 1L;

	public CatalogValidationException(String message)
	{
		super(message);
	}

	public CatalogValidationException(String message, Throwable cause)
	{
		super(message, cause);
	}
}

package com.bronzemantcg.catalog.remote;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Downloads the public OSRS TCG catalogue without retaining its raw response in OkHttp's cache. */
@Singleton
public class OsrsTcgCatalogClient
{
	static final String LIVE_CATALOG_URL = "https://api.osrs-tcg.net/api/v1/catalog/cards/live";
	static final int MAX_RESPONSE_BYTES = 8 * 1024 * 1024;

	private final OkHttpClient httpClient;
	private final String endpoint;
	private final int maximumResponseBytes;

	@Inject
	public OsrsTcgCatalogClient(OkHttpClient httpClient)
	{
		this(httpClient, LIVE_CATALOG_URL, MAX_RESPONSE_BYTES);
	}

	OsrsTcgCatalogClient(OkHttpClient httpClient, String endpoint, int maximumResponseBytes)
	{
		if (httpClient == null)
		{
			throw new IllegalArgumentException("httpClient is required");
		}
		if (endpoint == null || endpoint.trim().isEmpty())
		{
			throw new IllegalArgumentException("endpoint is required");
		}
		if (maximumResponseBytes <= 0)
		{
			throw new IllegalArgumentException("maximumResponseBytes must be positive");
		}
		this.httpClient = httpClient;
		this.endpoint = endpoint;
		this.maximumResponseBytes = maximumResponseBytes;
	}

	public FetchHandle fetch(Listener listener)
	{
		return fetch(null, listener);
	}

	public FetchHandle fetch(String currentEtag, Listener listener)
	{
		if (listener == null)
		{
			throw new IllegalArgumentException("listener is required");
		}
		FetchHandle handle = new FetchHandle();
		enqueue(handle, currentEtag, listener);
		return handle;
	}

	private void enqueue(FetchHandle handle, String currentEtag, Listener listener)
	{
		if (handle.isCancelled())
		{
			return;
		}
		CacheControl cacheControl = new CacheControl.Builder().noCache().noStore().build();
		Request.Builder builder = new Request.Builder().url(endpoint).get()
			.cacheControl(cacheControl);
		if (currentEtag != null && !currentEtag.trim().isEmpty())
		{
			builder.header("If-None-Match", currentEtag.trim());
		}
		Call call = httpClient.newCall(builder.build());
		handle.setActiveCall(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call failedCall, @Nonnull IOException exception)
			{
				if (handle.isCancelled())
				{
					return;
				}
				listener.onFailure(failureMessage(exception.getMessage()), exception);
			}

			@Override
			public void onResponse(@Nonnull Call completedCall, @Nonnull Response response)
			{
				try (Response closeableResponse = response)
				{
					if (handle.isCancelled())
					{
						return;
					}
					if (response.code() == 304)
					{
						if (currentEtag == null || currentEtag.trim().isEmpty())
						{
							listener.onFailure(
								"HTTP 304 without a cached catalogue validator", null);
							return;
						}
						listener.onSuccess(CatalogResponse.notModified(
							catalogVersion(response), response.header("ETag")));
						return;
					}
					if (!response.isSuccessful())
					{
						listener.onFailure("HTTP " + response.code(), null);
						return;
					}

					ResponseBody body = response.body();
					if (body == null)
					{
						listener.onFailure("catalogue response has no body", null);
						return;
					}
					byte[] bytes;
					try
					{
						bytes = readBounded(body);
					}
					catch (IOException exception)
					{
						listener.onFailure(failureMessage(exception.getMessage()), exception);
						return;
					}
					if (!handle.isCancelled())
					{
						listener.onSuccess(new CatalogResponse(bytes,
							catalogVersion(response), response.header("ETag")));
					}
				}
			}
		});
	}

	private byte[] readBounded(ResponseBody body) throws IOException
	{
		long contentLength = body.contentLength();
		if (contentLength > maximumResponseBytes)
		{
			throw new IOException("catalogue response exceeds " + maximumResponseBytes + " bytes");
		}
		try (InputStream input = body.byteStream();
			ByteArrayOutputStream output = new ByteArrayOutputStream(
				contentLength > 0 ? (int) contentLength : 8192))
		{
			byte[] buffer = new byte[8192];
			int total = 0;
			int read;
			while ((read = input.read(buffer)) != -1)
			{
				total += read;
				if (total > maximumResponseBytes)
				{
					throw new IOException("catalogue response exceeds "
						+ maximumResponseBytes + " bytes");
				}
				output.write(buffer, 0, read);
			}
			return output.toByteArray();
		}
	}

	private static String catalogVersion(Response response)
	{
		String version = response.header("X-Catalog-Version");
		if (version == null || version.trim().isEmpty())
		{
			version = response.header("ETag");
		}
		return version == null ? "unknown" : version.trim();
	}

	private static String failureMessage(String currentFailure)
	{
		return currentFailure == null || currentFailure.trim().isEmpty()
			? "catalogue request failed" : currentFailure.trim();
	}

	public interface Listener
	{
		void onSuccess(CatalogResponse response);

		void onFailure(String reason, Throwable cause);
	}

	public static final class FetchHandle
	{
		private final AtomicBoolean cancelled = new AtomicBoolean();
		private final AtomicReference<Call> activeCall = new AtomicReference<>();

		public void cancel()
		{
			cancelled.set(true);
			Call call = activeCall.getAndSet(null);
			if (call != null)
			{
				call.cancel();
			}
		}

		public boolean isCancelled()
		{
			return cancelled.get();
		}

		private void setActiveCall(Call call)
		{
			Call previous = activeCall.getAndSet(call);
			if (previous != null && previous != call)
			{
				previous.cancel();
			}
			if (cancelled.get() && activeCall.compareAndSet(call, null))
			{
				call.cancel();
			}
		}
	}

	public static final class CatalogResponse
	{
		private final byte[] body;
		private final String version;
		private final String etag;
		private final boolean notModified;

		CatalogResponse(byte[] body, String version)
		{
			this(body, version, null, false);
		}

		CatalogResponse(byte[] body, String version, String etag)
		{
			this(body, version, etag, false);
		}

		private CatalogResponse(byte[] body, String version, String etag,
			boolean notModified)
		{
			this.body = body.clone();
			this.version = version;
			this.etag = etag;
			this.notModified = notModified;
		}

		static CatalogResponse notModified(String version, String etag)
		{
			return new CatalogResponse(new byte[0], version, etag, true);
		}

		public byte[] getBody()
		{
			return body.clone();
		}

		public String getVersion()
		{
			return version;
		}

		public String getEtag()
		{
			return etag;
		}

		public boolean isNotModified()
		{
			return notModified;
		}
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.ActiveCardIdentityCatalog;
import com.bronzemantcg.ownership.BundledCardIdentityCatalog;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Fetches, validates and capability-gates the public OSRS TCG identity catalogue. */
@Slf4j
@Singleton
public final class RemoteCatalogService
{
	private final OsrsTcgCatalogClient client;
	private final OsrsTcgCatalogParser parser;
	private final RemoteCatalogValidator validator;
	private final BundledCardIdentityCatalog bundledCatalog;
	private final ActiveCardIdentityCatalog activeCatalog;
	private final RemoteCatalogCacheStore cacheStore;
	private final AtomicLong generation = new AtomicLong();
	private final AtomicReference<OsrsTcgCatalogClient.FetchHandle> activeFetch =
		new AtomicReference<>();

	private boolean running;
	private boolean enabled;
	private boolean v1Capable;
	private boolean fetchStarted;
	private OsrsTcgCatalogSnapshot pendingSnapshot;
	private String pendingVersion;
	private String pendingEtag;
	private volatile Listener listener = Listener.NONE;

	@Inject
	public RemoteCatalogService(OsrsTcgCatalogClient client,
		OsrsTcgCatalogParser parser, RemoteCatalogValidator validator,
		BundledCardIdentityCatalog bundledCatalog,
		ActiveCardIdentityCatalog activeCatalog, RemoteCatalogCacheStore cacheStore)
	{
		this.client = client;
		this.parser = parser;
		this.validator = validator;
		this.bundledCatalog = bundledCatalog;
		this.activeCatalog = activeCatalog;
		this.cacheStore = cacheStore;
	}

	public void setListener(Listener listener)
	{
		this.listener = listener == null ? Listener.NONE : listener;
	}

	public void startUp()
	{
		generation.incrementAndGet();
		cancelActiveFetch();
		OsrsTcgCatalogSnapshot cachedSnapshot = null;
		String cachedVersion = null;
		String cachedEtag = null;
		try
		{
			RemoteCatalogCacheStore.CachedCatalog cached = cacheStore.load();
			if (cached != null)
			{
				validator.validate(cached.getSnapshot());
				cachedSnapshot = cached.getSnapshot()
					.withLegacyAliases(bundledCatalog.getEntries());
				cachedVersion = cached.getVersion();
				cachedEtag = cached.getEtag();
			}
		}
		catch (CatalogValidationException | IOException | RuntimeException ex)
		{
			log.warn("Ignoring invalid Bronzeman live-catalogue cache; "
				+ "bundled fallback remains active.", ex);
		}
		synchronized (this)
		{
			running = true;
			enabled = false;
			v1Capable = false;
			fetchStarted = false;
			pendingSnapshot = cachedSnapshot;
			pendingVersion = cachedVersion;
			pendingEtag = cachedEtag;
			activeCatalog.useBundled();
		}
	}

	/** Enables or disables every request to the public catalogue endpoint. */
	public void setEnabled(boolean enabled)
	{
		boolean cancelFetch = false;
		long changedRevision;
		long fetchGeneration = -1L;
		synchronized (this)
		{
			long before = activeCatalog.getRevision();
			boolean wasEnabled = this.enabled;
			this.enabled = running && enabled;
			if (!this.enabled)
			{
				activeCatalog.useBundled();
				if (wasEnabled)
				{
					generation.incrementAndGet();
					cancelFetch = true;
					fetchStarted = false;
				}
			}
			else
			{
				activatePendingIfReady();
				if (v1Capable && !fetchStarted)
				{
					fetchStarted = true;
					fetchGeneration = generation.get();
				}
			}
			changedRevision = changedRevision(before);
		}
		if (cancelFetch)
		{
			cancelActiveFetch();
		}
		notifyChanged(changedRevision);
		if (fetchGeneration >= 0)
		{
			startFetch(fetchGeneration);
		}
	}

	private void startFetch(long activeGeneration)
	{
		String currentEtag;
		synchronized (this)
		{
			currentEtag = pendingEtag;
		}
		OsrsTcgCatalogClient.FetchHandle handle = client.fetch(currentEtag,
			new OsrsTcgCatalogClient.Listener()
			{
				@Override
				public void onSuccess(OsrsTcgCatalogClient.CatalogResponse response)
				{
					handleSuccess(activeGeneration, response);
				}

				@Override
				public void onFailure(String reason, Throwable cause)
				{
					if (activeGeneration == generation.get())
					{
						log.debug("Remote OSRS TCG catalogue unavailable: {}", reason, cause);
					}
				}
			});
		activeFetch.set(handle);
		if (activeGeneration != generation.get())
		{
			handle.cancel();
		}
	}

	public void setV1Capable(boolean capable)
	{
		long changedRevision;
		long fetchGeneration = -1L;
		synchronized (this)
		{
			long before = activeCatalog.getRevision();
			v1Capable = running && capable;
			if (!v1Capable)
			{
				activeCatalog.useBundled();
			}
			else if (enabled)
			{
				activatePendingIfReady();
				if (!fetchStarted)
				{
					fetchStarted = true;
					fetchGeneration = generation.get();
				}
			}
			changedRevision = changedRevision(before);
		}
		notifyChanged(changedRevision);
		if (fetchGeneration >= 0)
		{
			startFetch(fetchGeneration);
		}
	}

	public void shutDown()
	{
		generation.incrementAndGet();
		cancelActiveFetch();
		synchronized (this)
		{
			running = false;
			enabled = false;
			v1Capable = false;
			fetchStarted = false;
			pendingSnapshot = null;
			pendingVersion = null;
			pendingEtag = null;
			activeCatalog.useBundled();
		}
	}

	private void cancelActiveFetch()
	{
		OsrsTcgCatalogClient.FetchHandle handle = activeFetch.getAndSet(null);
		if (handle != null)
		{
			handle.cancel();
		}
	}

	private void handleSuccess(long activeGeneration,
		OsrsTcgCatalogClient.CatalogResponse response)
	{
		if (activeGeneration != generation.get())
		{
			return;
		}
		try
		{
			if (response.isNotModified())
			{
				long changedRevision;
				synchronized (this)
				{
					if (!running || pendingSnapshot == null
						|| activeGeneration != generation.get())
					{
						return;
					}
					long before = activeCatalog.getRevision();
					activatePendingIfReady();
					changedRevision = changedRevision(before);
				}
				notifyChanged(changedRevision);
				log.info("Validated cached OSRS TCG catalogue remains current (version={})",
					pendingVersion);
				return;
			}
			OsrsTcgCatalogSnapshot remote;
			try (InputStreamReader reader = new InputStreamReader(
				new ByteArrayInputStream(response.getBody()), StandardCharsets.UTF_8))
			{
				remote = parser.parse(reader);
			}
			validator.validate(remote);
			if (activeGeneration != generation.get())
			{
				return;
			}
			try
			{
				cacheStore.save(remote, response.getVersion(), response.getEtag(),
					Instant.now().toEpochMilli());
			}
			catch (IOException | RuntimeException ex)
			{
				log.warn("Could not update the Bronzeman live-catalogue cache; using this "
					+ "validated response for the current session.", ex);
			}
			remote = remote.withLegacyAliases(bundledCatalog.getEntries());
			long changedRevision;
			synchronized (this)
			{
				if (!running || activeGeneration != generation.get())
				{
					return;
				}
				pendingSnapshot = remote;
				pendingVersion = response.getVersion();
				pendingEtag = response.getEtag();
				long before = activeCatalog.getRevision();
				activatePendingIfReady();
				changedRevision = changedRevision(before);
			}
			notifyChanged(changedRevision);
			log.info("Validated OSRS TCG catalogue (version={}, active={})",
				response.getVersion(), activeCatalog.isRemoteActive());
		}
		catch (CatalogValidationException | IOException | RuntimeException exception)
		{
			if (activeGeneration == generation.get())
			{
				log.warn("Rejected remote OSRS TCG catalogue; bundled fallback remains active.",
					exception);
			}
		}
	}

	private void activatePendingIfReady()
	{
		if (running && enabled && v1Capable && pendingSnapshot != null)
		{
			activeCatalog.activate(pendingSnapshot, pendingSnapshot.getEntries(), pendingVersion);
		}
	}

	private long changedRevision(long before)
	{
		long after = activeCatalog.getRevision();
		return after == before ? -1L : after;
	}

	private void notifyChanged(long revision)
	{
		if (revision < 0)
		{
			return;
		}
		try
		{
			listener.onActiveCatalogChanged(revision, activeCatalog.isV1CatalogAvailable());
		}
		catch (RuntimeException ex)
		{
			log.warn("Remote catalogue listener failed", ex);
		}
	}

	public interface Listener
	{
		Listener NONE = (revision, v1CatalogAvailable) -> { };

		void onActiveCatalogChanged(long revision, boolean v1CatalogAvailable);
	}
}

package com.bronzemantcg.catalog.remote;

import com.bronzemantcg.ownership.CardEntityKind;
import com.bronzemantcg.ownership.CardIdentity;
import com.bronzemantcg.ownership.CardIdentityCatalog;
import com.bronzemantcg.ownership.ImmutableCardIdentityCatalog;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** One fully validated, immutable OSRS TCG live-catalogue response. */
public final class OsrsTcgCatalogSnapshot implements CardIdentityCatalog
{
	private final ImmutableCardIdentityCatalog catalog;
	private final Map<CardEntityKind, Map<String, Set<String>>> cardNamesByEntityName;

	OsrsTcgCatalogSnapshot(List<ImmutableCardIdentityCatalog.Entry> entries)
	{
		catalog = new ImmutableCardIdentityCatalog(entries);
		Map<CardEntityKind, Map<String, Set<String>>> tracked = new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			tracked.put(kind, new LinkedHashMap<>());
		}
		for (ImmutableCardIdentityCatalog.Entry entry : catalog.getEntries())
		{
			CardIdentity identity = entry.getIdentity();
			Map<String, Set<String>> names = tracked.get(identity.getKind());
			for (String entityName : entry.getEntityNames())
			{
				names.computeIfAbsent(normalize(entityName), ignored -> new LinkedHashSet<>())
					.add(identity.getCardName());
			}
		}
		cardNamesByEntityName = freeze(tracked);
	}

	@Override
	public List<CardIdentity> findById(CardEntityKind kind, int entityId)
	{
		return catalog.findById(kind, entityId);
	}

	@Override
	public List<CardIdentity> findByName(CardEntityKind kind, String entityName)
	{
		return catalog.findByName(kind, entityName);
	}

	@Override
	public List<CardIdentity> findByCardName(CardEntityKind kind, String cardName)
	{
		return catalog.findByCardName(kind, cardName);
	}

	public List<ImmutableCardIdentityCatalog.Entry> getEntries()
	{
		return catalog.getEntries();
	}

	public int size()
	{
		return catalog.size();
	}

	public int getAmbiguousIdCount(CardEntityKind kind)
	{
		return catalog.getAmbiguousIdCount(kind);
	}

	public Map<String, Set<String>> getCardNamesByEntityName(CardEntityKind kind)
	{
		return cardNamesByEntityName.getOrDefault(kind, Collections.emptyMap());
	}

	/**
	 * Adds reviewed Beta card-name aliases to matching live parents without importing any
	 * fallback entity ID or entity-name authority into the live snapshot.
	 */
	public OsrsTcgCatalogSnapshot withLegacyAliases(
		List<ImmutableCardIdentityCatalog.Entry> fallbackEntries)
	{
		Map<CardEntityKind, Map<String, CardIdentity>> fallbackByParent =
			new EnumMap<>(CardEntityKind.class);
		for (CardEntityKind kind : CardEntityKind.values())
		{
			fallbackByParent.put(kind, new LinkedHashMap<>());
		}
		if (fallbackEntries != null)
		{
			for (ImmutableCardIdentityCatalog.Entry entry : fallbackEntries)
			{
				if (entry != null)
				{
					CardIdentity identity = entry.getIdentity();
					fallbackByParent.get(identity.getKind()).put(
						normalize(identity.getCardName()), identity);
				}
			}
		}

		List<ImmutableCardIdentityCatalog.Entry> enriched = new ArrayList<>();
		for (ImmutableCardIdentityCatalog.Entry entry : catalog.getEntries())
		{
			CardIdentity live = entry.getIdentity();
			LinkedHashSet<String> legacyNames = new LinkedHashSet<>(live.getLegacyCardNames());
			CardIdentity fallback = fallbackByParent.get(live.getKind())
				.get(normalize(live.getCardName()));
			if (fallback != null)
			{
				legacyNames.addAll(fallback.getLegacyCardNames());
			}
			CardIdentity identity = new CardIdentity(live.getKind(), live.getCardName(),
				legacyNames, live.getEntityIds(), live.getOwnedNameRequiredEntityIds());
			enriched.add(new ImmutableCardIdentityCatalog.Entry(identity, entry.getEntityNames()));
		}
		return new OsrsTcgCatalogSnapshot(enriched);
	}

	private static Map<CardEntityKind, Map<String, Set<String>>> freeze(
		Map<CardEntityKind, Map<String, Set<String>>> source)
	{
		Map<CardEntityKind, Map<String, Set<String>>> result =
			new EnumMap<>(CardEntityKind.class);
		for (Map.Entry<CardEntityKind, Map<String, Set<String>>> kindEntry
			: source.entrySet())
		{
			Map<String, Set<String>> names = new LinkedHashMap<>();
			for (Map.Entry<String, Set<String>> entry : kindEntry.getValue().entrySet())
			{
				names.put(entry.getKey(), Collections.unmodifiableSet(
					new LinkedHashSet<>(entry.getValue())));
			}
			result.put(kindEntry.getKey(), Collections.unmodifiableMap(names));
		}
		return Collections.unmodifiableMap(result);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}
}

package com.bronzemantcg.catalog;


import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Skill levels, prerequisite quests and quest-point gates per quest, generated from the
 * OSRS Wiki (scripts/build_quest_requirements.py). Purely a side-panel aid: it drives the
 * independent quest-panel filters and the quest hover, and never restricts anything in game.
 *
 * <p>Levels are compared strictly against real levels - boosts are deliberately not
 * honoured. Requirements the wiki states as free text (combat ability, area access) are
 * either omitted or carried as display-only {@link Requirements#other} notes that the
 * filter ignores.
 */
@Slf4j
@Singleton
public class QuestRequirementCatalog
{
	private Map<String, Requirements> byQuestName = Collections.emptyMap();

	@Inject
	public QuestRequirementCatalog(Gson gson)
	{
		load(gson);
	}

	/** Requirements for a quest, or null when it has none worth checking. */
	public Requirements get(String questName)
	{
		if (questName == null)
		{
			return null;
		}
		return byQuestName.get(questName.toLowerCase(Locale.ROOT));
	}

	public int size()
	{
		return byQuestName.size();
	}

	private void load(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream(
			"/quest/quest_requirements.json"))
		{
			if (stream == null)
			{
				log.info("quest_requirements.json not present; the quest requirement "
					+ "filter will treat every quest as unrestricted.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.quests == null)
			{
				return;
			}
			Map<String, Requirements> loaded = new HashMap<>();
			for (QuestDto dto : snapshot.quests)
			{
				if (dto == null || dto.name == null || dto.name.trim().isEmpty())
				{
					continue;
				}
				Requirements requirements = toRequirements(dto);
				if (requirements != null)
				{
					loaded.put(dto.name.trim().toLowerCase(Locale.ROOT), requirements);
				}
			}
			byQuestName = Collections.unmodifiableMap(loaded);
			log.info("Loaded requirements for {} quests", byQuestName.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load quest_requirements.json", ex);
		}
	}

	private static Requirements toRequirements(QuestDto dto)
	{
		List<SkillRequirement> skills = new ArrayList<>();
		if (dto.skills != null)
		{
			for (SkillDto skill : dto.skills)
			{
				if (skill == null || skill.skill == null || skill.level < 1)
				{
					continue;
				}
				Skill parsed = parseSkill(skill.skill);
				// An unknown skill name means the generator and this client disagree.
				// Skip it rather than block the whole quest on data we cannot evaluate.
				if (parsed != null)
				{
					skills.add(new SkillRequirement(parsed, skill.level));
				}
			}
		}

		List<QuestRequirement> quests = new ArrayList<>();
		if (dto.quests != null)
		{
			for (QuestDto prerequisite : dto.quests)
			{
				if (prerequisite == null || prerequisite.runeliteQuest == null)
				{
					continue;
				}
				Quest quest = parseQuest(prerequisite.runeliteQuest);
				if (quest != null)
				{
					quests.add(new QuestRequirement(
						prerequisite.name == null ? quest.getName() : prerequisite.name.trim(),
						quest));
				}
			}
		}

		List<String> other = new ArrayList<>();
		if (dto.other != null)
		{
			for (String note : dto.other)
			{
				if (note != null && !note.trim().isEmpty())
				{
					other.add(note.trim());
				}
			}
		}

		int questPoints = Math.max(dto.questPoints, 0);
		if (skills.isEmpty() && quests.isEmpty() && questPoints == 0 && other.isEmpty())
		{
			return null;
		}
		return new Requirements(skills, quests, questPoints, other);
	}

	private static Skill parseSkill(String name)
	{
		for (Skill skill : Skill.values())
		{
			if (skill.name().equalsIgnoreCase(name.trim()))
			{
				return skill;
			}
		}
		log.warn("Unknown skill '{}' in quest_requirements.json", name);
		return null;
	}

	private static Quest parseQuest(String constant)
	{
		for (Quest quest : Quest.values())
		{
			if (quest.name().equals(constant.trim()))
			{
				return quest;
			}
		}
		log.warn("Unknown quest constant '{}' in quest_requirements.json", constant);
		return null;
	}

	/** Everything gating one quest. Only skills, prerequisites and quest points count. */
	public static class Requirements
	{
		public final List<SkillRequirement> skills;
		public final List<QuestRequirement> quests;
		public final int questPoints;
		/** Display-only notes; real gates we cannot evaluate, never used for filtering. */
		public final List<String> other;

		private Requirements(List<SkillRequirement> skills, List<QuestRequirement> quests,
			int questPoints, List<String> other)
		{
			this.skills = Collections.unmodifiableList(skills);
			this.quests = Collections.unmodifiableList(quests);
			this.questPoints = questPoints;
			this.other = Collections.unmodifiableList(other);
		}

		/**
		 * @param levels real skill levels indexed by {@link Skill#ordinal()}, or null when
		 *               unknown (logged out) - unknown means "cannot judge", so it passes
		 * @param completedQuests lower-case names of finished quests
		 */
		public boolean isMet(int[] levels, int questPointCount, java.util.Set<String> completedQuests)
		{
			if (levels == null)
			{
				return true;
			}
			for (SkillRequirement requirement : skills)
			{
				int ordinal = requirement.skill.ordinal();
				if (ordinal >= levels.length || levels[ordinal] < requirement.level)
				{
					return false;
				}
			}
			if (questPointCount < questPoints)
			{
				return false;
			}
			for (QuestRequirement requirement : quests)
			{
				if (!completedQuests.contains(
					requirement.quest.getName().toLowerCase(Locale.ROOT)))
				{
					return false;
				}
			}
			return true;
		}
	}

	public static class SkillRequirement
	{
		public final Skill skill;
		public final int level;

		private SkillRequirement(Skill skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}
	}

	public static class QuestRequirement
	{
		public final String name;
		public final Quest quest;

		private QuestRequirement(String name, Quest quest)
		{
			this.name = name;
			this.quest = quest;
		}
	}

	private static class Snapshot
	{
		List<QuestDto> quests;
	}

	private static class QuestDto
	{
		String name;
		String runeliteQuest;
		List<SkillDto> skills;
		List<QuestDto> quests;
		int questPoints;
		List<String> other;
	}

	private static class SkillDto
	{
		String skill;
		int level;
	}
}

package com.bronzemantcg.catalog;


import java.util.Locale;

/** The point in a potion chain represented by a generated Herblore recipe. */
public enum HerbloreRecipeStage
{
	UNFINISHED,
	FINISHED,
	UPGRADE;

	public static HerbloreRecipeStage from(String value)
	{
		if (value == null)
		{
			return null;
		}
		try
		{
			return valueOf(value.trim().toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}
}

package com.bronzemantcg.catalog;

import java.util.regex.Pattern;

/**
 * Name-normalization helpers shared by every catalog lookup.
 */
public final class CardNames
{
	// "Attack potion(3)", "Saradomin brew(4)" -> card names carry no dose suffix.
	private static final Pattern DOSE_SUFFIX = Pattern.compile("\\s*\\([1-4]\\)$");

	private CardNames()
	{
	}

	public static String stripDoseSuffix(String name)
	{
		return DOSE_SUFFIX.matcher(name).replaceFirst("");
	}
}

package com.bronzemantcg.catalog;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.function.Predicate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Processing-skill recipes (firemaking, smithing, crafting, enchanting, fletching, herblore)
 * loaded from resources/nodes/recipe_nodes.json. Each recipe declares input card groups (any one
 * card per group, all groups needed) and an output card; the per-skill config mode decides
 * whether inputs, output, or both are enforced at click time.
 *
 * Trigger kinds and their lookup keys:
 *  - item-on-item:  (used item name, target item name) e.g. ("Tinderbox", "oak logs")
 *  - item-on-object:(used item name, target object)    e.g. ("Iron ore", "furnace")
 *  - interface:     (product name, "*") - make-X interface clicks only carry the product
 *  - spell-on-item: keyed by the TARGET item alone ((item, "*")) since each enchantable
 *    item has exactly one enchant spell; spell-name strings vary by client widget.
 */
@Slf4j
@Singleton
public class RecipeCatalog
{
	public static final String KIND_ITEM_ON_ITEM = "item-on-item";
	public static final String KIND_ITEM_ON_OBJECT = "item-on-object";
	public static final String KIND_INTERFACE = "interface";
	public static final String KIND_SPELL_ON_ITEM = "spell-on-item";
	public static final String ANY_TARGET = "*";
	private static final String COSTUME_NEEDLE = "costume needle";
	private static final Set<String> COSTUME_NEEDLE_REPLACEMENTS = new HashSet<>(Arrays.asList(
		"needle", "thread"));

	private static final Set<String> EVENT_LOGS = new HashSet<>(Arrays.asList(
		"blue logs", "green logs", "red logs", "purple logs", "white logs"));

	private Map<String, Recipe> recipes = Collections.emptyMap();

	@Inject
	public RecipeCatalog(Gson gson)
	{
		load(gson);
	}

	/**
	 * Exact lookup with no ANY_TARGET fallback. Used to decide which of several
	 * candidate items is the real material behind a generic interface label: a
	 * fallback match would answer "yes" for every candidate and tell us nothing.
	 */
	public Recipe findExact(String kind, String name, String target)
	{
		if (name == null || target == null)
		{
			return null;
		}
		return recipes.get(key(kind,
			canonicalTriggerName(kind,
				CardNames.stripDoseSuffix(name.trim().toLowerCase(Locale.ROOT))),
			CardNames.stripDoseSuffix(target.trim().toLowerCase(Locale.ROOT))));
	}

	/** @return the recipe for this interaction, or null if unrestricted. */
	public Recipe find(String kind, String name, String target)
	{
		if (name == null)
		{
			return null;
		}
		String nameKey = canonicalTriggerName(kind,
			CardNames.stripDoseSuffix(name.trim().toLowerCase(Locale.ROOT)));
		String targetKey = target == null ? ANY_TARGET
			: CardNames.stripDoseSuffix(target.trim().toLowerCase(Locale.ROOT));
		Recipe recipe = recipes.get(key(kind, nameKey, targetKey));
		if (recipe == null && !ANY_TARGET.equals(targetKey))
		{
			recipe = recipes.get(key(kind, nameKey, ANY_TARGET));
		}
		return recipe;
	}

	public int size()
	{
		return recipes.size();
	}

	private static String key(String kind, String nameLower, String targetLower)
	{
		return kind + '|' + nameLower + '|' + targetLower;
	}

	/** Costume needle opens the same sewing interfaces as Needle. */
	private static String canonicalTriggerName(String kind, String nameLower)
	{
		return KIND_ITEM_ON_ITEM.equals(kind) && COSTUME_NEEDLE.equals(nameLower)
			? "needle" : nameLower;
	}

	private void load(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream("/nodes/recipe_nodes.json"))
		{
			if (stream == null)
			{
				log.warn("recipe_nodes.json missing from classpath; recipe restrictions disabled.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.recipes == null)
			{
				return;
			}
			// Interface names shared by several recipes (e.g. the knife menu labels every
			// crossbow stock tier "Crossbow stock") cannot take the ANY_TARGET catch-all
			// below: all of them would write the same key and only the last would survive,
			// silently gating every tier on the last one's cards. Those must be matched on
			// their declared target instead. Counted up front so the rule is automatic -
			// any future generic-label family is handled without anyone noticing this trap.
			Map<String, Integer> interfaceNameCounts = new HashMap<>();
			for (RecipeDto dto : snapshot.recipes)
			{
				if (dto != null && dto.trigger != null && dto.trigger.kind != null
					&& dto.trigger.name != null
					&& KIND_INTERFACE.equals(dto.trigger.kind.trim().toLowerCase(Locale.ROOT)))
				{
					String n = dto.trigger.name.trim().toLowerCase(Locale.ROOT);
					interfaceNameCounts.merge(n, 1, Integer::sum);
				}
			}

			Map<String, Recipe> map = new HashMap<>();
			for (RecipeDto dto : snapshot.recipes)
			{
				if (dto == null || dto.category == null || dto.trigger == null
					|| dto.trigger.kind == null || dto.trigger.name == null)
				{
					continue;
				}
				List<ResourceNodeCatalog.CardGroup> inputs = new ArrayList<>();
				if (dto.inputs != null)
				{
					for (List<String> group : dto.inputs)
					{
						ResourceNodeCatalog.CardGroup g =
							ResourceNodeCatalog.CardGroup.of(group, null, null);
						if (g != null)
						{
							inputs.add(g);
						}
					}
				}
				String kind = dto.trigger.kind.trim().toLowerCase(Locale.ROOT);
				String name = dto.trigger.name.trim().toLowerCase(Locale.ROOT);
				List<String> targets = dto.trigger.targets == null || dto.trigger.targets.isEmpty()
					? Collections.singletonList(ANY_TARGET) : dto.trigger.targets;

				for (String target : targets)
				{
					String targetKey = target == null ? ANY_TARGET : target.trim().toLowerCase(Locale.ROOT);
					boolean eventLog = "firemaking".equals(dto.category) && EVENT_LOGS.contains(targetKey);
					Recipe recipe = new Recipe(dto.category, inputs, dto.output, eventLog,
						dto.crushable, HerbloreRecipeStage.from(dto.stage));
					map.put(key(kind, name, targetKey), recipe);
					if (KIND_SPELL_ON_ITEM.equals(kind))
					{
						// Also key enchants by the target jewellery alone: each enchantable
						// item has exactly one enchant spell, and the clicked spell's menu
						// string is less stable than the item name.
						map.put(key(kind, targetKey, ANY_TARGET), recipe);
					}
					if (KIND_INTERFACE.equals(kind) && interfaceNameCounts.getOrDefault(name, 0) <= 1)
					{
						// Make-X clicks only expose the product name, not the station, so a
						// uniquely-named product is matched by name alone. Skipped for shared
						// names (see interfaceNameCounts above) - those match on target only,
						// and failing to resolve one simply means no restriction.
						map.put(key(kind, name, ANY_TARGET), recipe);
					}
				}
			}
			recipes = Collections.unmodifiableMap(map);
			log.info("Loaded {} recipe rules from snapshot", recipes.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load recipe_nodes.json", ex);
		}
	}

	public static class Recipe
	{
		public final String category;
		public final List<ResourceNodeCatalog.CardGroup> inputGroups;
		/** Exact output card name, or null (e.g. firemaking produces no item). */
		public final String output;
		public final boolean eventLog;
		/** Gem-cutting recipes whose gem can shatter into a Crushed gem; config-gated extra. */
		public final boolean crushable;
		/** Herblore chain position; null for non-Herblore recipes. */
		public final HerbloreRecipeStage herbloreStage;

		Recipe(String category, List<ResourceNodeCatalog.CardGroup> inputGroups, String output,
			boolean eventLog, boolean crushable, HerbloreRecipeStage herbloreStage)
		{
			this.category = category.trim().toLowerCase(Locale.ROOT);
			this.inputGroups = Collections.unmodifiableList(inputGroups);
			this.output = output;
			this.eventLog = eventLog;
			this.crushable = crushable;
			this.herbloreStage = herbloreStage;
		}

		/** Display strings for unmet requirements under the given enforcement, empty = allowed. */
		public List<String> missingRequirements(Set<String> owned, boolean enforceInputs,
			boolean enforceOutput)
		{
			return missingRequirements(owned::contains, enforceInputs, enforceOutput);
		}

		/** Identity-aware form used by enforcement; display strings and any-of groups are unchanged. */
		public List<String> missingRequirements(Predicate<String> ownsCard,
			boolean enforceInputs, boolean enforceOutput)
		{
			List<String> missing = new ArrayList<>();
			boolean costumeNeedleOwned = "crafting".equals(category)
				&& ownsCard.test(COSTUME_NEEDLE);
			if (enforceInputs)
			{
				for (ResourceNodeCatalog.CardGroup group : inputGroups)
				{
					if (!group.isSatisfied(ownsCard)
						&& !(costumeNeedleOwned && isCostumeNeedleReplacement(group)))
					{
						missing.add(String.join(" / ", group.displayCards));
					}
				}
			}
			if (enforceOutput && output != null
				&& !ownsCard.test(output.toLowerCase(Locale.ROOT)))
			{
				missing.add(output);
			}
			return missing;
		}

		private static boolean isCostumeNeedleReplacement(ResourceNodeCatalog.CardGroup group)
		{
			return group.displayCards.size() == 1
				&& COSTUME_NEEDLE_REPLACEMENTS.contains(
					group.displayCards.get(0).toLowerCase(Locale.ROOT));
		}
	}

	private static class Snapshot
	{
		List<RecipeDto> recipes;
	}

	private static class RecipeDto
	{
		String category;
		String stage;
		List<List<String>> inputs;
		String output;
		boolean crushable;
		TriggerDto trigger;
	}

	private static class TriggerDto
	{
		String kind;
		String name;
		List<String> targets;
	}
}

package com.bronzemantcg.catalog;


import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * Quest-state awareness for NPC restriction: an NPC tied to a quest the player has
 * STARTED (in progress or finished) is "shown" - visible in Hide mode and granted
 * Prevent Combat treatment in the strict tiers, so no quest is ever bricked by
 * restriction settings while the quest-NPC exception is enabled. Attack always stays
 * card-gated; quest progression is the permit for everything else.
 *
 * Quest names from quest_cards.json are matched to RuneLite's {@link Quest} enum by
 * normalised name. Unmatched quests (renames, miniquests missing from the enum) FAIL
 * OPEN: their NPCs are always shown, because over-showing is recoverable while a
 * silently hidden quest NPC bricks a quest.
 *
 * {@link Quest#getState} reads varps, so it never runs on the render path; the
 * plugin calls {@link #refresh} on a slow game-tick cadence and everything else
 * reads the cached set.
 */
@Slf4j
@Singleton
public class QuestNpcIndex
{
	// NPCs whose quest interaction lives in node rules rather than monsterCards;
	// currently just the CotS Guards (Mark option).
	private static final Map<String, Quest> INTERACTION_NPCS =
		Map.of("guard", Quest.CHILDREN_OF_THE_SUN);
	// Generic names cannot safely identify one quest NPC. Children of the Sun's
	// Guard is handled explicitly above because that interaction has its own rule.
	private static final Set<String> NON_UNIQUE_NPC_NAMES = Set.of("guard");

	private final Map<String, List<Quest>> npcQuests = new HashMap<>();
	private final Set<String> alwaysShown = new HashSet<>();

	private volatile Set<String> shownNpcs = Collections.emptySet();
	private volatile boolean cotsInProgress;

	@Inject
	public QuestNpcIndex(QuestCatalog questCatalog)
	{
		Map<String, Quest> questsByName = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			questsByName.put(normalise(quest.getName()), quest);
		}

		int unmatched = 0;
		for (Map.Entry<String, List<String>> entry : questCatalog.getQuestMonsterCards().entrySet())
		{
			Quest quest = questsByName.get(normalise(entry.getKey()));
			for (String card : entry.getValue())
			{
				// Cards use wiki-style disambiguation ("Monkey (monster)"); the in-game
				// NPC name is the bare prefix, same convention as the monster snapshot.
				String npc = card.replaceAll("\\s*\\([^)]*\\)$", "").trim().toLowerCase(Locale.ROOT);
				if (npc.isEmpty())
				{
					continue;
				}
				if (!isIndexableNpcName(npc))
				{
					continue;
				}
				if (quest == null)
				{
					alwaysShown.add(npc);
				}
				else
				{
					npcQuests.computeIfAbsent(npc, k -> new ArrayList<>()).add(quest);
				}
			}
			if (quest == null)
			{
				unmatched++;
			}
		}
		for (Map.Entry<String, Quest> entry : INTERACTION_NPCS.entrySet())
		{
			npcQuests.computeIfAbsent(entry.getKey(), k -> new ArrayList<>()).add(entry.getValue());
		}
		log.info("Quest NPC index: {} NPCs across matched quests, {} fail-open from {} unmatched quest names",
			npcQuests.size(), alwaysShown.size(), unmatched);
	}

	/** Recompute the shown set. Client thread only; called on a slow tick cadence. */
	public void refresh(Client client)
	{
		Set<String> shown = new HashSet<>(alwaysShown);
		for (Map.Entry<String, List<Quest>> entry : npcQuests.entrySet())
		{
			for (Quest quest : entry.getValue())
			{
				if (quest.getState(client) != QuestState.NOT_STARTED)
				{
					shown.add(entry.getKey());
					break;
				}
			}
		}
		shownNpcs = shown;
		cotsInProgress = Quest.CHILDREN_OF_THE_SUN.getState(client) == QuestState.IN_PROGRESS;
	}

	/** True when this NPC belongs to a started (or unmatched) quest and is exception-eligible. */
	public boolean isShownQuestNpc(String npcName)
	{
		return npcName != null && shownNpcs.contains(npcName.trim().toLowerCase(Locale.ROOT));
	}

	/** Waives the quest-cots node rule (Guard marking) while the quest is actually running. */
	public boolean isCotsInProgress()
	{
		return cotsInProgress;
	}

	private static String normalise(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	static boolean isIndexableNpcName(String name)
	{
		return name != null && !NON_UNIQUE_NPC_NAMES.contains(
			name.trim().toLowerCase(Locale.ROOT));
	}
}

