package com.bronzemantcg.catalog;


import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;

/**
 * Informational quest data for the side panel: which cards a player must own to complete
 * each quest (required items as any-of groups, plus resolvable quest enemies). Loaded from
 * resources/quest/quest_cards.json; purely display - quests are never blocked by this plugin,
 * but under forced-drop a locked quest item genuinely can't be used, so "own the cards"
 * and "can physically complete it" coincide.
 */
@Slf4j
@Singleton
public class QuestCatalog
{
	private List<QuestEntry> quests = Collections.emptyList();
	private List<QuestEntry> miniquests = Collections.emptyList();
	// Quest name -> quest-linked in-game NPC names, including miniquests. Enemy card
	// names and explicit NPC labels feed QuestNpcIndex's quest-state override.
	private Map<String, List<String>> questMonsterCards = Collections.emptyMap();
	private Map<String, List<String>> cardQuests = Collections.emptyMap();

	@Inject
	public QuestCatalog(Gson gson)
	{
		load(gson);
	}

	public List<QuestEntry> getQuests()
	{
		return quests;
	}

	public List<QuestEntry> getMiniquests()
	{
		return miniquests;
	}

	public Map<String, List<String>> getQuestMonsterCards()
	{
		return questMonsterCards;
	}

	public List<String> getQuestsForCard(String cardName)
	{
		if (cardName == null)
		{
			return Collections.emptyList();
		}
		return cardQuests.getOrDefault(
			cardName.toLowerCase(Locale.ROOT), Collections.emptyList());
	}

	private void load(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream("/quest/quest_cards.json"))
		{
			if (stream == null)
			{
				log.info("quest_cards.json not present; quest panel section will be empty.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.quests == null)
			{
				return;
			}
			List<QuestEntry> loaded = new ArrayList<>();
			List<QuestEntry> loadedMiniquests = new ArrayList<>();
			Map<String, List<String>> monsterMap = new HashMap<>();
			Map<String, List<String>> questsByCard = new HashMap<>();
			for (QuestDto dto : snapshot.quests)
			{
				if (dto == null || dto.name == null || dto.name.trim().isEmpty())
				{
					continue;
				}
				List<Section> sections = new ArrayList<>();
				List<String> monsters = new ArrayList<>();
				if (dto.sections != null)
				{
					for (SectionDto sectionDto : dto.sections)
					{
						if (sectionDto == null)
						{
							continue;
						}
						List<Requirement> requirements = new ArrayList<>();
						if (sectionDto.requirements != null)
						{
							for (RequirementDto requirementDto : sectionDto.requirements)
							{
								Requirement requirement = loadRequirement(requirementDto);
								if (requirement != null)
								{
									requirements.add(requirement);
									indexRequirement(questsByCard, dto.name.trim(),
										requirement, monsters);
								}
							}
						}
						sections.add(new Section(sectionDto.label, requirements));
					}
				}
				if (!monsters.isEmpty())
				{
					// Keyed by the game name: QuestNpcIndex matches these against Quest.getName().
					monsterMap.put(gameName(dto), Collections.unmodifiableList(monsters));
				}
				QuestEntry entry = new QuestEntry(dto.name.trim(), gameName(dto), dto.miniquest,
					sections.toArray(new Section[0]),
					dto.notes == null ? "" : dto.notes.trim());
				(dto.miniquest ? loadedMiniquests : loaded).add(entry);
			}
			loaded.sort((a, b) -> sortName(a.name).compareToIgnoreCase(sortName(b.name)));
			loadedMiniquests.sort((a, b) -> sortName(a.name).compareToIgnoreCase(sortName(b.name)));
			quests = Collections.unmodifiableList(loaded);
			miniquests = Collections.unmodifiableList(loadedMiniquests);
			questMonsterCards = Collections.unmodifiableMap(monsterMap);
			Map<String, List<String>> immutableCardQuests = new HashMap<>();
			for (Map.Entry<String, List<String>> entry : questsByCard.entrySet())
			{
				entry.getValue().sort(String.CASE_INSENSITIVE_ORDER);
				immutableCardQuests.put(entry.getKey(),
					Collections.unmodifiableList(entry.getValue()));
			}
			cardQuests = Collections.unmodifiableMap(immutableCardQuests);
			log.info("Loaded {} quests and {} miniquests from card-requirement snapshot",
				quests.size(), miniquests.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load quest_cards.json", ex);
		}
	}

	/** Resolve the optional RuneLite constant to the game's own quest name. */
	private static String gameName(QuestDto dto)
	{
		if (dto.runeliteQuest == null || dto.runeliteQuest.trim().isEmpty())
		{
			return dto.name.trim();
		}
		for (Quest quest : Quest.values())
		{
			if (quest.name().equals(dto.runeliteQuest.trim()))
			{
				return quest.getName();
			}
		}
		log.warn("Unknown quest constant '{}' on '{}'", dto.runeliteQuest, dto.name);
		return dto.name.trim();
	}

	private static Requirement loadRequirement(RequirementDto dto)
	{
		return loadRequirement(dto, null);
	}

	private static Requirement loadRequirement(RequirementDto dto, String inheritedType)
	{
		if (dto == null || dto.label == null || dto.label.trim().isEmpty())
		{
			return null;
		}
		List<Requirement> children = new ArrayList<>();
		if (dto.children != null)
		{
			for (RequirementDto childDto : dto.children)
			{
				Requirement child = loadRequirement(childDto,
					dto.type == null || dto.type.trim().isEmpty() ? inheritedType : dto.type);
				if (child != null)
				{
					children.add(child);
				}
			}
		}
		String type = dto.type == null || dto.type.trim().isEmpty()
			? inheritedType : dto.type;
		return new Requirement(dto.label.trim(), dto.cards, dto.cards, dto.quantity,
			parseLogic(dto.logic), type, children, dto.selector, dto.selectorValue,
			dto.displayCardsOnly);
	}

	private static Logic parseLogic(String value)
	{
		return "ANY".equalsIgnoreCase(value) ? Logic.ANY : Logic.ALL;
	}

	private static String sortName(String name)
	{
		return name.regionMatches(true, 0, "The ", 0, 4) ? name.substring(4) : name;
	}

	private static void indexRequirement(Map<String, List<String>> questsByCard,
		String questName, Requirement requirement, List<String> monsters)
	{
		indexQuestCards(questsByCard, questName, requirement.displayCards);
		if ("enemy".equals(requirement.type))
		{
			for (String card : requirement.displayCards)
			{
				indexQuestNpc(monsters, card);
			}
		}
		else if ("npc".equals(requirement.type))
		{
			// A v1 card can represent several named NPCs (for example the
			// Goblin generals parent). The requirement label is the in-game
			// NPC identity; the card name remains the ownership requirement.
			indexQuestNpc(monsters, requirement.label);
		}
		for (Requirement child : requirement.children)
		{
			indexRequirement(questsByCard, questName, child, monsters);
		}
	}

	private static void indexQuestNpc(List<String> monsters, String npcName)
	{
		if (npcName != null && !npcName.trim().isEmpty() && !monsters.contains(npcName))
		{
			monsters.add(npcName);
		}
	}

	private static void indexQuestCards(Map<String, List<String>> questsByCard,
		String questName, List<String> cards)
	{
		for (String card : cards)
		{
			if (card == null || card.trim().isEmpty())
			{
				continue;
			}
			List<String> quests = questsByCard.computeIfAbsent(
				card.trim().toLowerCase(Locale.ROOT), ignored -> new ArrayList<>());
			if (!quests.contains(questName))
			{
				quests.add(questName);
			}
		}
	}

	public static class QuestEntry
	{
		public final String name;
		/**
		 * The name RuneLite's {@link Quest} enum uses. Usually identical to {@link #name},
		 * but a shortened display name ("RFD - King Awowogei") must still resolve to the
		 * game's own name or quest-completion lookups silently never match.
		 */
		public final String questName;
		public final boolean miniquest;
		public final List<Section> sections;
		public final List<Requirement> requirements;
		public final String notes;

		public QuestEntry(String name, boolean miniquest, List<Requirement> requirements)
		{
			this(name, miniquest, requirements, "");
		}

		public QuestEntry(String name, boolean miniquest, List<Requirement> requirements, String notes)
		{
			this(name, miniquest,
				new Section[]{new Section("", requirements)}, notes);
		}

		private QuestEntry(String name, boolean miniquest, Section[] sections, String notes)
		{
			this(name, name, miniquest, sections, notes);
		}

		private QuestEntry(String name, String questName, boolean miniquest,
			Section[] sections, String notes)
		{
			this.name = name;
			this.questName = questName == null || questName.trim().isEmpty() ? name : questName;
			this.miniquest = miniquest;
			List<Section> sectionList = new ArrayList<>();
			Collections.addAll(sectionList, sections);
			this.sections = Collections.unmodifiableList(sectionList);
			List<Requirement> flattened = new ArrayList<>();
			for (Section section : sectionList)
			{
				flattened.addAll(section.requirements);
			}
			this.requirements = Collections.unmodifiableList(flattened);
			this.notes = notes;
		}

		/** Copy this entry with presentation-only sections while preserving game identity. */
		public QuestEntry withSections(List<Section> projectedSections)
		{
			return new QuestEntry(name, questName, miniquest,
				projectedSections.toArray(new Section[0]), notes);
		}

		public int satisfiedCount(Set<String> ownedLowerCase)
		{
			return satisfiedCount(ownedLowerCase, RouteSelection.UNKNOWN);
		}

		public int satisfiedCount(Set<String> ownedLowerCase, RouteSelection route)
		{
			int count = 0;
			for (Requirement requirement : requirements)
			{
				if (requirement.isSatisfied(ownedLowerCase, route))
				{
					count++;
				}
			}
			return count;
		}
	}

	public static class Section
	{
		public final String label;
		public final List<Requirement> requirements;

		Section(String label, List<Requirement> requirements)
		{
			this.label = label == null ? "" : label.trim();
			this.requirements = Collections.unmodifiableList(new ArrayList<>(requirements));
		}

		/** Copy this section with presentation-only requirements. */
		public Section withRequirements(List<Requirement> projectedRequirements)
		{
			return new Section(label, projectedRequirements);
		}

		public int satisfiedCount(Set<String> ownedLowerCase, RouteSelection route)
		{
			int count = 0;
			for (Requirement requirement : requirements)
			{
				if (requirement.isSatisfied(ownedLowerCase, route))
				{
					count++;
				}
			}
			return count;
		}
	}

	public enum Logic
	{
		ALL,
		ANY
	}

	public enum RouteSelection
	{
		UNKNOWN,
		BLACK_ARM,
		PHOENIX
	}

	/** Recursive card requirement. A leaf owns any card; a branch combines child nodes. */
	public static class Requirement
	{
		public final String label;
		public final List<String> displayCards;
		public final List<String> lowerCards;
		public final int quantity;
		public final Logic logic;
		public final String type;
		public final List<Requirement> children;
		public final String selector;
		public final String selectorValue;
		public final boolean displayCardsOnly;

		public Requirement(String label, List<String> cards)
		{
			this(label, cards, cards, null, Logic.ANY, "card",
				Collections.emptyList(), null, null, false);
		}

		Requirement(String label, List<String> displayCards, List<String> acceptedCards,
			Integer quantity,
			Logic logic, String type, List<Requirement> children,
			String selector, String selectorValue, boolean displayCardsOnly)
		{
			this.label = label;
			List<String> display = new ArrayList<>();
			for (String card : displayCards == null
				? Collections.<String>emptyList() : displayCards)
			{
				if (card != null && !card.trim().isEmpty())
				{
					display.add(card.trim());
				}
			}
			List<String> lower = new ArrayList<>();
			for (String card : acceptedCards == null
				? Collections.<String>emptyList() : acceptedCards)
			{
				if (card != null && !card.trim().isEmpty())
				{
					String normalized = card.trim().toLowerCase(Locale.ROOT);
					if (!lower.contains(normalized))
					{
						lower.add(normalized);
					}
				}
			}
			this.displayCards = Collections.unmodifiableList(display);
			this.lowerCards = Collections.unmodifiableList(lower);
			this.quantity = quantity == null || quantity < 1 ? 1 : quantity;
			this.logic = logic == null ? Logic.ALL : logic;
			this.type = type == null ? "card" : type.trim().toLowerCase(Locale.ROOT);
			this.children = Collections.unmodifiableList(new ArrayList<>(children));
			this.selector = selector == null ? "" : selector.trim();
			this.selectorValue = selectorValue == null ? "" : selectorValue.trim();
			this.displayCardsOnly = displayCardsOnly;
		}

		/**
		 * Copy this requirement for another presentation catalogue. Display cards remain
		 * canonical and compact while accepted cards may include reviewed legacy aliases.
		 */
		public Requirement withProjection(List<String> projectedDisplayCards,
			List<String> acceptedCards, List<Requirement> projectedChildren)
		{
			return new Requirement(label, projectedDisplayCards, acceptedCards, quantity,
				logic, type, projectedChildren, selector, selectorValue, displayCardsOnly);
		}

		public boolean isSatisfied(Set<String> ownedLowerCase)
		{
			return isSatisfied(ownedLowerCase, RouteSelection.UNKNOWN);
		}

		public boolean isSatisfied(Set<String> ownedLowerCase, RouteSelection route)
		{
			Requirement selected = selectedChild(route);
			if (selected != null)
			{
				return selected.isSatisfied(ownedLowerCase, route);
			}
			if (!children.isEmpty())
			{
				if (logic == Logic.ANY)
				{
					for (Requirement child : children)
					{
						if (child.isSatisfied(ownedLowerCase, route))
						{
							return true;
						}
					}
					return false;
				}
				for (Requirement child : children)
				{
					if (!child.isSatisfied(ownedLowerCase, route))
					{
						return false;
					}
				}
				return true;
			}
			for (String card : lowerCards)
			{
				if (ownedLowerCase.contains(card))
				{
					return true;
				}
			}
			return lowerCards.isEmpty();
		}

		private Requirement selectedChild(RouteSelection route)
		{
			if (!"SHIELD_GANG".equals(selector) || route == RouteSelection.UNKNOWN)
			{
				return null;
			}
			for (Requirement child : children)
			{
				if (route.name().equals(child.selectorValue))
				{
					return child;
				}
			}
			return null;
		}
	}

	private static class Snapshot
	{
		int schema;
		List<QuestDto> quests;
	}

	private static class QuestDto
	{
		String name;
		/** Optional RuneLite Quest constant when the display name differs from the game's. */
		String runeliteQuest;
		boolean miniquest;
		List<SectionDto> sections;
		String notes;
	}

	private static class SectionDto
	{
		String label;
		List<RequirementDto> requirements;
	}

	private static class RequirementDto
	{
		String label;
		List<String> cards;
		Integer quantity;
		String logic;
		String type;
		List<RequirementDto> children;
		String selector;
		String selectorValue;
		boolean displayCardsOnly;
	}
}

package com.bronzemantcg.catalog;

import java.util.Locale;
import java.util.Set;

/** Classifies carried item names that satisfy gathering-tool requirements. */
public final class ToolNameClassifier
{
	/*
	 * Woodcutting axes only. Generic " axe" suffix matching would also accept
	 * carded combat weapons such as the Zombie axe, Soulreaper axe and
	 * Morrigan's throwing axe. Felling axes are retained for future catalogue
	 * support; untracked names remain inert until OSRS TCG cards them.
	 */
	private static final Set<String> WOODCUTTING_AXES = Set.of(
		"bronze axe", "iron axe", "steel axe", "black axe", "mithril axe",
		"adamant axe", "rune axe", "dragon axe", "crystal axe", "infernal axe",
		"gilded axe", "3rd age axe", "corrupted axe",
		"bronze felling axe", "iron felling axe", "steel felling axe",
		"black felling axe", "mithril felling axe", "adamant felling axe",
		"rune felling axe", "dragon felling axe", "crystal felling axe");

	private ToolNameClassifier()
	{
	}

	public static boolean isMiningPickaxe(String itemName)
	{
		return itemName != null
			&& itemName.toLowerCase(Locale.ROOT).endsWith(" pickaxe");
	}

	public static boolean isWoodcuttingAxe(String itemName)
	{
		return itemName != null
			&& WOODCUTTING_AXES.contains(itemName.toLowerCase(Locale.ROOT));
	}
}

package com.bronzemantcg.catalog;


import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.function.Predicate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Rules for gating skill resource nodes (trees, rocks, fishing spots, pickpocket targets,
 * raw-food-on-fire, ...) behind ownership of the cards of the items they yield or consume.
 * Loaded from resources/nodes/resource_nodes.json, which is hand-curated (assisted by audits of
 * osrs-tcg's Card.json for exact card names) and expected to grow over time.
 *
 * Lookup is by (kind, in-game name, menu option) — all lower-cased. For "item-on-object"
 * rules the roles shift: name = the used item, options = the target object names, because
 * that's what a "Use Raw shrimps -> Fire" click gives us.
 *
 * Requirements come in two data shapes, unified internally into card GROUPS:
 *  - requiredCards + requireAll (legacy): requireAll=true -> each card its own group
 *    (all needed); requireAll=false -> one group (any one card suffices).
 *  - requiredCardGroups (+ optional parallel groupRoles): every group must be satisfied,
 *    a group is satisfied by owning ANY one of its cards. Roles let config modes drop
 *    groups (e.g. runecrafting's "rune" group in Talisman-only mode).
 */
@Slf4j
@Singleton
public class ResourceNodeCatalog
{
	public static final String KIND_OBJECT = "object";
	public static final String KIND_NPC = "npc";
	/** RuneLite FishingSpot enum name + the clicked fishing option. */
	public static final String KIND_FISHING_SPOT = "fishing-spot";
	public static final String KIND_ITEM_ON_OBJECT = "item-on-object";
	public static final String KIND_INVENTORY = "inventory";
	/** Make-interface product clicks; nodes use options ["*"] since only the product name is known. */
	public static final String KIND_INTERFACE = "interface";
	public static final String ANY_OPTION = "*";

	private Map<String, Rule> rules = Collections.emptyMap();
	private List<String> masterFarmerSeedCards = Collections.emptyList();
	// Lowercased names of NPCs carrying "slayer"-category rules (the masters). The NPC
	// visibility sweep exempts them: their interactions answer only to the Slayer section.
	private Set<String> slayerNpcNamesLower = Collections.emptySet();

	@Inject
	public ResourceNodeCatalog(Gson gson)
	{
		load(gson);
	}

	/** Exact card names of every seed on Master Farmer's drop table (for Insanity mode). */
	public List<String> getMasterFarmerSeedCards()
	{
		return masterFarmerSeedCards;
	}

	/** True when this NPC has any slayer-category rule (i.e. it's a slayer master). */
	public boolean isSlayerNpc(String name)
	{
		return name != null && slayerNpcNamesLower.contains(name.trim().toLowerCase(Locale.ROOT));
	}

	/** @return the rule for this interaction, or null if the node is unrestricted. */
	public Rule find(String kind, String name, String option)
	{
		return find(kind, name, option, -1);
	}

	/**
	 * ID-aware lookup for objects whose display name is not specific enough to identify
	 * their loot table (notably Thieving chests, which are commonly all named "Chest").
	 * Exact ID rules take priority; ordinary name-based rules remain the fallback.
	 */
	public Rule find(String kind, String name, String option, int targetId)
	{
		if (name == null || option == null)
		{
			return null;
		}
		String cleanKind = kind.trim().toLowerCase(Locale.ROOT);
		String cleanOption = option.trim().toLowerCase(Locale.ROOT);
		if (targetId >= 0)
		{
			Rule idRule = rules.get(idKey(cleanKind, targetId, cleanOption));
			if (idRule != null)
			{
				return idRule;
			}
		}
		String nameKey = CardNames.stripDoseSuffix(name.trim().toLowerCase(Locale.ROOT));
		return rules.get(key(cleanKind, nameKey, cleanOption));
	}

	public int size()
	{
		return rules.size();
	}

	/**
	 * Unmodifiable view of all rules keyed "kind|name|option" (all lowercased), for the
	 * side panel's progress meters. The same Rule instance appears once per option.
	 */
	public Map<String, Rule> getRuleEntries()
	{
		return rules;
	}

	private static String key(String kind, String nameLower, String optionLower)
	{
		return kind + '|' + nameLower + '|' + optionLower;
	}

	private static String idKey(String kind, int id, String optionLower)
	{
		return kind + "|#" + id + '|' + optionLower;
	}

	private void load(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream(
			"/nodes/resource_nodes.json"))
		{
			if (stream == null)
			{
				log.warn("resource_nodes.json missing from classpath; resource nodes will be unrestricted.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.nodes == null)
			{
				return;
			}
			Map<String, Rule> map = new HashMap<>();
			Set<String> slayerNames = new HashSet<>();
			for (NodeDto node : snapshot.nodes)
			{
				if (node == null || node.kind == null || node.name == null || node.options == null)
				{
					continue;
				}
				List<CardGroup> groups = buildGroups(node);
				if (groups.isEmpty())
				{
					continue;
				}
				Rule rule = new Rule(node.category, groups);
				String kindLower = node.kind.trim().toLowerCase(Locale.ROOT);
				String nameLower = node.name.trim().toLowerCase(Locale.ROOT);
				if ("slayer".equals(node.category)
					&& KIND_NPC.equals(kindLower))
				{
					slayerNames.add(nameLower);
				}
				for (String option : node.options)
				{
					if (option != null && !option.trim().isEmpty())
					{
						String optionLower = option.trim().toLowerCase(Locale.ROOT);
						if (node.objectIds != null && !node.objectIds.isEmpty())
						{
							for (Integer objectId : node.objectIds)
							{
								if (objectId != null && objectId >= 0)
								{
									map.put(idKey(kindLower, objectId, optionLower), rule);
								}
							}
						}
						else
						{
							map.put(key(kindLower, nameLower, optionLower), rule);
						}
					}
				}
			}
			rules = Collections.unmodifiableMap(map);
			slayerNpcNamesLower = Collections.unmodifiableSet(slayerNames);
			if (snapshot.masterFarmerSeedCards != null)
			{
				masterFarmerSeedCards = Collections.unmodifiableList(snapshot.masterFarmerSeedCards);
			}
			log.info("Loaded {} resource node rules ({} Master Farmer seeds) from snapshot",
				rules.size(), masterFarmerSeedCards.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load resource_nodes.json", ex);
		}
	}

	private static List<CardGroup> buildGroups(NodeDto node)
	{
		List<CardGroup> groups = new ArrayList<>();
		if (node.requiredCardGroups != null)
		{
			for (int i = 0; i < node.requiredCardGroups.size(); i++)
			{
				List<String> cards = node.requiredCardGroups.get(i);
				String role = node.groupRoles != null && i < node.groupRoles.size()
					? node.groupRoles.get(i) : null;
				String label = node.groupLabels != null && i < node.groupLabels.size()
					? node.groupLabels.get(i) : null;
				CardGroup group = CardGroup.of(cards, role, label);
				if (group != null)
				{
					groups.add(group);
				}
			}
		}
		else if (node.requiredCards != null)
		{
			if (node.requireAll)
			{
				for (String card : node.requiredCards)
				{
					CardGroup group = CardGroup.of(Collections.singletonList(card), null, null);
					if (group != null)
					{
						groups.add(group);
					}
				}
			}
			else
			{
				CardGroup group = CardGroup.of(node.requiredCards, null, null);
				if (group != null)
				{
					groups.add(group);
				}
			}
		}
		return groups;
	}

	public static class Rule
	{
		public final String category;
		public final List<CardGroup> groups;

		Rule(String category, List<CardGroup> groups)
		{
			this.category = category == null ? "" : category.toLowerCase(Locale.ROOT);
			this.groups = Collections.unmodifiableList(groups);
		}

		/**
		 * @param owned         lower-cased owned card names
		 * @param excludedRoles group roles a config mode has switched off (never null)
		 * @param forceAllInGroups treat any-of groups as all-required (stall thieving "All items")
		 * @return display strings for each unsatisfied requirement, empty when allowed.
		 *         Any-of groups render as "A / B" so the player sees the alternatives.
		 */
		public List<String> missingRequirements(Set<String> owned, Set<String> excludedRoles,
			boolean forceAllInGroups)
		{
			return missingRequirements(owned::contains, excludedRoles, forceAllInGroups);
		}

		public List<String> missingRequirements(Predicate<String> ownsCard,
			Set<String> excludedRoles, boolean forceAllInGroups)
		{
			List<String> missing = new ArrayList<>();
			for (CardGroup group : groups)
			{
				if (group.role != null && excludedRoles.contains(group.role))
				{
					continue;
				}
				if (forceAllInGroups)
				{
					for (int i = 0; i < group.displayCards.size(); i++)
					{
						if (!ownsCard.test(group.lowerCards.get(i)))
						{
							missing.add(group.displayCards.get(i));
						}
					}
				}
				else if (!group.isSatisfied(ownsCard))
				{
					missing.add(String.join(" / ", group.displayCards));
				}
			}
			return missing;
		}

		/** Missing requirements from one named role only; unlabelled groups are ignored. */
		public List<String> missingRequirementsForRole(Set<String> owned, String includedRole)
		{
			return missingRequirementsForRole(owned::contains, includedRole);
		}

		public List<String> missingRequirementsForRole(Predicate<String> ownsCard,
			String includedRole)
		{
			if (includedRole == null)
			{
				return Collections.emptyList();
			}
			String cleanRole = includedRole.trim().toLowerCase(Locale.ROOT);
			List<String> missing = new ArrayList<>();
			for (CardGroup group : groups)
			{
				if (cleanRole.equals(group.role) && !group.isSatisfied(ownsCard))
				{
					missing.add(String.join(" / ", group.displayCards));
				}
			}
			return missing;
		}
	}

	public static class CardGroup
	{
		/** Original casing, for chat messages; lowerCards is index-aligned. */
		public final List<String> displayCards;
		public final List<String> lowerCards;
		public final String role;
		public final String label;

		private CardGroup(List<String> displayCards, List<String> lowerCards, String role,
			String label)
		{
			this.displayCards = Collections.unmodifiableList(displayCards);
			this.lowerCards = Collections.unmodifiableList(lowerCards);
			this.role = role;
			this.label = label;
		}

		static CardGroup of(List<String> cards, String role, String label)
		{
			if (cards == null)
			{
				return null;
			}
			List<String> display = new ArrayList<>();
			List<String> lower = new ArrayList<>();
			for (String card : cards)
			{
				if (card != null && !card.trim().isEmpty())
				{
					display.add(card.trim());
					lower.add(card.trim().toLowerCase(Locale.ROOT));
				}
			}
			if (display.isEmpty())
			{
				return null;
			}
			String cleanRole = role == null || role.trim().isEmpty()
				? null : role.trim().toLowerCase(Locale.ROOT);
			String cleanLabel = label == null || label.trim().isEmpty()
				? display.get(0) : label.trim();
			return new CardGroup(display, lower, cleanRole, cleanLabel);
		}

		public boolean isSatisfied(Predicate<String> ownsCard)
		{
			for (String card : lowerCards)
			{
				if (ownsCard.test(card))
				{
					return true;
				}
			}
			return false;
		}
	}

	private static class Snapshot
	{
		List<NodeDto> nodes;
		List<String> masterFarmerSeedCards;
	}

	private static class NodeDto
	{
		String category;
		String kind;
		String name;
		List<String> options;
		List<Integer> objectIds;
		List<String> requiredCards;
		List<List<String>> requiredCardGroups;
		List<String> groupRoles;
		List<String> groupLabels;
		boolean requireAll;
	}
}

package com.bronzemantcg.util;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/** Small shared primitives for private, versioned Bronzeman cache files. */
public final class CacheFiles
{
	private CacheFiles()
	{
	}

	public static void writeAtomically(Path target, byte[] bytes) throws IOException
	{
		if (target == null || bytes == null)
		{
			throw new IllegalArgumentException("target and bytes are required");
		}
		Path parent = target.toAbsolutePath().getParent();
		if (parent == null)
		{
			throw new IOException("cache target has no parent directory");
		}
		Files.createDirectories(parent);
		Path temporary = Files.createTempFile(parent, target.getFileName().toString(), ".tmp");
		boolean moved = false;
		try
		{
			try (FileChannel channel = FileChannel.open(temporary,
				StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING))
			{
				ByteBuffer buffer = ByteBuffer.wrap(bytes);
				while (buffer.hasRemaining())
				{
					channel.write(buffer);
				}
				channel.force(true);
			}
			Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE,
				StandardCopyOption.REPLACE_EXISTING);
			moved = true;
		}
		finally
		{
			if (!moved)
			{
				Files.deleteIfExists(temporary);
			}
		}
	}

	public static String sha256Hex(String value)
	{
		if (value == null || value.isEmpty())
		{
			throw new IllegalArgumentException("value is required");
		}
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
			StringBuilder result = new StringBuilder(digest.length * 2);
			for (byte valueByte : digest)
			{
				result.append(String.format("%02x", valueByte & 0xff));
			}
			return result.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException("SHA-256 is unavailable", ex);
		}
	}
}
